// Ejercicios: RepDB free tier (https://repdb.co). Exercise data by RepDB (repdb.co).
// Uso dentro de la app permitido con atribución visible; no redistribuir como dataset.
const EX_IMG_BASE = "https://raw.githubusercontent.com/RepDB/exercise-dataset/main/images/flat/";
const EXERCISE_DB = [{"id":"90-90-hold","n":"Estiramiento 90/90","d":"Una postura de movilidad de cadera que se mantiene sentado en el suelo: las dos rodillas flexionadas a unos 90 grados, una pierna delante de ti y girada hacia fuera, y la otra a un lado y girada hacia dentro. Mantener la posición con el tronco erguido estira la parte externa de la cadera de la pierna delantera y la parte anterior de la cadera de la pierna trasera.","cat":"estiramiento","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["flexores de cadera"],"m2":["glúteo mayor","glúteo medio"],"ins":["Siéntate en el suelo y flexiona la pierna delantera delante de ti, de modo que la espinilla quede cruzada frente al cuerpo y la rodilla flexionada a unos 90 grados.","Coloca la pierna trasera a un lado, con esa rodilla también flexionada a unos 90 grados y la espinilla apuntando hacia atrás.","Apoya las manos en el suelo a los lados de las caderas para sostenerte.","Siéntate erguido, con el pecho elevado y ambos isquiones lo más cerca del suelo que puedas.","Mantén la posición respirando despacio y nota el estiramiento en la parte externa de la cadera de la pierna delantera y en la parte anterior de la cadera de la pierna trasera.","Mantén la postura durante el tiempo previsto; luego intercambia las piernas y mantenla del otro lado."],"tips":["Mantén el tronco erguido; si te encorvas, el estiramiento deja de llegar a las caderas.","Si tienes las caderas rígidas, carga más peso en las manos o siéntate sobre una toalla doblada hasta que puedas sentarte más erguido.","Entra en el estiramiento poco a poco y no fuerces las rodillas hacia el suelo; la posición debe sentirse intensa, pero no dolorosa."],"met":5.0,"uni":true,"img":["90-90-hold-main.webp"]},{"id":"ab-wheel-rollout","n":"Rueda Abdominal","d":"Un ejercicio de core haciendo rodar una rueda adelante y atrás, que entrena la antiextensión de la columna.","cat":"fuerza","g":"core","bp":"core","eq":"rueda abdominal","home":true,"bw":false,"lv":"intermedio","m":["abdominales","transverso abdominal"],"m2":["deltoides anterior","dorsales","oblicuos","serrato"],"ins":["Arrodíllate en el suelo y agarra las asas de la rueda a la anchura de los hombros.","Activa fuertemente el core para que la zona lumbar quede neutra.","Rueda la rueda lentamente hacia adelante, extendiendo el cuerpo lo más lejos que puedas controlar.","Detente antes de que las caderas se hundan o la espalda se arquee.","Tira de la rueda de regreso hacia las rodillas contrayendo los abdominales."],"tips":["Activa el core antes de cada repetición — no dejes que la lumbar se arquee.","Aumenta el rango progresivamente, parando antes de que las caderas se hundan.","Usa un tope contra la pared si no puedes controlar la posición baja."],"met":6.0,"uni":false,"img":["ab-wheel-rollout-start.webp","ab-wheel-rollout-peak.webp"]},{"id":"air-bike","n":"Bicicleta de Aire","d":"Un ejercicio de cuerpo completo en bicicleta de aire que combina el empuje y la tracción de los brazos con el pedaleo continuo.","cat":"cardio","g":"cuerpo completo","bp":"full_body","eq":"air bike","home":false,"bw":false,"lv":"intermedio","m":["isquiotibiales","cuádriceps"],"m2":["glúteo mayor","dorsales","pectoral","abdominales"],"ins":["Siéntate en la bicicleta de aire y sujeta los manillares móviles.","Coloca los pies en los pedales y contrae el core.","Empuja y jala los manillares mientras pedaleas a un ritmo constante.","Impulsa con brazos y piernas para mantener la potencia.","Continúa durante la duración o distancia deseada."],"tips":["Mantén las rodillas alineadas con los pedales al pedalear.","Evita encorvar la espalda cuando aumente la fatiga.","Respira de forma rítmica para sostener la potencia."],"met":8.0,"uni":false,"img":["air-bike-main.webp"]},{"id":"archer-pull-ups","n":"Dominadas Arquero","d":"Una dominada unilateral desplazando el cuerpo hacia una mano mientras el otro brazo permanece estirado, desarrollando fuerza de tracción a un brazo.","cat":"fuerza","g":"espalda","bp":"back","eq":"barra de dominadas","home":true,"bw":false,"lv":"avanzado","m":["dorsales"],"m2":["bíceps","antebrazo","deltoides posterior","romboides"],"ins":["Agarra la barra más ancha que la anchura de los hombros con las palmas mirando hacia afuera.","Tírate hacia arriba desplazando el cuerpo hacia una mano.","Mantén el brazo opuesto extendido como soporte.","Bájate de forma controlada hasta quedar colgado.","Alterna lados en cada repetición o completa las repeticiones de un lado primero."],"tips":["Mantén el brazo estirado completamente extendido y úsalo solo como guía.","Lleva la barbilla hacia la mano que trabaja, no directamente hacia arriba.","Domina las dominadas con agarre ancho antes de progresar a las arqueras."],"met":6.0,"uni":false,"img":["archer-pull-ups-start.webp","archer-pull-ups-peak.webp"]},{"id":"archer-push-ups","n":"Push-Ups Arquero","d":"Una flexión ancha bajando hacia una mano mientras el brazo contrario permanece estirado, cargando un lado cada vez.","cat":"fuerza","g":"pecho","bp":"chest","eq":"sin equipo","home":true,"bw":true,"lv":"avanzado","m":["pectoral"],"m2":["deltoides anterior","abdominales","serrato","tríceps"],"ins":["Colócate en posición de push-up amplia con los brazos extendidos.","Bájate hacia una mano mientras mantienes el otro brazo extendido.","Mantén el core apretado y el cuerpo en línea recta.","Empuja de vuelta a la posición inicial.","Alterna lados en cada repetición el número de veces deseado."],"tips":["Mantén las caderas paralelas al suelo mientras te desplazas hacia el lado.","Deja que el brazo estirado ayude lo menos posible.","Empieza con flexiones anchas y desplázate un poco más en cada sesión."],"met":5.0,"uni":false,"img":["archer-push-ups-start.webp","archer-push-ups-peak.webp"]},{"id":"arnold-press","n":"Press Arnold","d":"Un press de hombros con mancuernas que rota las palmas durante el ascenso, dirigido al deltoides anterior y lateral.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["deltoides anterior","deltoides lateral"],"m2":["serrato","trapecio","tríceps"],"ins":["Sostén un par de mancuernas a la altura de los hombros con las palmas mirando hacia ti.","Empuja las mancuernas sobre la cabeza mientras rotas las palmas hacia adelante.","Extiende los brazos por completo en la parte superior sin bloquear los codos.","Invierte el movimiento y rota de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"tips":["Evita arquear la zona lumbar al empujar hacia arriba.","Mantén las muñecas firmes y alineadas con los antebrazos.","Controla la bajada en lugar de dejar caer el peso."],"met":6.0,"uni":false,"img":["arnold-press-start.webp","arnold-press-peak.webp"]},{"id":"assisted-dips","n":"Fondos en Máquina Asistida","d":"Un ejercicio de fondos en máquina asistida que descarga parte del peso corporal para fortalecer pecho y tríceps.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"máquina de fondos","home":false,"bw":false,"lv":"principiante","m":["pectoral","tríceps"],"m2":["deltoides anterior","romboides"],"ins":["Sube a la máquina de fondos asistidos con las rodillas en el pad.","Agarra las barras paralelas y soporta tu peso con los brazos extendidos.","Baja el cuerpo flexionando los codos hasta que los hombros queden por debajo de los codos.","Empuja de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"tips":["Baja de forma controlada, sin rebotar en la parte inferior.","Mantén los hombros alejados de las orejas durante todo el recorrido.","Reduce la asistencia de forma gradual a medida que ganes fuerza."],"met":6.0,"uni":false,"img":["assisted-dips-start.webp","assisted-dips-peak.webp"]},{"id":"assisted-pull-ups","n":"Dominadas Asistidas","d":"Una dominada en máquina asistida que contrarresta parte del peso corporal, pensada para construir la fuerza de espalda necesaria para dominadas estrictas.","cat":"fuerza","g":"espalda","bp":"back","eq":"máquina de dominadas asistidas","home":false,"bw":false,"lv":"principiante","m":["dorsales"],"m2":["bíceps","antebrazo","deltoides posterior","romboides"],"ins":["Coloca las rodillas en el pad de la máquina de dominadas asistidas.","Agarra la barra con las palmas mirando hacia afuera, ligeramente más ancho que los hombros.","Tira del pecho hacia la barra impulsando los codos hacia abajo.","Bájate de forma controlada hasta quedar colgado con los brazos extendidos.","Repite el número de repeticiones deseado."],"tips":["Inicia el movimiento bajando los omóplatos antes de doblar los codos.","Evita balancearte para no restar trabajo a la espalda.","Ajusta el contrapeso para completar todas las repeticiones con buena técnica."],"met":6.0,"uni":false,"img":["assisted-pull-ups-start.webp","assisted-pull-ups-peak.webp"]},{"id":"back-extension","n":"Extensión de Espalda","d":"Un movimiento de aislamiento que trabaja los erectores espinales de la zona lumbar en un banco de hiperextensión.","cat":"fuerza","g":"espalda","bp":"back","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["lumbares"],"m2":["glúteo mayor","isquiotibiales"],"ins":["Acuéstate boca abajo en un banco de hiperextensión con las caderas en el borde del pad.","Baja el torso hacia el suelo.","Sube el torso hasta que el cuerpo quede recto.","Repite."],"tips":["Mantén los movimientos controlados.","No hiperextiendas más allá de la posición neutra de la columna."],"met":3.5,"uni":false,"img":["back-extension-start.webp","back-extension-peak.webp"]},{"id":"back-lever","n":"Back lever","d":"Un isométrico gimnástico avanzado: colgado de una barra, el cuerpo se mantiene horizontal y boca abajo en línea recta, exigiendo tensión de todo el cuerpo a través de dorsales, core y cadena posterior.","cat":"fuerza","g":"cuerpo completo","bp":"full_body","eq":"barra de dominadas","home":true,"bw":false,"lv":"avanzado","m":["lumbares","dorsales"],"m2":["deltoides anterior","glúteo mayor","abdominales"],"ins":["Cuélgate de una barra con agarre prono y rota hacia atrás a través de los brazos hasta quedar invertido.","Baja el cuerpo hacia delante y abajo hasta que quede horizontal, con la cara hacia el suelo.","Mantén los brazos rectos y todo el cuerpo en una línea rígida de la cabeza a los pies.","Aprieta el core y los glúteos para que la cadera y los hombros no se hundan.","Mantén la posición el tiempo deseado y rota de nuevo hacia arriba de forma controlada."],"tips":["Progresa con variantes agrupadas y a una pierna antes de intentar el lever completo con el cuerpo recto.","Deprime y retrae las escápulas para proteger los hombros.","Mantente rígido: cualquier flexión o arqueo colapsa la postura."],"met":6.0,"uni":false,"img":["back-lever-main.webp"]},{"id":"ball-leg-curl","n":"Curl de Piernas con Pelota de Estabilidad","d":"Un curl de isquiotibiales con el propio peso usando una pelota de estabilidad, rodando los talones hacia los glúteos mientras se eleva la cadera.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"fitball","home":true,"bw":false,"lv":"intermedio","m":["isquiotibiales"],"m2":["gemelos","glúteo mayor"],"ins":["Acuéstate boca arriba en el suelo con los talones y la parte inferior de las pantorrillas sobre la pelota de estabilidad y los brazos estirados para hacer equilibrio.","Presiona con los talones para elevar las caderas formando una línea recta desde los hombros hasta los tobillos.","Manteniendo las caderas arriba, flexiona las rodillas para rodar la pelota hacia los glúteos.","Extiende las piernas de vuelta de forma controlada sin bajar las caderas.","Completa todas las repeticiones, luego baja las caderas y sepárate de la pelota."],"tips":["Las caderas permanecen arriba durante toda la serie: es una combinación de puente y curl.","Empieza con ambos pies; progresa a una sola pierna cuando se vuelva fácil."],"met":5.0,"uni":false,"img":["ball-leg-curl-start.webp","ball-leg-curl-peak.webp"]},{"id":"ball-pike","n":"Pike con Pelota","d":"Un ejercicio avanzado de core en el que las caderas se elevan mientras los pies ruedan una pelota suiza hacia el pecho.","cat":"fuerza","g":"core","bp":"core","eq":"fitball","home":true,"bw":false,"lv":"avanzado","m":["oblicuos","abdominales"],"m2":["deltoides anterior","flexores de cadera","serrato"],"ins":["Coloca las espinillas sobre una pelota suiza y las manos en el suelo en plancha alta.","Activa el core y mantén las piernas rectas.","Eleva las caderas, rodando la pelota hacia el pecho hasta formar una V invertida.","Pausa brevemente arriba.","Rueda la pelota de vuelta a la posición inicial de plancha."],"tips":["Mantén las piernas rectas todo el tiempo — sin doblar las rodillas.","Mueve desde la cadera, no desde la zona lumbar.","Trabaja primero con flexiones de rodilla si el pike es demasiado difícil."],"met":6.0,"uni":false,"img":["ball-pike-start.webp","ball-pike-peak.webp"]},{"id":"band-assisted-pull-ups","n":"Dominadas Asistidas con Banda","d":"Una dominada con banda elástica enganchada a la barra que reduce el peso corporal a vencer en cada repetición.","cat":"fuerza","g":"espalda","bp":"back","eq":"banda elástica","home":true,"bw":false,"lv":"principiante","m":["dorsales"],"m2":["bíceps","antebrazo","deltoides posterior","romboides"],"ins":["Engancha una banda elástica en la barra de dominadas e introduce un pie en ella.","Agarra la barra con las palmas mirando hacia afuera, a la anchura de los hombros.","Tira del pecho hacia la barra impulsando los codos hacia abajo.","Bájate de forma controlada hasta quedar colgado con los brazos extendidos.","Repite el número de repeticiones deseado."],"tips":["Comprueba que la banda esté bien sujeta antes de colgarte.","No tomes impulso con las piernas, deja que trabaje la espalda.","Usa una banda más fina a medida que progreses."],"met":6.0,"uni":false,"img":["band-assisted-pull-ups-start.webp","band-assisted-pull-ups-peak.webp"]},{"id":"band-pull-apart","n":"Separación de Banda Elástica","d":"Un ejercicio de alto volumen para el deltoides posterior y los retractores escapulares que se realiza separando una banda elástica a la altura de los hombros.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"banda elástica","home":true,"bw":false,"lv":"principiante","m":["deltoides posterior"],"m2":["romboides","trapecio"],"ins":["Párate sosteniendo una banda elástica ligera con ambas manos, brazos extendidos al frente a la altura de los hombros.","Las manos comienzan a la anchura de los hombros, palmas mirando hacia abajo.","Manteniendo los brazos extendidos, separa la banda llevando las manos hacia los lados.","Termina con la banda tocando el pecho y los omóplatos juntos.","Vuelve lentamente a la posición inicial y repite."],"tips":["Lidera el movimiento con los meñiques: esto rota externamente los hombros.","Usa una banda lo suficientemente ligera para hacer 15-30 repeticiones limpias; es un ejercicio preventivo de alto número de repeticiones."],"met":5.0,"uni":false,"img":["band-pull-apart-start.webp","band-pull-apart-peak.webp"]},{"id":"banded-adductor-stretch","n":"Estiramiento de Aductores con Banda","d":"Un estiramiento tumbado que usa una banda para llevar una pierna estirada hacia el lado y alargar el aductor.","cat":"estiramiento","g":"piernas","bp":"upper_legs","eq":"banda elástica","home":true,"bw":false,"lv":"principiante","m":["aductores"],"m2":["isquiotibiales"],"ins":["Acuéstate boca arriba con una banda en un pie.","Eleva esa pierna y déjala abrir hacia el lado.","Sujeta la banda para controlar cuánto baja la pierna.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],"tips":["Mantén las caderas planas y ambos glúteos en el suelo.","Estira hasta una tensión leve, nunca hasta el dolor."],"met":5.0,"uni":true,"img":["banded-adductor-stretch-main.webp"]},{"id":"banded-ankle-stretch","n":"Estiramiento de Tobillo con Banda","d":"Un estiramiento sentado que usa una banda en el antepié para flexionar el tobillo y alargar la pantorrilla.","cat":"estiramiento","g":"piernas","bp":"lower_legs","eq":"banda elástica","home":true,"bw":false,"lv":"principiante","m":["gemelos"],"m2":["sóleo"],"ins":["Siéntate con una pierna extendida y una banda en el antepié.","Sujeta la banda con ambas manos.","Tira para que los dedos se acerquen a la espinilla.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],"tips":["Mantén la pierna estirada y relajada.","Estira hasta una tensión leve, nunca hasta el dolor."],"met":5.0,"uni":true,"img":["banded-ankle-stretch-main.webp"]},{"id":"banded-calf-stretch","n":"Estiramiento de Pantorrilla con Banda","d":"Un estiramiento tumbado que usa una banda en la planta del pie para flexionar el tobillo y alargar la pantorrilla.","cat":"estiramiento","g":"piernas","bp":"lower_legs","eq":"banda elástica","home":true,"bw":false,"lv":"principiante","m":["gemelos"],"m2":["sóleo"],"ins":["Acuéstate boca arriba y pasa una banda por la planta de un pie.","Eleva la pierna y mantenla bastante recta.","Tira de la banda para que los dedos se acerquen a la espinilla.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],"tips":["Mantén el tirón constante, sin tirones bruscos.","Mantén la rodilla suavemente estirada."],"met":5.0,"uni":true,"img":["banded-calf-stretch-main.webp"]},{"id":"banded-chest-stretch","n":"Estiramiento de Pecho con Banda","d":"Un estiramiento de pie que abre el pecho sujetando una banda tras la espalda y separando los brazos.","cat":"estiramiento","g":"pecho","bp":"chest","eq":"banda elástica","home":true,"bw":false,"lv":"principiante","m":["pectoral"],"m2":["deltoides anterior"],"ins":["Sujeta una banda con ambas manos tras la espalda.","Estira los brazos y sepáralos.","Eleva el pecho y junta los omóplatos.","Mantén de 20 a 30 segundos, respirando de forma constante."],"tips":["Mantén los hombros abajo, lejos de las orejas.","Estira hasta una tensión leve, nunca hasta el dolor."],"met":5.0,"uni":false,"img":["banded-chest-stretch-main.webp"]},{"id":"banded-clamshell","n":"Almeja con Banda","d":"Una abducción de cadera tipo almeja con una banda circular por encima de las rodillas, que aísla el glúteo medio.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"mini banda","home":true,"bw":false,"lv":"principiante","m":["glúteo medio"],"m2":["glúteo mayor"],"ins":["Túmbate de lado con las caderas y rodillas flexionadas a unos 45 grados y los pies juntos uno sobre otro.","Coloca una banda circular alrededor de ambas piernas por encima de las rodillas.","Mantén los pies pegados y la pelvis estable; no rotes hacia atrás durante el movimiento.","Abre la rodilla de arriba contra la banda, como una almeja al abrirse, hasta notar que el glúteo se activa.","Haz una breve pausa arriba y baja de forma controlada hasta la posición inicial.","Completa todas las repeticiones de un lado y luego cambia."],"tips":["La pelvis se queda fija; en cuanto rotas hacia atrás, el glúteo deja de trabajar.","Un tempo lento y controlado vale más que una banda dura.","Si te da un calambre en el lateral de la cadera, acorta la serie."],"met":5.0,"uni":false,"img":["banded-clamshell-start.webp","banded-clamshell-peak.webp"]},{"id":"banded-figure-4-stretch","n":"Estiramiento Figura 4 con Banda","d":"Un estiramiento de glúteos tumbado en posición de figura 4, usando una banda para acercar ambas piernas al pecho.","cat":"estiramiento","g":"piernas","bp":"upper_legs","eq":"banda elástica","home":true,"bw":false,"lv":"principiante","m":["glúteo mayor"],"m2":["glúteo medio"],"ins":["Acuéstate boca arriba y cruza un tobillo sobre el muslo opuesto.","Pasa una banda por el muslo de apoyo.","Lleva ambas piernas al pecho con la banda.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],"tips":["Mantén la cabeza y los hombros relajados en el suelo.","Deja que la rodilla cruzada caiga hacia afuera."],"met":5.0,"uni":true,"img":["banded-figure-4-stretch-main.webp"]},{"id":"banded-fire-hydrant","n":"Hidrante de Fuego con Banda","d":"Este ejercicio de aislamiento utiliza una banda de resistencia para fortalecer el glúteo medio y mayor, mejorando la abducción y estabilidad de la cadera.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"mini banda","home":true,"bw":false,"lv":"principiante","m":["glúteo medio"],"m2":["glúteo mayor"],"ins":["Coloca una banda de resistencia justo por encima de tus rodillas y ponte en posición de cuadrupedia, manos bajo los hombros y rodillas bajo las caderas.","Mantén tu core activado y la espalda recta, conservando una columna vertebral neutra durante todo el movimiento.","Levanta lentamente una rodilla hacia un lado, manteniendo la rodilla flexionada a 90 grados, hasta que tu muslo esté paralelo al suelo.","Sostén brevemente en la parte superior, contrayendo el glúteo, luego baja la pierna de forma controlada a la posición inicial.","Completa todas las repeticiones de un lado antes de cambiar al otro lado."],"tips":["Concéntrate en un movimiento controlado; evita usar el impulso para levantar la pierna.","Mantén tus caderas estables y evita que tu torso rote o se incline.","Asegúrate de que la banda permanezca tensa durante todo el rango de movimiento."],"met":5.0,"uni":true,"img":["banded-fire-hydrant-start.webp","banded-fire-hydrant-peak.webp"]},{"id":"banded-glute-bridge","n":"Puente de Glúteos con Banda","d":"Un puente de glúteos con una banda circular por encima de las rodillas que suma tensión de abducción al empuje de cadera.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"mini banda","home":true,"bw":false,"lv":"principiante","m":["glúteo mayor"],"m2":["glúteo medio","isquiotibiales"],"ins":["Túmbate boca arriba con las rodillas flexionadas y los pies apoyados en el suelo a la anchura de los hombros.","Coloca una banda circular alrededor de ambas piernas justo por encima de las rodillas.","Presiona la zona lumbar contra el suelo y activa el core.","Empuja con los talones y aprieta los glúteos para elevar las caderas en puente, manteniendo la tensión de la banda al empujar las rodillas hacia afuera.","Arriba, el cuerpo forma una línea recta de los hombros a las rodillas. Haz una breve pausa.","Baja de forma controlada hasta la posición inicial y repite el número de repeticiones recomendado."],"tips":["Las rodillas tienden a irse hacia dentro; empújalas hacia afuera contra la banda.","Detén la subida cuando las caderas queden a la altura de hombros y rodillas; no hiperextiendas la lumbar.","Aprieta fuerte arriba; un puente rápido a medio recorrido se siente fácil porque lo es."],"met":6.0,"uni":false,"img":["banded-glute-bridge-start.webp","banded-glute-bridge-peak.webp"]},{"id":"banded-good-morning","n":"Buenos Días con Banda","d":"Un hip-hinge con banda elástica sobre la espalda alta, que trabaja isquiotibiales y glúteos.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"mini banda","home":true,"bw":false,"lv":"principiante","m":["glúteo mayor","isquiotibiales"],"m2":["lumbares"],"ins":["Pisa una banda elástica con ambos pies y pásala por la nuca.","Coloca los pies a la anchura de las caderas, ligera flexión de rodillas.","Flexiona desde la cadera empujándola atrás, espalda recta.","Baja hasta sentir el estiramiento en los isquiotibiales.","Empuja las caderas adelante para volver a la posición inicial."],"tips":["Mueve desde la cadera, no desde la zona lumbar.","Pecho arriba y espalda recta.","Usa una banda lo bastante ligera para permitir el rango completo."],"met":6.0,"uni":false,"img":["banded-good-morning-start.webp","banded-good-morning-peak.webp"]},{"id":"banded-hamstring-stretch","n":"Estiramiento de Isquiotibiales con Banda","d":"Un estiramiento tumbado que usa una banda en el pie para acercar la pierna estirada al torso y alargar el isquiotibial.","cat":"estiramiento","g":"piernas","bp":"upper_legs","eq":"banda elástica","home":true,"bw":false,"lv":"principiante","m":["isquiotibiales"],"m2":["gemelos"],"ins":["Acuéstate boca arriba y pasa una banda por un pie.","Eleva esa pierna recta, sujetando la banda con ambas manos.","Tira suavemente de la banda para acercar la pierna.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],"tips":["Mantén la pierna elevada lo más recta posible.","Mantén la otra pierna plana en el suelo."],"met":5.0,"uni":true,"img":["banded-hamstring-stretch-main.webp"]},{"id":"banded-hip-thrust","n":"Empuje de Cadera con Banda","d":"Este ejercicio utiliza una banda de bucle para aumentar la activación de los glúteos durante un empuje de cadera, trabajando eficazmente el glúteo mayor, los isquiotibiales y el glúteo medio para mejorar la fuerza de la parte inferior del cuerpo.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"mini banda","home":true,"bw":false,"lv":"principiante","m":["glúteo mayor"],"m2":["glúteo medio","isquiotibiales"],"ins":["Coloca una banda de bucle justo por encima de tus rodillas y siéntate en el suelo con la parte superior de tu espalda contra un banco.","Dobla las rodillas, apoya los pies al ancho de las caderas y posiciona la banda para crear tensión.","Impúlsate a través de los talones, extiende las caderas y levanta los glúteos del suelo hasta que tu cuerpo forme una línea recta.","Aprieta los glúteos con fuerza en la parte superior, asegurándote de empujar las rodillas hacia afuera contra la banda.","Baja lentamente las caderas a la posición inicial con control."],"tips":["Mantén una tensión constante en la banda durante todo el movimiento.","Concéntrate en una fuerte contracción de los glúteos en el pico del empuje.","Mantén la barbilla metida y la mirada al frente para una columna vertebral neutra.","Asegúrate de que tus espinillas estén verticales en la parte superior del movimiento."],"met":6.0,"uni":false,"img":["banded-hip-thrust-start.webp","banded-hip-thrust-peak.webp"]},{"id":"banded-it-band-stretch","n":"Estiramiento de Banda Iliotibial con Banda","d":"Un estiramiento tumbado que usa una banda para cruzar una pierna sobre el cuerpo y trabajar el muslo y la cadera externos.","cat":"estiramiento","g":"piernas","bp":"upper_legs","eq":"banda elástica","home":true,"bw":false,"lv":"principiante","m":["abductores"],"m2":["glúteo mayor","glúteo medio"],"ins":["Acuéstate boca arriba con una banda en un pie elevado.","Sujeta la banda con la mano contraria.","Lleva la pierna estirada cruzando el cuerpo hacia el suelo.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],"tips":["Mantén ambos hombros en el suelo.","Detente al sentir el estiramiento en el muslo externo."],"met":5.0,"uni":true,"img":["banded-it-band-stretch-main.webp"]},{"id":"banded-kneeling-hip-thrust","n":"Empuje de Cadera Arrodillado con Banda","d":"Este ejercicio fortalece los glúteos y los isquiotibiales al impulsar las caderas hacia adelante contra la resistencia de una banda desde una posición arrodillada.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"mini banda","home":true,"bw":false,"lv":"principiante","m":["glúteo mayor"],"m2":["isquiotibiales"],"ins":["Coloca una banda de bucle justo por encima de tus rodillas. Arrodíllate en el suelo con el torso erguido y las rodillas separadas al ancho de las caderas.","Inclínate ligeramente hacia adelante desde las caderas, manteniendo la espalda recta y el core contraído.","Inicia el movimiento apretando los glúteos, impulsando las caderas hacia adelante hasta que tu torso esté erguido.","Aprieta los glúteos con fuerza en la parte superior, manteniendo la tensión en la banda.","Invierte lentamente el movimiento, controlando la resistencia de la banda mientras regresas a la posición inicial."],"tips":["Concéntrate en una fuerte contracción de los glúteos en la parte superior del movimiento.","Mantén el core activado en todo momento para evitar arquear la espalda baja.","Mantén una tensión constante en la banda empujando las rodillas ligeramente hacia afuera."],"met":6.0,"uni":false,"img":["banded-kneeling-hip-thrust-start.webp","banded-kneeling-hip-thrust-peak.webp"]},{"id":"banded-lat-stretch","n":"Estiramiento de Dorsales con Banda","d":"Un estiramiento de pie que alarga los dorsales al inclinarse hacia adelante sosteniendo una banda en tensión sobre la cabeza.","cat":"estiramiento","g":"espalda","bp":"back","eq":"banda elástica","home":true,"bw":false,"lv":"principiante","m":["dorsales"],"m2":["deltoides posterior"],"ins":["Sujeta una banda sobre la cabeza con ambas manos en tensión ligera.","Inclínate desde las caderas con los brazos extendidos al frente.","Deja caer el pecho para alargar los lados de la espalda.","Mantén de 20 a 30 segundos, respirando de forma constante."],"tips":["Mantén los brazos estirados y los hombros relajados.","Relájate y sigue respirando todo el tiempo."],"met":5.0,"uni":false,"img":["banded-lat-stretch-main.webp"]},{"id":"banded-lateral-walk","n":"Caminata Lateral con Banda","d":"Un desplazamiento lateral a pasos con una banda circular por encima de las rodillas o en los tobillos, que activa el glúteo medio.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"mini banda","home":true,"bw":false,"lv":"principiante","m":["glúteo medio"],"m2":["glúteo mayor","cuádriceps"],"ins":["Coloca una banda circular alrededor de las piernas por encima de las rodillas (o en los tobillos para una versión más difícil).","Ponte en cuarto de sentadilla: pies a la anchura de los hombros, caderas atrás, pecho alto y rodillas alineadas con los pies.","Da un paso lateral con un pie directamente hacia el lado contra la tensión de la banda.","Acerca el pie de atrás hacia el de delante manteniendo la tensión de la banda en todo momento; no dejes que los pies se junten de golpe.","Sigue dando pasos laterales en una dirección durante las repeticiones o la distancia indicada y luego invierte.","Permanece abajo todo el rato; no te incorpores entre paso y paso."],"tips":["Mantén las puntas de los pies hacia el frente; no dejes que el pie de delante se abra.","Las caderas se quedan niveladas; no te balancees de lado a lado al caminar.","Si las rodillas se van hacia dentro, la banda es demasiado dura; usa una más suave."],"met":6.0,"uni":false,"img":["banded-lateral-walk-start.webp","banded-lateral-walk-peak.webp"]},{"id":"banded-rear-delt-stretch","n":"Estiramiento de Deltoides Posterior con Banda","d":"Un estiramiento de pie para el hombro posterior llevando un brazo cruzado contra la tensión de la banda.","cat":"estiramiento","g":"hombros","bp":"shoulders","eq":"banda elástica","home":true,"bw":false,"lv":"principiante","m":["deltoides posterior"],"m2":["romboides","trapecio"],"ins":["Pasa una banda por un brazo y sujeta el otro extremo.","Lleva ese brazo en horizontal sobre el pecho.","Usa la banda para profundizar el tirón suavemente.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],"tips":["Mantén el hombro que trabaja relajado y abajo.","Relájate y sigue respirando todo el tiempo."],"met":5.0,"uni":true,"img":["banded-rear-delt-stretch-main.webp"]},{"id":"banded-romanian-deadlift","n":"Peso Muerto Rumano con Banda","d":"Un peso muerto rumano con banda elástica, ideal para calentar y aprender el patrón de hip-hinge.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"mini banda","home":true,"bw":false,"lv":"principiante","m":["glúteo mayor","isquiotibiales"],"m2":["lumbares"],"ins":["Pisa una banda elástica con ambos pies y agarra el extremo superior.","Coloca los pies a la anchura de las caderas, ligera flexión de rodillas.","Flexiona desde la cadera, deslizando las manos por las piernas.","Baja hasta sentir el estiramiento en los isquiotibiales.","Empuja las caderas adelante para volver a la posición inicial."],"tips":["Mantén la banda cerca de las piernas.","Detente en el punto bajo de tu rango limpio — no redondees la espalda.","El movimiento es un hinge, no una sentadilla — las rodillas casi no se flexionan."],"met":6.0,"uni":false,"img":["banded-romanian-deadlift-start.webp","banded-romanian-deadlift-peak.webp"]},{"id":"banded-seated-hip-abduction","n":"Abducción de Cadera Sentado con Banda","d":"Este ejercicio de aislamiento trabaja el glúteo medio y mayor al rotar externamente las caderas contra la resistencia de una banda mientras estás sentado.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"mini banda","home":true,"bw":false,"lv":"principiante","m":["glúteo medio"],"m2":["glúteo mayor"],"ins":["Siéntate en un banco o silla con una banda elástica alrededor de tus rodillas.","Mantén los pies apoyados en el suelo, separados al ancho de tus caderas, y conserva una postura erguida.","Empuja tus rodillas hacia afuera contra la banda, activando tus glúteos.","Sostén la contracción máxima brevemente, luego regresa lentamente tus rodillas a la posición inicial.","Controla el movimiento a lo largo de todo el rango de movimiento."],"tips":["Concéntrate en apretar tus glúteos para iniciar el movimiento.","Evita inclinarte hacia atrás o usar el impulso; mantén tu torso estable.","Elige una resistencia de banda que permita un movimiento controlado.","Mantén la tensión en la banda incluso en la posición inicial."],"met":5.0,"uni":false,"img":["banded-seated-hip-abduction-start.webp","banded-seated-hip-abduction-peak.webp"]},{"id":"banded-shoulder-stretch","n":"Estiramiento de Hombros con Banda","d":"Un estiramiento de pie que abre los hombros y el pecho sujetando una banda tras la espalda, una mano arriba y otra abajo.","cat":"estiramiento","g":"hombros","bp":"shoulders","eq":"banda elástica","home":true,"bw":false,"lv":"principiante","m":["deltoides anterior"],"m2":["pectoral"],"ins":["Sujeta una banda tras la espalda, una mano arriba y otra abajo.","Mantén una tensión ligera en la banda.","Abre el pecho y lleva los hombros suavemente atrás.","Mantén de 20 a 30 segundos, respirando de forma constante."],"tips":["Mantén las costillas abajo y evita arquear la espalda.","Separa más las manos para suavizar el estiramiento."],"met":5.0,"uni":false,"img":["banded-shoulder-stretch-main.webp"]},{"id":"banded-squat","n":"Sentadilla con Banda","d":"Una sentadilla con peso corporal y banda sobre las rodillas para enseñar a sacar las rodillas afuera.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"mini banda","home":true,"bw":false,"lv":"principiante","m":["glúteo mayor","cuádriceps"],"m2":["glúteo medio","isquiotibiales"],"ins":["Coloca una banda elástica justo sobre las rodillas.","Pies a la anchura de los hombros, puntas ligeramente afuera.","Empuja las rodillas hacia afuera contra la banda al bajar.","Desciende hasta que los muslos queden paralelos o más abajo.","Empuja con los talones para volver a subir."],"tips":["Empuja las rodillas contra la banda durante toda la repetición.","Pecho arriba y espalda recta.","No dejes que las rodillas se vayan hacia adentro."],"met":6.0,"uni":false,"img":["banded-squat-start.webp","banded-squat-peak.webp"]},{"id":"banded-standing-curl","n":"Curl de Pierna de Pie con Banda","d":"Un curl femoral de pie con una banda elástica alrededor del tobillo, útil para viajes o como finalizador con poca carga para isquiotibiales.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"mini banda","home":true,"bw":false,"lv":"principiante","m":["isquiotibiales"],"m2":["gemelos"],"ins":["Coloca una banda elástica alrededor de un tobillo y ancla el otro extremo bajo el pie de apoyo o en un punto fijo delante de ti.","Mantente erguido, sujétate a algo si necesitas equilibrio, con ligera flexión en la pierna de apoyo.","Sube el talón con la banda hacia el glúteo, manteniendo el muslo quieto.","Contrae el isquiotibial arriba, luego baja con control hasta el estiramiento completo.","Completa todas las repeticiones de un lado y cambia de pierna."],"tips":["Mantén el muslo quieto — solo se mueve la parte inferior de la pierna.","Evita balancear la cadera para tomar impulso.","Usa una banda más ligera si no puedes controlar el descenso."],"met":5.0,"uni":true,"img":["banded-standing-curl-start.webp","banded-standing-curl-peak.webp"]},{"id":"banded-standing-hip-abduction","n":"Abducción de Cadera de Pie con Banda","d":"Este ejercicio de aislamiento trabaja el glúteo medio y mayor, mejorando la estabilidad y fuerza de la cadera al abducir la pierna contra la resistencia de la banda.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"mini banda","home":true,"bw":false,"lv":"principiante","m":["glúteo medio"],"m2":["glúteo mayor"],"ins":["Coloca una banda elástica alrededor de tus tobillos o justo encima de tus rodillas.","Ponte de pie con una ligera flexión de rodillas y activa tu core.","Transfiere tu peso a una pierna, manteniendo el torso estable.","Abduce lentamente la pierna libre hacia un lado, sintiendo la contracción del glúteo.","Controla el movimiento mientras regresas la pierna a la posición inicial.","Completa todas las repeticiones por lado antes de cambiar."],"tips":["Mantén tu torso erguido y evita inclinarte hacia un lado.","Concéntrate en un movimiento controlado, no en el impulso.","Asegúrate de que la banda mantenga la tensión durante todo el rango de movimiento.","Inicia el movimiento desde tu cadera, no desde tu pie."],"met":5.0,"uni":true,"img":["banded-standing-hip-abduction-start.webp","banded-standing-hip-abduction-peak.webp"]},{"id":"banded-standing-hip-adduction","n":"Aducción de Cadera de Pie con Banda","d":"Una aducción de cadera de pie con banda elástica, aislando los aductores del muslo interno.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"mini banda","home":true,"bw":false,"lv":"principiante","m":["aductores"],"m2":[],"ins":["Ancla una banda elástica a un poste firme a la altura del tobillo.","Pasa el bucle por la pierna que trabaja, orientada hacia el anclaje.","Aléjate algunos pasos para que la banda quede tensa.","Lleva la pierna que trabaja cruzando el cuerpo hacia la otra pierna.","Regresa lentamente. Completa las repeticiones por lado y cambia."],"tips":["Mantén la pierna de apoyo ligeramente flexionada para estabilidad.","Mueve solo la pierna que trabaja — el torso permanece quieto.","Controla la fase excéntrica para un estiramiento completo del aductor."],"met":5.0,"uni":true,"img":["banded-standing-hip-adduction-start.webp","banded-standing-hip-adduction-peak.webp"]},{"id":"banded-sumo-walk","n":"Caminata Sumo con Banda","d":"Una caminata lateral en posición sumo con una banda alrededor de la parte baja de las piernas, que trabaja el glúteo medio y mayor.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"mini banda","home":true,"bw":false,"lv":"principiante","m":["glúteo mayor","glúteo medio"],"m2":["cuádriceps"],"ins":["Coloca una banda elástica alrededor de la parte baja de las piernas, justo por encima de los tobillos.","Baja a una media sentadilla con los pies más anchos que los hombros.","Da un paso lateral en posición ancha, manteniendo tensión en la banda.","Acerca el pie de atrás solo en parte para que la banda siga tensa y sigue avanzando de lado la distancia indicada antes de cambiar de pierna guía.","Permanece bajo — no te incorpores entre pasos."],"tips":["Mantén tensión en la banda durante toda la serie.","Quédate en media sentadilla — no te levantes entre pasos.","Da pasos cortos y controlados con las puntas ligeramente afuera."],"met":6.0,"uni":false,"img":["banded-sumo-walk-start.webp","banded-sumo-walk-peak.webp"]},{"id":"banded-terminal-knee-extension","n":"Extensión Terminal de Rodilla con Banda","d":"Un ejercicio de aislamiento que extiende la rodilla contra la banda, usado para el VMO y rehabilitación.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"mini banda","home":true,"bw":false,"lv":"principiante","m":["cuádriceps"],"m2":[],"ins":["Ancla una banda elástica a un poste firme a la altura de la rodilla.","Pasa el bucle de modo que la banda quede detrás de una rodilla.","Da un paso atrás para que la banda flexione ligeramente la rodilla.","Extiende la rodilla completamente contra la banda, contrayendo el cuádriceps.","Regresa lentamente. Repeticiones por lado y cambia."],"tips":["Contrae fuerte el cuádriceps en la extensión completa.","Mantén el pie plano — no levantes el talón.","Mueve solo la rodilla — la cadera permanece inmóvil."],"met":5.0,"uni":true,"img":["banded-terminal-knee-extension-start.webp","banded-terminal-knee-extension-peak.webp"]},{"id":"banded-triceps-stretch","n":"Estiramiento de Tríceps con Banda","d":"Un estiramiento de pie que alarga el tríceps llevando una mano tras la cabeza contra la tensión de la banda.","cat":"estiramiento","g":"brazos","bp":"upper_arms","eq":"banda elástica","home":true,"bw":false,"lv":"principiante","m":["tríceps"],"m2":["dorsales"],"ins":["Sujeta una banda que baja por la espalda, con la mano de arriba tras la cabeza.","Fija la mano de abajo en la zona lumbar.","Baja la mano de arriba hasta sentir el tríceps estirarse.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],"tips":["Mantén la cabeza erguida y las costillas abajo.","Relájate y sigue respirando todo el tiempo."],"met":5.0,"uni":true,"img":["banded-triceps-stretch-main.webp"]},{"id":"barbell-ab-rollout","n":"Rueda Abdominal con Barra","d":"Una rueda abdominal de rodillas usando una barra cargada con discos, que ofrece un rodamiento más suave y carga ajustable en comparación con la rueda abdominal.","cat":"fuerza","g":"core","bp":"core","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["abdominales"],"m2":["dorsales","oblicuos","transverso abdominal"],"ins":["Carga discos del mismo tamaño en ambos extremos de la barra y colócala en el suelo.","Arrodíllate detrás de la barra y agárrala a la anchura de los hombros con los brazos extendidos.","Contrae el core con fuerza, luego rueda la barra hacia adelante alejándola del cuerpo.","Avanza hasta donde puedas mantener la columna neutra: detente antes de que las caderas se hundan.","Tira de la barra de vuelta a la posición inicial contrayendo los abdominales y el dorsal.","Repite el número de repeticiones recomendado."],"tips":["Empieza con discos pequeños para un rango limitado; pasa a los de 20 kg para rodamientos completos.","En el momento en que la zona lumbar se arquee o caiga, detente: has superado tu rango."],"met":6.0,"uni":false,"img":["barbell-ab-rollout-start.webp","barbell-ab-rollout-peak.webp"]},{"id":"barbell-bulgarian-split-squat","n":"Sentadilla Búlgara con Barra","d":"Una sentadilla a una pierna con el pie trasero apoyado en un banco y una barra sobre la parte alta de la espalda. La carga pesada y unilateral trabaja los cuádriceps y los glúteos de la pierna delantera y exige equilibrio y movilidad de cadera.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"barra","home":false,"bw":false,"lv":"avanzado","m":["glúteo mayor","cuádriceps"],"m2":["aductores","lumbares","glúteo medio","isquiotibiales"],"ins":["Coloca una barra sobre la parte alta de la espalda y ponte de pie a unos 60 cm de un banco plano, de espaldas a él.","Apoya el empeine de un pie en el banco detrás de ti, con el pie delantero lo bastante adelantado para mantener la espinilla casi vertical al bajar.","Contrae el tronco y baja la rodilla trasera hacia el suelo flexionando la cadera y la rodilla delanteras.","Desciende hasta que el muslo delantero quede aproximadamente paralelo al suelo, manteniendo el pecho erguido.","Empuja con el centro del pie delantero para volver a la posición inicial.","Completa las repeticiones con una pierna y luego cambia."],"tips":["Carga la mayor parte del peso en la pierna delantera; el pie trasero solo está para el equilibrio.","Mantén la rodilla delantera en línea con las puntas de los pies y el torso erguido.","Usa una carga menor que en una sentadilla trasera normal, y prepara la barra y una forma segura de soltarla antes de ponerte en posición."],"met":6.0,"uni":true,"img":["barbell-bulgarian-split-squat-start.webp","barbell-bulgarian-split-squat-peak.webp"]},{"id":"barbell-calf-raise","n":"Elevación de Talones con Barra","d":"Una elevación de talones con barra sobre la espalda realizada en una plataforma, que aísla los gemelos con un rango completo.","cat":"fuerza","g":"piernas","bp":"lower_legs","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["gemelos"],"m2":["sóleo"],"ins":["Coloca una barra en la parte alta de la espalda como en una sentadilla.","Párate con las puntas de los pies en una plataforma elevada.","Sube sobre los dedos de los pies lo más alto posible.","Haz una pausa y aprieta los gemelos en la parte superior.","Baja los talones por debajo de la plataforma y repite."],"tips":["Evita rebotar en la parte baja del movimiento.","Mantén las rodillas extendidas pero sin bloquearlas con fuerza.","Sube y baja en vertical, sin dejar que los tobillos se venzan hacia fuera."],"met":5.0,"uni":false,"img":["barbell-calf-raise-start.webp","barbell-calf-raise-peak.webp"]},{"id":"barbell-curl","n":"Curl con Barra","d":"Un ejercicio clásico de aislamiento de bíceps que usa la barra para una carga máxima.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"barra","home":false,"bw":false,"lv":"principiante","m":["bíceps"],"m2":["braquial","antebrazo"],"ins":["Párate sosteniendo una barra con agarre supino a la anchura de los hombros.","Sube la barra hacia los hombros.","Aprieta en la parte superior, luego baja de forma controlada.","Repite."],"tips":["Evita balancear el torso.","Mantén los codos pegados a los costados."],"met":5.0,"uni":false,"img":["barbell-curl-start.webp","barbell-curl-peak.webp"]},{"id":"barbell-front-raise","n":"Elevación Frontal con Barra","d":"Una elevación frontal con barra que aísla el deltoides anterior al subir el peso con los brazos rectos hasta la altura de los hombros.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["deltoides anterior"],"m2":["deltoides lateral","pectoral","serrato"],"ins":["Párate sosteniendo una barra con agarre prono a la altura de los muslos.","Mantén los brazos extendidos y el core contraído.","Eleva la barra frente a ti hasta la altura de los hombros.","Haz una breve pausa en la parte superior.","Baja de forma controlada y repite."],"tips":["Usa un peso moderado para no balancear el cuerpo.","Evita encoger los hombros mientras subes la barra.","Mantén las muñecas neutras, sin dejar que se doblen hacia atrás."],"met":5.0,"uni":false,"img":["barbell-front-raise-start.webp","barbell-front-raise-peak.webp"]},{"id":"barbell-glute-bridge","n":"Puente de Glúteos con Barra","d":"Un puente de glúteos con carga usando una barra para mayor resistencia.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["glúteo mayor"],"m2":["isquiotibiales"],"ins":["Acuéstate en el suelo con una barra sobre las caderas y las rodillas flexionadas.","Eleva las caderas apretando los glúteos.","Aguanta en la parte superior con las caderas completamente extendidas.","Baja con control.","Repite."],"tips":["Evita arquear la zona lumbar al extender la cadera.","Empuja con los talones, no con las puntas de los pies.","Mete la barbilla y mantén la parte alta de la espalda apoyada."],"met":6.0,"uni":false,"img":["barbell-glute-bridge-start.webp","barbell-glute-bridge-peak.webp"]},{"id":"barbell-lunge","n":"Zancada con Barra","d":"Una zancada hacia delante con la barra sobre la parte alta de la espalda, entrenando cuádriceps y glúteos una pierna a la vez.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["glúteo mayor","cuádriceps"],"m2":["lumbares","glúteo medio","isquiotibiales"],"ins":["Coloca una barra en la parte alta de la espalda y párate erguido.","Da un paso adelante con una pierna en una zancada larga.","Baja la rodilla trasera hacia el suelo hasta que el muslo delantero quede paralelo.","Impulsa a través del talón delantero para volver a la posición inicial.","Completa las repeticiones de un lado, luego cambia."],"tips":["Da una zancada lo bastante larga para que la rodilla delantera quede sobre el tobillo.","Mantén el torso erguido y el core contraído bajo la barra.","Empuja el suelo con el talón delantero, no con los dedos."],"met":6.0,"uni":true,"img":["barbell-lunge-start.webp","barbell-lunge-peak.webp"]},{"id":"barbell-overhead-extension","n":"Extensión de Barra por Encima de la Cabeza","d":"Este ejercicio de aislamiento trabaja eficazmente el tríceps braquial al extender los codos por encima de la cabeza, promoviendo la hipertrofia y fuerza muscular.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["tríceps"],"m2":[],"ins":["Carga una barra con el peso adecuado y ponte de pie o siéntate con la columna neutra.","Agarra la barra con un agarre prono, al ancho de los hombros, y presiónala por encima de tu cabeza.","Baja lentamente la barra detrás de tu cabeza flexionando los codos, manteniendo los brazos estables.","Extiende los codos para presionar la barra de vuelta a la posición inicial por encima de la cabeza, contrayendo tus tríceps.","Mantén el control durante todo el movimiento, evitando el impulso."],"tips":["Mantén los codos pegados y apuntando hacia adelante para maximizar la activación del tríceps y proteger tus hombros.","Controla la fase excéntrica (descenso) para mejorar la tensión muscular y el crecimiento.","Evita arquear demasiado la espalda baja; contrae tu core para mantener la estabilidad."],"met":5.0,"uni":false,"img":["barbell-overhead-extension-start.webp","barbell-overhead-extension-peak.webp"]},{"id":"barbell-preacher-curl","n":"Curl Predicador con Barra","d":"Este ejercicio de aislamiento trabaja el bíceps braquial y el braquial al fijar los brazos en un banco predicador, minimizando el impulso y maximizando la tensión muscular.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["bíceps"],"m2":["braquial"],"ins":["Siéntate en un banco predicador con el pecho contra la almohadilla, sujetando una barra con agarre supino al ancho de los hombros.","Apoya firmemente tus brazos en la almohadilla, asegurándote de que tus codos estén ligeramente flexionados al inicio.","Sube la barra contrayendo tus bíceps, manteniendo tus brazos inmóviles sobre la almohadilla.","Aprieta los bíceps en la parte superior del movimiento, enfocándote en la contracción máxima.","Baja lentamente la barra a la posición inicial, controlando la fase excéntrica.","Baja hasta que los brazos estén casi completamente extendidos para lograr un estiramiento completo del bíceps."],"tips":["Mantén una tensión constante en los bíceps durante todo el rango de movimiento.","Evita levantar los codos de la almohadilla; esto indica que estás usando demasiado peso o impulso.","Baja la barra despacio y con control; la posición estirada de abajo es donde los codos están más expuestos.","Mantén tus muñecas rectas y alineadas con tus antebrazos para prevenir tensiones."],"met":5.0,"uni":false,"img":["barbell-preacher-curl-start.webp","barbell-preacher-curl-peak.webp"]},{"id":"barbell-pullover","n":"Pullover con Barra","d":"Un movimiento compuesto que estira y trabaja el dorsal y el pectoral a través de un arco amplio.","cat":"fuerza","g":"espalda","bp":"back","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["dorsales","pectoral"],"m2":["tríceps"],"ins":["Acuéstate en un banco con una barra sostenida sobre el pecho.","Baja la barra hacia atrás sobre tu cabeza en un arco.","Tírala de vuelta al inicio sobre el pecho.","Repite."],"tips":["Mantén una ligera flexión en los codos.","Activa el dorsal para impulsar la barra de vuelta."],"met":6.0,"uni":false,"img":["barbell-pullover-start.webp","barbell-pullover-peak.webp"]},{"id":"barbell-rear-delt-row","n":"Remo con Barra para Deltoides Posterior","d":"Un remo con barra inclinado con los codos abiertos que traslada el énfasis de los dorsales a los deltoides posteriores y la parte alta de la espalda.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["deltoides posterior"],"m2":["dorsales","romboides","trapecio"],"ins":["Inclínate en las caderas con la espalda plana hasta que el torso quede casi paralelo al suelo.","Sostén una barra con agarre prono, más ancho que la anchura de los hombros, brazos colgando.","Rema la barra hacia el pecho superior con los codos abiertos hacia los lados.","Haz una pausa y aprieta los deltoides posteriores y la parte alta de la espalda en la cima.","Baja la barra de forma controlada y repite."],"tips":["Jala con los codos, no con las manos: piensa en impulsarlos hacia arriba y hacia afuera.","Usa una carga menor que en un remo estándar; el agarre ancho reduce el brazo de palanca."],"met":6.0,"uni":false,"img":["barbell-rear-delt-row-start.webp","barbell-rear-delt-row-peak.webp"]},{"id":"barbell-reverse-lunge","n":"Zancada Inversa con Barra","d":"Una zancada con barra dando el paso hacia atrás en lugar de hacia delante, manteniendo la tibia delantera vertical mientras carga cuádriceps y glúteos.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["glúteo mayor","cuádriceps"],"m2":["lumbares","glúteo medio","isquiotibiales"],"ins":["Coloca una barra en la parte alta de la espalda y párate erguido.","Da un paso hacia atrás con un pie en una zancada larga.","Baja la rodilla trasera hacia el suelo de forma controlada.","Impulsa a través del talón delantero para volver a la posición inicial.","Completa las repeticiones de un lado, luego cambia."],"tips":["Da el paso atrás lo bastante largo para que la tibia delantera quede casi vertical.","Baja la rodilla trasera en línea recta en lugar de inclinarte hacia delante.","Mantén el pecho erguido y las caderas alineadas."],"met":6.0,"uni":true,"img":["barbell-reverse-lunge-start.webp","barbell-reverse-lunge-peak.webp"]},{"id":"barbell-row","n":"Remo con Barra Inclinado","d":"Un movimiento de jalón compuesto que trabaja la parte superior e intermedia de la espalda.","cat":"fuerza","g":"espalda","bp":"back","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["dorsales","romboides"],"m2":["bíceps","deltoides posterior"],"ins":["Inclínate en las caderas con una ligera flexión de rodillas.","Agarra la barra ligeramente más ancho que la anchura de los hombros.","Tira de la barra hacia el pecho inferior apretando los omóplatos.","Baja la barra de forma controlada.","Repite."],"tips":["Mantén el torso a aproximadamente 45 grados.","No uses el impulso para balancear el peso."],"met":6.0,"uni":false,"img":["barbell-row-start.webp","barbell-row-peak.webp"]},{"id":"barbell-wrist-curl","n":"Curl de Muñeca con Barra","d":"Un curl de muñeca con barra que aísla los flexores del antebrazo para fuerza de agarre y tamaño.","cat":"fuerza","g":"brazos","bp":"lower_arms","eq":"barra","home":false,"bw":false,"lv":"principiante","m":["antebrazo"],"m2":[],"ins":["Siéntate en un banco con los antebrazos sobre los muslos, palmas hacia arriba.","Sujeta una barra con las manos a la anchura de los hombros, muñecas fuera de las rodillas.","Deja que la barra ruede hasta las puntas de los dedos.","Sube la barra flexionando las muñecas.","Baja con control."],"tips":["Mueve solo la muñeca — los antebrazos permanecen quietos.","Rueda la barra a las puntas de los dedos para el rango completo.","Usa un agarre sin pulgar si te resulta más cómodo."],"met":5.0,"uni":false,"img":["barbell-wrist-curl-start.webp","barbell-wrist-curl-peak.webp"]},{"id":"battle-rope-double-slam","n":"Golpe Doble con Cuerdas de Batalla","d":"Un ejercicio de acondicionamiento en el que ambos extremos de la cuerda suben y se golpean contra el suelo a la vez, generando una gran onda por repetición en lugar de las ondas alternas del ejercicio clásico.","cat":"cardio","g":"cuerpo completo","bp":"full_body","eq":"cuerdas de batalla","home":false,"bw":false,"lv":"intermedio","m":["deltoides anterior","dorsales"],"m2":["antebrazo","glúteo mayor","oblicuos","cuádriceps","abdominales","trapecio"],"ins":["Toma un extremo de la cuerda en cada mano y colócate frente al anclaje, lo bastante atrás como para que las cuerdas queden algo destensadas.","Separa los pies algo más que la anchura de las caderas y baja a una sentadilla de cuarto, con el pecho alto.","Sube ambos brazos a la vez, dejando que las cuerdas se eleven por delante mientras extiendes la cadera.","Golpea ambos extremos contra el suelo al mismo tiempo, flexionando por la cadera y empujando desde los dorsales.","Aprovecha el rebote para encadenar el siguiente golpe, manteniendo ambos brazos al unísono en lugar de alternarlos.","Sigue golpeando el tiempo o las repeticiones deseadas."],"tips":["Los dos brazos se mueven juntos — en cuanto empiezan a alternarse estás haciendo el ejercicio de ondas clásico, que es otro ejercicio distinto.","Impulsa el golpe con la cadera y los dorsales en vez de con los brazos, o los hombros se agotarán mucho antes que los pulmones.","Colócate a la distancia correcta del anclaje: demasiado cerca la cuerda queda floja, demasiado lejos no consigues meterle onda."],"met":10.3,"uni":false,"img":["battle-rope-double-slam-start.webp","battle-rope-double-slam-peak.webp"]},{"id":"battle-ropes","n":"Cuerdas de Batalla","d":"Un ejercicio de acondicionamiento de alta intensidad con cuerdas gruesas, trabaja espalda alta, hombros y agarre.","cat":"cardio","g":"cuerpo completo","bp":"full_body","eq":"cuerdas de batalla","home":false,"bw":false,"lv":"intermedio","m":["deltoides anterior","deltoides lateral","dorsales"],"m2":["antebrazo","cuádriceps","abdominales","trapecio"],"ins":["Ancla las cuerdas a un punto fijo y agarra un extremo en cada mano.","Da unos pasos atrás para que las cuerdas tengan tensión moderada.","Baja a una media sentadilla con los pies a la anchura de los hombros.","Mueve cada brazo arriba y abajo rápidamente generando ondas en las cuerdas.","Continúa durante el intervalo de trabajo indicado."],"tips":["Permanece en media sentadilla todo el intervalo.","Genera fuerza desde piernas y caderas, no solo desde los brazos.","Mantén las ondas constantes y compactas."],"met":10.3,"uni":false,"img":["battle-ropes-main.webp"]},{"id":"bear-crawl","n":"Caminata del Oso","d":"Un gateo en cuadrupedia sobre manos y puntas de los pies con las rodillas suspendidas justo por encima del suelo, que desarrolla la estabilidad del hombro y el control del core al desplazarse hacia adelante.","cat":"fuerza","g":"cuerpo completo","bp":"full_body","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["deltoides anterior","abdominales"],"m2":["oblicuos","cuádriceps","tríceps"],"ins":["Empieza en cuadrupedia con las manos bajo los hombros y las rodillas bajo las caderas.","Apoya las puntas de los pies y eleva las rodillas unos centímetros del suelo.","Con la espalda plana y las caderas bajas, avanza juntos la mano derecha y el pie izquierdo.","Luego mueve la mano izquierda y el pie derecho, gateando hacia adelante con ritmo controlado.","Mantén el core firme y evita que las caderas se balanceen de lado a lado."],"tips":["Mueve juntos la mano y el pie opuestos, como un gateo exagerado.","Mantén las rodillas bajas y las caderas niveladas: que no suban ni se balanceen."],"met":5.0,"uni":false,"img":["bear-crawl-start.webp","bear-crawl-peak.webp"]},{"id":"bear-plank-hold","n":"Plancha del Oso Isométrica","d":"Un mantenimiento estático de core a cuatro apoyos en el que las rodillas flotan justo encima del suelo mientras la espalda permanece plana. Entrena el abdomen y los hombros para estabilizar el tronco y es un paso previo a la plancha completa.","cat":"fuerza","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["abdominales","transverso abdominal"],"m2":["deltoides anterior","oblicuos","cuádriceps","serrato"],"ins":["Colócate a cuatro apoyos con las manos bajo los hombros y las rodillas bajo la cadera.","Apoya las puntas de los pies en el suelo y contrae el abdomen para que la espalda quede plana.","Empuja con las manos y levanta las rodillas unos 5 cm del suelo.","Mantén la posición con la cadera nivelada y la cabeza alineada con la columna.","Respira con regularidad y luego baja las rodillas para descansar."],"tips":["Mantén las rodillas cerca del suelo; si las subes más, el ejercicio se convierte en una pica.","Separa los dedos de las manos y empuja el suelo para que los hombros no se hundan.","Mantén el cuello largo y mira al suelo, un poco por delante de las manos."],"met":5.0,"uni":false,"img":["bear-plank-hold-main.webp"]},{"id":"behind-the-back-barbell-shrug","n":"Encogimiento de Hombros con Barra Detrás de la Espalda","d":"Un encogimiento de hombros con la barra sujeta por detrás del cuerpo, una variante que concentra el trabajo en el trapecio.","cat":"fuerza","g":"espalda","bp":"back","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["trapecio"],"m2":["antebrazo","romboides"],"ins":["Párate sosteniendo una barra detrás de la espalda con agarre prono.","Mantén los brazos extendidos y el pecho hacia arriba.","Encoge los hombros directamente hacia las orejas.","Haz una pausa y aprieta en la parte superior.","Baja de forma controlada y repite."],"tips":["Evita hacer círculos con los hombros al subir.","Mantén la cabeza neutra, sin adelantar la barbilla.","Elige un peso que permita un recorrido completo hacia arriba."],"met":5.0,"uni":false,"img":["behind-the-back-barbell-shrug-start.webp","behind-the-back-barbell-shrug-peak.webp"]},{"id":"behind-the-neck-lat-pulldown","n":"Jalón al Cuello Detrás de la Cabeza","d":"Un jalón al dorsal con agarre ancho llevado detrás de la cabeza, que trabaja la parte superior del dorsal y los trapecios: requiere movilidad de hombro completa sobre la cabeza.","cat":"fuerza","g":"espalda","bp":"back","eq":"polea al pecho","home":false,"bw":false,"lv":"avanzado","m":["dorsales"],"m2":["deltoides posterior","romboides","trapecio"],"ins":["Siéntate en la máquina de jalón con los muslos asegurados bajo el pad.","Agarra la barra con un agarre ancho prono, más ancho que la anchura de los hombros.","Mantén el torso erguido e inclina la barbilla ligeramente hacia adelante.","Tira de la barra hacia abajo detrás de la cabeza hasta que toque la base del cuello.","Vuelve de forma controlada al estiramiento completo sobre la cabeza.","Repite el número de repeticiones recomendado."],"tips":["Solo realiza este ejercicio si tienes movilidad de hombro completa y sin dolor sobre la cabeza.","Usa una carga moderada: no es un levantamiento de fuerza, es un accesorio de hipertrofia."],"met":6.0,"uni":false,"img":["behind-the-neck-lat-pulldown-start.webp","behind-the-neck-lat-pulldown-peak.webp"]},{"id":"behind-the-neck-press","n":"Press Detrás del Cuello","d":"Un press vertical con barra realizado por detrás de la nuca, dirigido al deltoides anterior y lateral.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["deltoides anterior","deltoides lateral"],"m2":["trapecio","tríceps"],"ins":["Siéntate o párate con una barra descansando en la parte alta de los trapecios detrás del cuello.","Agarra la barra más ancho que la anchura de los hombros.","Empuja la barra directamente sobre la cabeza hasta que los brazos estén extendidos.","Baja la barra de vuelta a la posición inicial de forma controlada.","Repite el número de repeticiones deseado."],"tips":["Trabaja primero la movilidad de hombros si la posición resulta incómoda.","Baja la barra solo hasta donde tu rango lo permita.","Mantén el core firme para no arquear la zona lumbar."],"met":6.0,"uni":false,"img":["behind-the-neck-press-start.webp","behind-the-neck-press-peak.webp"]},{"id":"behind-the-neck-pull-ups","n":"Dominada tras nuca","d":"Una dominada con agarre ancho en la que se tira lo suficientemente alto como para que la barra pase por detrás de la cabeza en lugar de por debajo de la barbilla, lo que obliga a los hombros a llegar al final de su rotación externa.","cat":"fuerza","g":"espalda","bp":"back","eq":"barra de dominadas","home":true,"bw":false,"lv":"avanzado","m":["dorsales"],"m2":["bíceps","deltoides posterior","romboides","trapecio"],"ins":["Sujeta la barra de dominadas en pronación, con las manos más separadas que los hombros, y cuélgate con los brazos extendidos y las piernas juntas.","Mantén el torso vertical en lugar de inclinarte hacia atrás y tira de los codos hacia abajo y hacia los lados.","Sigue tirando hasta que la barra pase por detrás de la cabeza y la nuca quede a su altura, sin que la barra llegue a tocarte el cuello.","Baja de forma controlada hasta la suspensión completa, manteniendo la cabeza quieta en lugar de dejar que se desplace hacia adelante.","Repite el número de repeticiones deseado."],"tips":["Esta variante está desaconsejada de forma generalizada. Terminar por detrás de la cabeza carga el hombro en el final de su rotación externa, donde la articulación tiene menos capacidad de protegerse, y cualquier contacto entre la barra y el cuello transmite esa carga a la columna cervical.","Una dominada normal o con agarre ancho trabaja los mismos músculos en el mismo rango de movimiento del hombro: nada en el desarrollo de la espalda exige que la barra pase por detrás de la cabeza, así que no hay ningún beneficio que compense el riesgo.","Si aun así la haces, detente bastante antes de que la barra toque el cuello, y descártala por completo si no tienes movilidad de hombro completa y sin dolor por encima de la cabeza o si tienes antecedentes de problemas de hombro o cuello."],"met":6.0,"uni":false,"img":["behind-the-neck-pull-ups-start.webp","behind-the-neck-pull-ups-peak.webp"]},{"id":"bench-adductor-stretch","n":"Estiramiento de Aductores en Banco","d":"Un estiramiento de pie con una pierna estirada apoyada en el banco hacia el lado para alargar el aductor.","cat":"estiramiento","g":"piernas","bp":"upper_legs","eq":"banco plano","home":false,"bw":false,"lv":"principiante","m":["aductores"],"m2":["isquiotibiales"],"ins":["Ponte de lado al banco.","Apoya una pierna estirada sobre el banco hacia el lado.","Mantén el torso erguido y desplázate suavemente hacia el banco.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],"tips":["Mantén ambas piernas estiradas.","Mantén el pie de apoyo apuntando al frente."],"met":5.0,"uni":true,"img":["bench-adductor-stretch-main.webp"]},{"id":"bench-ankle-stretch","n":"Estiramiento de Tobillo en Banco","d":"Un estiramiento de pie con el pie plano en el banco, llevando la rodilla por delante de los dedos para flexionar el tobillo.","cat":"estiramiento","g":"piernas","bp":"lower_legs","eq":"banco plano","home":false,"bw":false,"lv":"principiante","m":["gemelos"],"m2":["sóleo"],"ins":["Coloca un pie entero plano sobre el banco.","Mantén el torso erguido.","Lleva esa rodilla hacia adelante por encima de los dedos.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],"tips":["Mantén el talón apoyado en el banco.","Muévete despacio y mantén el pie plano."],"met":5.0,"uni":true,"img":["bench-ankle-stretch-main.webp"]},{"id":"bench-bulgarian-split-stretch","n":"Estiramiento Búlgaro en Banco","d":"Un estiramiento en zancada con el pie trasero en un banco, bajando la cadera para abrir los flexores de cadera y el cuádriceps.","cat":"estiramiento","g":"piernas","bp":"upper_legs","eq":"banco plano","home":false,"bw":false,"lv":"principiante","m":["flexores de cadera","cuádriceps"],"m2":["glúteo mayor"],"ins":["Apoya el empeine del pie trasero en un banco detrás de ti.","Coloca el pie delantero plano y flexiona esa rodilla.","Baja la cadera recto hacia abajo.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],"tips":["Apóyate en una pared si lo necesitas.","Mantén el torso erguido."],"met":5.0,"uni":true,"img":["bench-bulgarian-split-stretch-main.webp"]},{"id":"bench-calf-stretch","n":"Estiramiento de Pantorrilla en Banco","d":"Un estiramiento de pie con la planta del pie en el borde del banco, dejando caer el talón para alargar la pantorrilla.","cat":"estiramiento","g":"piernas","bp":"lower_legs","eq":"banco plano","home":false,"bw":false,"lv":"principiante","m":["gemelos"],"m2":["sóleo"],"ins":["Coloca la planta de un pie en el borde del banco.","Mantén esa rodilla estirada.","Deja caer el talón por debajo de los dedos.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],"tips":["Sujétate del banco o de una pared para equilibrarte.","Mantén el movimiento lento y controlado."],"met":5.0,"uni":true,"img":["bench-calf-stretch-main.webp"]},{"id":"bench-chest-stretch","n":"Estiramiento de Pecho en Banco","d":"Un estiramiento de rodillas con las manos detrás en el banco, bajando la cadera para abrir el pecho y los hombros.","cat":"estiramiento","g":"pecho","bp":"chest","eq":"banco plano","home":false,"bw":false,"lv":"principiante","m":["pectoral"],"m2":["deltoides anterior"],"ins":["Arrodíllate de espaldas al banco.","Coloca ambas manos detrás en el borde del banco.","Baja la cadera para abrir el pecho.","Mantén de 20 a 30 segundos, respirando de forma constante."],"tips":["Mantén los hombros abajo, lejos de las orejas.","Estira hasta una tensión leve, nunca hasta el dolor."],"met":5.0,"uni":false,"img":["bench-chest-stretch-main.webp"]},{"id":"bench-childs-pose","n":"Postura del Niño en Banco","d":"Un estiramiento de rodillas con los brazos sobre el banco, llevando la cadera atrás para alargar los dorsales y la zona lumbar.","cat":"estiramiento","g":"espalda","bp":"back","eq":"banco plano","home":false,"bw":false,"lv":"principiante","m":["lumbares","dorsales"],"m2":[],"ins":["Arrodíllate en el suelo frente a un banco.","Extiende ambos brazos al frente y apóyalos en el banco.","Lleva la cadera hacia los talones y deja caer el pecho.","Mantén de 20 a 30 segundos, respirando de forma constante."],"tips":["Mantén los brazos estirados y relaja el cuello.","Relájate y sigue respirando todo el tiempo."],"met":5.0,"uni":false,"img":["bench-childs-pose-main.webp"]},{"id":"bench-couch-stretch","n":"Estiramiento Couch en Banco","d":"Un estiramiento profundo de cuádriceps y flexores de cadera con la espinilla trasera apoyada en el frente del banco.","cat":"estiramiento","g":"piernas","bp":"upper_legs","eq":"banco plano","home":false,"bw":false,"lv":"principiante","m":["flexores de cadera","cuádriceps"],"m2":[],"ins":["Arrodíllate con la espinilla trasera contra el frente del banco.","Coloca el pie delantero plano en el suelo.","Lleva el torso erguido hasta que se estire el frente del muslo.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],"tips":["Aprieta el glúteo trasero para proteger la zona lumbar.","Acolcha la rodilla trasera con un cojín."],"met":5.0,"uni":true,"img":["bench-couch-stretch-main.webp"]},{"id":"bench-dips","n":"Fondos en Banco","d":"Un ejercicio de fondos apoyado en un banco que trabaja principalmente el tríceps con el propio peso corporal.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["tríceps"],"m2":["deltoides anterior","pectoral"],"ins":["Siéntate en un banco y coloca las manos en el borde junto a las caderas.","Desliza las caderas fuera del banco con las piernas extendidas.","Baja el cuerpo flexionando los codos hasta 90 grados.","Empuja con las palmas para volver a la posición inicial.","Repite el número de repeticiones deseado."],"tips":["Mantén la espalda cerca del banco durante todo el recorrido.","No dejes que los hombros se hundan hacia las orejas.","Flexiona las rodillas si necesitas una versión más fácil."],"met":5.0,"uni":false,"img":["bench-dips-start.webp","bench-dips-peak.webp"]},{"id":"bench-figure-4-glute-stretch","n":"Estiramiento Figura 4 de Glúteos en Banco","d":"Un estiramiento sentado en banco con un tobillo cruzado sobre la rodilla, inclinándose para trabajar el glúteo.","cat":"estiramiento","g":"piernas","bp":"upper_legs","eq":"banco plano","home":false,"bw":false,"lv":"principiante","m":["glúteo mayor"],"m2":["glúteo medio"],"ins":["Siéntate en el extremo de un banco.","Cruza un tobillo sobre la rodilla opuesta.","Mantén la espalda recta e inclínate sobre la pierna cruzada.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],"tips":["Deja que la rodilla cruzada caiga hacia afuera.","Inclínate desde las caderas, manteniendo el pecho abierto."],"met":5.0,"uni":true,"img":["bench-figure-4-glute-stretch-main.webp"]},{"id":"bench-hamstring-stretch","n":"Estiramiento de Isquiotibiales en Banco","d":"Un estiramiento de pie con el talón en un banco, inclinándose sobre la pierna estirada para alargar el isquiotibial.","cat":"estiramiento","g":"piernas","bp":"upper_legs","eq":"banco plano","home":false,"bw":false,"lv":"principiante","m":["isquiotibiales"],"m2":["lumbares"],"ins":["Coloca un talón en el banco con esa pierna estirada.","Mantente erguido sobre la pierna de apoyo.","Inclínate desde las caderas sobre la pierna elevada.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],"tips":["Mantén la espalda recta al inclinarte.","Mantén la pierna elevada recta, con los dedos arriba."],"met":5.0,"uni":true,"img":["bench-hamstring-stretch-main.webp"]},{"id":"bench-hollow-hold","n":"Mantenimiento del Cuerpo Hueco en Banco","d":"Un mantenimiento estático de core hecho tumbado en un banco plano: los brazos se estiran por encima de la cabeza y los hombros y las piernas rectas se elevan hasta formar una curva hueca poco profunda, mientras la zona lumbar permanece pegada al banco.","cat":"fuerza","g":"core","bp":"core","eq":"banco plano","home":false,"bw":false,"lv":"intermedio","m":["flexores de cadera","abdominales"],"m2":["oblicuos","cuádriceps","transverso abdominal"],"ins":["Túmbate boca arriba en un banco plano con los glúteos y la zona lumbar sobre el pad y las piernas extendidas.","Estira los brazos por encima de la cabeza, junto a las orejas.","Contrae el abdomen y presiona la zona lumbar contra el banco.","Levanta los hombros y las piernas rectas unos pocos centímetros para formar un hueco poco profundo.","Mantén la posición respirando con regularidad y luego baja para descansar."],"tips":["Si la zona lumbar se despega del pad, sube más las piernas o flexiona ligeramente las rodillas.","Mantén las costillas hacia abajo y el cuello relajado.","Aguanta solo el tiempo en que puedas mantener la zona lumbar plana."],"met":6.0,"uni":false,"img":["bench-hollow-hold-main.webp"]},{"id":"bench-lat-stretch","n":"Estiramiento de Dorsales en Banco","d":"Un estiramiento de rodillas con las manos en el banco, hundiendo el pecho hacia el suelo para alargar los dorsales.","cat":"estiramiento","g":"espalda","bp":"back","eq":"banco plano","home":false,"bw":false,"lv":"principiante","m":["dorsales"],"m2":["deltoides posterior"],"ins":["Arrodíllate en el suelo frente a un banco.","Coloca ambas manos sobre el banco.","Lleva la cadera atrás y deja caer el pecho.","Mantén de 20 a 30 segundos, respirando de forma constante."],"tips":["Mantén los brazos estirados y la cabeza entre ellos.","Relájate y sigue respirando todo el tiempo."],"met":5.0,"uni":false,"img":["bench-lat-stretch-main.webp"]},{"id":"bench-leg-pull-in","n":"Encogimiento de Piernas en Banco","d":"Un ejercicio de core en decúbito supino sobre un banco plano que trabaja el recto abdominal llevando las rodillas hacia el pecho.","cat":"fuerza","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["abdominales"],"m2":["flexores de cadera","oblicuos"],"ins":["Túmbate boca arriba sobre un banco plano y agárrate a los lados por encima de la cabeza.","Extiende las piernas rectas con los talones justo por encima de la superficie del banco.","Lleva las rodillas hacia el pecho levantando ligeramente las caderas del banco.","Devuelve las piernas a la posición extendida de forma controlada sin apoyar los talones.","Repite el número de repeticiones indicado."],"tips":["Presiona la zona lumbar contra el banco para reducir la participación del psoas.","Controla la fase excéntrica; no dejes que la gravedad baje las piernas sin control.","Contrae el abdomen en el punto más alto de cada repetición."],"met":3.5,"uni":false,"img":["bench-leg-pull-in-start.webp","bench-leg-pull-in-peak.webp"]},{"id":"bench-press","n":"Press de Banca con Barra","d":"Un movimiento compuesto de empuje que trabaja el pecho, los hombros y los tríceps.","cat":"fuerza","g":"pecho","bp":"chest","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["pectoral"],"m2":["deltoides anterior","tríceps"],"ins":["Acuéstate en el banco con los ojos bajo la barra.","Agarra la barra ligeramente más ancho que la anchura de los hombros.","Saca la barra del rack y bájala hasta el centro del pecho.","Empuja la barra de vuelta hasta la extensión completa de los brazos.","Repite el número de repeticiones deseado."],"tips":["Mantén los pies planos en el suelo.","Conserva una ligera curvatura en la zona lumbar.","Impulsa con las piernas para dar estabilidad."],"met":6.0,"uni":false,"img":["bench-press-start.webp","bench-press-peak.webp"]},{"id":"bench-pull","n":"Remo en Banco","d":"Un remo tumbado boca abajo sobre un banco elevado que centra el trabajo en la espalda al apoyar el torso.","cat":"fuerza","g":"espalda","bp":"back","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["dorsales","romboides"],"m2":["bíceps","deltoides posterior","trapecio"],"ins":["Acuéstate boca abajo en un banco elevado con los brazos colgando rectos hacia abajo.","Agarra una barra o mancuernas debajo de ti.","Rema el peso hasta la parte inferior del banco.","Aprieta los omóplatos en la parte superior.","Baja de forma controlada y repite."],"tips":["Mantén el pecho pegado al banco durante toda la serie.","Tira con los codos en lugar de con las manos.","Evita los tirones bruscos al iniciar cada repetición."],"met":6.0,"uni":false,"img":["bench-pull-start.webp","bench-pull-peak.webp"]},{"id":"bent-arm-barbell-pullover","n":"Pullover con Barra y Brazos Flexionados","d":"Un pullover con barra y codos flexionados que lleva el peso por detrás de la cabeza para trabajar dorsales y pectoral.","cat":"fuerza","g":"espalda","bp":"back","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["dorsales","pectoral"],"m2":["serrato","tríceps"],"ins":["Acuéstate en un banco sosteniendo una barra sobre el pecho con los codos flexionados.","Mantén los codos flexionados durante todo el movimiento.","Baja la barra detrás de la cabeza en un arco.","Tira de la barra de vuelta sobre el pecho usando el dorsal.","Repite el número de repeticiones deseado."],"tips":["Mantén la cadera y la zona lumbar en contacto con el banco.","Baja solo hasta donde notes un estiramiento cómodo.","Empieza con un peso ligero hasta dominar la trayectoria."],"met":5.0,"uni":false,"img":["bent-arm-barbell-pullover-start.webp","bent-arm-barbell-pullover-peak.webp"]},{"id":"bent-arm-ez-bar-pullover","n":"Pullover con Barra Z y Brazos Flexionados","d":"Un pullover con brazos flexionados en un banco plano usando una barra Z, más amigable para las muñecas que la versión con barra recta, manteniendo el estiramiento profundo del dorsal y el pectoral.","cat":"fuerza","g":"espalda","bp":"back","eq":"barra Z","home":false,"bw":false,"lv":"intermedio","m":["dorsales","pectoral"],"m2":["deltoides posterior","serrato","tríceps"],"ins":["Acuéstate en un banco plano sosteniendo una barra Z con un agarre prono estrecho en las curvas internas.","Comienza con la barra sobre el pecho, codos flexionados a aproximadamente 90 grados.","Mantén el ángulo de los codos fijo y baja la barra en un arco sobre la cabeza hasta sentir un estiramiento profundo en el dorsal y el pectoral.","Tira de la barra de vuelta sobre el pecho por el mismo arco, sin extender los codos.","Repite el número de repeticiones recomendado."],"tips":["El ángulo de los codos permanece fijo: solo se mueve el hombro.","Carga menor que en un pullover con brazos extendidos: el rango es mayor y el brazo de palanca es menor.","Si la zona lumbar se arquea, planta los pies con más firmeza y aprieta el abdomen."],"met":6.0,"uni":false,"img":["bent-arm-ez-bar-pullover-start.webp","bent-arm-ez-bar-pullover-peak.webp"]},{"id":"bent-over-db-row","n":"Remo con Mancuernas Inclinado","d":"Un remo inclinado a dos brazos con una mancuerna en cada mano, que trabaja la espalda y exige estabilidad.","cat":"fuerza","g":"espalda","bp":"back","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["dorsales","romboides"],"m2":["bíceps","deltoides posterior","trapecio"],"ins":["Ponte de pie con los pies a la anchura de las caderas, sujetando una mancuerna en cada mano a los lados, con las palmas hacia dentro.","Flexiona las caderas con la espalda recta hasta que el torso quede a unos 30–45 grados de la horizontal, con las mancuernas colgando justo debajo de los hombros.","Activa el core y tira de ambas mancuernas hacia arriba y ligeramente atrás, llevando los codos por detrás de las costillas.","Aprieta la parte alta de la espalda arriba, manteniendo los codos pegados.","Baja de forma controlada hasta la posición inicial con los brazos completamente estirados.","Repite el número de repeticiones recomendado."],"tips":["El ángulo del torso se mantiene fijo todo el rato; no te incorpores para ayudar al peso.","Tira hacia las costillas bajas o el abdomen, no hacia el pecho; así mantienes el dorsal cargado.","Si la lumbar se redondea, flexiona menos y recoloca antes de la siguiente serie."],"met":6.0,"uni":false,"img":["bent-over-db-row-start.webp","bent-over-db-row-peak.webp"]},{"id":"bent-over-ez-bar-row","n":"Remo con Barra Z Inclinado","d":"Un movimiento de jalón horizontal con barra Z para un ejercicio de remo de espalda amigable con las muñecas.","cat":"fuerza","g":"espalda","bp":"back","eq":"barra Z","home":false,"bw":false,"lv":"intermedio","m":["dorsales","romboides"],"m2":["bíceps","deltoides posterior"],"ins":["Sostén una barra Z con agarre prono e inclínate en las caderas a 45 grados.","Tira de la barra hacia la parte inferior de las costillas.","Baja de forma controlada.","Repite."],"tips":["Mantén la espalda plana durante todo el movimiento.","Inicia el movimiento con los codos, no con las manos."],"met":6.0,"uni":false,"img":["bent-over-ez-bar-row-start.webp","bent-over-ez-bar-row-peak.webp"]},{"id":"bicep-curl","n":"Curl de Bíceps con Mancuernas","d":"Un ejercicio de aislamiento que trabaja los bíceps.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"mancuernas","home":true,"bw":false,"lv":"principiante","m":["bíceps"],"m2":["braquial","antebrazo"],"ins":["Párate sosteniendo mancuernas a los lados, palmas hacia adelante.","Sube las mancuernas hacia los hombros.","Aprieta en la parte superior, luego baja de forma controlada.","Repite."],"tips":["Mantén los codos pegados a los costados.","Evita balancear las mancuernas."],"met":5.0,"uni":false,"img":["bicep-curl-start.webp","bicep-curl-peak.webp"]},{"id":"bicycle-crunch","n":"Crunch de Bicicleta","d":"Una variación dinámica del crunch que trabaja tanto el recto abdominal como los oblicuos.","cat":"fuerza","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["oblicuos","abdominales"],"m2":["flexores de cadera"],"ins":["Acuéstate boca arriba con las manos detrás de la cabeza y las piernas elevadas.","Acerca una rodilla al pecho mientras rotas el torso para encontrarla con el codo opuesto.","Extiende esa pierna mientras traes la otra rodilla hacia adentro.","Continúa alternando en un movimiento de pedaleo.","Repite."],"tips":["No tires del cuello con las manos.","Lleva el hombro hacia la rodilla, no solo el codo.","Mantén la zona lumbar apoyada en el suelo."],"met":5.0,"uni":false,"img":["bicycle-crunch-start.webp","bicycle-crunch-peak.webp"]},{"id":"bird-dog","n":"Bird-Dog","d":"Un ejercicio de estabilidad del core que extiende el brazo y la pierna opuestos para trabajar los erectores espinales y el core profundo.","cat":"fuerza","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["lumbares","transverso abdominal"],"m2":["glúteo mayor"],"ins":["Comienza a cuatro patas con la columna en posición neutra.","Extiende el brazo derecho hacia adelante y la pierna izquierda hacia atrás simultáneamente.","Aguanta un momento, luego vuelve.","Repite en el otro lado.","Alterna."],"tips":["Muévete lentamente y con control.","Mantén las caderas niveladas en todo momento."],"met":5.0,"uni":false,"img":["bird-dog-start.webp","bird-dog-peak.webp"]},{"id":"bird-dog-hold","n":"Bird-Dog Isométrico","d":"Un ejercicio isométrico de core a cuatro patas que extiende un brazo y la pierna contraria manteniendo la columna estable.","cat":"fuerza","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["lumbares","abdominales"],"m2":["glúteo mayor","oblicuos","deltoides posterior"],"ins":["Comienza a cuatro patas con las manos bajo los hombros y las rodillas bajo las caderas.","Extiende un brazo hacia adelante y la pierna opuesta hacia atrás.","Mantén el core apretado y el cuerpo nivelado.","Aguanta la posición sin rotar el torso.","Mantén el tiempo indicado. Completa en un lado, luego cambia."],"tips":["Imagina que llevas un vaso de agua sobre la zona lumbar.","Evita que la cadera rote al extender la pierna.","Empuja el suelo con la mano de apoyo para estabilizar el hombro."],"met":3.5,"uni":false,"img":["bird-dog-hold-main.webp"]},{"id":"boat-pose","n":"Postura del Barco","d":"Un equilibrio sentado sobre los isquiones con las piernas elevadas y el pecho alto: la forma de V carga los flexores de la cadera y toda la parte frontal del tronco.","cat":"fuerza","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["flexores de cadera","abdominales"],"m2":["lumbares","cuádriceps"],"ins":["Siéntate en el suelo con las rodillas flexionadas y los pies apoyados, las manos detrás de los muslos.","Inclínate hacia atrás hasta equilibrarte justo por detrás de los isquiones y eleva el pecho para mantener la columna larga.","Sube las espinillas hasta dejarlas paralelas al suelo y estira las piernas todo lo que la espalda pueda mantenerse plana.","Extiende los brazos hacia delante junto a las piernas y mantén la posición durante el tiempo indicado.","Baja los pies de forma controlada para terminar."],"tips":["Mantén el pecho alto; en cuanto la espalda se redondee, vuelve a flexionar las rodillas.","Sujétate por detrás de los muslos si los isquiotibiales te limitan más que el core.","Respira de forma constante en lugar de aguantar el aire."],"met":5.0,"uni":false,"img":["boat-pose-main.webp"]},{"id":"bodyweight-calf-raise","n":"Elevación de Talones con Peso Corporal","d":"Una elevación de talones con el propio peso corporal, un ejercicio básico para fortalecer los gemelos.","cat":"fuerza","g":"piernas","bp":"lower_legs","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["gemelos"],"m2":["sóleo"],"ins":["Colócate de pie con los pies separados al ancho de las caderas sobre una superficie plana.","Sube de puntillas lo más alto posible.","Aprieta los gemelos en la parte superior.","Baja los talones al suelo de forma controlada.","Repite el número deseado de repeticiones."],"tips":["Reparte el peso entre todos los dedos al subir.","Mantén las piernas rectas para centrar el trabajo en el gemelo.","Fija la mirada en un punto para mantener el equilibrio."],"met":3.5,"uni":false,"img":["bodyweight-calf-raise-start.webp","bodyweight-calf-raise-peak.webp"]},{"id":"bodyweight-good-morning","n":"Buenos Días con Peso Corporal","d":"Una bisagra de cadera con el propio peso corporal que fortalece los erectores espinales y los isquiotibiales.","cat":"fuerza","g":"espalda","bp":"back","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["lumbares","isquiotibiales"],"m2":["glúteo mayor"],"ins":["Colócate de pie con los pies separados al ancho de las caderas y las manos detrás de la cabeza.","Mantén una ligera flexión en las rodillas y contrae el core.","Bisagra en las caderas y baja el torso hasta quedar casi paralelo al suelo.","Impulsa las caderas hacia adelante para volver a la posición erguida.","Repite el número deseado de repeticiones."],"tips":["Empuja la cadera hacia atrás como si cerraras un cajón.","Mantén la espalda recta durante toda la bajada.","Detén el descenso si notas que la zona lumbar se redondea."],"met":5.0,"uni":false,"img":["bodyweight-good-morning-start.webp","bodyweight-good-morning-peak.webp"]},{"id":"bodyweight-lateral-raise","n":"Elevación Lateral con Peso Corporal","d":"Un movimiento de aislamiento de hombros sin equipamiento para desarrollar el ancho del deltoides lateral.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["deltoides lateral"],"m2":["deltoides anterior","trapecio"],"ins":["Párate erguido con los brazos colgando a los lados.","Levanta ambos brazos hacia los lados con un ligero codo doblado hasta la altura de los hombros.","Haz una pausa breve arriba.","Baja lentamente a la posición inicial.","Repite el número de repeticiones deseado."],"tips":["Lidera el movimiento con los codos, no con las manos.","Evita encoger los hombros en la parte superior.","Controla el descenso para maximizar el tiempo bajo tensión."],"met":3.5,"uni":false,"img":["bodyweight-lateral-raise-start.webp","bodyweight-lateral-raise-peak.webp"]},{"id":"bodyweight-overhead-press","n":"Press por Encima de la Cabeza con Peso Corporal","d":"Un press por encima de la cabeza de pie y sin carga: los brazos empujan desde los hombros hasta quedar estirados sobre la cabeza, practicando el patrón de empuje de hombros y tríceps sin ningún material.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["deltoides anterior","tríceps"],"m2":["serrato","trapecio"],"ins":["Ponte de pie con los pies a la anchura de las caderas y las manos en puños relajados a la altura de los hombros, palmas hacia delante y codos bajo las muñecas.","Activa el core y aprieta los glúteos para que las costillas no se abran.","Empuja ambos brazos hacia arriba hasta extender del todo los codos, con los brazos junto a las orejas.","Baja las manos con control hasta la altura de los hombros.","Repite el número de repeticiones deseado."],"tips":["Termina con las manos justo encima de los hombros, no delante de la cara.","No te inclines hacia atrás ni arquees la zona lumbar para subir más los brazos.","Cuando domines el patrón, sujeta mancuernas ligeras o una banda para añadir carga."],"met":5.0,"uni":false,"img":["bodyweight-overhead-press-start.webp","bodyweight-overhead-press-peak.webp"]},{"id":"bodyweight-reverse-lunge","n":"Zancada Inversa con Peso Corporal","d":"Una variante de zancada usando solo el peso corporal, dando un paso hacia atrás para mayor estabilidad de rodilla que una zancada hacia adelante.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["glúteo mayor","cuádriceps"],"m2":["isquiotibiales"],"ins":["Ponte de pie con los pies separados a la altura de las caderas.","Da un paso hacia atrás con una pierna y baja la rodilla hacia el suelo.","Baja hasta que tu muslo delantero quede paralelo al suelo.","Empuja a través del talón delantero para volver a la posición de pie.","Repite con ambas piernas."],"tips":["No necesitas peso -- concéntrate en el equilibrio y un descenso controlado.","Mantén el torso erguido en lugar de inclinarte hacia adelante.","Da un paso lo suficientemente atrás para que tu rodilla delantera quede detrás de los dedos del pie."],"met":5.0,"uni":true,"img":["bodyweight-reverse-lunge-start.webp","bodyweight-reverse-lunge-peak.webp"]},{"id":"bodyweight-squat","n":"Sentadilla con Peso Corporal","d":"Una sentadilla con el propio peso corporal, apta para principiantes, que desarrolla los glúteos y los cuádriceps.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["glúteo mayor","cuádriceps"],"m2":["lumbares","glúteo medio","isquiotibiales"],"ins":["Colócate de pie con los pies separados al ancho de los hombros y los brazos extendidos al frente.","Siéntate hacia atrás y hacia abajo flexionando caderas y rodillas.","Baja hasta que los muslos queden paralelos al suelo.","Empuja con los talones para volver a la posición de pie.","Repite el número deseado de repeticiones."],"tips":["Empuja las rodillas hacia afuera en línea con los pies.","Mantén el pecho erguido y la mirada al frente.","Evita que los talones se despeguen del suelo al bajar."],"met":6.0,"uni":false,"img":["bodyweight-squat-start.webp","bodyweight-squat-peak.webp"]},{"id":"bow-pose","n":"Postura del Arco","d":"Una extensión en decúbito prono: las manos sujetan los tobillos y las piernas empujan contra ellas, elevando pecho y muslos del suelo y activando toda la cadena posterior.","cat":"fuerza","g":"espalda","bp":"back","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["lumbares","glúteo mayor"],"m2":["isquiotibiales","pectoral"],"ins":["Túmbate boca abajo con los brazos junto al cuerpo y la frente apoyada en la esterilla.","Flexiona las rodillas y agarra la parte externa de ambos tobillos.","Empuja las espinillas contra las manos para que el pecho y los muslos se despeguen del suelo.","Mantén la posición elevada durante el tiempo indicado, con el cuello largo y la mirada al frente.","Suelta los tobillos y baja de forma controlada."],"tips":["La elevación viene de las piernas empujando contra las manos, no de tirar con los brazos.","Mantén las rodillas a la anchura de las caderas en lugar de dejarlas abrirse.","Si notas pinzamiento en los hombros, eleva menos y prioriza mantener el pecho abierto."],"met":5.0,"uni":false,"img":["bow-pose-main.webp"]},{"id":"box-jump","n":"Salto al Cajón","d":"Un salto pliométrico desde media sentadilla a un cajón estable, que entrena la potencia del tren inferior.","cat":"pliometría","g":"piernas","bp":"upper_legs","eq":"cajón","home":false,"bw":false,"lv":"intermedio","m":["glúteo mayor","cuádriceps"],"m2":["gemelos","isquiotibiales","sóleo"],"ins":["Mantente a unos 30 cm frente a un cajón firme con los pies a la anchura de los hombros.","Baja a una media sentadilla y balancea los brazos atrás.","Lanza los brazos arriba y salta explosivamente al cajón.","Aterriza suave con los pies planos y rodillas flexionadas.","Baja caminando — no saltando — y reinicia."],"tips":["Baja siempre caminando — los saltos hacia abajo repetidos sobrecargan el Aquiles.","Aterriza suave con todo el pie, rodillas alineadas con los dedos.","Elige una altura que puedas superar sin doblar la cadera."],"met":7.0,"uni":false,"img":["box-jump-start.webp","box-jump-peak.webp"]},{"id":"box-squat","n":"Sentadilla en Caja","d":"Una sentadilla realizada hasta una caja o banco, que fija la profundidad y enseña a sentarse hacia atrás en las caderas.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["glúteo mayor","cuádriceps"],"m2":["lumbares","glúteo medio","isquiotibiales"],"ins":["Ponte de pie frente a una caja o banco, con los pies al ancho de los hombros y los brazos extendidos hacia adelante para el equilibrio.","Empuja las caderas hacia atrás y flexiona las rodillas, sentándote hacia la caja en lugar de bajar en línea recta.","Toca la caja ligeramente con los glúteos sin dejarte caer sobre ella.","Empuja con los pies para volver a ponerte de pie, apretando los glúteos arriba.","Repite las repeticiones deseadas."],"tips":["Usa una altura de caja que permita que los muslos queden aproximadamente paralelos al suelo, y bájala a medida que mejore tu movilidad.","Mantén el peso en el centro de los pies — no te inclines hacia los dedos.","No te sientes por completo en la caja: relajar todo el peso sobre ella te hace perder tensión en el core y sobrecarga la columna."],"met":6.0,"uni":false,"img":["box-squat-start.webp","box-squat-peak.webp"]},{"id":"bulgarian-split-squat","n":"Sentadilla Búlgara","d":"Una variante de sentadilla unilateral con el pie trasero elevado.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["glúteo mayor","cuádriceps"],"m2":["isquiotibiales"],"ins":["Colócate de pie frente a un banco y apoya un pie detrás sobre el banco.","Sujeta mancuernas a los lados.","Baja el cuerpo hasta que el muslo delantero quede paralelo al suelo.","Empuja con el talón delantero para volver a la posición de pie.","Repite en ambos lados."],"tips":["Mantén casi todo el peso sobre la pierna adelantada.","Ajusta la distancia al banco hasta que la zancada sea estable.","Completa todas las repeticiones con una pierna antes de cambiar."],"met":6.0,"uni":true,"img":["bulgarian-split-squat-start.webp","bulgarian-split-squat-peak.webp"]},{"id":"burpees","n":"Burpees","d":"Un ejercicio de acondicionamiento de cuerpo completo que combina sentadilla, plank, flexión y salto.","cat":"cardio","g":"cuerpo completo","bp":"full_body","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["glúteo mayor","pectoral","cuádriceps"],"m2":["deltoides anterior","abdominales","tríceps"],"ins":["Mantente en pie con los pies a la anchura de los hombros.","Baja en sentadilla y apoya las manos en el suelo delante de ti.","Salta o lleva los pies atrás a la posición de plank y haz una flexión.","Salta o lleva los pies adelante hasta las manos.","Levántate y salta explosivamente con los brazos arriba."],"tips":["Mantén la espalda recta en el plank — no dejes caer las caderas.","Aterriza suavemente del salto.","Escálalo dando pasos atrás en lugar de saltar."],"met":8.0,"uni":false,"img":["burpees-main.webp"]},{"id":"butterfly-stretch","n":"Estiramiento de Mariposa","d":"Un estiramiento sentado para los aductores, juntando las plantas de los pies con las rodillas caídas hacia afuera.","cat":"estiramiento","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["aductores"],"m2":["flexores de cadera"],"ins":["Siéntate erguido y junta las plantas de los pies.","Deja caer las rodillas hacia el suelo.","Sujeta los pies y mantente erguido.","Mantén de 20 a 30 segundos, respirando de forma constante."],"tips":["Presiona suavemente las rodillas con los codos para más estiramiento.","Acerca los talones al cuerpo para aumentar la intensidad."],"met":5.0,"uni":false,"img":["butterfly-stretch-main.webp"]},{"id":"cable-bent-over-row","n":"Remo Inclinado con Cable","d":"Una variante de remo con cable que proporciona tensión constante durante todo el movimiento.","cat":"fuerza","g":"espalda","bp":"back","eq":"polea","home":false,"bw":false,"lv":"intermedio","m":["dorsales","romboides"],"m2":["bíceps","deltoides posterior"],"ins":["Engancha una barra recta o un agarre en V a la polea baja.","Inclínate hacia adelante desde las caderas con las rodillas ligeramente flexionadas.","Tira del agarre hacia la parte inferior del pecho.","Aprieta los omóplatos en la parte superior.","Baja de forma controlada y repite."],"tips":["Mantén la espalda recta y el torso estable durante toda la serie.","Piensa en llevar los codos hacia atrás, no en tirar con las manos.","No dejes que el peso te arrastre hacia delante al bajar."],"met":6.0,"uni":false,"img":["cable-bent-over-row-start.webp","cable-bent-over-row-peak.webp"]},{"id":"cable-chest-press","n":"Press de Pecho con Cable","d":"Un press de pecho de pie en polea que ofrece tensión constante sobre el pectoral durante todo el recorrido.","cat":"fuerza","g":"pecho","bp":"chest","eq":"polea","home":false,"bw":false,"lv":"intermedio","m":["pectoral"],"m2":["deltoides anterior","serrato","tríceps"],"ins":["Ajusta los cables a la altura del pecho y colócate de espaldas a la máquina.","Sujeta un agarre en cada mano y da un paso adelante adoptando una postura escalonada.","Empuja los agarres hacia adelante hasta extender los brazos completamente.","Aprieta el pecho en la parte superior.","Vuelve de forma controlada y repite."],"tips":["Evita que los hombros se adelanten al extender los brazos.","Mantén el core activo para no perder el equilibrio.","Mantén las muñecas rectas durante la fase de empuje."],"met":6.0,"uni":false,"img":["cable-chest-press-start.webp","cable-chest-press-peak.webp"]},{"id":"cable-crunch","n":"Crunch con Cable","d":"Un encogimiento abdominal de rodillas en polea alta con cuerda, que permite añadir carga progresiva al trabajo del recto abdominal.","cat":"fuerza","g":"core","bp":"core","eq":"polea","home":false,"bw":false,"lv":"intermedio","m":["abdominales"],"m2":["oblicuos","transverso abdominal"],"ins":["Arrodíllate frente a una máquina de cable con el accesorio de cuerda en la parte superior.","Sujeta la cuerda cerca de la frente con los codos flexionados.","Baja flexionando la columna y llevando los codos hacia los muslos.","Aprieta fuerte los abdominales en la parte inferior.","Vuelve a la posición inicial y repite."],"tips":["Flexiona la columna en lugar de tirar con los brazos.","Evita sentarte hacia atrás con la cadera en cada repetición.","Exhala con fuerza al bajar para contraer mejor el abdomen."],"met":5.0,"uni":false,"img":["cable-crunch-start.webp","cable-crunch-peak.webp"]},{"id":"cable-curl","n":"Curl con Cable","d":"Un curl de bíceps con resistencia de cable para tensión constante.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"polea","home":false,"bw":false,"lv":"principiante","m":["bíceps"],"m2":["braquial"],"ins":["Colócate de pie frente a una polea baja con una barra recta o barra Z.","Agarra la barra con agarre supino y los codos pegados a los costados.","Sube la barra hacia los hombros.","Baja de forma controlada.","Repite."],"tips":["Evita que los codos se adelanten al subir la barra.","No balancees el torso para ayudarte con el peso.","Aleja un poco el cuerpo de la polea para mantener la tensión."],"met":5.0,"uni":false,"img":["cable-curl-start.webp","cable-curl-peak.webp"]},{"id":"cable-external-rotation","n":"Rotación Externa con Cable","d":"Un ejercicio de rotación externa en polea, con el codo pegado al costado, que fortalece los rotadores externos del manguito rotador con ayuda del deltoides posterior.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"polea","home":false,"bw":false,"lv":"intermedio","m":["deltoides posterior"],"m2":["romboides","trapecio"],"ins":["Ajusta la polea a la altura del codo y agarra el handle.","Colócate de lado a la máquina con el codo de trabajo flexionado a 90 grados.","Mantén el codo pegado al costado y rota el antebrazo hacia afuera.","Pausa al final del movimiento.","Vuelve de forma controlada. Completa las repeticiones de un lado y luego cambia."],"tips":["Evita encoger los hombros mientras giras el brazo.","Trabaja con poco peso y de forma lenta y controlada.","Mantén la muñeca firme, alineada con el antebrazo."],"met":6.0,"uni":false,"img":["cable-external-rotation-start.webp","cable-external-rotation-peak.webp"]},{"id":"cable-fly","n":"Aperturas con Cable","d":"Un ejercicio de aislamiento para el pecho con resistencia de cable para tensión constante.","cat":"fuerza","g":"pecho","bp":"chest","eq":"polea","home":false,"bw":false,"lv":"intermedio","m":["pectoral"],"m2":["deltoides anterior"],"ins":["Colócate entre dos columnas de cable con los agarres enganchados a las poleas altas.","Con una ligera flexión en los codos, abre los brazos hacia los lados.","Junta las manos frente al pecho en un movimiento de abrazo.","Vuelve lentamente a la posición inicial.","Repite."],"tips":["Mantén el ángulo de los codos constante para no convertirlo en un press.","Aprieta el pecho un segundo cuando las manos se encuentren.","No adelantes los hombros cuando los brazos están abiertos."],"met":5.0,"uni":false,"img":["cable-fly-start.webp","cable-fly-peak.webp"]},{"id":"cable-front-raise","n":"Elevación Frontal con Cable","d":"Una elevación frontal en polea que aísla el deltoides anterior con tensión constante durante todo el recorrido.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"polea","home":false,"bw":false,"lv":"intermedio","m":["deltoides anterior"],"m2":["deltoides lateral","pectoral"],"ins":["Colócate de espaldas a una polea baja con un agarre.","Sujeta el agarre con el brazo extendido a la altura del muslo.","Levanta el brazo hacia adelante hasta la altura del hombro manteniéndolo recto.","Pausa en la parte superior.","Baja de forma controlada y repite."],"tips":["Evita balancear el torso para ayudarte a subir.","Mantén el codo casi recto, sin bloquearlo.","Baja más despacio de lo que subes para aprovechar la tensión del cable."],"met":5.0,"uni":true,"img":["cable-front-raise-start.webp","cable-front-raise-peak.webp"]},{"id":"cable-hammer-curl","n":"Curl de Martillo en Cable","d":"Un curl en cable con cuerda y agarre neutro que trabaja el braquial y braquiorradial con tensión constante.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"polea","home":false,"bw":false,"lv":"intermedio","m":["bíceps","braquial","braquiorradial"],"m2":["antebrazo"],"ins":["Engancha una cuerda a la polea baja y párate frente a la máquina.","Agarra la cuerda con agarre neutro, palmas enfrentadas.","Sube la cuerda hacia los hombros manteniendo los codos fijos a los lados.","Aprieta arriba, luego baja lentamente hasta la extensión completa.","Repite el número de repeticiones deseado."],"tips":["Mantén los codos inmóviles durante todo el movimiento.","Separa ligeramente los extremos de la cuerda arriba para mayor contracción.","Evita balancear el torso."],"met":5.0,"uni":false,"img":["cable-hammer-curl-start.webp","cable-hammer-curl-peak.webp"]},{"id":"cable-kickback","n":"Patada Trasera de Glúteos en Cable","d":"Un ejercicio de aislamiento en cable para el glúteo mayor que extiende la cadera hacia atrás contra resistencia constante.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"polea","home":false,"bw":false,"lv":"intermedio","m":["glúteo mayor"],"m2":["isquiotibiales"],"ins":["Coloca una correa de tobillo en la polea baja y sujétala alrededor de un tobillo.","De pie frente a la máquina, agárrate ligeramente al soporte e inclínate un poco desde las caderas.","Lleva la pierna con la correa hacia atrás extendiendo la cadera completamente y manteniendo la rodilla casi recta.","Aprieta el glúteo en la extensión máxima y regresa el pie lentamente a la posición inicial.","Completa todas las repeticiones de un lado antes de cambiar."],"tips":["Conduce el movimiento con el talón para maximizar la activación del glúteo.","Mantén las caderas paralelas; evita rotar la pelvis al patear hacia atrás.","El movimiento viene solo de la cadera: mantén la espalda y la pierna de apoyo estables."],"met":5.0,"uni":true,"img":["cable-kickback-start.webp","cable-kickback-peak.webp"]},{"id":"cable-lateral-raise","n":"Elevación Lateral en Polea","d":"Una elevación lateral unilateral en polea, que ofrece tensión constante sobre el deltoides lateral.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"polea","home":false,"bw":false,"lv":"intermedio","m":["deltoides lateral"],"m2":["deltoides anterior","trapecio"],"ins":["Colócate de lado a una polea baja y agarra el asa con la mano más alejada de la máquina.","Mantén una ligera flexión en el codo y deja que el cable cruce por delante del cuerpo.","Sube el brazo hacia el lado hasta quedar paralelo al suelo.","Baja con control. Repeticiones por lado, luego cambia.","Mantén la tensión — no dejes que el peso descanse abajo."],"tips":["Lidera con el codo, no con la mano.","Pausa brevemente arriba, sin balanceo.","Usa menos carga que con mancuerna — la tensión del cable es constante."],"met":5.0,"uni":true,"img":["cable-lateral-raise-start.webp","cable-lateral-raise-peak.webp"]},{"id":"cable-overhead-tricep-extension","n":"Extensión de Tríceps por Encima de la Cabeza con Cable","d":"Un ejercicio de tríceps con cable: de espaldas a la pila de pesas, sujetas una cuerda detrás de la cabeza y extiendes los codos para empujarla hacia arriba y por encima de la cabeza. La posición sobre la cabeza estira la cabeza larga del tríceps y el cable mantiene la tensión en el músculo durante todo el movimiento.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"polea","home":false,"bw":false,"lv":"intermedio","m":["tríceps"],"m2":["deltoides anterior"],"ins":["Engancha una cuerda a la polea baja y selecciona un peso ligero.","Agarra la cuerda con ambas manos, gírate de espaldas a la pila y da un paso al frente en posición escalonada para que el cable tire de ti hacia atrás.","Sube la cuerda por encima de la cabeza con los codos flexionados y la parte superior de los brazos cerca de las orejas, de modo que las manos queden detrás de la cabeza.","Aprieta el tronco y mantén quietos la parte superior de los brazos, luego extiende los codos para empujar la cuerda hacia arriba hasta que los brazos queden completamente estirados sobre la cabeza.","Haz una breve pausa arriba y luego flexiona los codos para bajar la cuerda de nuevo detrás de la cabeza de forma controlada.","Repite el número de repeticiones previsto."],"tips":["Mantén los codos apuntando al frente y la parte superior de los brazos quietos; si se abren o se desplazan, la extensión se convierte en un press.","Da un paso lo bastante largo al frente para que el cable te mantenga estable y evita arquear la zona lumbar al subir los brazos sobre la cabeza.","Usa un peso que puedas controlar en todo el estiramiento; las cargas pesadas separan los codos."],"met":5.0,"uni":false,"img":["cable-overhead-tricep-extension-start.webp","cable-overhead-tricep-extension-peak.webp"]},{"id":"cable-pallof-press","n":"Press Pallof en Polea","d":"Un ejercicio de core antirrotación en el que la polea tira de ti hacia un lado mientras empujas el agarre recto desde el pecho y te niegas a dejar que el torso gire.","cat":"fuerza","g":"core","bp":"core","eq":"polea","home":false,"bw":false,"lv":"intermedio","m":["oblicuos","transverso abdominal"],"m2":["deltoides anterior","lumbares","glúteo medio","abdominales"],"ins":["Coloca la polea a la altura del pecho y toma el agarre con ambas manos, situado de lado respecto a la máquina.","Sepárate hasta que haya tensión real en el cable, con los pies a la anchura de los hombros y las rodillas ligeramente flexionadas.","Lleva el agarre al centro del pecho y aprieta el tronco y los glúteos.","Empuja el agarre recto hacia delante hasta extender los brazos, resistiendo el tirón que quiere rotarte hacia la máquina.","Mantén un instante la posición extendida y devuelve después el agarre al pecho de forma controlada.","Completa las repeticiones deseadas, luego date la vuelta y repite hacia el otro lado."],"tips":["Nada debe rotar. Si los hombros giran hacia la polea al empujar, baja el peso — lo que entrena es la rotación que no llega a ocurrir.","Cuanto más te alejes de la máquina, más largo es el brazo de palanca y más cuesta, así que puedes cambiar la dificultad sin tocar el stack.","Mantén los brazos a la altura del pecho y los hombros abajo; dejar que el agarre suba lo convierte en una elevación frontal."],"met":3.5,"uni":false,"img":["cable-pallof-press-start.webp","cable-pallof-press-peak.webp"]},{"id":"cable-pull-through","n":"Pull-Through en Polea","d":"Una bisagra de cadera con resistencia de polea, de espaldas a una polea baja, que carga glúteos e isquiotibiales sin colocar una barra sobre la columna.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"polea","home":false,"bw":false,"lv":"intermedio","m":["glúteo mayor","isquiotibiales"],"m2":["lumbares"],"ins":["Coloca una cuerda en la polea baja y ponte de espaldas a la máquina con la cuerda entre las piernas.","Avanza hasta tensar el cable, activa el tronco y flexiona ligeramente las rodillas.","Lleva las caderas hacia atrás manteniendo la columna neutra y los brazos largos.","Empuja las caderas hacia delante y contrae los glúteos hasta quedar erguido.","Vuelve de forma controlada a la siguiente bisagra sin dejar caer el bloque de pesas."],"tips":["Piensa en caderas atrás y caderas adelante; los brazos solo sujetan la cuerda.","Mantén las tibias casi verticales para que siga siendo una bisagra y no una sentadilla.","Termina erguido sin inclinarte hacia atrás en el bloqueo."],"met":6.0,"uni":false,"img":["cable-pull-through-start.webp","cable-pull-through-peak.webp"]},{"id":"cable-reverse-fly","n":"Apertura Inversa con Cable","d":"Un ejercicio de pie con cable para los deltoides posteriores: de cara al espacio entre dos torres de polea, sujetas las empuñaduras opuestas con los cables cruzados delante de ti y llevas los brazos hacia fuera y atrás hasta que quedan a la altura de los hombros. Los cables mantienen la tensión en la parte posterior de los hombros durante todo el arco.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"polea","home":false,"bw":false,"lv":"intermedio","m":["deltoides posterior"],"m2":["romboides","trapecio"],"ins":["Coloca ambas poleas aproximadamente a la altura de los hombros y sitúate en el centro, entre las dos torres de polea.","Agarra la empuñadura izquierda con la mano derecha y la empuñadura derecha con la mano izquierda, de modo que los cables se crucen delante de ti.","Ponte erguido con los brazos estirados al frente a la altura de los hombros y una ligera flexión en los codos.","Lleva los brazos hacia fuera y atrás en un arco amplio, guiando el movimiento con los codos, hasta que queden en línea con los hombros.","Junta los omóplatos brevemente sin arquear la zona lumbar.","Devuelve las empuñaduras despacio a la posición inicial cruzada y repite el número de repeticiones previsto."],"tips":["Mantén los codos ligeramente flexionados y fijos; si los flexionas y extiendes, la apertura se convierte en un remo.","Mantén los hombros bajos y el cuello relajado para que trabajen los deltoides posteriores y no el trapecio superior.","Usa un peso ligero y un retorno lento; los cables tiran con más fuerza al final del arco, así que controla esa posición."],"met":5.0,"uni":false,"img":["cable-reverse-fly-start.webp","cable-reverse-fly-peak.webp"]},{"id":"cable-tricep-kickback","n":"Patada de Tríceps con Cable","d":"Una extensión de tríceps en polea baja, realizada con el torso inclinado, que mantiene la tensión en el bloqueo final.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"polea","home":false,"bw":false,"lv":"intermedio","m":["tríceps"],"m2":["deltoides posterior"],"ins":["Engancha un handle a la polea baja e inclínate hacia adelante desde las caderas.","Pega la parte superior del brazo al costado con el codo flexionado a 90 grados.","Extiende el codo para empujar el handle hacia atrás.","Aprieta el tríceps al final del movimiento.","Vuelve de forma controlada. Completa las repeticiones de un lado y luego cambia."],"tips":["Evita que el codo caiga o se abra durante la extensión.","Mantén la espalda recta mientras el torso está inclinado.","Usa un peso ligero para no recurrir al impulso."],"met":5.0,"uni":false,"img":["cable-tricep-kickback-start.webp","cable-tricep-kickback-peak.webp"]},{"id":"cable-upright-row","n":"Remo al Mentón con Cable","d":"Un remo al mentón con cable para tensión constante en los deltoides laterales y el trapecio.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"polea","home":false,"bw":false,"lv":"intermedio","m":["deltoides lateral","trapecio"],"m2":["deltoides anterior","bíceps"],"ins":["Colócate frente a la máquina de cable y agarra una barra recta o cuerda a la altura de los muslos.","Tira de la barra hacia el mentón llevando los codos por delante.","Baja de forma controlada.","Repite."],"tips":["Mantén los codos más altos que las muñecas.","Evita encoger los hombros en exceso."],"met":6.0,"uni":false,"img":["cable-upright-row-start.webp","cable-upright-row-peak.webp"]},{"id":"cable-wrist-curl","n":"Curl de Muñeca con Cable","d":"Un ejercicio de aislamiento para los flexores del antebrazo: sentado en un banco plano con los antebrazos apoyados en los muslos, sujetas una barra corta enganchada a una polea baja delante de ti y la subes flexionando las muñecas. Los muslos mantienen quietos los antebrazos, de modo que solo se mueven las muñecas.","cat":"fuerza","g":"brazos","bp":"lower_arms","eq":"polea","home":false,"bw":false,"lv":"intermedio","m":["antebrazo"],"m2":[],"ins":["Engancha una barra recta corta a una polea baja y siéntate en un banco plano mirando hacia la polea, con los pies apoyados en el suelo.","Agarra la barra en supinación, con las palmas hacia arriba y las manos más o menos a la anchura de los hombros.","Apoya los antebrazos en los muslos de forma que las muñecas y las manos sobresalgan justo por delante de las rodillas.","Deja que el cable lleve las muñecas hacia abajo hasta notar un estiramiento en los antebrazos.","Sube la barra flexionando las muñecas, manteniendo los antebrazos sobre los muslos.","Baja la barra con control y repite el número de repeticiones previsto."],"tips":["Mueve solo las muñecas; mantén los antebrazos presionados contra los muslos.","Haz las repeticiones despacio para no sobrecargar las muñecas.","Haz una breve pausa arriba en cada repetición para una contracción más fuerte."],"met":5.0,"uni":false,"img":["cable-wrist-curl-start.webp","cable-wrist-curl-peak.webp"]},{"id":"camel-pose","n":"Postura del Camello","d":"Una extensión de rodillas que abre la parte frontal de las caderas, el abdomen y el pecho, con las manos apoyadas en los talones o en la zona lumbar.","cat":"estiramiento","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["lumbares","flexores de cadera"],"m2":["pectoral","cuádriceps"],"ins":["Arrodíllate con las rodillas a la anchura de las caderas y las caderas alineadas sobre ellas.","Coloca las manos en la parte posterior de la pelvis con los dedos hacia abajo y eleva el pecho.","Empuja las caderas hacia delante y arquéate hacia atrás, buscando los talones si la posición sigue cómoda.","Mantén la postura durante el tiempo indicado, con el cuello en línea con la columna.","Devuelve las manos a la pelvis y sube liderando con el pecho."],"tips":["Mantén las caderas sobre las rodillas; si se van hacia atrás, la postura se derrumba.","Apoya los dedos de los pies y coloca las manos sobre los talones elevados si el alcance completo es demasiado.","Sal despacio: levantar primero la cabeza es lo que suele marear."],"met":5.0,"uni":false,"img":["camel-pose-main.webp"]},{"id":"captains-chair-knee-raise","n":"Elevación de Rodillas en Silla Romana","d":"Un ejercicio de peso corporal en silla romana que trabaja el abdomen bajo y los flexores de cadera.","cat":"fuerza","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["flexores de cadera","abdominales"],"m2":["oblicuos","transverso abdominal"],"ins":["Colócate en la silla romana con la espalda plana contra el respaldo y los antebrazos en los apoyos.","Deja las piernas colgando rectas hacia abajo.","Activa el core y sube las rodillas hacia el pecho.","Mantén brevemente arriba, luego baja despacio a la posición inicial.","Repite el número de repeticiones deseado."],"tips":["Evita balancear las piernas para tomar impulso.","Exhala al subir las rodillas.","Mantén la espalda contra el respaldo durante todo el ejercicio."],"met":5.0,"uni":false,"img":["captains-chair-knee-raise-start.webp","captains-chair-knee-raise-peak.webp"]},{"id":"captains-chair-leg-raise","n":"Elevación de Piernas en Silla Romana","d":"Un ejercicio de peso corporal en silla romana para el abdomen bajo con piernas rectas, de mayor dificultad.","cat":"fuerza","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["flexores de cadera","abdominales"],"m2":["oblicuos","transverso abdominal"],"ins":["Colócate en la silla romana con la espalda plana contra el respaldo y los antebrazos en los apoyos.","Deja las piernas colgando rectas hacia abajo.","Con las piernas rectas, súbelas hasta la horizontal o más arriba.","Mantén brevemente arriba, luego baja despacio.","Repite el número de repeticiones deseado."],"tips":["Mantén las piernas lo más rectas posible.","Evita el balanceo — controla el movimiento con el core.","Dobla ligeramente las rodillas para reducir la dificultad si es necesario."],"met":5.0,"uni":false,"img":["captains-chair-leg-raise-start.webp","captains-chair-leg-raise-peak.webp"]},{"id":"cat-cow","n":"Gato-Vaca","d":"Un flujo a cuatro apoyos que alterna entre redondear la columna hacia el techo y dejarla descender mientras el pecho se abre, moviendo cada segmento de la espalda por su recorrido.","cat":"estiramiento","g":"espalda","bp":"back","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["lumbares","abdominales"],"m2":["transverso abdominal","trapecio"],"ins":["Colócate a cuatro apoyos con las manos bajo los hombros y las rodillas bajo las caderas.","Exhala y redondea la columna hacia el techo, metiendo el coxis y dejando caer la cabeza.","Inhala e inviértelo: deja descender el abdomen, eleva el pecho y el coxis y mira ligeramente al frente.","Alterna entre ambas formas despacio, una respiración por posición.","Termina en columna neutra y siéntate sobre los talones."],"tips":["Deja que la respiración marque el ritmo en lugar de correr entre las dos posiciones.","Presiona las manos por igual para que los hombros no se hundan hacia el suelo.","Mueve toda la columna, incluido el cuello, en lugar de doblar solo la zona lumbar."],"met":5.0,"uni":false,"img":["cat-cow-main.webp"]},{"id":"cat-stretch","n":"Estiramiento del Gato","d":"Un estiramiento de rodillas que redondea la columna hacia arriba para alargar los músculos de la espalda.","cat":"estiramiento","g":"espalda","bp":"back","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["lumbares"],"m2":["romboides","trapecio"],"ins":["Empieza en cuadrupedia, manos bajo los hombros y rodillas bajo las caderas.","Redondea la columna hacia el techo.","Lleva el mentón hacia el pecho.","Mantén de 20 a 30 segundos, respirando de forma constante."],"tips":["Empuja el suelo con las manos para separar los omóplatos.","Relájate y sigue respirando todo el tiempo."],"met":5.0,"uni":false,"img":["cat-stretch-main.webp"]},{"id":"chair-pose","n":"Postura de la Silla","d":"Un sostén de pie con las caderas hacia atrás y los brazos arriba, donde el cuádriceps y la espalda alta trabajan de forma isométrica contra el peso corporal.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["glúteo mayor","cuádriceps"],"m2":["deltoides anterior","lumbares"],"ins":["Ponte de pie con los pies juntos o a la anchura de las caderas y el peso en los talones.","Flexiona las rodillas y lleva las caderas atrás como si fueras a sentarte en una silla.","Eleva los brazos junto a las orejas sin dejar que las costillas se abran.","Mantén la posición durante el tiempo indicado, con el pecho alto y las rodillas siguiendo la línea de los pies.","Empuja con los talones para volver a ponerte de pie."],"tips":["Deja suficiente peso en los talones como para poder levantar los dedos de los pies.","Lleva los brazos algo más adelante si subirlos del todo te arquea la zona lumbar.","Baja más para exigir al cuádriceps, pero solo mientras los talones sigan apoyados."],"met":5.0,"uni":false,"img":["chair-pose-main.webp"]},{"id":"cheat-curl","n":"Curl con Impulso","d":"Un curl de bíceps que emplea un ligero impulso de cadera para iniciar la subida y enfatiza una bajada lenta y controlada.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["bíceps"],"m2":["braquial","braquiorradial","lumbares"],"ins":["Colócate de pie sujetando el peso a la altura de los muslos con agarre supino.","Usa un ligero impulso de cadera para iniciar el curl.","Sube el peso hacia los hombros de forma explosiva.","Baja el peso lentamente de forma controlada por todo el rango de movimiento.","Repite el número deseado de repeticiones."],"tips":["Evita convertir el ejercicio en un balanceo de todo el cuerpo.","Si no puedes controlar la bajada, reduce la carga.","Mantén el abdomen firme para proteger la zona lumbar."],"met":5.0,"uni":false,"img":["cheat-curl-start.webp","cheat-curl-peak.webp"]},{"id":"chest-press-machine","n":"Press de Pecho en Máquina","d":"Un movimiento de empuje para el pecho en máquina, ideal para principiantes.","cat":"fuerza","g":"pecho","bp":"chest","eq":"máquina de press de pecho","home":false,"bw":false,"lv":"principiante","m":["pectoral"],"m2":["deltoides anterior","tríceps"],"ins":["Siéntate en la máquina con la espalda plana contra el respaldo.","Agarra los mangos a la altura del pecho.","Empuja los mangos hacia adelante hasta extender los brazos completamente.","Vuelve lentamente a la posición inicial.","Repite."],"tips":["Ajusta el asiento para que las manijas queden a la altura del pecho.","Empuja sin bloquear los codos de golpe.","Vuelve atrás con control, sin soltar el peso de golpe."],"met":6.0,"uni":false,"img":["chest-press-machine-start.webp","chest-press-machine-peak.webp"]},{"id":"chest-supported-db-row","n":"Remo con Mancuernas con Apoyo en el Pecho","d":"Un remo con mancuernas con apoyo en el pecho para eliminar la tensión en la zona lumbar y aislar los músculos de la espalda.","cat":"fuerza","g":"espalda","bp":"back","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["dorsales","romboides"],"m2":["bíceps","deltoides posterior"],"ins":["Túmbate boca abajo en un banco inclinado con las mancuernas colgando por debajo.","Rema las mancuernas hacia los lados.","Aprieta en la parte superior y baja.","Repite."],"tips":["El apoyo en el pecho elimina la fatiga de la espalda.","Concéntrate en juntar los omóplatos."],"met":6.0,"uni":false,"img":["chest-supported-db-row-start.webp","chest-supported-db-row-peak.webp"]},{"id":"chest-supported-dumbbell-shrug","n":"Encogimiento de Hombros con Mancuernas y Apoyo en el Pecho","d":"Un encogimiento de hombros boca abajo en un banco inclinado, donde el apoyo del pecho aísla el trapecio y elimina el impulso.","cat":"fuerza","g":"espalda","bp":"back","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["trapecio"],"m2":["deltoides posterior","romboides"],"ins":["Ajusta un banco inclinado a unos 30 grados.","Túmbate boca abajo en el banco sujetando mancuernas con los brazos extendidos.","Encoge los hombros hacia arriba y hacia atrás en dirección a las orejas.","Aprieta el trapecio superior en la parte superior.","Baja de forma controlada y repite."],"tips":["Encoge hacia arriba y atrás hacia las orejas, no solo recto hacia arriba.","Mantén el pecho pegado a la almohadilla para no usar impulso.","Haz una pausa y aprieta arriba antes de bajar con control."],"met":5.0,"uni":false,"img":["chest-supported-dumbbell-shrug-start.webp","chest-supported-dumbbell-shrug-peak.webp"]},{"id":"chest-supported-kettlebell-row","n":"Remo con Kettlebell Apoyado en el Pecho","d":"Este ejercicio trabaja los músculos de tu espalda, principalmente el dorsal ancho y los romboides, remando con una kettlebell en cada mano hacia las caderas mientras el torso está apoyado en un banco inclinado.","cat":"fuerza","g":"espalda","bp":"back","eq":"kettlebell","home":true,"bw":false,"lv":"principiante","m":["dorsales","romboides"],"m2":["bíceps","deltoides posterior","trapecio"],"ins":["Acuéstate boca abajo en un banco inclinado, dejando que tus brazos cuelguen libremente con una kettlebell en cada mano.","Contrae tu abdomen y retrae tus escápulas.","Tira de las kettlebells hacia tus caderas, apretando tus escápulas.","Haz una breve pausa en la parte superior, sintiendo la contracción en tu espalda.","Baja lentamente las kettlebells a la posición inicial con control."],"tips":["Mantén el torso estable durante todo el movimiento; evita balancearte.","Concéntrate en iniciar el tirón con los músculos de la espalda, no solo con los brazos.","Mantén los codos cerca de tu cuerpo para enfatizar el dorsal ancho."],"met":6.0,"uni":false,"img":["chest-supported-kettlebell-row-start.webp","chest-supported-kettlebell-row-peak.webp"]},{"id":"chest-supported-machine-row","n":"Remo en Máquina con Apoyo en el Pecho","d":"Un ejercicio de remo sentado en máquina con una almohadilla en el pecho que sostiene el torso, de modo que los dorsales y los músculos entre los omóplatos hacen el tirón y la zona lumbar queda fuera. Tiras de las empuñaduras hacia atrás llevando los codos detrás de ti y luego las dejas volver hacia delante con control.","cat":"fuerza","g":"espalda","bp":"back","eq":"máquina de remo","home":false,"bw":false,"lv":"principiante","m":["dorsales","romboides"],"m2":["bíceps","deltoides posterior","trapecio"],"ins":["Ajusta el asiento para que las empuñaduras queden a la altura de la parte baja del pecho y siéntate con el pecho contra la almohadilla y los pies bien apoyados.","Estírate hacia delante y agarra las empuñaduras con los brazos extendidos y los hombros relajados.","Aprieta el tronco y tira de las empuñaduras hacia atrás llevando los codos detrás de ti.","Junta los omóplatos al final del tirón sin despegar el pecho de la almohadilla.","Haz una breve pausa y luego extiende los brazos para devolver las empuñaduras hacia delante de forma controlada.","Repite el número de repeticiones previsto manteniendo el pecho sobre la almohadilla en todo momento."],"tips":["Tira con los codos en lugar de con las manos, para que los dorsales y la espalda media lleven el movimiento y los bíceps ayuden.","Mantén el pecho en la almohadilla y los hombros bajos; si encoges los hombros o te echas hacia atrás, el remo se convierte en un tirón del trapecio superior.","Deja que los omóplatos se separen hacia delante al inicio de cada repetición para lograr un estiramiento completo antes del siguiente tirón."],"met":6.0,"uni":false,"img":["chest-supported-machine-row-start.webp","chest-supported-machine-row-peak.webp"]},{"id":"chest-supported-smith-machine-row","n":"Remo con Apoyo en el Pecho en Máquina Smith","d":"Un remo contra un respaldo inclinado dentro de la máquina Smith, donde el apoyo del pecho saca la zona lumbar del movimiento y la barra guiada mantiene el tirón en una sola línea.","cat":"fuerza","g":"espalda","bp":"back","eq":"máquina Smith","home":false,"bw":false,"lv":"principiante","m":["dorsales","romboides"],"m2":["bíceps","deltoides posterior"],"ins":["Coloca un banco inclinado dentro de la máquina Smith mirando hacia la barra, y baja la barra lo suficiente para que tus brazos cuelguen rectos al apoyarte en el respaldo.","Ponte de pie a horcajadas del banco con los pies firmes y el pecho apoyado en la parte alta del respaldo.","Toma un agarre prono algo más ancho que los hombros y desengancha la barra con los brazos extendidos.","Tira de la barra hacia la parte baja del pecho, guiando con los codos y juntando las escápulas arriba.","Baja la barra de forma controlada hasta estirar los brazos de nuevo y repite el número de repeticiones deseado."],"tips":["Mantén el pecho en el respaldo en cada repetición. En cuanto te separas de él para mover el peso lo has convertido otra vez en un remo inclinado y has perdido la razón del montaje.","Guía con los codos y detente cuando pasen del torso. Tirar más solo adelanta los hombros, y la trayectoria fija de la barra no les deja escapatoria.","Como aquí la zona lumbar no hace nada, este es el remo para los días en que un remo inclinado no es opción: ajusta el peso a lo que tu espalda puede tirar, no a lo que tus piernas podrían aguantar."],"met":6.0,"uni":false,"img":["chest-supported-smith-machine-row-start.webp","chest-supported-smith-machine-row-peak.webp"]},{"id":"childs-pose","n":"Postura del Niño","d":"Un estiramiento de descanso de rodillas que alarga los dorsales, la zona lumbar y los hombros con los brazos al frente.","cat":"estiramiento","g":"espalda","bp":"back","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["lumbares","dorsales"],"m2":["trapecio"],"ins":["Arrodíllate y lleva la cadera hacia los talones.","Inclina el torso hacia adelante sobre los muslos.","Extiende ambos brazos largos sobre el suelo al frente.","Mantén de 20 a 30 segundos, respirando de forma constante."],"tips":["Abre más las rodillas para apoyar el pecho más abajo.","Relájate y sigue respirando todo el tiempo."],"met":5.0,"uni":false,"img":["childs-pose-main.webp"]},{"id":"chin-tuck-hold","n":"Retracción de Mentón Sostenida","d":"Un ejercicio estático de cuello que retrae la cabeza hacia atrás para fortalecer los flexores profundos del cuello y contrarrestar la postura de cabeza adelantada.","cat":"fuerza","g":"cuerpo completo","bp":"full_body","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["trapecio"],"m2":["romboides"],"ins":["Ponte de pie o siéntate erguido con los hombros relajados.","Lleva el mentón recto hacia atrás, creando una papada.","Mantén la cabeza nivelada sin inclinarla.","Mantén la posición durante el tiempo deseado.","Suelta y repite durante varias series."],"tips":["Imagina deslizar la cabeza hacia atrás sobre la columna, no asentir hacia abajo.","Mantén la mirada nivelada y la respiración relajada."],"met":5.0,"uni":false,"img":["chin-tuck-hold-main.webp"]},{"id":"chin-ups","n":"Dominadas en Supinación","d":"Una variante de dominadas con agarre supino que activa fuertemente los bíceps junto con el dorsal ancho.","cat":"fuerza","g":"espalda","bp":"back","eq":"barra de dominadas","home":true,"bw":false,"lv":"intermedio","m":["bíceps","dorsales"],"m2":["romboides"],"ins":["Cuélgate de una barra con agarre supino a la anchura de los hombros.","Sube hasta que el mentón supere la barra.","Baja de forma controlada.","Repite."],"tips":["Mantén el core contraído durante todo el ejercicio.","Evita el balanceo excesivo."],"met":6.0,"uni":false,"img":["chin-ups-start.webp","chin-ups-peak.webp"]},{"id":"clamshells","n":"Almejas","d":"Un ejercicio de abducción de cadera, realizado tumbado de lado, que activa el glúteo medio sin material adicional.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["abductores","glúteo medio"],"m2":["glúteo mayor"],"ins":["Túmbate de lado con las rodillas dobladas y apiladas una sobre la otra.","Mantén los pies juntos y las caderas alineadas.","Abre la rodilla superior hacia el techo sin rotar las caderas.","Aprieta el glúteo externo en la posición superior.","Baja de forma controlada. Completa las repeticiones de un lado y luego cambia."],"tips":["Sube la rodilla solo hasta donde la pelvis no se mueva.","Hazlo lento y controlado para notar bien el glúteo medio.","Exhala al abrir la rodilla y mantén el abdomen activo."],"met":5.0,"uni":false,"img":["clamshells-start.webp","clamshells-peak.webp"]},{"id":"clamshells-hold","n":"Almejas Isométricas","d":"La posición final de la almeja mantenida en el tiempo: tumbado de lado con las rodillas flexionadas y apiladas, la rodilla superior se abre y la pelvis se mantiene firme, de modo que el glúteo medio trabaja de forma isométrica en lugar de por repeticiones.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["abductores","glúteo medio"],"m2":["glúteo mayor"],"ins":["Túmbate de lado con las caderas y las rodillas flexionadas unos 45 y 90 grados, los talones juntos y las rodillas apiladas.","Alinea los hombros y las caderas en vertical y aprieta el tronco para que la pelvis no ruede hacia atrás.","Abre la rodilla superior todo lo que puedas sin que la pelvis rote, manteniendo los talones en contacto.","Mantén esa posición abierta durante el tiempo indicado, respirando con normalidad.","Baja la rodilla de forma controlada y repite del otro lado."],"tips":["Detén la apertura donde la pelvis empieza a rodar hacia atrás; el recorrido es menor de lo que la mayoría espera.","Mantén los talones presionados entre sí para que el movimiento se quede en la cadera y no en el tobillo.","Añade una banda circular por encima de las rodillas solo cuando la pelvis se mantenga completamente quieta."],"met":5.0,"uni":false,"img":["clamshells-hold-main.webp"]},{"id":"clap-push-ups","n":"Flexiones con Palmada","d":"Una flexión pliométrica explosiva que desarrolla la potencia del pecho y las fibras musculares de contracción rápida.","cat":"fuerza","g":"pecho","bp":"chest","eq":"sin equipo","home":true,"bw":true,"lv":"avanzado","m":["pectoral"],"m2":["tríceps"],"ins":["Comienza en la posición estándar de flexión.","Baja el pecho hacia el suelo.","Empuja hacia arriba de forma explosiva para que las manos despeguen del suelo.","Da una palmada y aterriza suavemente, volviendo a la posición inicial.","Repite."],"tips":["Aterriza con los codos ligeramente flexionados para absorber el impacto.","Asegúrate de tener suficiente fuerza en la parte superior del cuerpo antes de intentarlo."],"met":7.0,"uni":false,"img":["clap-push-ups-start.webp","clap-push-ups-peak.webp"]},{"id":"clean","n":"Clean","d":"Un levantamiento olímpico en el que tiras de la barra de forma explosiva desde el suelo hasta la posición de rack frontal sobre los hombros.","cat":"olímpico","g":"cuerpo completo","bp":"full_body","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["glúteo mayor","cuádriceps"],"m2":["deltoides anterior","lumbares","isquiotibiales","trapecio"],"ins":["Colócate sobre una barra cargada con los pies a la anchura de las caderas.","Agarra la barra justo por fuera de las rodillas con un agarre prono.","Empuja de forma explosiva con las piernas y extiende las caderas.","Métete bajo la barra y recíbela sobre los deltoides anteriores.","Ponte completamente erguido para completar el levantamiento."],"tips":["Mantén la barra cerca del cuerpo mientras sube.","Completa el empuje de piernas antes de tirar por debajo de la barra.","Recibe con los codos altos para que la barra descanse en los hombros."],"met":8.0,"uni":false,"img":["clean-start.webp","clean-peak.webp"]},{"id":"clean-and-jerk","n":"Clean and Jerk","d":"Un levantamiento olímpico en dos partes: cargas la barra hasta los hombros y luego la impulsas por encima de la cabeza en posición de tijera.","cat":"olímpico","g":"cuerpo completo","bp":"full_body","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["deltoides anterior","glúteo mayor","cuádriceps"],"m2":["lumbares","trapecio","tríceps"],"ins":["Lleva la barra cargada desde el suelo hasta los hombros como en un clean.","Ponte completamente erguido con la barra apoyada en los deltoides anteriores.","Flexiona ligeramente las rodillas y lanza la barra sobre la cabeza de forma explosiva.","Separa las piernas para recibir la barra con los brazos extendidos.","Recupera la posición juntando los pies."],"tips":["Ponte de pie por completo y recoloca tu posición antes de iniciar el envión.","Impulsa la barra con las piernas, no solo con los brazos.","Bloquea los brazos mientras los pies aterrizan en la tijera."],"met":8.0,"uni":false,"img":["clean-and-jerk-start.webp","clean-and-jerk-peak.webp"]},{"id":"close-grip-barbell-curl","n":"Curl de Barra con Agarre Cerrado","d":"Un curl de barra de pie con agarre estrecho que enfatiza la cabeza larga del bíceps y el braquial.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"barra","home":false,"bw":false,"lv":"principiante","m":["bíceps"],"m2":["braquial","braquiorradial"],"ins":["De pie, sujeta la barra con un agarre supino con las manos más juntas que la anchura de los hombros.","Comienza con la barra a la altura de los muslos, brazos extendidos y codos pegados a los costados.","Sube la barra hasta los hombros flexionando los codos.","Aprieta los bíceps en la parte superior y luego baja de forma controlada.","Repite el número de repeticiones recomendado."],"tips":["Mantén los codos pegados a los costados; no dejes que se desplacen hacia adelante.","Si el agarre estrecho molesta las muñecas, usa una barra Z."],"met":5.0,"uni":false,"img":["close-grip-barbell-curl-start.webp","close-grip-barbell-curl-peak.webp"]},{"id":"close-grip-bench-press","n":"Press de Banca con Agarre Cerrado","d":"Una variación del press de banca con agarre estrecho que desplaza el énfasis hacia los tríceps.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["tríceps"],"m2":["deltoides anterior","pectoral"],"ins":["Túmbate en un banco plano y agarra la barra con las manos a la anchura de los hombros.","Baja la barra hasta el pecho inferior manteniendo los codos cerca de los costados.","Vuelve a empujar hasta la extensión completa.","Repite."],"tips":["Mantén los codos pegados para maximizar la activación de los tríceps.","Evita un agarre demasiado estrecho para prevenir tensión en las muñecas."],"met":6.0,"uni":false,"img":["close-grip-bench-press-start.webp","close-grip-bench-press-peak.webp"]},{"id":"close-grip-db-bench-press","n":"Press de Banca con Mancuernas y Agarre Cerrado","d":"Un press de banca con mancuernas sostenidas juntas para aumentar la participación de los tríceps.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["tríceps"],"m2":["deltoides anterior","pectoral"],"ins":["Túmbate en un banco plano y sostén dos mancuernas juntas sobre el pecho.","Bájalas hasta el pecho manteniendo los codos cerca.","Empuja hacia arriba.","Repite."],"tips":["Mantén las mancuernas presionadas entre sí durante todo el movimiento.","Mantén los codos pegados."],"met":6.0,"uni":false,"img":["close-grip-db-bench-press-start.webp","close-grip-db-bench-press-peak.webp"]},{"id":"close-grip-ez-bar-bench-press","n":"Press de Banca con Barra Z y Agarre Cerrado","d":"Un press enfocado en los tríceps con barra Z y agarre estrecho para mayor comodidad en las muñecas.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"barra Z","home":false,"bw":false,"lv":"intermedio","m":["tríceps"],"m2":["deltoides anterior","pectoral"],"ins":["Túmbate en un banco plano y agarra las curvas internas de la barra Z.","Baja la barra hasta el pecho con los codos pegados.","Empuja hacia arriba hasta la extensión completa.","Repite."],"tips":["La barra Z reduce la incomodidad en las muñecas.","Mantén el movimiento controlado."],"met":6.0,"uni":false,"img":["close-grip-ez-bar-bench-press-start.webp","close-grip-ez-bar-bench-press-peak.webp"]},{"id":"close-grip-ez-bar-curl","n":"Curl con Barra Z y Agarre Cerrado","d":"Un curl de bíceps con barra Z y manos juntas, que carga más la cabeza larga del bíceps.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"barra Z","home":false,"bw":false,"lv":"principiante","m":["bíceps"],"m2":["braquial"],"ins":["Sujeta una barra Z con las manos en las curvas internas, palmas arriba.","Mantén los codos pegados al cuerpo.","Sube la barra hasta los hombros contrayendo el bíceps.","Baja con control hasta el estiramiento completo.","Repite el número de repeticiones indicado."],"tips":["Mantén los codos pegados — no dejes que se vayan adelante.","Contrae fuerte arriba.","Evita balancear el torso para tomar impulso."],"met":5.0,"uni":false,"img":["close-grip-ez-bar-curl-start.webp","close-grip-ez-bar-curl-peak.webp"]},{"id":"close-grip-incline-bench","n":"Press de Banca Inclinado con Agarre Cerrado","d":"Un press de banca inclinado con agarre cerrado que trabaja los tríceps y el pecho superior.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["tríceps"],"m2":["deltoides anterior","pectoral"],"ins":["Ajusta el banco en inclinación. Agarra la barra con las manos a la anchura de los hombros o más juntas.","Baja la barra hasta el pecho superior.","Empuja hacia arriba.","Repite."],"tips":["La inclinación aumenta el estiramiento de la cabeza larga de los tríceps.","Mantén los codos pegados para mantener el foco en los tríceps."],"met":6.0,"uni":false,"img":["close-grip-incline-bench-start.webp","close-grip-incline-bench-peak.webp"]},{"id":"close-grip-lat-pulldown","n":"Jalón al Pecho con Agarre Cerrado","d":"Una variante del jalón al pecho con agarre cerrado y paralelo que enfatiza la parte baja del dorsal y el bíceps.","cat":"fuerza","g":"espalda","bp":"back","eq":"polea","home":false,"bw":false,"lv":"intermedio","m":["dorsales"],"m2":["bíceps","braquial","deltoides posterior","romboides"],"ins":["Siéntate en una máquina de jalón al pecho y asegura tus muslos bajo la almohadilla.","Sujeta el agarre cerrado con las palmas enfrentadas.","Tira de la barra hacia la parte superior del pecho.","Contrae el dorsal en la parte baja.","Vuelve con control y repite."],"tips":["Inclínate hacia atrás solo ligeramente, no en exceso.","Evita usar impulso para bajar la barra.","Lleva los codos hacia abajo y atrás, no solo las manos."],"met":6.0,"uni":false,"img":["close-grip-lat-pulldown-start.webp","close-grip-lat-pulldown-peak.webp"]},{"id":"close-grip-pull-ups","n":"Dominadas con Agarre Cerrado","d":"Una dominada con agarre prono estrecho que aumenta la activación de los bíceps y la parte interna de la espalda.","cat":"fuerza","g":"espalda","bp":"back","eq":"barra de dominadas","home":true,"bw":false,"lv":"intermedio","m":["bíceps","dorsales"],"m2":["romboides"],"ins":["Cuélgate de la barra de dominadas con las manos a la anchura de los hombros o más juntas, palmas mirando hacia afuera.","Súbete hasta que la barbilla supere la barra.","Baja de forma controlada.","Repite."],"tips":["El agarre estrecho aumenta la participación de los bíceps.","Evita los impulsos para el desarrollo de fuerza."],"met":6.0,"uni":false,"img":["close-grip-pull-ups-start.webp","close-grip-pull-ups-peak.webp"]},{"id":"close-grip-push-ups","n":"Flexiones con Agarre Cerrado","d":"Una variante de flexión con las manos juntas que enfatiza el tríceps.","cat":"fuerza","g":"pecho","bp":"chest","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["pectoral","tríceps"],"m2":["deltoides anterior","serrato"],"ins":["Adopta una posición de flexión con las manos directamente bajo los hombros.","Mantén los codos pegados a las costillas.","Baja el pecho hacia el suelo.","Empuja de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"tips":["Lleva los codos hacia atrás, no hacia los lados.","Mantén el cuerpo rígido como una tabla durante todo el movimiento.","Baja despacio para mayor activación del tríceps."],"met":5.0,"uni":false,"img":["close-grip-push-ups-start.webp","close-grip-push-ups-peak.webp"]},{"id":"close-stance-leg-press","n":"Prensa de piernas con postura cerrada","d":"Una prensa de piernas con los pies juntos, que aumenta la flexión de rodilla y mantiene el énfasis en los cuádriceps con la espalda apoyada.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"prensa","home":false,"bw":false,"lv":"principiante","m":["cuádriceps"],"m2":["glúteo mayor","isquiotibiales"],"ins":["Ajusta el asiento y el respaldo para que la zona lumbar permanezca apoyada durante toda la repetición.","Coloca los pies juntos cerca del centro de la plataforma y alinea rodillas y puntas de los pies.","Baja el carro flexionando rodillas y caderas mientras mantienes ambos pies planos.","Empuja la plataforma con todo el pie y extiende las piernas sin golpear el bloqueo de las rodillas.","Regresa bajo control y repite el número deseado de repeticiones."],"tips":["Usa solo la postura más cerrada que permita que las rodillas sigan cómodamente a los pies.","Mantén los talones abajo y evita que las rodillas se junten al descender.","No sacrifiques la posición de la pelvis para conseguir más profundidad."],"met":6.0,"uni":false,"img":["close-stance-leg-press-start.webp","close-stance-leg-press-peak.webp"]},{"id":"cobra-stretch","n":"Estiramiento de la Cobra","d":"Una extensión boca abajo que estira los abdominales y la parte frontal del torso al elevar el pecho.","cat":"estiramiento","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["abdominales"],"m2":["flexores de cadera","transverso abdominal"],"ins":["Acuéstate boca abajo con las manos bajo los hombros.","Empuja con las manos para levantar el pecho del suelo.","Mantén caderas y piernas en el suelo, con los hombros relajados.","Mantén de 20 a 30 segundos, respirando de forma constante."],"tips":["Mantén los codos algo flexionados, no fuerces la extensión completa.","Baja los hombros alejándolos de las orejas."],"met":5.0,"uni":false,"img":["cobra-stretch-main.webp"]},{"id":"cocoons","n":"Cocoons","d":"Un ejercicio abdominal dinámico que combina un encogimiento de rodillas con un crunch desde una posición extendida boca arriba.","cat":"fuerza","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["abdominales"],"m2":["flexores de cadera","oblicuos"],"ins":["Túmbate boca arriba con los brazos extendidos sobre la cabeza; manos y pies ligeramente elevados.","Lleva las rodillas al pecho y balancea los brazos hacia adelante en un crunch simultáneamente.","Intenta tocar las espinillas con las manos en el punto máximo.","Extiende brazos y piernas de forma controlada sin tocar el suelo.","Repite el movimiento durante las repeticiones indicadas."],"tips":["Las manos y los pies no tocan el suelo entre repeticiones.","Exhala con fuerza al llegar al punto máximo."],"met":5.0,"uni":false,"img":["cocoons-start.webp","cocoons-peak.webp"]},{"id":"commando-pull-up","n":"Dominada Commando","d":"Una variante de la dominada con agarre escalonado: las manos se colocan una delante de la otra en la barra y el cuerpo queda de lado, de modo que la cabeza pasa junto a la barra en cada repetición. Exige más a los dorsales, los brazos y el tronco que una dominada estándar.","cat":"fuerza","g":"espalda","bp":"back","eq":"barra de dominadas","home":true,"bw":false,"lv":"avanzado","m":["bíceps","dorsales"],"m2":["braquial","braquiorradial","antebrazo","oblicuos","romboides","trapecio"],"ins":["Agarra la barra con las manos una delante de la otra, con las palmas enfrentadas, y cuélgate con los brazos estirados y el cuerpo girado de lado.","Aprieta el tronco y baja los omóplatos para iniciar el movimiento.","Sube llevando los codos hacia abajo hasta que la cabeza pase la barra por uno de sus lados.","Haz una breve pausa arriba con el pecho cerca de la barra.","Baja de forma controlada hasta colgarte por completo.","En la siguiente repetición pasa la cabeza al otro lado de la barra, o cambia la posición de las manos en cada serie."],"tips":["Mantén quietos las piernas y el tronco; si te balanceas, la dominada se convierte en un kipping.","Alterna los lados por igual para que ambos brazos y dorsales hagan el mismo trabajo.","Empieza con pocas repeticiones por serie: el agarre escalonado es más difícil que una dominada normal."],"met":6.0,"uni":false,"img":["commando-pull-up-start.webp","commando-pull-up-peak.webp"]},{"id":"concentration-curl","n":"Curl de Concentración","d":"Un curl de aislamiento realizado sentado para la máxima contracción del bíceps.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"mancuernas","home":true,"bw":false,"lv":"principiante","m":["bíceps"],"m2":["braquial"],"ins":["Siéntate en un banco con las piernas separadas y sujeta una mancuerna en una mano.","Apoya el codo en la cara interna del muslo.","Sube la mancuerna hacia el hombro.","Baja con control.","Repite en ambos lados."],"tips":["No balancees el torso para ayudarte a subir.","Gira ligeramente la muñeca hacia fuera para contraer más el bíceps.","Trabaja ambos brazos por igual, empezando por el más débil."],"met":5.0,"uni":true,"img":["concentration-curl-start.webp","concentration-curl-peak.webp"]},{"id":"cossack-squat","n":"Sentadilla cosaca","d":"Una sentadilla lateral de base amplia que hunde el cuerpo profundamente sobre una pierna flexionada mientras la otra permanece recta, entrenando fuerza unilateral, movilidad de cadera y flexibilidad de aductores.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["glúteo mayor","cuádriceps"],"m2":["aductores","isquiotibiales"],"ins":["Ponte en una postura amplia con las puntas de los pies ligeramente hacia afuera.","Desplaza el peso hacia un lado, flexiona esa rodilla y húndete en una sentadilla profunda.","Mantén la pierna contraria recta, con el talón en el suelo y los dedos hacia arriba.","Baja tanto como te permita tu movilidad, manteniendo el pecho erguido.","Empuja con la pierna flexionada para volver al centro y repite hacia el otro lado."],"tips":["Mantén el talón de la pierna que trabaja apoyado: no ruedes hacia las puntas.","Apunta con los dedos de la pierna recta hacia arriba para mantener tensión en los aductores.","Sujeta un peso ligero frente al pecho como contrapeso si lo necesitas."],"met":6.0,"uni":true,"img":["cossack-squat-start.webp","cossack-squat-peak.webp"]},{"id":"cow-face-pose","n":"Postura de la Cara de Vaca","d":"Una postura sentada con las rodillas apiladas y los brazos enlazados a la espalda, que estira la cadera externa de un lado y los hombros en direcciones opuestas.","cat":"estiramiento","g":"hombros","bp":"shoulders","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["glúteo mayor","glúteo medio"],"m2":["deltoides posterior","tríceps"],"ins":["Siéntate en el suelo y cruza una rodilla justo encima de la otra para que queden apiladas en la línea media.","Camina los pies hacia las caderas y apoya ambos isquiones por igual.","Sube el brazo del lado de la rodilla superior y flexiónalo por detrás de la cabeza; sube el otro brazo por la espalda hasta engancharlos.","Mantén la posición durante el tiempo indicado, con el pecho abierto y la columna larga.","Suelta y repite con la otra pierna y el otro brazo arriba."],"tips":["Siéntate sobre una manta doblada si un isquion se despega del suelo.","Usa una cinta entre las manos cuando los dedos no se toquen; forzar el enganche redondea la espalda.","Mantén el codo de arriba apuntando al techo en lugar de dejarlo abrirse hacia el lado."],"met":5.0,"uni":true,"img":["cow-face-pose-main.webp"]},{"id":"crab-dips","n":"Fondos de Cangrejo","d":"Un ejercicio de tríceps en el suelo desde la mesa invertida: con las manos detrás de las caderas y el tronco elevado, los codos se flexionan y estiran para subir y bajar el cuerpo.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["tríceps"],"m2":["deltoides anterior","glúteo mayor","pectoral"],"ins":["Siéntate con las rodillas flexionadas, los pies apoyados y las manos en el suelo detrás de ti, con los dedos hacia los talones.","Empuja con manos y pies y eleva las caderas hasta que el tronco quede a la altura de las rodillas.","Flexiona los codos hacia atrás para bajar las caderas hacia el suelo sin sentarte.","Empuja de nuevo hasta estirar los brazos, manteniendo las caderas elevadas.","Repite las veces indicadas y baja las caderas para terminar."],"tips":["Mantén los codos apuntando hacia atrás, sin abrirlos hacia los lados.","Sostén las caderas altas toda la serie; dejarlas caer convierte el ejercicio en un descanso.","Aleja más los pies para alargar la palanca y exigir más al tríceps."],"met":5.0,"uni":false,"img":["crab-dips-start.webp","crab-dips-peak.webp"]},{"id":"crescent-lunge","n":"Zancada Alta","d":"Un sostén en paso largo con el talón trasero elevado y los brazos arriba, que carga la pierna delantera mientras la cadera trasera se mantiene larga.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["glúteo mayor","cuádriceps"],"m2":["lumbares","flexores de cadera"],"ins":["Adelanta un pie a un paso largo con el talón trasero elevado y los dedos apuntando al frente.","Flexiona la rodilla delantera unos noventa grados para que quede sobre el tobillo.","Lleva la cadera trasera hacia delante hasta que ambas apunten al frente de la esterilla y eleva los brazos.","Mantén la posición durante el tiempo indicado, con las costillas cerradas y la pierna trasera estirada.","Junta los pies y repite del otro lado."],"tips":["Separa un poco los pies lateralmente si el equilibrio es lo que te limita.","Empuja el talón trasero hacia la pared de detrás para mantener activa la pierna de atrás.","Baja los brazos a las caderas si estirarlos arriba te arquea la zona lumbar."],"met":5.0,"uni":true,"img":["crescent-lunge-main.webp"]},{"id":"cross-body-crunch","n":"Crunch Cruzado","d":"Un crunch de oblicuos en el suelo que acerca el codo y la rodilla opuestos entre sí, trabajando los oblicuos y el recto abdominal juntos.","cat":"fuerza","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["oblicuos"],"m2":["abdominales"],"ins":["Túmbate boca arriba en el suelo con las rodillas dobladas y las manos ligeramente detrás de las orejas.","Contrae y rota llevando el codo derecho hacia la rodilla izquierda mientras la rodilla sube.","Regresa a la posición inicial de forma controlada.","Repite del otro lado, alternando en cada repetición."],"tips":["Gira desde la caja torácica, no desde los brazos; los codos siguen a los hombros.","La zona lumbar permanece en el suelo durante todo el ejercicio."],"met":3.5,"uni":false,"img":["cross-body-crunch-start.webp","cross-body-crunch-peak.webp"]},{"id":"cross-body-hammer-curl","n":"Curl Martillo Cruzado","d":"Un curl con agarre neutro que lleva la mancuerna cruzando el cuerpo hacia el hombro opuesto, enfatizando el braquial y los antebrazos.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["braquial","braquiorradial"],"m2":["bíceps","antebrazo"],"ins":["De pie, sujeta una mancuerna en cada mano con agarre neutro.","Sube una mancuerna cruzando el cuerpo hacia el hombro opuesto.","Mantén el codo fijo a tu costado.","Baja de forma controlada y repite del otro lado.","Continúa alternando el número de repeticiones deseado."],"tips":["Mantén el codo pegado al costado durante todo el curl.","Evita balancear el torso para levantar el peso.","Baja con control en lugar de dejar caer la mancuerna."],"met":5.0,"uni":false,"img":["cross-body-hammer-curl-start.webp","cross-body-hammer-curl-peak.webp"]},{"id":"cross-body-shoulder-stretch","n":"Estiramiento de Hombro Cruzado","d":"Un estiramiento de pie para el hombro posterior llevando un brazo en horizontal sobre el pecho.","cat":"estiramiento","g":"hombros","bp":"shoulders","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["deltoides posterior"],"m2":["romboides"],"ins":["Párate erguido y cruza un brazo estirado sobre el pecho.","Engancha el otro antebrazo por debajo.","Tira suavemente del brazo hacia el pecho.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],"tips":["Mantén el hombro estirado abajo, sin encogerlo.","No tires de la articulación del codo en sí."],"met":5.0,"uni":true,"img":["cross-body-shoulder-stretch-main.webp"]},{"id":"crow-pose","n":"Postura del Cuervo","d":"Un equilibrio sobre brazos: las rodillas descansan en la parte posterior de los brazos y los pies se elevan, sostenidos por hombros, brazos y tronco.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"sin equipo","home":true,"bw":true,"lv":"avanzado","m":["deltoides anterior","tríceps"],"m2":["abdominales","serrato"],"ins":["Ponte en cuclillas con los pies juntos y apoya las palmas en el suelo a la anchura de los hombros.","Flexiona los codos hacia atrás y coloca las rodillas altas sobre la parte posterior de los brazos.","Desplaza el peso hacia delante sobre las manos hasta que los pies se despeguen del suelo.","Mantén el equilibrio durante el tiempo indicado, con la espalda alta redondeada y la mirada algo adelante.","Baja los pies de forma controlada."],"tips":["Mira al suelo por delante de las manos, no hacia los pies; la mirada dirige el equilibrio.","Coloca un cojín delante mientras aprendes, para caer hacia delante sin riesgo.","Agarra el suelo con las yemas de los dedos para que el peso no se vaya a las muñecas."],"met":5.0,"uni":false,"img":["crow-pose-main.webp"]},{"id":"crunches","n":"Crunches","d":"Un ejercicio abdominal básico enfocado en el recto abdominal.","cat":"fuerza","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["abdominales"],"m2":["oblicuos"],"ins":["Túmbate boca arriba con las rodillas dobladas y las manos detrás de la cabeza.","Enrolla el tronco superior hacia las rodillas levantando los omóplatos del suelo.","Aprieta el abdomen en la posición superior.","Baja con control.","Repite."],"tips":["No tires del cuello con las manos al subir.","Exhala al subir y mantén la zona lumbar pegada al suelo.","Piensa en acercar las costillas a la pelvis, no en sentarte."],"met":3.5,"uni":false,"img":["crunches-start.webp","crunches-peak.webp"]},{"id":"cycling","n":"Ciclismo","d":"Montar en bicicleta de carretera como cardio de resistencia a ritmo constante. Sentado en el sillín con las manos en el manillar, pedaleas en círculos suaves; los muslos impulsan cada pedalada, mientras que los glúteos, los isquiotibiales y las pantorrillas la completan.","cat":"cardio","g":"piernas","bp":"upper_legs","eq":"bicicleta","home":false,"bw":false,"lv":"principiante","m":["cuádriceps"],"m2":["gemelos","glúteo mayor","isquiotibiales","sóleo"],"ins":["Ajusta el sillín para que la rodilla quede solo ligeramente flexionada cuando el pedal esté en el punto más bajo de la pedalada.","Siéntate en el sillín con las manos en el manillar, los codos ligeramente flexionados y los hombros relajados.","Coloca los metatarsos sobre los ejes de los pedales.","Empuja cada pedal hacia abajo y hacia delante, y luego deja que suba y pase por arriba en un círculo suave.","Mantén una cadencia constante y elige una marcha que te permita pedalear sin rebotar en el sillín.","Pedalea durante el tiempo o la distancia previstos, bajando el ritmo en los últimos minutos para volver a la calma."],"tips":["Mantén las rodillas en línea con los pies; si las rodillas se van hacia dentro o hacia fuera, normalmente hay que ajustar el sillín o las calas.","Una cadencia más alta con una marcha más suave cuida más las rodillas que mover despacio una marcha dura.","Mantén el tren superior relajado y la espalda larga, en lugar de encorvada o balanceándose de lado a lado."],"met":8.0,"uni":false,"img":["cycling-main.webp"]},{"id":"dancer-pose","n":"Postura del Bailarín","d":"Un equilibrio de pie sobre una pierna en el que el pie libre se sujeta por detrás y empuja hacia atrás, combinando extensión de columna y sostén unipodal.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"avanzado","m":["glúteo mayor","cuádriceps"],"m2":["lumbares","flexores de cadera"],"ins":["Ponte de pie y pasa el peso a un pie, con esa rodilla ligeramente flexionada.","Flexiona la otra rodilla y agarra la cara interna de ese tobillo por detrás.","Empuja el pie elevado contra la mano y estira el brazo contrario hacia delante mientras el pecho sube.","Mantén la forma durante el tiempo indicado, con la cadera de apoyo nivelada y la mirada fija.","Suelta el pie y repite del otro lado."],"tips":["Fija los ojos en un punto; una mirada que se mueve es lo primero que rompe el equilibrio.","Mantén la rodilla elevada en línea con la cadera en lugar de dejarla abrirse hacia fuera.","Usa una cinta alrededor del pie si el hombro no permite el agarre directo."],"met":5.0,"uni":true,"img":["dancer-pose-main.webp"]},{"id":"db-bench-press","n":"Press de Banca con Mancuernas","d":"Un ejercicio compuesto de pecho con mancuernas que permite mayor rango de movimiento que el press de banca con barra.","cat":"fuerza","g":"pecho","bp":"chest","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["pectoral"],"m2":["deltoides anterior","tríceps"],"ins":["Túmbate en un banco plano sosteniendo una mancuerna en cada mano a la altura del pecho.","Empuja las mancuernas hacia arriba hasta extender completamente los brazos.","Bájalas lentamente hasta la posición inicial.","Repite."],"tips":["Mantén las muñecas neutras durante todo el ejercicio.","Aprieta el pecho en la parte superior del movimiento."],"met":6.0,"uni":false,"img":["db-bench-press-start.webp","db-bench-press-peak.webp"]},{"id":"db-fly","n":"Aperturas con Mancuernas","d":"Un ejercicio de aislamiento que estira y contrae el pectoral a través de un amplio arco de movimiento.","cat":"fuerza","g":"pecho","bp":"chest","eq":"mancuernas","home":true,"bw":false,"lv":"principiante","m":["pectoral"],"m2":["deltoides anterior"],"ins":["Túmbate en un banco con las mancuernas sobre el pecho y las palmas mirándose entre sí.","Con una ligera flexión de codos, baja las mancuernas hacia los lados.","Regresa a la posición inicial apretando el pecho.","Repite."],"tips":["Mantén una flexión constante en los codos durante todo el ejercicio.","No bajes demasiado las mancuernas."],"met":5.0,"uni":false,"img":["db-fly-start.webp","db-fly-peak.webp"]},{"id":"db-kickstand-deadlift","n":"Peso Muerto Kickstand con Mancuerna","d":"Un movimiento de bisagra de cadera en postura escalonada con una mancuerna que carga la pierna delantera mientras el pie trasero ofrece apoyo ligero.","cat":"fuerza","g":"espalda","bp":"back","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["glúteo mayor","isquiotibiales"],"m2":["aductores","lumbares"],"ins":["Coloca un pie detrás de modo que solo los dedos rocen el suelo.","Sostén una mancuerna en la mano del lado del pie trasero.","Bisagra en la cadera bajando la mancuerna hacia la espinilla con la espalda recta.","Mantén la mayor parte del peso en el pie delantero.","Empuja con el talón delantero para volver a la posición inicial. Completa todas las repeticiones antes de cambiar de lado."],"tips":["Mantén la mancuerna cerca de la pierna durante el descenso.","Para cuando notes el estiramiento en el isquiotibial de la pierna delantera.","Completa todas las repeticiones en un lado antes de cambiar."],"met":6.0,"uni":true,"img":["db-kickstand-deadlift-start.webp","db-kickstand-deadlift-peak.webp"]},{"id":"db-lunge","n":"Zancada con Mancuernas","d":"Un ejercicio unilateral de tren inferior con mancuernas que trabaja los cuádriceps y los glúteos mediante un paso adelante.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["glúteo mayor","cuádriceps"],"m2":["isquiotibiales"],"ins":["De pie, sujeta mancuernas a los costados.","Da un paso adelante con un pie y baja la rodilla trasera hacia el suelo.","Empuja con el pie delantero para volver.","Alterna las piernas.","Repite."],"tips":["Mantén el torso erguido.","La rodilla delantera debe seguir la dirección de los pies."],"met":6.0,"uni":true,"img":["db-lunge-start.webp","db-lunge-peak.webp"]},{"id":"db-overhead-carry","n":"Paseo con Mancuerna sobre la Cabeza","d":"Un paseo cargado con una sola mancuerna bloqueada por encima del hombro, que exige estabilidad de hombro y un tronco erguido en cada paso.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["deltoides anterior","deltoides lateral"],"m2":["oblicuos","cuadrado lumbar","serrato","transverso abdominal","trapecio","tríceps"],"ins":["Lleva una mancuerna, en cargada o press, hasta quedar bloqueada justo encima del hombro.","Estira el brazo del todo, con el codo bloqueado y el bíceps cerca de la oreja.","Lleva las costillas hacia abajo en lugar de arquear la zona lumbar para sostener el peso arriba.","Camina hacia delante con zancadas controladas, manteniendo la mancuerna alineada sobre hombro y cadera.","Mira al frente — echar la cabeza atrás para vigilar el peso arrastra contigo toda la postura.","Carga la distancia deseada, baja de forma controlada y repite con el otro brazo."],"tips":["Iguala la distancia con ambos brazos para que la carga asimétrica no se convierta en una adaptación asimétrica.","El codo bloqueado no es opcional. Con el codo blando toda la carga recae en el músculo en lugar del esqueleto y la serie se acaba enseguida.","Si las costillas se abren y la espalda se arquea, el peso excede tu posición actual por encima de la cabeza — corrige la posición antes de añadir carga."],"met":5.5,"uni":true,"img":["db-overhead-carry-main.webp"]},{"id":"db-preacher-curl","n":"Curl Predicador con Mancuernas","d":"Un curl de aislamiento de bíceps con una mancuerna en cada mano y la parte superior de los brazos apoyada en un banco predicador. El pad fija los codos en su sitio, así que el bíceps hace el trabajo casi sin balanceo.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"mancuernas","home":true,"bw":false,"lv":"principiante","m":["bíceps"],"m2":["braquial","braquiorradial"],"ins":["Ajusta el asiento para que las axilas descansen contra la parte superior del pad y la parte superior de los brazos quede plana sobre él.","Sujeta una mancuerna en cada mano con agarre supino y deja que los brazos cuelguen a lo largo del pad.","Sube ambas mancuernas hacia los hombros sin despegar los codos del pad.","Aprieta brevemente los bíceps arriba.","Baja las mancuernas despacio hasta que los brazos queden casi extendidos y repite."],"tips":["Detente justo antes de la extensión completa abajo para mantener la tensión en el bíceps y proteger los codos.","Mantén el pecho pegado al pad; si te echas hacia atrás, los hombros toman el relevo.","Baja los pesos despacio; no los dejes caer."],"met":5.0,"uni":false,"img":["db-preacher-curl-start.webp","db-preacher-curl-peak.webp"]},{"id":"db-pullover","n":"Pullover con Mancuerna","d":"Un movimiento compuesto que trabaja los dorsales y el pecho con un movimiento de estiramiento.","cat":"fuerza","g":"pecho","bp":"chest","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["dorsales","pectoral"],"m2":["tríceps"],"ins":["Túmbate en un banco plano con una mancuerna sobre el pecho y los brazos extendidos.","Baja la mancuerna detrás de la cabeza en arco, manteniendo una ligera flexión de codos.","Estira hasta sentir tensión en los dorsales y el pecho.","Tira de la mancuerna de vuelta a la posición inicial.","Repite."],"tips":["Baja la mancuerna solo hasta donde el hombro lo permita.","Evita arquear la zona lumbar en la fase de estiramiento.","Mantén la flexión de los codos constante durante todo el arco."],"met":6.0,"uni":false,"img":["db-pullover-start.webp","db-pullover-peak.webp"]},{"id":"db-reverse-curl","n":"Curl Inverso con Mancuernas","d":"Una variación del curl con agarre prono que trabaja el braquial y los extensores del antebrazo.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"mancuernas","home":true,"bw":false,"lv":"principiante","m":["braquial","antebrazo"],"m2":["bíceps"],"ins":["Sujeta las mancuernas con agarre prono a los costados.","Súbelas hasta la altura de los hombros.","Baja de forma controlada.","Repite."],"tips":["Mantén las muñecas neutras durante todo el ejercicio.","El movimiento controlado es clave."],"met":5.0,"uni":false,"img":["db-reverse-curl-start.webp","db-reverse-curl-peak.webp"]},{"id":"db-reverse-wrist-curl","n":"Curl de Muñeca Inverso con Mancuerna","d":"Un curl de muñeca con mancuerna y palma hacia abajo, que entrena los extensores del antebrazo.","cat":"fuerza","g":"brazos","bp":"lower_arms","eq":"mancuernas","home":true,"bw":false,"lv":"principiante","m":["antebrazo"],"m2":[],"ins":["Siéntate en un banco con el antebrazo sobre el muslo, palma hacia abajo.","Sujeta una mancuerna con la muñeca fuera de la rodilla.","Deja caer la muñeca, bajando la mancuerna.","Levanta el dorso de la mano hacia el techo extendiendo la muñeca.","Baja con control. Repeticiones por lado."],"tips":["Usa una carga mucho más ligera que en el curl de muñeca normal.","Mueve solo la muñeca.","Contrae la parte posterior del antebrazo arriba."],"met":5.0,"uni":false,"img":["db-reverse-wrist-curl-start.webp","db-reverse-wrist-curl-peak.webp"]},{"id":"db-shrug","n":"Encogimiento de Hombros con Mancuernas","d":"Un encogimiento de hombros con mancuernas que trabaja el trapecio superior para dar volumen al cuello y la espalda alta.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"mancuernas","home":true,"bw":false,"lv":"principiante","m":["trapecio"],"m2":["romboides"],"ins":["De pie, sujeta mancuernas a los costados.","Encoge los hombros hacia arriba lo más alto posible.","Mantén brevemente y luego baja.","Repite."],"tips":["No hagas círculos con los hombros.","Concéntrate en apretar el trapecio en la posición superior."],"met":5.0,"uni":false,"img":["db-shrug-start.webp","db-shrug-peak.webp"]},{"id":"db-skull-crusher","n":"Skull Crusher con Mancuernas","d":"Una extensión de tríceps tumbado con mancuernas que permite el movimiento independiente de cada brazo.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["tríceps"],"m2":[],"ins":["Túmbate en un banco plano sosteniendo mancuernas sobre el pecho.","Baja las mancuernas hacia los lados de la cabeza.","Extiende los brazos hacia arriba.","Repite."],"tips":["Mantén los codos apuntando hacia el techo.","Usa un tempo controlado."],"met":5.0,"uni":false,"img":["db-skull-crusher-start.webp","db-skull-crusher-peak.webp"]},{"id":"db-somersault-squat","n":"Sentadilla Somersault con Mancuerna","d":"Una sentadilla unilateral con alcance y mancuerna, que añade rotación y movilidad de hombro al patrón de sentadilla.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["glúteo mayor","cuádriceps"],"m2":["isquiotibiales","oblicuos"],"ins":["Pies a la anchura de los hombros, sostén una mancuerna en una mano a la altura del hombro.","Baja en sentadilla mientras llevas la mancuerna al frente y cruzando el cuerpo.","Alcanza el punto bajo con la mancuerna extendida pasando la rodilla opuesta.","Empuja con los talones para subir, regresando la mancuerna al hombro.","Repeticiones por lado, luego cambia."],"tips":["Mueve lento durante la rotación para mantener la columna controlada.","Usa una mancuerna ligera — la palanca larga exige al hombro.","Empuja las rodillas afuera para mantener la trayectoria estable."],"met":6.0,"uni":true,"img":["db-somersault-squat-start.webp","db-somersault-squat-peak.webp"]},{"id":"db-squat","n":"Sentadilla con Mancuernas","d":"Una sentadilla cargada con una mancuerna en cada mano a los costados, accesible sin barra.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"mancuernas","home":true,"bw":false,"lv":"principiante","m":["glúteo mayor","cuádriceps"],"m2":["isquiotibiales"],"ins":["Pies a la anchura de los hombros, una mancuerna en cada mano a los lados.","Activa el core y mantén el pecho arriba.","Baja en sentadilla flexionando caderas y rodillas.","Desciende hasta que los muslos queden paralelos o más abajo.","Empuja con los talones para volver a subir."],"tips":["Mantén el pecho arriba y la espalda recta.","Empuja las rodillas en línea con los dedos del pie.","Usa straps si el agarre se convierte en el factor limitante."],"met":6.0,"uni":false,"img":["db-squat-start.webp","db-squat-peak.webp"]},{"id":"db-sumo-squat","n":"Sentadilla Sumo con Mancuernas","d":"Una sentadilla de pies anchos con mancuernas sujetadas a los lados, que enfatiza la cara interna de los muslos y los glúteos.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"mancuernas","home":true,"bw":false,"lv":"principiante","m":["glúteo mayor","cuádriceps"],"m2":["aductores","glúteo medio","isquiotibiales"],"ins":["Ponte de pie con los pies más anchos que los hombros y las puntas giradas hacia afuera unos 30 grados.","Sujeta una mancuerna en cada mano a los lados.","Activa el core y mantén el pecho alto.","Flexiona caderas y rodillas para bajar recto en una sentadilla profunda.","Empuja con los talones para volver a ponerte de pie.","Repite el número de repeticiones deseado."],"tips":["Alinea las rodillas con las puntas de los pies; no dejes que se vayan hacia dentro.","Mantén el torso tan erguido como te permita la movilidad de cadera.","Elige mancuernas más ligeras que en una sentadilla normal; el agarre es el límite."],"met":6.0,"uni":false,"img":["db-sumo-squat-start.webp","db-sumo-squat-peak.webp"]},{"id":"db-svend-press","n":"Press Svend con Mancuernas","d":"Un ejercicio de pecho de pie presionando dos mancuernas entre sí frente al cuerpo, donde la presión hacia dentro mantiene los pectorales en tensión constante.","cat":"fuerza","g":"pecho","bp":"chest","eq":"mancuernas","home":true,"bw":false,"lv":"principiante","m":["pectoral"],"m2":["deltoides anterior","tríceps"],"ins":["De pie, junta dos mancuernas horizontalmente a la altura del pecho.","Mantén la presión hacia adentro sobre las mancuernas todo el tiempo.","Empuja las mancuernas al frente hasta que los brazos queden casi estirados.","Tíralas de regreso al pecho con control.","Repite el número de repeticiones indicado."],"tips":["La presión entre las mancuernas hace el ejercicio — no dejes que se separen.","Usa carga ligera — el objetivo es activar el pecho, no levantar mucho.","Mantén los codos ligeramente flexionados en el lockout."],"met":5.0,"uni":false,"img":["db-svend-press-start.webp","db-svend-press-peak.webp"]},{"id":"dead-bug","n":"Dead Bug","d":"Un ejercicio de core en decúbito supino que coordina la extensión de extremidades opuestas para entrenar la estabilidad del core profundo.","cat":"fuerza","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["abdominales","transverso abdominal"],"m2":["flexores de cadera"],"ins":["Túmbate boca arriba con los brazos extendidos hacia el techo y las rodillas a 90 grados.","Baja el brazo derecho y la pierna izquierda hacia el suelo manteniendo la zona lumbar presionada contra el suelo.","Regresa a la posición inicial.","Repite del otro lado.","Alterna."],"tips":["Presiona la zona lumbar contra el suelo en todo momento.","Muévete despacio."],"met":5.0,"uni":false,"img":["dead-bug-start.webp","dead-bug-peak.webp"]},{"id":"dead-bug-hold","n":"Dead Bug Isométrico","d":"La posición extendida del dead bug mantenida en el tiempo: tumbado boca arriba con un brazo por encima de la cabeza y la pierna contraria estirada justo por encima del suelo, con la zona lumbar pegada al suelo.","cat":"fuerza","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["abdominales","transverso abdominal"],"m2":["flexores de cadera"],"ins":["Túmbate boca arriba con los brazos apuntando al techo y las caderas y rodillas flexionadas a 90 grados.","Presiona la zona lumbar contra el suelo y mantenla ahí durante toda la serie.","Extiende un brazo por encima de la cabeza y estira la pierna contraria hasta que ambos queden suspendidos justo sobre el suelo.","Mantén esa posición extendida durante el tiempo indicado, sin que las costillas se abran ni la espalda se arquee.","Vuelve al inicio y repite con el otro brazo y la otra pierna."],"tips":["Si la zona lumbar se despega del suelo, mantén la pierna más alta en lugar de buscar el suelo.","Exhala despacio durante el mantenimiento; aguantar la respiración es lo que suele romper la tensión del tronco.","Mantén el brazo extendido junto a la oreja, no abierto hacia el lado."],"met":5.0,"uni":false,"img":["dead-bug-hold-main.webp"]},{"id":"dead-hang","n":"Colgado Pasivo","d":"Una suspensión estática en barra de dominadas que fortalece el agarre y la musculatura de antebrazos y espalda.","cat":"fuerza","g":"espalda","bp":"back","eq":"barra de dominadas","home":true,"bw":false,"lv":"intermedio","m":["antebrazo"],"m2":["dorsales","abdominales","trapecio"],"ins":["Agarra la barra de dominadas con las palmas mirando hacia afuera, a la anchura de los hombros.","Cuélgate con los brazos completamente extendidos y los pies sin tocar el suelo.","Relaja los hombros y deja que el cuerpo cuelgue.","Mantén el core ligeramente activo.","Aguanta el tiempo deseado."],"tips":["Empieza con tiempos cortos y auméntalos de forma gradual.","Respira tranquilo y evita tensar el cuello.","Baja con control en lugar de soltarte de golpe."],"met":4.5,"uni":false,"img":["dead-hang-main.webp"]},{"id":"deadlift","n":"Peso Muerto con Barra","d":"Un levantamiento compuesto de cuerpo completo que trabaja principalmente la cadena posterior.","cat":"fuerza","g":"espalda","bp":"back","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["lumbares","glúteo mayor","isquiotibiales"],"m2":["cuádriceps","trapecio"],"ins":["De pie con los pies a la anchura de las caderas y la barra sobre el medio del pie.","Bisagra en las caderas y agarra la barra.","Contrae el core y levanta extendiendo caderas y rodillas.","Ponte completamente erguido arriba y luego baja de forma controlada.","Repite."],"tips":["Mantén la barra cerca del cuerpo.","No redondees la zona lumbar."],"met":6.0,"uni":false,"img":["deadlift-start.webp","deadlift-peak.webp"]},{"id":"decline-bench-press","n":"Press de Banca Declinado","d":"Un press de pecho compuesto en banco declinado con una mancuerna en cada mano que trabaja el pectoral inferior.","cat":"fuerza","g":"pecho","bp":"chest","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["pectoral"],"m2":["deltoides anterior","tríceps"],"ins":["Ajusta el banco en declinación. Túmbate y asegura los pies.","Sujeta una mancuerna en cada mano por encima del pecho y bájalas a los lados del pecho inferior.","Vuelve a empujar las mancuernas hasta la posición inicial.","Repite."],"tips":["Mantén la espalda plana sobre el banco.","Usa un ayudante cuando trabajes con cargas más pesadas."],"met":6.0,"uni":false,"img":["decline-bench-press-start.webp","decline-bench-press-peak.webp"]},{"id":"decline-bench-press-barbell","n":"Press de Banca Declinado con Barra","d":"Un press compuesto con barra en banco declinado que enfatiza el pecho inferior.","cat":"fuerza","g":"pecho","bp":"chest","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["pectoral"],"m2":["deltoides anterior","tríceps"],"ins":["Ajusta el banco en declinación. Túmbate y asegura los pies.","Agarra la barra ligeramente más ancha que la anchura de los hombros.","Baja la barra hasta el pecho inferior y luego empuja hacia arriba.","Repite."],"tips":["Controla el descenso.","Mantén los codos a unos 45 grados respecto al torso."],"met":6.0,"uni":false,"img":["decline-bench-press-barbell-start.webp","decline-bench-press-barbell-peak.webp"]},{"id":"decline-bench-press-ez-bar","n":"Press de Banca Declinado con Barra Z","d":"Un press declinado con barra Z y agarre cómodo para las muñecas que trabaja el pecho inferior.","cat":"fuerza","g":"pecho","bp":"chest","eq":"barra Z","home":false,"bw":false,"lv":"intermedio","m":["pectoral"],"m2":["deltoides anterior","tríceps"],"ins":["Ajusta el banco en declinación. Asegura los pies y agarra la barra Z.","Baja la barra hasta el pecho inferior.","Empuja hacia arriba de forma explosiva.","Repite."],"tips":["El agarre angulado reduce la tensión en las muñecas.","Mantén el core contraído."],"met":6.0,"uni":false,"img":["decline-bench-press-ez-bar-start.webp","decline-bench-press-ez-bar-peak.webp"]},{"id":"decline-crunch","n":"Crunch Declinado","d":"Un crunch realizado en banco declinado, aumentando el rango de movimiento y la resistencia sobre los abdominales.","cat":"fuerza","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["abdominales"],"m2":["flexores de cadera","oblicuos"],"ins":["Asegura los pies en la parte superior del banco declinado.","Recuéstate con las manos cruzadas sobre el pecho o detrás de la cabeza.","Sube contrayendo la columna hacia las rodillas.","Aprieta el abdomen en la posición superior.","Baja de forma controlada y repite."],"tips":["Enrolla la columna en lugar de tirar del cuello.","Exhala al subir y aprieta los abdominales arriba.","Baja despacio en lugar de dejarte caer sobre el banco."],"met":3.5,"uni":false,"img":["decline-crunch-start.webp","decline-crunch-peak.webp"]},{"id":"decline-db-fly","n":"Aperturas con Mancuernas en Banco Declinado","d":"Un movimiento de apertura en banco declinado para enfatizar el pecho inferior.","cat":"fuerza","g":"pecho","bp":"chest","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["pectoral"],"m2":["deltoides anterior"],"ins":["Túmbate en un banco declinado sosteniendo mancuernas sobre el pecho.","Con una ligera flexión de codos, baja las mancuernas ampliamente hacia los lados.","Aprieta el pecho para subirlas de nuevo.","Repite."],"tips":["No extiendas completamente los codos.","Concéntrate en el estiramiento en la posición inferior."],"met":5.0,"uni":false,"img":["decline-db-fly-start.webp","decline-db-fly-peak.webp"]},{"id":"decline-push-up","n":"Flexión Declinada","d":"Una flexión con los pies elevados para aumentar la activación del pecho superior y los hombros.","cat":"fuerza","g":"pecho","bp":"chest","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["pectoral"],"m2":["deltoides anterior","tríceps"],"ins":["Coloca los pies en una superficie elevada y las manos en el suelo.","Baja el pecho hacia el suelo de forma controlada.","Vuelve a empujar hasta la posición inicial.","Repite."],"tips":["Mantén el cuerpo en línea recta.","Cuanto mayor sea la elevación, más se trabaja el pecho superior."],"met":5.0,"uni":false,"img":["decline-push-up-start.webp","decline-push-up-peak.webp"]},{"id":"deep-squat-hold","n":"Sentadilla Profunda Isométrica","d":"Una sentadilla estática en la posición más baja, con la cadera por debajo de las rodillas, los talones apoyados y las manos juntas delante del pecho. Desarrolla resistencia y movilidad en caderas, rodillas y tobillos.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["glúteo mayor","cuádriceps"],"m2":["aductores","lumbares","isquiotibiales","sóleo"],"ins":["Colócate de pie con los pies algo más abiertos que los hombros y las puntas hacia fuera.","Junta las manos delante del pecho y baja la cadera entre los talones.","Desciende hasta que la cadera quede por debajo de las rodillas mientras los talones permanecen apoyados en el suelo.","Mantén el pecho erguido y presiona los codos contra las rodillas para empujarlas hacia fuera.","Mantén la posición respirando con regularidad y luego ponte de pie."],"tips":["Mantén los talones apoyados; si se levantan, coloca un disco pequeño o una cuña debajo.","Empuja las rodillas hacia fuera en línea con las puntas de los pies y mantén la columna larga.","Aumenta el tiempo de mantenimiento poco a poco, poniéndote de pie para reiniciar entre series."],"met":5.0,"uni":false,"img":["deep-squat-hold-main.webp"]},{"id":"deficit-deadlift","n":"Peso Muerto en Déficit","d":"Un peso muerto ejecutado sobre una plataforma baja que amplía el recorrido y exige más a isquiotibiales y glúteos.","cat":"fuerza","g":"espalda","bp":"back","eq":"barra","home":false,"bw":false,"lv":"avanzado","m":["lumbares","glúteo mayor","isquiotibiales"],"m2":["dorsales","cuádriceps","trapecio"],"ins":["De pie sobre una plataforma pequeña con una barra cargada sobre el medio del pie.","Bisagra hacia abajo y agarra la barra justo por fuera de las rodillas.","Empuja con las piernas para ponerte erguido manteniendo la barra cerca.","Bloquea caderas y rodillas en la parte superior.","Baja de forma controlada y repite."],"tips":["Mantén la columna neutra en todo el recorrido ampliado.","Usa menos peso del que mueves en tu peso muerto habitual.","Domina el peso muerto convencional antes de probar esta variante."],"met":6.0,"uni":false,"img":["deficit-deadlift-start.webp","deficit-deadlift-peak.webp"]},{"id":"deficit-push-ups","n":"Flexiones en Déficit","d":"Una flexión de brazos con las manos sobre soportes elevados, que aumenta el rango de movimiento y el estiramiento del pectoral.","cat":"fuerza","g":"pecho","bp":"chest","eq":"sin equipo","home":true,"bw":true,"lv":"avanzado","m":["pectoral"],"m2":["deltoides anterior","serrato","tríceps"],"ins":["Coloca las manos en dos superficies elevadas como parallettes o bloques.","Adopta la posición de plancha con las manos bajo los hombros.","Baja el pecho por debajo del nivel de las manos.","Empuja hacia arriba para extender los brazos.","Repite el número de repeticiones deseado."],"tips":["Baja solo hasta donde tus hombros toleren el estiramiento.","Mantén el cuerpo en línea recta, sin hundir la cadera.","Progresa desde las flexiones normales antes de añadir déficit."],"met":5.0,"uni":false,"img":["deficit-push-ups-start.webp","deficit-push-ups-peak.webp"]},{"id":"diamond-push-ups","n":"Flexiones en Diamante","d":"Una flexión con las manos juntas formando un diamante con pulgares e índices, trasladando el énfasis a los tríceps.","cat":"fuerza","g":"pecho","bp":"chest","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["pectoral","tríceps"],"m2":["deltoides anterior","serrato"],"ins":["Adopta la posición de flexión con las manos juntas formando un diamante.","Mantén los codos pegados a los costados.","Baja el pecho hacia las manos.","Empuja hacia arriba para extender los brazos.","Repite el número de repeticiones deseado."],"tips":["Lleva los codos hacia atrás pegados a los costados, sin abrirlos.","Mantén el cuerpo en una línea recta y rígida de la cabeza a los talones.","Baja con control hasta que el pecho llegue a las manos."],"met":5.0,"uni":false,"img":["diamond-push-ups-start.webp","diamond-push-ups-peak.webp"]},{"id":"dips","n":"Fondos para Pecho","d":"Un ejercicio compuesto de peso corporal que trabaja el pecho inferior y los tríceps.","cat":"fuerza","g":"pecho","bp":"chest","eq":"paralelas","home":false,"bw":false,"lv":"intermedio","m":["pectoral","tríceps"],"m2":["deltoides anterior"],"ins":["Agarra las barras paralelas y súbete a la posición superior con los brazos extendidos.","Inclina el torso ligeramente hacia adelante.","Baja el cuerpo doblando los codos hasta que los hombros queden por debajo de los codos.","Vuelve a empujar hasta la posición inicial.","Repite."],"tips":["Acentúa la inclinación del torso si quieres más trabajo de pecho.","Detén la bajada si notas molestia en el hombro.","Evita encoger los hombros hacia las orejas al empujar."],"met":6.0,"uni":false,"img":["dips-start.webp","dips-peak.webp"]},{"id":"dolphin-pose","n":"Postura del Delfín","d":"Una V invertida sostenida sobre los antebrazos: las caderas suben hacia el techo mientras los hombros asumen la carga, la preparación estándar para las inversiones sobre antebrazos.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["deltoides anterior","trapecio"],"m2":["isquiotibiales","serrato"],"ins":["Arrodíllate y apoya los antebrazos en el suelo a la anchura de los hombros, con los codos bajo los hombros.","Mete los dedos de los pies y eleva las caderas arriba y atrás hasta formar una V invertida.","Presiona los antebrazos contra el suelo y aleja los hombros de las orejas; los talones pueden quedar altos.","Mantén la posición durante el tiempo indicado, con el cuello relajado entre los brazos.","Baja las rodillas al suelo para salir."],"tips":["Evita que los codos se abran; una cinta alrededor de los brazos mantiene la distancia.","Flexiona bien las rodillas para que la columna siga larga en lugar de perseguir piernas rectas.","Acerca un poco los pies a los codos para llevar más peso a los hombros."],"met":5.0,"uni":false,"img":["dolphin-pose-main.webp"]},{"id":"donkey-calf-raise","n":"Elevación de Pantorrilla a la Burra","d":"Una elevación de pantorrilla inclinada que maximiza el estiramiento al flexionar las caderas.","cat":"fuerza","g":"piernas","bp":"lower_legs","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["gemelos"],"m2":["sóleo"],"ins":["Flexiona las caderas y apoya los antebrazos sobre un banco.","Coloca las puntas de los pies en una plataforma elevada, talones al aire.","Baja los talones por debajo de la plataforma para un estiramiento completo.","Empuja arriba sobre las puntas tanto como puedas, contrayendo las pantorrillas.","Baja con control hasta el estiramiento profundo."],"tips":["Pausa brevemente arriba para maximizar la contracción.","Usa una excéntrica lenta para el estiramiento completo.","Añade un compañero o peso sobre la zona lumbar para más resistencia."],"met":3.5,"uni":false,"img":["donkey-calf-raise-start.webp","donkey-calf-raise-peak.webp"]},{"id":"doorway-chest-stretch","n":"Estiramiento de Pecho en el Marco","d":"Un estiramiento de brazos abiertos que alarga el pecho y los hombros frontales al llevar los brazos atrás.","cat":"estiramiento","g":"pecho","bp":"chest","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["pectoral"],"m2":["deltoides anterior"],"ins":["Párate erguido y sube los brazos en posición de portería.","Flexiona los codos noventa grados, antebrazos verticales.","Lleva los codos atrás y junta los omóplatos.","Mantén de 20 a 30 segundos, respirando de forma constante."],"tips":["Mantén las costillas abajo y evita arquear la espalda.","Estira hasta una tensión leve, nunca hasta el dolor."],"met":5.0,"uni":false,"img":["doorway-chest-stretch-main.webp"]},{"id":"double-db-kickstand-deadlift","n":"Peso Muerto Kickstand con Doble Mancuerna","d":"Un movimiento de bisagra de cadera en postura escalonada con dos mancuernas que carga principalmente la pierna delantera con el pie trasero como apoyo de equilibrio.","cat":"fuerza","g":"espalda","bp":"back","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["glúteo mayor","isquiotibiales"],"m2":["aductores","lumbares"],"ins":["Coloca un pie detrás de modo que solo los dedos toquen el suelo.","Sostén una mancuerna en cada mano a la altura de la cadera.","Bisagra en la cadera bajando ambas mancuernas hacia la espinilla con la espalda recta.","Mantén la mayor parte del peso en el pie delantero.","Empuja con el talón delantero para volver a posición inicial. Cambia de lado."],"tips":["Mantén las mancuernas cerca de las piernas.","Para al notar el estiramiento en el isquiotibial de la pierna delantera.","Completa todas las repeticiones en un lado antes de cambiar."],"met":6.0,"uni":true,"img":["double-db-kickstand-deadlift-start.webp","double-db-kickstand-deadlift-peak.webp"]},{"id":"double-db-overhead-carry","n":"Paseo con Dos Mancuernas sobre la Cabeza","d":"Un paseo cargado con una mancuerna bloqueada sobre cada hombro, que duplica la carga por encima de la cabeza y elimina el brazo libre que de otro modo te ayudaría a equilibrarte.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["deltoides anterior","deltoides lateral"],"m2":["lumbares","serrato","transverso abdominal","trapecio","tríceps"],"ins":["Lleva una mancuerna, en cargada o press, hasta el bloqueo sobre cada hombro.","Estira ambos codos del todo y sigue empujando hacia arriba contra los pesos para que los hombros se mantengan activos, sin dejar que las mancuernas se hundan sobre ellos.","Aprieta fuerte y mantén las costillas abajo — con los dos brazos arriba la tentación de arquearse es mucho mayor.","Camina hacia delante con zancadas cortas y deliberadas, manteniendo ambas mancuernas alineadas sobre los hombros.","Sigue respirando de forma superficial y constante en vez de aguantar el aire todo el recorrido.","Carga la distancia deseada y baja después ambos pesos de forma controlada."],"tips":["Empieza con menos peso por mano que en el paseo a un brazo. Dos brazos por encima de la cabeza no son la mitad de fáciles, son el doble de estabilizar.","Ten pensado cómo abandonar la serie antes de empezar, y carga donde puedas soltar los pesos sin peligro.","Distancias cortas bien hechas superan a las largas hechas torcido. Corta la serie cuando se abran las costillas, no cuando cedan los hombros."],"met":5.5,"uni":false,"img":["double-db-overhead-carry-main.webp"]},{"id":"double-kettlebell-bicep-curl","n":"Curl de Bíceps con Dos Pesas Rusas","d":"Un curl de bíceps de pie con una pesa rusa en cada mano, sujeta por el asa. La masa descentrada en la parte inferior de la pesa añade un ligero reto de agarre y estabilidad.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"kettlebell","home":true,"bw":false,"lv":"principiante","m":["bíceps"],"m2":["braquial","antebrazo"],"ins":["Ponte de pie sujetando una pesa rusa en cada mano por el asa, con las palmas mirando hacia adelante.","Mantén los codos pegados a los costados y las pesas colgando a lo largo de los brazos.","Sube ambas pesas rusas hacia los hombros flexionando los codos.","Aprieta los bíceps en la parte superior, luego baja de forma controlada hasta la posición inicial.","Repite el número de repeticiones recomendado."],"tips":["No dejes que las pesas oscilen — controla la fase excéntrica.","Los codos permanecen pegados a los costados; sin flexión de hombros.","Agarra con fuerza durante todo el movimiento; la pesa tiende a extender la muñeca."],"met":5.0,"uni":false,"img":["double-kettlebell-bicep-curl-start.webp","double-kettlebell-bicep-curl-peak.webp"]},{"id":"double-kettlebell-clean","n":"Clean con Dos Pesas Rusas","d":"Un jalón de cadera explosivo que lleva dos pesas rusas simultáneamente hasta los hombros en posición de rack, base para los press y jerk con doble pesa rusa.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"kettlebell","home":true,"bw":false,"lv":"avanzado","m":["glúteo mayor","isquiotibiales"],"m2":["deltoides anterior","lumbares","antebrazo","trapecio"],"ins":["Ponte de pie con dos pesas rusas en el suelo entre tus pies, con las asas ligeramente giradas hacia adentro.","Inclínate desde las caderas, agarra las asas y envía las pesas rusas hacia atrás entre las piernas.","Extiende las caderas de forma explosiva para impulsar las pesas rusas hacia arriba a lo largo del cuerpo.","Cuando lleguen a la altura del pecho, mete las manos por las asas para recibirlas en la posición de rack sobre los hombros.","Baja de vuelta a la posición colgante inclinándote desde las caderas y guiando las pesas entre las piernas.","Repite el número de repeticiones recomendado."],"tips":["Mete las manos por las asas — no dejes que las pesas se vuelquen y golpeen las muñecas.","El impulso viene de las caderas; los brazos solo guían el trayecto."],"met":8.0,"uni":false,"img":["double-kettlebell-clean-start.webp","double-kettlebell-clean-peak.webp"]},{"id":"double-kettlebell-clean-and-press","n":"Clean and press con doble kettlebell","d":"Un ejercicio de fuerza de cuerpo completo que sube dos kettlebells desde el suelo hasta la posición de rack en los hombros y luego las presiona por encima de la cabeza hasta la extensión completa en una secuencia continua.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"kettlebell","home":true,"bw":false,"lv":"avanzado","m":["deltoides anterior","deltoides lateral"],"m2":["glúteo mayor","cuádriceps","abdominales","trapecio","tríceps"],"ins":["Colócate con dos kettlebells en el suelo entre los pies, separados a la anchura de las caderas, y flexiona las caderas para agarrar un asa con cada mano.","Empuja con las piernas y extiende las caderas de forma explosiva para tirar de ambas kettlebells hacia arriba; luego rota los codos por debajo y recibe las pesas en la posición de rack, al frente de los hombros.","Activa el core y presiona ambas kettlebells por encima de la cabeza hasta bloquear los brazos por completo.","Baja las kettlebells de vuelta a la posición de rack y después al suelo de forma controlada.","Repite las repeticiones deseadas."],"tips":["Mantén las kettlebells cerca del cuerpo durante el clean y pasa las manos alrededor y a través de las asas al recibirlas, para que las pesas se asienten sobre los antebrazos en lugar de golpearlos.","Inicia la presión con un breve impulso de piernas y caderas (dip-drive) y termina con los hombros; mantén el core firme para no inclinarte hacia atrás bajo la carga.","En el bloqueo mantén las muñecas rectas y las kettlebells alineadas sobre los codos y los hombros, con la cabeza en posición neutra entre las pesas."],"met":8.0,"uni":false,"img":["double-kettlebell-clean-and-press-start.webp","double-kettlebell-clean-and-press-peak.webp"]},{"id":"double-kettlebell-dead-clean","n":"Dead Clean con Dos Pesas Rusas","d":"Un clean con dos pesas rusas desde el suelo que desarrolla potencia de cadera llevando ambas pesas a la posición de rack.","cat":"olímpico","g":"cuerpo completo","bp":"full_body","eq":"kettlebell","home":true,"bw":false,"lv":"intermedio","m":["glúteo mayor","isquiotibiales"],"m2":["lumbares","antebrazo","cuádriceps","trapecio"],"ins":["Coloca dos pesas rusas en el suelo entre tus pies.","Inclínate y agarra ambas asas.","Empuja de forma explosiva con las piernas y las caderas.","Tira de las pesas rusas hacia arriba y gíralas hasta la posición de rack.","Bájalas de vuelta al suelo y repite."],"tips":["Genera la fuerza con las caderas, no con los brazos.","Mantén las pesas cerca del cuerpo durante la subida.","Recibe en el rack con suavidad, sin golpear los antebrazos."],"met":8.0,"uni":false,"img":["double-kettlebell-dead-clean-start.webp","double-kettlebell-dead-clean-peak.webp"]},{"id":"double-kettlebell-dead-split-snatch","n":"Dead Split Snatch con Dos Pesas Rusas","d":"Un snatch con dos pesas rusas desde el suelo que se recibe en posición de tijera con los brazos bloqueados arriba.","cat":"olímpico","g":"cuerpo completo","bp":"full_body","eq":"kettlebell","home":true,"bw":false,"lv":"intermedio","m":["deltoides anterior","glúteo mayor"],"m2":["lumbares","isquiotibiales","cuádriceps","trapecio"],"ins":["Coloca dos pesas rusas en el suelo entre tus pies.","Inclínate y agarra ambas asas con firmeza.","Tira de las pesas rusas por encima de la cabeza de forma explosiva en un solo movimiento.","Cae en postura dividida para recibirlas con los brazos bloqueados.","Recupera la posición juntando los pies."],"tips":["Practica la tijera sin peso hasta dominar la recepción.","Recibe con los codos completamente bloqueados.","Mantén el torso erguido al entrar en la tijera."],"met":8.0,"uni":false,"img":["double-kettlebell-dead-split-snatch-start.webp","double-kettlebell-dead-split-snatch-peak.webp"]},{"id":"double-kettlebell-jerk","n":"Jerk con Dos Pesas Rusas","d":"Un levantamiento por encima de la cabeza que utiliza un doble impulso de piernas para elevar dos pesas rusas desde el rack hasta el bloqueo, el movimiento emblema del deporte de pesas rusas.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"kettlebell","home":true,"bw":false,"lv":"avanzado","m":["deltoides anterior","cuádriceps"],"m2":["glúteo mayor","trapecio","tríceps"],"ins":["Comienza con dos pesas rusas en rack sobre los hombros, con los codos apoyados sobre las caderas.","Realiza una pequeña flexión de rodillas y luego extiende las piernas de forma explosiva para impulsar las pesas hacia arriba.","Cuando suban, realiza una segunda flexión de rodillas por debajo de ellas.","Recibe las pesas rusas por encima de la cabeza con los brazos bloqueados y ponte completamente de pie.","Bájalas de vuelta al rack de forma controlada y repite."],"tips":["El jerk tiene dos impulsos, no uno — el segundo impulso es el que te permite bloquear con los brazos relajados.","Respira en cada repetición, exhalando en cada flexión y empuje, en lugar de aguantar la respiración durante toda la serie."],"met":8.0,"uni":false,"img":["double-kettlebell-jerk-start.webp","double-kettlebell-jerk-peak.webp"]},{"id":"double-kettlebell-overhead-carry","n":"Paseo con Dos Kettlebells sobre la Cabeza","d":"Un paseo cargado con una kettlebell bloqueada sobre cada hombro — el más difícil de sostener quieto de todos los paseos, ya que combina la masa descentrada de las bolas con el doble de carga por encima de la cabeza.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"kettlebell","home":true,"bw":false,"lv":"avanzado","m":["deltoides anterior","deltoides lateral"],"m2":["lumbares","antebrazo","serrato","transverso abdominal","trapecio","tríceps"],"ins":["Lleva dos kettlebells al rack y luego pásalas a bloqueo por encima de la cabeza con press o push press.","Estira ambos codos y asienta cada bola por detrás y por encima de su muñeca, con las muñecas rectas.","Lleva las costillas abajo y aprieta fuerte antes del primer paso; con las dos bolas arriba no queda nada con lo que contrapesar.","Camina hacia delante con zancadas cortas y controladas, manteniendo ambas bolas alineadas sobre los hombros.","Sigue mirando al frente y respira de forma constante durante todo el paseo.","Cubre la distancia deseada y baja después ambas bolas al rack y al suelo de forma controlada."],"tips":["Gánate este ejercicio. Domina el paseo con una sola kettlebell por ambos lados antes de cargar dos.","Hazlo solo donde puedas soltar ambas bolas con seguridad, y ten claro hacia dónde te apartarás si hace falta.","La distancia debe ser corta y la postura perfecta. En cuanto la espalda se arquee o se doble una muñeca, la serie ha terminado."],"met":5.5,"uni":false,"img":["double-kettlebell-overhead-carry-main.webp"]},{"id":"double-kettlebell-overhead-press","n":"Press por Encima de la Cabeza con Dos Pesas Rusas","d":"Un press vertical con dos pesas rusas desde la posición de rack que desarrolla hombros y tríceps con gran exigencia del core.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"kettlebell","home":true,"bw":false,"lv":"intermedio","m":["deltoides anterior","tríceps"],"m2":["abdominales","serrato","trapecio"],"ins":["Lleva dos pesas rusas al rack sobre los hombros.","Ponte de pie con los pies separados al ancho de las caderas.","Empuja ambas pesas rusas directamente hacia arriba.","Bloquea los brazos en la parte superior.","Baja de vuelta a la posición de rack y repite."],"tips":["Aprieta el abdomen para evitar arquear la zona lumbar.","Adelanta ligeramente la cabeza cuando las pesas pasen la frente.","Baja al rack con control entre repeticiones."],"met":6.0,"uni":false,"img":["double-kettlebell-overhead-press-start.webp","double-kettlebell-overhead-press-peak.webp"]},{"id":"double-kettlebell-push-press","n":"Push Press con Dos Pesas Rusas","d":"Un push press con dos pesas rusas en rack. El impulso de piernas (un solo descenso) permite lanzar más carga por encima de la cabeza que en un press estricto — el nivel intermedio entre el press militar estricto y el jerk.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"kettlebell","home":true,"bw":false,"lv":"intermedio","m":["deltoides anterior"],"m2":["glúteo mayor","deltoides lateral","cuádriceps","tríceps"],"ins":["Ponte de pie con dos pesas rusas en rack sobre los hombros, codos hacia abajo y pegados.","Pies al ancho de los hombros, core contraído.","Flexiona ligeramente las rodillas manteniendo el torso vertical.","Extiende las piernas de forma explosiva y empuja ambas pesas por encima de la cabeza en un solo movimiento.","Bloquea los brazos con las pesas sobre el punto medio del pie.","Baja de vuelta al rack de forma controlada.","Repite el número de repeticiones recomendado."],"tips":["Solo UN descenso — si vuelves a doblar las rodillas bajo las pesas, eso es un jerk.","El impulso viene de las piernas; los brazos terminan el movimiento.","El torso permanece vertical en todo momento; sin inclinación."],"met":6.0,"uni":false,"img":["double-kettlebell-push-press-start.webp","double-kettlebell-push-press-peak.webp"]},{"id":"double-kettlebell-rear-delt-row","n":"Remo con Dos Pesas Rusas para Deltoides Posterior","d":"Un remo inclinado con una pesa rusa en cada mano y los codos abiertos hacia fuera, lejos del torso, que traslada el trabajo de los dorsales a los deltoides posteriores y la parte alta de la espalda.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"kettlebell","home":true,"bw":false,"lv":"intermedio","m":["deltoides posterior","romboides"],"m2":["bíceps","lumbares","dorsales","trapecio"],"ins":["Coloca una pesa rusa justo por fuera de cada pie, con los pies separados a la anchura de las caderas.","Inclínate desde las caderas con la espalda plana hasta que el torso quede casi paralelo al suelo, con las rodillas ligeramente flexionadas.","Sujeta ambas asas con agarre prono y deja los brazos colgando rectos desde los hombros.","Rema ambas pesas llevando los codos hacia los lados, alejándolos de las costillas en lugar de deslizarlos hacia atrás junto a ellas.","Detente cuando los brazos queden más o menos en línea con los hombros y aprieta los omóplatos.","Baja las pesas de forma controlada hasta que los brazos vuelvan a colgar rectos y repite las repeticiones deseadas."],"tips":["El codo abierto es toda la clave. Si se pega a las costillas estarás haciendo un remo con dos pesas rusas normal y trabajando los dorsales en lugar de los deltoides posteriores.","Usa menos carga que en un remo convencional. El codo abierto es una palanca larga y el deltoides posterior es un motor mucho más pequeño que el dorsal.","Mantén constante el ángulo de la inclinación. Enderezarte al tirar traslada el trabajo al trapecio y a la zona lumbar y acorta justo el rango en el que trabaja el deltoides posterior."],"met":6.0,"uni":false,"img":["double-kettlebell-rear-delt-row-start.webp","double-kettlebell-rear-delt-row-peak.webp"]},{"id":"double-kettlebell-row","n":"Remo con Dos Pesas Rusas","d":"Un remo inclinado con dos pesas rusas que desarrolla dorsales y romboides con fuerte trabajo postural.","cat":"fuerza","g":"espalda","bp":"back","eq":"kettlebell","home":true,"bw":false,"lv":"intermedio","m":["dorsales","romboides"],"m2":["bíceps","lumbares","trapecio"],"ins":["Sujeta una pesa rusa en cada mano e inclínate hacia adelante desde las caderas.","Deja los brazos colgando rectos desde los hombros.","Rema ambas pesas rusas hacia las caderas llevando los codos hacia atrás.","Aprieta los omóplatos en la parte superior.","Baja de forma controlada y repite."],"tips":["No redondees la zona lumbar al mantener la inclinación.","Evita los tirones y rema con un movimiento fluido.","Si la fatiga rompe tu postura, termina la serie."],"met":6.0,"uni":false,"img":["double-kettlebell-row-start.webp","double-kettlebell-row-peak.webp"]},{"id":"double-kettlebell-split-jerk","n":"Split Jerk con Dos Pesas Rusas","d":"Un jerk con dos pesas rusas que combina un impulso de piernas con una recepción en tijera bajo la carga.","cat":"olímpico","g":"cuerpo completo","bp":"full_body","eq":"kettlebell","home":true,"bw":false,"lv":"intermedio","m":["deltoides anterior","cuádriceps"],"m2":["glúteo mayor","trapecio","tríceps"],"ins":["Lleva dos pesas rusas al rack sobre los hombros.","Flexiona ligeramente las rodillas.","Impulsa las pesas rusas por encima de la cabeza de forma explosiva.","Separa las piernas para recibirlas con los brazos bloqueados.","Recupera la posición juntando los pies."],"tips":["Haz el dip corto y vertical, sin inclinar el torso.","Genera el empuje con las piernas, no con los hombros.","Bloquea los codos antes de juntar los pies."],"met":8.0,"uni":false,"img":["double-kettlebell-split-jerk-start.webp","double-kettlebell-split-jerk-peak.webp"]},{"id":"double-kettlebell-swing-snatch","n":"Swing Snatch con Dos Pesas Rusas","d":"Un snatch con dos pesas rusas iniciado con un swing entre las piernas y finalizado con ambas pesas bloqueadas arriba.","cat":"olímpico","g":"cuerpo completo","bp":"full_body","eq":"kettlebell","home":true,"bw":false,"lv":"intermedio","m":["glúteo mayor","isquiotibiales"],"m2":["deltoides anterior","lumbares","antebrazo","trapecio"],"ins":["Ponte de pie con los pies al ancho de los hombros sujetando dos pesas rusas.","Inclínate desde las caderas para balancear las pesas entre las piernas.","Extiende las caderas de forma explosiva para balancear las pesas hacia arriba.","Empuja hacia arriba para recibir ambas pesas rusas por encima de la cabeza con los brazos bloqueados.","Baja de forma controlada y repite."],"tips":["Genera la potencia con un golpe seco de cadera.","Mantén la espalda plana cuando las pesas pasan entre las piernas.","Suaviza la recepción arriba para que las pesas no golpeen tus antebrazos."],"met":8.0,"uni":false,"img":["double-kettlebell-swing-snatch-start.webp","double-kettlebell-swing-snatch-peak.webp"]},{"id":"downward-dog","n":"Perro Boca Abajo","d":"Un estiramiento en V invertida que alarga a la vez isquiotibiales, pantorrillas, hombros y espalda.","cat":"estiramiento","g":"cuerpo completo","bp":"full_body","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["gemelos","isquiotibiales"],"m2":["lumbares","glúteo mayor","dorsales"],"ins":["Empieza en cuadrupedia con las manos algo por delante de los hombros.","Apoya los dedos de los pies y eleva la cadera hacia arriba y atrás.","Estira las piernas y lleva los talones hacia el suelo.","Mantén de 20 a 30 segundos, respirando de forma constante."],"tips":["Flexiona las rodillas si la zona lumbar se redondea.","Empuja el suelo para alargar la columna."],"met":5.0,"uni":false,"img":["downward-dog-main.webp"]},{"id":"downward-dog-knee-tuck","n":"Rodilla al Pecho en Perro Boca Abajo","d":"Un ejercicio dinámico de core sostenido en perro boca abajo: las caderas se mantienen altas mientras una rodilla se lleva bajo el pecho y vuelve al inicio, alternando lados. Los hombros sostienen toda la serie, de modo que el tronco trabaja sin la posición baja de cadera de una plancha.","cat":"fuerza","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["flexores de cadera","abdominales"],"m2":["deltoides anterior","serrato","transverso abdominal"],"ins":["Colócate en perro boca abajo con las manos a la anchura de los hombros y las caderas altas.","Empuja el suelo y aprieta el tronco para que la zona lumbar siga larga.","Lleva una rodilla hacia el pecho, redondeando ligeramente la espalda alta al entrar.","Extiende la pierna de vuelta a la posición inicial de forma controlada.","Repite con la otra pierna y sigue alternando las veces indicadas."],"tips":["Mantén las caderas altas; si caen, esto se convierte en un escalador.","Lleva la rodilla con el abdomen en lugar de impulsarte con el pie de apoyo.","Aleja los hombros de las orejas para que el tronco no se hunda entre los brazos."],"met":5.0,"uni":false,"img":["downward-dog-knee-tuck-start.webp","downward-dog-knee-tuck-peak.webp"]},{"id":"downward-dog-pedal","n":"Pedaleo en Perro Boca Abajo","d":"Un calentamiento dentro del perro boca abajo: las rodillas se flexionan alternando, de modo que cada talón presiona hacia el suelo por turnos y la pantorrilla y el tobillo reciben un estiramiento en movimiento en lugar de un mantenimiento estático.","cat":"estiramiento","g":"piernas","bp":"lower_legs","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["gemelos","sóleo"],"m2":["isquiotibiales"],"ins":["Colócate en perro boca abajo con las manos a la anchura de los hombros y las caderas altas.","Flexiona una rodilla y deja que ese talón se eleve mientras el talón contrario presiona hacia el suelo.","Cambia de lado con fluidez, como pedaleando, manteniendo las caderas altas todo el tiempo.","Presiona las manos por igual para que los hombros se mantengan estables.","Sigue alternando las veces o el tiempo indicados."],"tips":["Mantén las caderas altas; el objetivo son las pantorrillas, no una flexión más profunda.","Presiona toda la mano contra el suelo para que las muñecas no carguen con todo.","Muévete lo bastante despacio como para sentir cada lado en lugar de rebotar."],"met":5.0,"uni":false,"img":["downward-dog-pedal-start.webp","downward-dog-pedal-peak.webp"]},{"id":"downward-dog-to-knee-drive","n":"Rodilla al Codo desde Perro de Tres Patas","d":"Desde el perro de tres patas, la pierna elevada se pliega hacia delante para llevar la rodilla hacia el codo o la nariz y vuelve a extenderse. Los hombros sostienen la posición y el tronco hace el plegado, un lado cada vez.","cat":"fuerza","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["flexores de cadera","abdominales"],"m2":["deltoides anterior","glúteo mayor","serrato"],"ins":["Colócate en perro boca abajo y eleva una pierna por detrás a perro de tres patas.","Presiona ambas manos contra el suelo y desplaza el peso ligeramente hacia delante.","Redondea la espalda alta y lleva esa rodilla hacia el codo o la nariz.","Extiende la pierna de vuelta arriba de forma controlada.","Termina las repeticiones de ese lado y cambia."],"tips":["Deja que la espalda alta se redondee al entrar la rodilla; con la espalda plana la rodilla se queda corta.","Mantén los hombros sobre las muñecas al desplazarte en lugar de pasarte por delante.","Eleva la pierna solo hasta donde las caderas sigan niveladas al salir."],"met":5.0,"uni":true,"img":["downward-dog-to-knee-drive-start.webp","downward-dog-to-knee-drive-peak.webp"]},{"id":"downward-dog-to-low-lunge","n":"Perro Boca Abajo a Zancada Baja","d":"El paso al frente clásico: desde el perro boca abajo un pie viaja entre las manos hasta una zancada baja y regresa. Abre el flexor de la cadera de la pierna trasera y ensaya la transición que aparece en toda práctica de flujo.","cat":"estiramiento","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["flexores de cadera"],"m2":["glúteo mayor","cuádriceps"],"ins":["Empieza en perro boca abajo con las manos a la anchura de los hombros.","Desplaza el peso hacia delante y lleva un pie entre las manos.","Baja la rodilla trasera al suelo y hunde las caderas en una zancada baja.","Empuja con las manos, levanta la rodilla trasera y devuelve el pie delantero al perro boca abajo.","Repite del otro lado y sigue alternando."],"tips":["Lleva el pie hasta la altura de las manos en lugar de quedarte corto y arrastrarlo.","Acolcha la rodilla trasera con una esterilla doblada si el suelo es duro.","Mantén la rodilla delantera sobre el tobillo cuando bajen las caderas."],"met":5.0,"uni":true,"img":["downward-dog-to-low-lunge-start.webp","downward-dog-to-low-lunge-peak.webp"]},{"id":"downward-dog-to-plank","n":"Perro Boca Abajo a Plancha","d":"Una transición en movimiento entre el perro boca abajo y la plancha alta: las caderas viajan de arriba a la horizontal y de vuelta, de modo que hombros y tronco trabajan en recorrido completo en lugar de sostener una posición.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["deltoides anterior","abdominales"],"m2":["isquiotibiales","serrato","trapecio"],"ins":["Colócate en perro boca abajo con las caderas altas y las manos a la anchura de los hombros.","Desplaza el peso hacia delante y baja las caderas hasta formar una línea recta en plancha alta.","Sostén la plancha un instante con las costillas cerradas y los glúteos activos.","Empuja el suelo y eleva las caderas de vuelta al perro boca abajo.","Sigue alternando las veces indicadas."],"tips":["Lo que se mueve son las caderas, no las manos; las palmas se quedan en el mismo sitio toda la serie.","Mantén los hombros alejados de las orejas en ambas posiciones.","Frena la transición si la zona lumbar se hunde al entrar en la plancha."],"met":5.0,"uni":false,"img":["downward-dog-to-plank-start.webp","downward-dog-to-plank-peak.webp"]},{"id":"downward-dog-to-upward-dog","n":"Perro Boca Abajo a Perro Boca Arriba","d":"La transición del vinyasa: el cuerpo viaja desde el perro boca abajo hacia delante al perro boca arriba y de vuelta, alternando entre una V invertida cargada en los hombros y una extensión con el pecho abierto.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["deltoides anterior","lumbares"],"m2":["pectoral","serrato","tríceps"],"ins":["Empieza en perro boca abajo con las caderas altas y las manos a la anchura de los hombros.","Desplázate hacia delante pasando por la plancha, baja un poco y lleva el pecho al frente hasta el perro boca arriba con los muslos despegados.","Lleva los hombros atrás y abajo y mantén el cuello largo.","Mete los dedos de los pies, empuja el suelo y eleva las caderas de vuelta al perro boca abajo.","Sigue moviéndote entre ambas posiciones las veces indicadas."],"tips":["Lo que se mueve son las caderas, no las manos; las palmas siguen plantadas toda la serie.","Presiona el empeine en el perro boca arriba para que los muslos se despeguen de verdad.","Frena en mitad de la transición en lugar de balancearte entre los extremos."],"met":5.0,"uni":false,"img":["downward-dog-to-upward-dog-start.webp","downward-dog-to-upward-dog-peak.webp"]},{"id":"drag-curl","n":"Drag Curl","d":"Un curl con barra en el que los codos viajan hacia atrás y la barra se desliza por el torso, eliminando la asistencia del deltoides anterior y enfatizando la cabeza larga del bíceps.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["bíceps"],"m2":["braquial"],"ins":["Ponte de pie sujetando una barra con agarre supino, con las manos al ancho de los hombros.","Comienza con la barra en los muslos y los codos a los costados.","Sube la barra deslizándola (arrastrándola) hacia arriba a lo largo del cuerpo.","A medida que sube, deja que los codos viajen hacia atrás para que la barra permanezca en contacto con el torso.","Para cuando la barra llegue a la altura del pecho; los bíceps estarán completamente contraídos.","Baja de forma controlada siguiendo el mismo trayecto y repite."],"tips":["Usa significativamente menos peso que en un curl estándar — la mecánica modificada lo hace mucho más difícil.","La barra nunca debe separarse del cuerpo."],"met":5.0,"uni":false,"img":["drag-curl-start.webp","drag-curl-peak.webp"]},{"id":"dragon-flag","n":"Dragon Flag","d":"Un exigente ejercicio de core en banco: agarrando detrás de la cabeza, elevas todo el cuerpo en una línea recta y rígida apoyada solo en la parte alta de la espalda.","cat":"fuerza","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"avanzado","m":["abdominales"],"m2":["lumbares","flexores de cadera","oblicuos","transverso abdominal"],"ins":["Túmbate en un banco y agárralo firmemente detrás de la cabeza.","Eleva el cuerpo de forma que solo la parte superior de la espalda permanezca apoyada en el banco.","Mantén el cuerpo rígido en línea recta.","Baja el cuerpo de forma controlada hasta quedar casi horizontal.","Sube de vuelta y repite."],"tips":["Mantén el cuerpo rígido de hombros a pies y muévete solo desde los hombros.","Baja tan despacio como puedas: la fase excéntrica es el ejercicio.","Empieza con progresiones con piernas recogidas o a una pierna antes del dragon flag completo."],"met":5.0,"uni":false,"img":["dragon-flag-start.webp","dragon-flag-peak.webp"]},{"id":"dumbbell-bench-pull","n":"Remo en Banco con Mancuernas","d":"Un movimiento de remo boca abajo sobre un banco para trabajar la parte superior de la espalda de forma estricta.","cat":"fuerza","g":"espalda","bp":"back","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["dorsales","romboides"],"m2":["bíceps","deltoides posterior"],"ins":["Túmbate boca abajo en un banco inclinado sujetando mancuernas.","Deja los brazos colgando rectos hacia abajo.","Tira de las mancuernas hacia el pecho apretando los omóplatos.","Baja de forma controlada.","Repite."],"tips":["Mantén el pecho pegado al banco en todo momento.","Inicia el tirón con la espalda, no con los bíceps.","Controla la bajada hasta estirar por completo los brazos."],"met":6.0,"uni":false,"img":["dumbbell-bench-pull-start.webp","dumbbell-bench-pull-peak.webp"]},{"id":"dumbbell-calf-raise","n":"Elevación de Talones con Mancuernas","d":"Una elevación de talones con mancuernas sobre una superficie elevada que trabaja gemelos y sóleo en rango completo.","cat":"fuerza","g":"piernas","bp":"lower_legs","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["gemelos","sóleo"],"m2":["antebrazo"],"ins":["Ponte de pie sujetando una mancuerna en cada mano a los costados.","Coloca las puntas de los pies sobre una superficie elevada con los talones colgando.","Empuja a través de las puntas de los pies para subir los talones lo más alto posible.","Aprieta los gemelos en la parte superior del movimiento.","Baja los talones por debajo de la plataforma para estirar los gemelos.","Repite el número de repeticiones deseado."],"tips":["Evita rebotar abajo y haz una pausa breve en el estiramiento.","Mantén las rodillas extendidas pero sin bloquearlas.","Sube y baja despacio para no perder el equilibrio."],"met":5.0,"uni":false,"img":["dumbbell-calf-raise-start.webp","dumbbell-calf-raise-peak.webp"]},{"id":"dumbbell-clean-and-press","n":"Clean and Press con Mancuernas","d":"Un ejercicio de potencia de cuerpo completo en el que dos mancuernas se suben en clean hasta los hombros y luego se empujan por encima de la cabeza en una secuencia fluida. Desarrolla potencia explosiva de cadera, además de hombros y tríceps fuertes.","cat":"olímpico","g":"cuerpo completo","bp":"full_body","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["deltoides anterior","glúteo mayor","cuádriceps"],"m2":["lumbares","trapecio","tríceps"],"ins":["Colócate de pie con los pies a la anchura de las caderas y una mancuerna en cada mano, colgando a los costados.","Haz una bisagra de cadera y flexiona ligeramente las rodillas para bajar las mancuernas justo por debajo de las rodillas.","Extiende las caderas y las rodillas de forma explosiva y encoge los hombros para subir las mancuernas hasta los hombros, recibiéndolas con los codos hacia delante.","Flexiona ligeramente las rodillas y empuja las mancuernas en vertical sobre la cabeza hasta bloquear los brazos.","Baja las mancuernas de nuevo a los hombros y luego a los costados, de forma controlada.","Repite el número de repeticiones deseado."],"tips":["Deja que las piernas y las caderas generen la potencia; los brazos solo guían las mancuernas.","Mantén las mancuernas cerca del cuerpo durante la subida.","Termina cada press con las costillas abajo y los glúteos apretados."],"met":8.0,"uni":false,"img":["dumbbell-clean-and-press-start.webp","dumbbell-clean-and-press-peak.webp"]},{"id":"dumbbell-curl-and-press","n":"Curl y Press con Mancuernas","d":"Un movimiento compuesto de pie que une un curl con mancuernas y un press por encima de la cabeza: las mancuernas se suben en curl hasta los hombros y luego se empujan en vertical sobre la cabeza antes de bajarlas. Trabaja los bíceps y los hombros en una sola repetición fluida.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["deltoides anterior","bíceps"],"m2":["braquial","deltoides lateral","trapecio","tríceps"],"ins":["Colócate de pie con los pies a la anchura de las caderas, sujetando una mancuerna en cada mano a los lados del cuerpo con las palmas hacia delante.","Sube ambas mancuernas en curl hasta los hombros, manteniendo los codos pegados al cuerpo.","Empuja las mancuernas por encima de la cabeza hasta extender del todo los brazos.","Baja las mancuernas de nuevo a los hombros de forma controlada.","Bájalas a los costados con un curl inverso controlado y repite."],"tips":["Contrae el abdomen y mantén las costillas abajo para que el press no se convierta en un arco de espalda.","No lances los pesos con las piernas; usa una carga con la que puedas hacer el curl de forma estricta.","Empuja describiendo un ligero arco para que las mancuernas terminen justo sobre los hombros."],"met":6.0,"uni":false,"img":["dumbbell-curl-and-press-start.webp","dumbbell-curl-and-press-peak.webp"]},{"id":"dumbbell-deadlift","n":"Peso Muerto con Mancuernas","d":"Un peso muerto con mancuernas que fortalece la cadena posterior mediante un patrón de bisagra de cadera.","cat":"fuerza","g":"espalda","bp":"back","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["lumbares","glúteo mayor","isquiotibiales"],"m2":["dorsales","cuádriceps","trapecio"],"ins":["Ponte de pie con las mancuernas frente a los muslos y los pies al ancho de las caderas.","Inclínate desde las caderas y baja las mancuernas a lo largo de las piernas con la espalda recta.","Mantén las mancuernas cerca de las espinillas durante el descenso.","Empuja a través de los talones para volver a la posición de pie.","Extiende completamente las caderas en la parte superior sin hiperlordosis lumbar.","Repite el número de repeticiones deseado."],"tips":["Empuja la cadera hacia atrás en lugar de redondear la espalda.","Mira al frente o ligeramente hacia abajo para alinear el cuello.","Levanta con las piernas y la cadera, no con la zona lumbar."],"met":6.0,"uni":false,"img":["dumbbell-deadlift-start.webp","dumbbell-deadlift-peak.webp"]},{"id":"dumbbell-face-pull","n":"Face Pull con Mancuernas","d":"Un ejercicio para el deltoides posterior y la espalda alta, tirando de mancuernas hacia la cara con los codos muy abiertos.","cat":"fuerza","g":"espalda","bp":"back","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["deltoides posterior","romboides"],"m2":["bíceps","trapecio"],"ins":["Ponte de pie o siéntate sosteniendo una mancuerna en cada mano con los brazos extendidos hacia adelante.","Flexiona los codos y tira de las mancuernas hacia la cara.","Abre los codos hasta la altura de los hombros.","Contrae el deltoides posterior y la espalda alta en el punto máximo.","Baja las mancuernas con control.","Repite el número de repeticiones deseado."],"tips":["Lidera el movimiento con los codos, no con las manos.","Mantén los brazos superiores casi paralelos al suelo.","Usa un peso ligero y prioriza la técnica."],"met":5.0,"uni":false,"img":["dumbbell-face-pull-start.webp","dumbbell-face-pull-peak.webp"]},{"id":"dumbbell-farmers-walk","n":"Caminata del Granjero con Mancuernas","d":"Este ejercicio de cuerpo completo implica caminar sosteniendo mancuernas pesadas, desarrollando eficazmente la fuerza de agarre, la estabilidad del core y la resistencia muscular general.","cat":"fuerza","g":"cuerpo completo","bp":"full_body","eq":"mancuernas","home":true,"bw":false,"lv":"principiante","m":["antebrazo","trapecio"],"m2":["glúteo mayor","oblicuos","cuádriceps","abdominales"],"ins":["Párate erguido con una mancuerna en cada mano, los brazos extendidos a los lados.","Retrae tus escápulas y activa tu core, manteniendo una columna vertebral neutra.","Camina lenta y deliberadamente por una distancia o duración establecida, dando pasos cortos y controlados.","Mantén el pecho erguido y evita inclinarte hacia un lado mientras caminas.","Concéntrate en mantener una postura fuerte y estable durante todo el movimiento."],"tips":["Usa las mancuernas más pesadas que puedas controlar sin comprometer la forma.","Respira profunda y rítmicamente para mantener la tensión del core.","Imagina que estás equilibrando un vaso de agua sobre tu cabeza."],"met":5.5,"uni":false,"img":["dumbbell-farmers-walk-main.webp"]},{"id":"dumbbell-floor-press","n":"Press de Suelo con Mancuernas","d":"Un press con mancuernas realizado tumbado en el suelo, que limita el rango de movimiento para un press más amigable con las articulaciones.","cat":"fuerza","g":"pecho","bp":"chest","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["pectoral"],"m2":["deltoides anterior","tríceps"],"ins":["Túmbate en el suelo con una mancuerna en cada mano a la altura del pecho.","Empuja las mancuernas hacia arriba hasta que los brazos queden extendidos.","Baja de forma controlada hasta que los codos toquen el suelo.","Repite."],"tips":["El suelo limita la tensión en el hombro en la posición inferior.","Mantén las muñecas alineadas sobre los codos."],"met":6.0,"uni":false,"img":["dumbbell-floor-press-start.webp","dumbbell-floor-press-peak.webp"]},{"id":"dumbbell-front-raise","n":"Elevación Frontal con Mancuernas","d":"Un ejercicio de aislamiento que trabaja el deltoides anterior mediante una elevación hacia adelante.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"mancuernas","home":true,"bw":false,"lv":"principiante","m":["deltoides anterior"],"m2":["deltoides lateral"],"ins":["Ponte de pie con las mancuernas a los costados, palmas frente a los muslos.","Sube una o ambas mancuernas hacia adelante hasta la altura de los hombros.","Baja de forma controlada.","Repite."],"tips":["Evita usar el impulso.","Una ligera flexión de codo reduce el estrés articular."],"met":5.0,"uni":false,"img":["dumbbell-front-raise-start.webp","dumbbell-front-raise-peak.webp"]},{"id":"dumbbell-front-squat","n":"Sentadilla Frontal con Mancuernas","d":"Una sentadilla sosteniendo mancuernas apoyadas en los hombros, manteniendo el torso erguido y enfatizando los cuádriceps.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["glúteo mayor","cuádriceps"],"m2":["lumbares","isquiotibiales","abdominales"],"ins":["Sujeta una mancuerna en cada mano apoyadas sobre los hombros.","Mantén los codos en alto y el torso erguido.","Baja las caderas flexionando las rodillas hasta que los muslos queden paralelos al suelo.","Empuja a través de los talones para ponerte de pie.","Mantén la columna en posición neutra durante todo el movimiento.","Repite el número de repeticiones deseado."],"tips":["Mantén los codos altos para que las mancuernas queden apoyadas en los hombros.","Siéntate entre las caderas en lugar de plegarte hacia delante.","Empuja con todo el pie y mantén los talones en el suelo."],"met":6.0,"uni":false,"img":["dumbbell-front-squat-start.webp","dumbbell-front-squat-peak.webp"]},{"id":"dumbbell-hip-thrust","n":"Empuje de Cadera con Mancuerna","d":"El Empuje de Cadera con Mancuerna es un ejercicio compuesto muy eficaz para construir glúteos y isquiotibiales fuertes, realizado empujando las caderas hacia arriba con una mancuerna sobre la pelvis.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"mancuernas","home":true,"bw":false,"lv":"principiante","m":["glúteo mayor"],"m2":["isquiotibiales","cuádriceps"],"ins":["Siéntate en el suelo con la parte superior de la espalda contra un banco, rodillas flexionadas, pies planos y una mancuerna sobre tus caderas.","Contrae tu abdomen y empuja a través de tus talones, levantando las caderas del suelo hasta que tu cuerpo forme una línea recta de hombros a rodillas.","Aprieta tus glúteos con fuerza en la parte superior del movimiento, asegurando una extensión completa de la cadera.","Baja lentamente tus caderas a la posición inicial con control, manteniendo la tensión.","Repite el ejercicio por el número deseado de repeticiones."],"tips":["Mantén la barbilla pegada al pecho para mantener una columna vertebral neutra durante todo el movimiento.","Concéntrate en empujar a través de los talones para maximizar la activación de los glúteos.","Controla la fase excéntrica (descenso) para mejorar el crecimiento muscular.","Usa una almohadilla o toalla debajo de la mancuerna para mayor comodidad."],"met":6.0,"uni":false,"img":["dumbbell-hip-thrust-start.webp","dumbbell-hip-thrust-peak.webp"]},{"id":"dumbbell-pistol-squat","n":"Sentadilla Pistola con Mancuerna","d":"La Sentadilla Pistola con Mancuerna es una variación avanzada de sentadilla a una pierna que desarrolla fuerza significativa en la parte inferior del cuerpo, equilibrio y movilidad, apuntando principalmente a los cuádriceps y glúteos.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"mancuernas","home":true,"bw":false,"lv":"avanzado","m":["glúteo mayor","cuádriceps"],"m2":["glúteo medio","isquiotibiales"],"ins":["Ponte de pie, sosteniendo una mancuerna en cada mano con los brazos colgando a los lados.","Levanta una pierna recta hacia adelante, manteniéndola extendida durante todo el movimiento.","Baja tu cuerpo doblando la rodilla de tu pierna de apoyo, manteniendo el pecho erguido y la espalda recta.","Desciende hasta que tus glúteos estén cerca de tu talón o tu muslo esté paralelo al suelo, manteniendo el equilibrio.","Empuja a través de tu talón para volver a la posición inicial, extendiendo completamente tu pierna de apoyo.","Completa todas las repeticiones de un lado, luego cambia de pierna y repite para el otro lado por serie."],"tips":["Empieza con sentadillas pistola sin peso para dominar el patrón de movimiento antes de añadir mancuernas.","Deja que las mancuernas cuelguen rectas a los lados y mantén el pecho erguido para conservar el equilibrio sobre el pie que trabaja.","Concéntrate en controlar la fase excéntrica (de descenso) para mejorar la estabilidad y la fuerza.","Eleva ligeramente el talón sobre un disco pequeño si la movilidad del tobillo es un factor limitante."],"met":6.0,"uni":true,"img":["dumbbell-pistol-squat-start.webp","dumbbell-pistol-squat-peak.webp"]},{"id":"dumbbell-push-press","n":"Press de Empuje con Mancuernas","d":"Un press de hombros compuesto que usa el impulso de las piernas para desarrollar potencia en hombros y tríceps.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["deltoides anterior","tríceps"],"m2":["glúteo mayor","deltoides lateral","cuádriceps","trapecio"],"ins":["Párate sosteniendo mancuernas a la altura de los hombros, palmas hacia adelante.","Dobla ligeramente las rodillas en una cuarta sentadilla.","Empuja con las piernas para generar impulso y presiona las mancuernas hacia arriba.","Extiende los brazos completamente arriba.","Baja las mancuernas con control a la altura de los hombros."],"tips":["Usa un descenso poco profundo — no es una sentadilla completa.","Empuja los talones contra el suelo para iniciar el press.","Mantén el core activado para proteger la zona lumbar."],"met":6.0,"uni":false,"img":["dumbbell-push-press-start.webp","dumbbell-push-press-peak.webp"]},{"id":"dumbbell-reverse-fly","n":"Pájaro Invertido con Mancuernas","d":"Un ejercicio de aislamiento inclinado que levanta las mancuernas hacia los lados, trabajando los deltoides posteriores y la espalda alta.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["deltoides posterior"],"m2":["romboides","trapecio"],"ins":["Inclínate hacia adelante desde las caderas sujetando mancuernas con los brazos colgando.","Mantén la espalda recta y las rodillas ligeramente dobladas.","Sube las mancuernas hacia los lados hasta la altura de los hombros.","Aprieta los omóplatos en la parte superior.","Baja las mancuernas de forma controlada.","Repite el número de repeticiones deseado."],"tips":["Usa un peso ligero para que trabajen los deltoides posteriores, no el impulso.","Aprieta los omóplatos juntos arriba.","Mantén una flexión suave y fija en los codos en todo momento."],"met":5.0,"uni":false,"img":["dumbbell-reverse-fly-start.webp","dumbbell-reverse-fly-peak.webp"]},{"id":"dumbbell-romanian-deadlift","n":"Peso Muerto Rumano con Mancuernas","d":"Un peso muerto rumano con mancuernas que enfatiza el estiramiento de los isquiotibiales mediante una bisagra de cadera.","cat":"fuerza","g":"espalda","bp":"back","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["glúteo mayor","isquiotibiales"],"m2":["lumbares","antebrazo"],"ins":["Ponte de pie sujetando mancuernas frente a los muslos con una ligera flexión de rodillas.","Inclínate desde las caderas y empuja los glúteos hacia atrás.","Baja las mancuernas a lo largo de las piernas hasta sentir el estiramiento en los isquiotibiales.","Mantén la espalda recta y los hombros hacia atrás.","Empuja las caderas hacia adelante para volver a la posición de pie.","Repite el número de repeticiones deseado."],"tips":["Baja hasta donde tu flexibilidad lo permita, sin forzar.","Mantén la misma flexión suave de rodillas en todo el recorrido.","No conviertas el movimiento en una sentadilla."],"met":6.0,"uni":false,"img":["dumbbell-romanian-deadlift-start.webp","dumbbell-romanian-deadlift-peak.webp"]},{"id":"dumbbell-shoulder-press","n":"Press de Hombros con Mancuernas","d":"Un press vertical con mancuernas, sentado o de pie, que desarrolla las porciones anterior y lateral del deltoides.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["deltoides anterior","deltoides lateral"],"m2":["trapecio","tríceps"],"ins":["Siéntate o ponte de pie sujetando mancuernas a la altura de los hombros con las palmas mirando hacia adelante.","Empuja ambas mancuernas por encima de la cabeza hasta que los brazos queden completamente extendidos.","Mantén el core contraído y evita arquear la zona lumbar.","Baja las mancuernas de forma controlada hasta la altura de los hombros.","No dejes que las mancuernas se desplacen detrás de la cabeza.","Repite el número de repeticiones deseado."],"tips":["Sube las mancuernas en línea recta, sin chocarlas arriba.","Mantén las muñecas firmes, alineadas con los antebrazos.","Si tu zona lumbar se arquea, reduce el peso."],"met":6.0,"uni":false,"img":["dumbbell-shoulder-press-start.webp","dumbbell-shoulder-press-peak.webp"]},{"id":"dumbbell-side-bend","n":"Flexión Lateral con Mancuerna","d":"Un ejercicio de aislamiento de oblicuos de pie con mancuerna para desarrollar la fuerza lateral del core.","cat":"fuerza","g":"core","bp":"core","eq":"mancuernas","home":true,"bw":false,"lv":"principiante","m":["oblicuos"],"m2":["lumbares","cuadrado lumbar","transverso abdominal"],"ins":["Párate erguido sosteniendo una mancuerna a un lado.","Coloca la otra mano en la cadera o detrás de la cabeza.","Inclínate lateralmente hacia el lado de la mancuerna, bajándola por el muslo.","Vuelve a la posición erguida, luego inclínate al lado opuesto con los oblicuos.","Completa todas las repeticiones por lado."],"tips":["Evita inclinarte hacia adelante o atrás — muévete estrictamente de lado.","Usa un tempo controlado en ambas direcciones.","Mantén el peso cerca de la pierna durante todo el movimiento."],"met":5.0,"uni":true,"img":["dumbbell-side-bend-start.webp","dumbbell-side-bend-peak.webp"]},{"id":"dumbbell-snatch","n":"Snatch con Mancuerna","d":"Un levantamiento explosivo a un brazo que impulsa la mancuerna desde el suelo hasta encima de la cabeza en un movimiento fluido.","cat":"olímpico","g":"cuerpo completo","bp":"full_body","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["deltoides anterior","glúteo mayor","trapecio"],"m2":["lumbares","isquiotibiales","cuádriceps"],"ins":["Ponte de pie con los pies al ancho de los hombros y la mancuerna en el suelo entre tus pies.","Inclínate y agarra la mancuerna con una mano.","Extiende caderas, rodillas y tobillos de forma explosiva para tirar de la mancuerna hacia arriba.","Empuja la mancuerna por encima de la cabeza en un movimiento fluido.","Bloquea el brazo y estabiliza en la parte superior.","Completa las repeticiones de un lado y luego cambia."],"tips":["Extiende completamente caderas y rodillas antes de tirar con el brazo.","Empuja la mancuerna hacia arriba hasta un bloqueo estable sobre la cabeza.","Mantén la mancuerna cerca del cuerpo mientras sube."],"met":8.0,"uni":false,"img":["dumbbell-snatch-start.webp","dumbbell-snatch-peak.webp"]},{"id":"dumbbell-split-squat","n":"Sentadilla en Postura Dividida con Mancuernas","d":"Una sentadilla en posición de tijera sosteniendo mancuernas a los lados, que trabaja los cuádriceps y glúteos una pierna a la vez.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["glúteo mayor","cuádriceps"],"m2":["glúteo medio","isquiotibiales"],"ins":["Ponte en postura dividida sujetando mancuernas a los costados.","Mantén el torso erguido y el core contraído.","Baja la rodilla trasera hacia el suelo doblando ambas rodillas.","Para cuando el muslo delantero quede paralelo al suelo.","Empuja a través del talón delantero para volver a la posición de pie.","Completa las repeticiones de un lado y luego cambia."],"tips":["Mantén la mayor parte del peso en la pierna delantera.","Baja la rodilla trasera recta hacia el suelo.","Lleva la rodilla delantera sobre los dedos sin dejar que se hunda hacia dentro."],"met":6.0,"uni":true,"img":["dumbbell-split-squat-start.webp","dumbbell-split-squat-peak.webp"]},{"id":"dumbbell-tricep-extension","n":"Extensión de Tríceps con Mancuerna","d":"Una extensión de tríceps en una mano por encima de la cabeza para un desarrollo equilibrado del brazo.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"mancuernas","home":true,"bw":false,"lv":"principiante","m":["tríceps"],"m2":[],"ins":["Ponte de pie sujetando una mancuerna en una mano por encima de la cabeza.","Baja la mancuerna detrás de la cabeza doblando el codo.","Extiende el brazo de vuelta a la posición inicial.","Mantén el codo cerca de la cabeza.","Repite en ambos lados."],"tips":["Mantén el codo apuntando al techo durante todo el movimiento.","Baja la mancuerna despacio hasta sentir el estiramiento del tríceps.","Evita arquear la espalda baja manteniendo el abdomen firme."],"met":5.0,"uni":false,"img":["dumbbell-tricep-extension-start.webp","dumbbell-tricep-extension-peak.webp"]},{"id":"dumbbell-upright-row","n":"Remo al Mentón con Mancuernas","d":"Un movimiento de tirón compuesto con mancuernas que trabaja los deltoides laterales y el trapecio superior.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["deltoides lateral","trapecio"],"m2":["deltoides anterior","bíceps","romboides"],"ins":["Párate sosteniendo dos mancuernas frente a los muslos, palmas hacia el cuerpo.","Tira de las mancuernas recto hacia arriba a lo largo del cuerpo, liderando con los codos.","Sube hasta la altura del mentón con los codos por encima de las muñecas.","Pausa brevemente, luego baja con control.","Repite el número de repeticiones deseado."],"tips":["Mantén las mancuernas cerca del cuerpo durante todo el movimiento.","Lidera con los codos, no con las manos.","Evita un agarre muy estrecho para reducir el riesgo de impingement de hombro."],"met":6.0,"uni":false,"img":["dumbbell-upright-row-start.webp","dumbbell-upright-row-peak.webp"]},{"id":"dumbbell-windmill","n":"Molino con Mancuerna","d":"Este ejercicio de cuerpo completo desarrolla estabilidad del core, fuerza de hombros y movilidad de cadera al rotar el torso con una mancuerna sobre la cabeza, trabajando principalmente los oblicuos y deltoides laterales.","cat":"fuerza","g":"cuerpo completo","bp":"full_body","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["deltoides lateral","oblicuos"],"m2":["deltoides anterior","glúteo medio","isquiotibiales"],"ins":["Ponte de pie con los pies al ancho de los hombros, sosteniendo una mancuerna sobre la cabeza con un brazo extendido.","Gira tus pies ligeramente alejándolos del lado de la mancuerna, manteniendo el brazo recto y la vista en el peso.","Inclínate desde las caderas, empujándolas hacia el lado de la mancuerna, y baja lentamente el torso hacia el suelo.","Mantén la espalda recta y el brazo de la mancuerna vertical mientras alcanzas con tu mano libre el pie o el suelo.","Invierte el movimiento impulsándote con las caderas y los oblicuos para regresar a la posición inicial.","Completa todas las repeticiones por lado, luego cambia y repite para el otro lado."],"tips":["Mantén el core contraído durante todo el movimiento para proteger tu columna y mejorar la estabilidad.","Mantén la vista fija en la mancuerna sobre la cabeza para ayudar a mantener el equilibrio y el brazo recto.","Concéntrate en inclinarte desde las caderas, no en redondear la espalda, para activar los isquiotibiales y glúteos.","Comienza con un peso ligero para dominar la forma antes de progresar a cargas más pesadas."],"met":5.0,"uni":true,"img":["dumbbell-windmill-start.webp","dumbbell-windmill-peak.webp"]},{"id":"dumbbell-wrist-curl","n":"Curl de Muñeca con Mancuerna","d":"Un curl de muñeca con mancuerna que aísla los flexores del antebrazo y trabaja ambos brazos por separado.","cat":"fuerza","g":"brazos","bp":"lower_arms","eq":"mancuernas","home":true,"bw":false,"lv":"principiante","m":["antebrazo"],"m2":["braquiorradial"],"ins":["Siéntate en un banco con el antebrazo sobre el muslo, palma hacia arriba.","Sujeta una mancuerna con la muñeca fuera de la rodilla.","Deja que la mancuerna ruede hasta las puntas de los dedos.","Sube la mancuerna flexionando la muñeca.","Baja con control. Repeticiones por lado."],"tips":["Mueve solo la muñeca — el antebrazo permanece quieto.","Rueda la mancuerna a las puntas de los dedos para el rango completo.","Entrena ambos brazos con la misma carga y repeticiones."],"met":5.0,"uni":true,"img":["dumbbell-wrist-curl-start.webp","dumbbell-wrist-curl-peak.webp"]},{"id":"eagle-pose","n":"Postura del Águila","d":"Un equilibrio de pie con una pierna enroscada sobre la otra y los brazos entrelazados frente al pecho, sosteniendo una forma estrecha y compacta sobre una pierna flexionada.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["glúteo medio","cuádriceps"],"m2":["deltoides posterior","trapecio"],"ins":["Ponte de pie, flexiona ligeramente ambas rodillas y pasa el peso a un pie.","Cruza el otro muslo sobre el muslo de apoyo y engancha el pie por detrás de la pantorrilla si llega.","Cruza el brazo contrario por debajo, enrosca los antebrazos y acerca las palmas.","Baja un poco sobre la pierna de apoyo y mantén durante el tiempo indicado, con los codos elevados.","Desenrosca y repite del otro lado."],"tips":["Deja el pie cruzado sobre un bloque o el suelo si engancharlo tras la pantorrilla no es posible.","Sube los codos a la altura de los hombros para que la espalda alta trabaje en lugar de hundirse.","Baja más solo mientras la rodilla de apoyo siga sobre el centro del pie."],"met":5.0,"uni":true,"img":["eagle-pose-main.webp"]},{"id":"easy-pose","n":"Postura Fácil","d":"Un sencillo sentado con las piernas cruzadas para respirar y meditar: la pelvis se mantiene erguida, la columna larga y las caderas se asientan sin tensión.","cat":"estiramiento","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["lumbares"],"m2":["aductores","glúteo medio"],"ins":["Siéntate en el suelo y cruza las espinillas con comodidad, cada pie bajo la rodilla contraria.","Elévate sobre una manta doblada o un cojín hasta que las rodillas queden por debajo de las caderas.","Alinea las costillas sobre la pelvis y deja las manos sobre los muslos.","Mantén el sentado durante el tiempo indicado, respirando lenta y regularmente.","Cambia qué espinilla queda delante en la siguiente ronda para repartir el tiempo entre ambos lados."],"tips":["Si las rodillas quedan altas, sube la altura del asiento en lugar de forzarlas hacia abajo.","Mantén la barbilla nivelada para que el cuello siga la línea de la columna.","Apoya las rodillas sobre cojines cuando un sentado largo se vuelva incómodo."],"met":1.5,"uni":false,"img":["easy-pose-main.webp"]},{"id":"elliptical-trainer","n":"Elíptica","d":"Un ejercicio de máquina cardiovascular de bajo impacto en el que los pies describen un óvalo continuo sobre las plataformas mientras los manillares móviles se empujan y se tiran, trabajando piernas y tren superior a la vez.","cat":"cardio","g":"cuerpo completo","bp":"full_body","eq":"elíptica","home":false,"bw":false,"lv":"principiante","m":["glúteo mayor","cuádriceps"],"m2":["gemelos","isquiotibiales","dorsales","pectoral","sóleo","tríceps"],"ins":["Súbete a las plataformas de una en una sujetándote al poste central fijo hasta estar estable, y luego toma un manillar móvil con cada mano.","Pon los pedales en marcha hacia delante manteniendo el pie entero apoyado en la plataforma, sin levantar el talón.","Empuja un manillar hacia delante mientras avanza el pie del lado contrario, y tira del otro hacia atrás, de modo que brazos y piernas trabajen en oposición.","Mantente erguido con la cadera sobre los pedales y el core activo, en lugar de dejarte caer hacia atrás sobre los manillares.","Ajusta la resistencia y la rampa para sostener una zancada fluida y continúa durante el tiempo o la distancia deseados."],"tips":["Mueve tú los manillares en lugar de dejar que las piernas te los empujen — el trabajo de brazos es lo que convierte a la elíptica en una máquina de cuerpo completo.","Mantén los talones apoyados en las plataformas. Ir de puntillas acalambra los gemelos y deja los glúteos fuera de la zancada.","Pedalear hacia atrás durante parte de la sesión desplaza el énfasis hacia isquiotibiales y glúteos y rompe la monotonía de un esfuerzo largo y constante."],"met":8.0,"uni":false,"img":["elliptical-trainer-main.webp"]},{"id":"extended-side-angle","n":"Ángulo Lateral Extendido","d":"Una postura de pie con base amplia, la rodilla delantera flexionada y el torso extendido sobre ese muslo, formando una línea larga desde el talón trasero hasta la mano de arriba.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["oblicuos","cuádriceps"],"m2":["aductores","glúteo medio"],"ins":["Sepárate en una base amplia con el pie delantero girado hacia fuera y el trasero algo hacia dentro.","Flexiona la rodilla delantera hasta que quede sobre el tobillo y mantén la pierna trasera estirada.","Apoya el antebrazo delantero sobre el muslo, o la mano en el suelo o un bloque, y estira el brazo de arriba por encima de la oreja.","Mantén la posición durante el tiempo indicado, girando el pecho hacia el techo.","Estira la pierna delantera para subir y repite del otro lado."],"tips":["Presiona el borde externo del pie trasero; la postura pierde su base en cuanto ese talón se levanta.","Mantén la rodilla delantera apuntando a los dedos centrales en lugar de dejarla caer hacia dentro.","Apoya el antebrazo en el muslo en lugar de la mano en el suelo para conservar el pecho abierto."],"met":5.0,"uni":true,"img":["extended-side-angle-main.webp"]},{"id":"ez-bar-bench-press","n":"Press de Banca con Barra Z","d":"Un press de pecho en banco plano realizado con una barra Z, cuyos agarres angulados son más cómodos para las muñecas mientras trabajan el pectoral, los deltoides anteriores y los tríceps.","cat":"fuerza","g":"pecho","bp":"chest","eq":"barra Z","home":false,"bw":false,"lv":"intermedio","m":["pectoral"],"m2":["deltoides anterior","tríceps"],"ins":["Túmbate en un banco plano con los pies apoyados en el suelo y agarra las curvas anguladas de la barra Z sobre el pecho.","Desengancha la barra y sostenla sobre la parte baja del pecho con los brazos extendidos.","Baja la barra de forma controlada hacia la parte baja del pecho.","Empuja la barra de nuevo hacia arriba hasta extender completamente los brazos.","Repite durante el número de repeticiones deseado."],"tips":["Mantén los pies apoyados en el suelo y un ligero arco en la zona lumbar para una base estable.","El agarre angulado de la barra Z es más cómodo para las muñecas que una barra recta.","Baja la barra hacia la parte baja del pecho y mantén los codos a unos 45 grados para proteger los hombros."],"met":6.0,"uni":false,"img":["ez-bar-bench-press-start.webp","ez-bar-bench-press-peak.webp"]},{"id":"ez-bar-curl","n":"Curl con Barra Z","d":"Un ejercicio de aislamiento para el bíceps con barra Z, que reduce la tensión en las muñecas en comparación con una barra recta.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"barra Z","home":false,"bw":false,"lv":"principiante","m":["bíceps"],"m2":["braquial","braquiorradial"],"ins":["Ponte de pie sujetando la barra Z con agarre supino en las partes anguladas.","Sube la barra hacia los hombros manteniendo los codos fijos.","Aprieta en la parte superior y luego baja de forma controlada.","Repite."],"tips":["Usa el agarre interior o exterior para variar el énfasis.","Mantén las muñecas en posición neutra en los agarres angulados."],"met":5.0,"uni":false,"img":["ez-bar-curl-start.webp","ez-bar-curl-peak.webp"]},{"id":"ez-bar-front-raise","n":"Elevación Frontal con Barra Z","d":"Una elevación frontal con ambas manos usando una barra Z. El agarre angulado es más cómodo para las muñecas que una barra recta y permite a ambas manos manejar la misma carga.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"barra Z","home":false,"bw":false,"lv":"principiante","m":["deltoides anterior"],"m2":["serrato"],"ins":["Ponte de pie sujetando la barra Z con agarre prono en las curvas internas, con los brazos colgando frente a los muslos.","Mantén los codos ligeramente doblados y fijos durante todo el movimiento.","Sube la barra en un arco suave hasta la altura de los hombros.","Haz una breve pausa en la parte superior y luego baja de forma controlada.","Repite el número de repeticiones recomendado."],"tips":["Sube y baja la barra por el mismo arco suave, sin balancearla lejos del cuerpo.","No balancees el torso; mantén el core contraído y las rodillas ligeramente flexionadas.","Para a la altura de los hombros — subir más desplaza la tensión fuera de los deltoides anteriores."],"met":5.0,"uni":false,"img":["ez-bar-front-raise-start.webp","ez-bar-front-raise-peak.webp"]},{"id":"ez-bar-lying-tricep-extension","n":"Extensión de Tríceps Tumbado con Barra Z","d":"Una extensión de tríceps tumbado realizada con una barra Z para aislar el tríceps a lo largo de todo el rango de movimiento.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"barra Z","home":false,"bw":false,"lv":"intermedio","m":["tríceps"],"m2":[],"ins":["Túmbate en un banco plano sujetando una barra Z sobre el pecho con un agarre estrecho.","Baja la barra hacia la frente flexionando los codos.","Extiende los brazos de vuelta a la posición inicial.","Repite."],"tips":["Mantén los brazos superiores verticales en todo momento para que trabaje el tríceps.","El agarre angulado de la barra Z es más cómodo para las muñecas que una barra recta.","Baja despacio para proteger los codos."],"met":5.0,"uni":false,"img":["ez-bar-lying-tricep-extension-start.webp","ez-bar-lying-tricep-extension-peak.webp"]},{"id":"ez-bar-overhead-extension","n":"Extensión de Tríceps por Encima de la Cabeza con Barra Z","d":"Extensión de tríceps por encima de la cabeza con barra Z — el agarre angulado es más cómodo para las muñecas que una barra recta y mantiene la cabeza larga bajo un estiramiento profundo.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"barra Z","home":false,"bw":false,"lv":"intermedio","m":["tríceps"],"m2":[],"ins":["Ponte de pie o siéntate sujetando la barra Z por encima de la cabeza con agarre prono en las curvas internas.","Brazos completamente extendidos con la barra sobre la cabeza.","Dobla solo los codos para bajar la barra detrás de la cabeza en un arco.","Mantén los brazos verticales y cerca de la cabeza; solo los antebrazos se mueven.","Extiende los codos para volver la barra a la posición inicial.","Repite el número de repeticiones recomendado."],"tips":["Si los codos se abren hacia afuera, baja el peso — significa que los hombros están ayudando.","Cuanto más profundo sea el estiramiento en la parte inferior, mayor será el estímulo de hipertrofia en la cabeza larga.","La versión sentada es más cómoda para la zona lumbar."],"met":5.0,"uni":false,"img":["ez-bar-overhead-extension-start.webp","ez-bar-overhead-extension-peak.webp"]},{"id":"ez-bar-pullover","n":"Pullover con Barra EZ","d":"Este ejercicio compuesto trabaja los dorsales y pectorales extendiendo los brazos por encima de la cabeza con una barra EZ, promoviendo la fuerza y la hipertrofia del tren superior.","cat":"fuerza","g":"espalda","bp":"back","eq":"barra Z","home":false,"bw":false,"lv":"intermedio","m":["dorsales","pectoral"],"m2":["serrato","tríceps"],"ins":["Acuéstate boca arriba en un banco plano con la cabeza ligeramente fuera del extremo, sosteniendo una barra EZ con agarre pronado.","Extiende la barra directamente sobre tu pecho, manteniendo una ligera flexión en los codos.","Baja lentamente la barra en un arco detrás de tu cabeza, sintiendo un estiramiento en tus dorsales y pecho.","Jala la barra de regreso a la posición inicial usando tus dorsales y pectorales.","Mantén el control durante todo el movimiento, evitando el impulso."],"tips":["Mantén tu core contraído para evitar arquear excesivamente la espalda baja.","Concéntrate en un estiramiento profundo en la parte inferior del movimiento.","Usa un compañero para cargas más pesadas y asegurar la seguridad.","Controla la fase excéntrica (descenso) para una máxima activación muscular."],"met":6.0,"uni":false,"img":["ez-bar-pullover-start.webp","ez-bar-pullover-peak.webp"]},{"id":"ez-bar-reverse-curl","n":"Curl Inverso con Barra Z","d":"Un curl inverso con barra Z que trabaja el braquial y los extensores del antebrazo con un agarre cómodo.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"barra Z","home":false,"bw":false,"lv":"principiante","m":["braquial","antebrazo"],"m2":["bíceps"],"ins":["Sujeta una barra Z con agarre prono.","Sube la barra hacia tus hombros.","Baja de forma controlada.","Repite."],"tips":["Mantén los codos cerca del torso.","La barra Z reduce la tensión en las muñecas."],"met":5.0,"uni":false,"img":["ez-bar-reverse-curl-start.webp","ez-bar-reverse-curl-peak.webp"]},{"id":"ez-bar-reverse-grip-row","n":"Remo con Barra EZ y Agarre Supino","d":"Este ejercicio compuesto de tracción trabaja el dorsal ancho y el bíceps, desarrollando eficazmente el grosor de la espalda y la fuerza de los brazos con un agarre supinado.","cat":"fuerza","g":"espalda","bp":"back","eq":"barra Z","home":false,"bw":false,"lv":"intermedio","m":["bíceps","dorsales"],"m2":["deltoides posterior","romboides","trapecio"],"ins":["Ponte de pie con los pies al ancho de los hombros, sujetando una barra EZ con un agarre supino al ancho de los hombros.","Inclínate desde las caderas, manteniendo una ligera flexión de rodillas y la espalda recta, hasta que tu torso esté casi paralelo al suelo.","Deja que la barra cuelgue directamente debajo de tus hombros con los brazos completamente extendidos.","Tira de la barra hacia tu abdomen inferior, apretando los omóplatos y llevando los codos hacia arriba.","Controla la fase excéntrica, bajando lentamente la barra a la posición inicial con los brazos completamente extendidos."],"tips":["Mantén una columna vertebral neutra durante todo el movimiento para proteger tu espalda baja.","Concéntrate en iniciar la tracción con los dorsales, no solo con los bíceps.","Evita encogerte de hombros; manténlos deprimidos y retraídos.","Utiliza un rango completo de movimiento, extendiendo los brazos por completo en la parte inferior."],"met":6.0,"uni":false,"img":["ez-bar-reverse-grip-row-start.webp","ez-bar-reverse-grip-row-peak.webp"]},{"id":"ez-bar-romanian-deadlift","n":"Peso Muerto Rumano con Barra Z","d":"Un peso muerto rumano con barra Z. El agarre angulado es más cómodo para las muñecas y es ideal para trabajo de bisagra ligero o personas con codos sensibles.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"barra Z","home":false,"bw":false,"lv":"principiante","m":["glúteo mayor","isquiotibiales"],"m2":["lumbares","antebrazo","trapecio"],"ins":["De pie, sujeta la barra Z a la altura media del muslo con agarre prono en las curvas internas.","Pies a la anchura de las caderas, rodillas ligeramente flexionadas, pecho arriba y dorsales activados.","Empuja las caderas hacia atrás dejando que la barra deslice por la parte delantera de las piernas.","Baja hasta sentir un estiramiento profundo en los isquiotibiales sin redondear la zona lumbar.","Impulsa las caderas hacia adelante para volver a la posición erguida, manteniendo la barra cerca del cuerpo.","Repite el número de repeticiones recomendado."],"tips":["El movimiento es una bisagra de cadera, no una sentadilla: las rodillas apenas se doblan.","La barra Z es más corta que una barra recta; agarra las curvas internas para una posición de muñeca casi neutra.","Detente en el límite inferior de tu rango de movimiento limpio: sin estiramiento con la espalda redondeada."],"met":6.0,"uni":false,"img":["ez-bar-romanian-deadlift-start.webp","ez-bar-romanian-deadlift-peak.webp"]},{"id":"ez-bar-shrug","n":"Encogimiento de Hombros con Barra Z","d":"Un encogimiento de hombros con barra Z para un agarre cómodo mientras se carga el trapecio.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"barra Z","home":false,"bw":false,"lv":"principiante","m":["trapecio"],"m2":["romboides"],"ins":["De pie, sujeta la barra Z frente a ti.","Encoge los hombros directamente hacia arriba.","Mantén la posición arriba y luego baja.","Repite."],"tips":["Evita girar los hombros en círculos.","Usa un rango completo de movimiento."],"met":5.0,"uni":false,"img":["ez-bar-shrug-start.webp","ez-bar-shrug-peak.webp"]},{"id":"ez-bar-spider-curl","n":"Spider Curl con Barra Z","d":"Un curl con el pecho apoyado sobre un banco inclinado usando barra Z, aislando el bíceps con técnica estricta.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"barra Z","home":false,"bw":false,"lv":"intermedio","m":["bíceps"],"m2":["braquial","braquiorradial"],"ins":["Túmbate boca abajo en un banco inclinado sujetando una barra Z con agarre supino.","Deja que tus brazos cuelguen rectos desde los hombros.","Sube la barra hacia tus hombros.","Aprieta los bíceps en la parte alta del movimiento.","Baja la barra de forma controlada.","Repite el número de repeticiones deseado."],"tips":["Deja los brazos colgando verticales y mantén fijos los brazos superiores.","Haz el curl solo con el bíceps: el banco elimina cualquier excusa para balancearte.","Baja hasta el estiramiento completo antes de empezar la siguiente repetición."],"met":5.0,"uni":false,"img":["ez-bar-spider-curl-start.webp","ez-bar-spider-curl-peak.webp"]},{"id":"ez-bar-upright-row","n":"Remo al Mentón con Barra Z","d":"Una variación del remo vertical con barra Z para una posición de muñecas más cómoda.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"barra Z","home":false,"bw":false,"lv":"intermedio","m":["deltoides lateral","trapecio"],"m2":["deltoides anterior","bíceps"],"ins":["De pie, sujeta la barra Z con agarre a la anchura de los hombros en las partes anguladas.","Tira de la barra hacia arriba a lo largo del cuerpo hasta la altura del mentón.","Lidera el movimiento con los codos, manteniéndolos por encima de las manos.","Baja de forma controlada.","Repite."],"tips":["Mantén las muñecas relajadas, sin doblarlas hacia arriba.","Evita balancear el torso para subir la barra.","Si notas molestias en los hombros, reduce el rango o la carga."],"met":6.0,"uni":false,"img":["ez-bar-upright-row-start.webp","ez-bar-upright-row-peak.webp"]},{"id":"ez-bar-wrist-curl","n":"Curl de Muñeca con Barra Z","d":"Un curl de muñeca con barra Z, más amigable con las muñecas que la barra recta.","cat":"fuerza","g":"brazos","bp":"lower_arms","eq":"barra Z","home":false,"bw":false,"lv":"principiante","m":["antebrazo"],"m2":[],"ins":["Siéntate en un banco con los antebrazos sobre los muslos, palmas hacia arriba.","Sujeta una barra Z por las curvas internas a la anchura de los hombros.","Deja que la barra ruede hasta las puntas de los dedos.","Sube la barra flexionando las muñecas.","Baja con control."],"tips":["El ángulo de la barra Z es más amable con las muñecas.","Mueve solo la muñeca — los antebrazos permanecen quietos.","Rueda la barra a las puntas de los dedos para el rango completo."],"met":5.0,"uni":false,"img":["ez-bar-wrist-curl-start.webp","ez-bar-wrist-curl-peak.webp"]},{"id":"face-pull","n":"Face Pull en Polea","d":"Un ejercicio de cable que trabaja los deltoides posteriores y los rotadores externos.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"polea","home":false,"bw":false,"lv":"principiante","m":["deltoides posterior","romboides"],"m2":["trapecio"],"ins":["Engancha una cuerda en una polea alta.","Tira de la cuerda hacia tu cara, separando los extremos.","Aprieta los deltoides posteriores y los rotadores externos.","Regresa a la posición inicial de forma controlada.","Repite."],"tips":["Mantén los codos altos, alineados con los hombros.","Junta las escápulas al final de cada repetición.","Trabaja con peso ligero para no perder la técnica."],"met":6.0,"uni":false,"img":["face-pull-start.webp","face-pull-peak.webp"]},{"id":"fire-hydrant","n":"Hidrante de Fuego","d":"Un ejercicio de glúteos con el peso corporal que se hace a cuatro apoyos: se levanta una rodilla hacia el lado, como un perro frente a un hidrante, mientras la cadera y la columna permanecen cuadradas respecto al suelo. Trabaja el glúteo medio y el resto de los abductores de cadera sin necesidad de equipo.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["abductores","glúteo medio"],"m2":["glúteo mayor","transverso abdominal"],"ins":["Colócate a cuatro apoyos con las manos bajo los hombros, las rodillas bajo la cadera y la espalda plana.","Aprieta el tronco para que la cadera se mantenga nivelada y cuadrada respecto al suelo.","Manteniendo la rodilla doblada a unos 90 grados, levanta una rodilla hacia el lado hasta que el muslo quede aproximadamente paralelo al suelo.","Haz una breve pausa arriba sin rotar la pelvis ni inclinarte hacia el lado contrario al que trabaja.","Baja la rodilla de vuelta a la posición inicial de forma controlada.","Completa las repeticiones de un lado y luego cambia de pierna."],"tips":["Mueve solo la cadera; si la zona lumbar se tuerce o el torso se inclina, el recorrido es demasiado grande.","Mantén la rodilla doblada con el mismo ángulo durante toda la serie.","Empuja el suelo con la mano y la rodilla de apoyo para que el lado de apoyo no se hunda."],"met":3.5,"uni":true,"img":["fire-hydrant-start.webp","fire-hydrant-peak.webp"]},{"id":"fish-pose","n":"Postura del Pez","d":"Una extensión boca arriba apoyada en los antebrazos, con el pecho elevado y la cabeza inclinada atrás, que abre la parte frontal del pecho y la garganta.","cat":"estiramiento","g":"pecho","bp":"chest","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["lumbares","pectoral"],"m2":["deltoides anterior","flexores de cadera"],"ins":["Túmbate boca arriba con las piernas estiradas y los brazos junto al cuerpo, las palmas bajo las caderas.","Presiona los antebrazos contra el suelo y eleva el pecho hacia el techo.","Deja que la coronilla apoye ligeramente en el suelo sin cargar peso en el cuello.","Mantén la posición durante el tiempo indicado, respirando hacia la parte alta del pecho.","Levanta la cabeza y baja la espalda al suelo."],"tips":["El peso va en los antebrazos, no en la cabeza; el cuello solo guía la posición.","Coloca un bloque a lo largo bajo la espalda alta si la versión en el suelo pincha.","Mantén las piernas activas y los muslos rotando ligeramente hacia dentro."],"met":5.0,"uni":false,"img":["fish-pose-main.webp"]},{"id":"flexed-arm-hang","n":"Colgado con Brazos Flexionados","d":"Un mantenimiento estático de dominada en el que la barbilla se mantiene por encima de una barra con los codos flexionados. Desarrolla resistencia y fuerza en los brazos, los dorsales y el agarre, y es un paso clásico previo a la dominada.","cat":"fuerza","g":"espalda","bp":"back","eq":"barra de dominadas","home":true,"bw":false,"lv":"intermedio","m":["bíceps","dorsales"],"m2":["braquial","antebrazo","romboides","trapecio"],"ins":["Agarra una barra de dominadas con las palmas hacia delante, un poco más abierto que la anchura de los hombros, o con las palmas hacia ti para una versión más fácil.","Sube tirando de ti mismo, o sube con ayuda de un cajón, hasta que la barbilla quede por encima de la barra.","Mantén los codos flexionados y apuntando hacia abajo, con los hombros alejados de las orejas.","Mantén la posición sin balancearte, con las piernas juntas y el tronco firme.","Baja despacio hasta colgarte por completo cuando la barbilla empiece a caer."],"tips":["Mantén la barbilla claramente por encima de la barra; cuando baja, el mantenimiento ha terminado.","Aprieta la barra y lleva los omóplatos hacia abajo y atrás.","Si todavía no puedes hacer una dominada, sube a la posición alta con un paso en lugar de saltar."],"met":6.0,"uni":false,"img":["flexed-arm-hang-main.webp"]},{"id":"floor-ez-bar-press","n":"Press en Suelo con Barra Z","d":"Una variación del press en suelo con barra Z para una posición más cómoda de muñecas y codos.","cat":"fuerza","g":"pecho","bp":"chest","eq":"barra Z","home":false,"bw":false,"lv":"intermedio","m":["pectoral"],"m2":["deltoides anterior","tríceps"],"ins":["Túmbate en el suelo sujetando una barra Z sobre el pecho.","Baja la barra hasta que los codos toquen el suelo.","Empuja de vuelta hasta la extensión completa.","Repite."],"tips":["La barra Z reduce la tensión en las muñecas en comparación con una barra recta.","Mantén los pies planos sobre el suelo."],"met":6.0,"uni":false,"img":["floor-ez-bar-press-start.webp","floor-ez-bar-press-peak.webp"]},{"id":"floor-kettlebell-pullover","n":"Pullover con Pesa Rusa en Suelo","d":"Un pullover realizado tumbado en el suelo con una pesa rusa sujetada por el asa o por las asas laterales. El suelo limita el rango de movimiento en comparación con la versión en banco, lo que reduce la tensión en los hombros y lo convierte en una buena opción para entrenar en casa o como ejercicio de prehabilitación.","cat":"fuerza","g":"espalda","bp":"back","eq":"kettlebell","home":true,"bw":false,"lv":"principiante","m":["dorsales","pectoral"],"m2":["serrato","tríceps"],"ins":["Túmbate boca arriba en el suelo con las rodillas flexionadas y los pies planos.","Sujeta una pesa rusa por el asa con ambas manos sobre el pecho, brazos casi extendidos (ligera flexión de codos).","Manteniendo el ángulo de los codos fijo, baja la pesa hacia atrás en arco hasta que los brazos toquen el suelo.","Tira de la pesa de vuelta sobre el pecho siguiendo el mismo arco.","Repite el número de repeticiones recomendado."],"tips":["El suelo limita el rango de movimiento; si te parece demasiado corto, usa la versión en banco.","Agarra el asa con firmeza y aprieta los dorsales en la parte alta.","Mantén la zona lumbar pegada al suelo durante todo el ejercicio."],"met":6.0,"uni":false,"img":["floor-kettlebell-pullover-start.webp","floor-kettlebell-pullover-peak.webp"]},{"id":"floor-press","n":"Press en Suelo","d":"Un movimiento de press con barra realizado en el suelo, limitando el rango de movimiento y eliminando la participación del tren inferior.","cat":"fuerza","g":"pecho","bp":"chest","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["pectoral"],"m2":["deltoides anterior","tríceps"],"ins":["Túmbate en el suelo y colócate bajo una barra en el rack.","Descuelga la barra y bájala hacia el pecho hasta que la parte superior de los brazos toque el suelo.","Empuja de vuelta hasta el bloqueo.","Repite."],"tips":["El contacto de los codos con el suelo proporciona un punto de parada natural.","Útil para trabajar la debilidad en la fase final de extensión."],"met":6.0,"uni":false,"img":["floor-press-start.webp","floor-press-peak.webp"]},{"id":"flutter-kicks","n":"Flutter Kicks","d":"Un ejercicio de core tumbado boca arriba alternando pequeñas patadas arriba y abajo mientras la zona lumbar permanece pegada al suelo.","cat":"fuerza","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["flexores de cadera","abdominales"],"m2":["transverso abdominal"],"ins":["Túmbate boca arriba con las piernas extendidas.","Coloca las manos bajo los glúteos como apoyo.","Levanta ambas piernas unos centímetros del suelo.","Alterna las piernas arriba y abajo en un rango pequeño.","Mantén el core contraído y la zona lumbar presionada contra el suelo.","Continúa durante el tiempo o las repeticiones deseadas."],"tips":["Presiona la zona lumbar contra el suelo durante toda la serie.","Mantén las patadas pequeñas y constantes en lugar de grandes y descontroladas.","Eleva más las piernas si notas que la zona lumbar se arquea."],"met":5.0,"uni":false,"img":["flutter-kicks-start.webp","flutter-kicks-peak.webp"]},{"id":"front-lever","n":"Front Lever","d":"Una posición estática avanzada en barra donde el cuerpo se mantiene horizontal con el pecho hacia arriba, requiriendo fuerza de tracción en dorsales y core.","cat":"fuerza","g":"espalda","bp":"back","eq":"barra de dominadas","home":true,"bw":false,"lv":"avanzado","m":["dorsales","pectoral"],"m2":["deltoides anterior","bíceps","lumbares","abdominales"],"ins":["Agarra la barra con agarre prono y cuelga.","Lleva las rodillas al pecho y tira de los brazos rectos hacia las caderas, echándote hacia atrás hasta que el torso quede horizontal y el pecho mire al techo.","Extiende el cuerpo horizontalmente con brazos rectos y pecho apuntando hacia arriba.","Mantén el cuerpo rígido y paralelo al suelo.","Aguanta el tiempo deseado, luego flexiona y baja de forma controlada."],"tips":["Progresa con variantes de rodillas flexionadas y piernas abiertas antes del hold completo.","Aprieta core y glúteos para evitar que las caderas caigan.","Mantén los hombros activamente deprimidos, alejados de las orejas."],"met":6.0,"uni":false,"img":["front-lever-main.webp"]},{"id":"front-squat","n":"Sentadilla Frontal","d":"Una sentadilla con barra sostenida al frente sobre los deltoides, enfatizando cuádriceps y core.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["glúteo mayor","cuádriceps"],"m2":["lumbares","isquiotibiales"],"ins":["Limpia o coloca la barra en los deltoides frontales con los codos altos.","Baja en sentadilla manteniendo el torso erguido hasta que los muslos estén paralelos al suelo.","Vuelve a subir.","Repite."],"tips":["Mantén los codos altos para estabilizar la barra.","Un torso más vertical aumenta la activación de los cuádriceps."],"met":6.0,"uni":false,"img":["front-squat-start.webp","front-squat-peak.webp"]},{"id":"garland-pose","n":"Postura de la Guirnalda","d":"Una sentadilla profunda sostenida con los talones apoyados y los codos empujando las rodillas hacia fuera, usada para abrir caderas, tobillos y zona lumbar.","cat":"estiramiento","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["aductores","glúteo mayor"],"m2":["cuádriceps","sóleo"],"ins":["Ponte de pie con los pies algo más separados que las caderas y las puntas ligeramente hacia fuera.","Baja en cuclillas todo lo que permitan los tobillos, manteniendo los talones en el suelo.","Junta las palmas frente al pecho y presiona los codos contra la cara interna de las rodillas.","Mantén la posición durante el tiempo indicado, con el pecho alto y la columna larga.","Empuja con los pies para volver a ponerte de pie."],"tips":["Coloca una toalla enrollada bajo los talones si se levantan; forzarlos redondea la zona lumbar.","Abre más los pies para dejar espacio a la pelvis en lugar de encajarte en una sentadilla estrecha.","Presiona ligeramente rodillas y codos entre sí para que el pecho no se hunda."],"met":5.0,"uni":false,"img":["garland-pose-main.webp"]},{"id":"glute-bridge","n":"Puente de Glúteos","d":"Un ejercicio de activación de glúteos con el peso corporal realizado tumbado en el suelo.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["glúteo mayor"],"m2":["isquiotibiales"],"ins":["Túmbate boca arriba con las rodillas flexionadas y los pies planos en el suelo.","Eleva las caderas apretando los glúteos.","Mantén brevemente en la parte alta con las caderas totalmente extendidas.","Baja las caderas de forma controlada.","Repite."],"tips":["Empuja con los talones para activar mejor los glúteos.","Evita arquear la zona lumbar al extender las caderas.","Mantén las rodillas alineadas con los pies durante todo el recorrido."],"met":3.5,"uni":false,"img":["glute-bridge-start.webp","glute-bridge-peak.webp"]},{"id":"glute-bridge-hold","n":"Puente de Glúteos Isométrico","d":"La parte alta del puente de glúteos mantenida en el tiempo: la cadera queda completamente extendida con hombros, caderas y rodillas en línea, de modo que los glúteos permanecen bajo tensión en lugar de encadenar repeticiones.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["glúteo mayor"],"m2":["isquiotibiales"],"ins":["Túmbate boca arriba con las rodillas flexionadas y los pies apoyados, separados a la anchura de las caderas y lo bastante cerca como para rozar los talones con los dedos.","Empuja con los talones y eleva la cadera hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros.","Aprieta los glúteos y lleva las costillas hacia abajo para que la zona lumbar no tome el mando.","Mantén la posición alta durante el tiempo indicado, con el peso en los talones.","Baja la cadera de forma controlada para terminar la serie."],"tips":["Empuja ligeramente las rodillas hacia fuera durante el mantenimiento para que los glúteos sigan activos.","Deja de subir en cuanto rodillas, caderas y hombros formen una línea recta; más arriba suele significar arquear la espalda.","Para añadir carga, apoya una mancuerna o un disco sobre la cadera antes de elevarla."],"met":3.5,"uni":false,"img":["glute-bridge-hold-main.webp"]},{"id":"glute-kickback","n":"Patada de Glúteo","d":"Un ejercicio de aislamiento de glúteos con peso corporal en posición de cuatro puntos para desarrollar el glúteo mayor.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["glúteo mayor"],"m2":["lumbares","glúteo medio","isquiotibiales"],"ins":["Comienza a cuatro patas con las manos bajo los hombros y las rodillas bajo las caderas.","Manteniendo la rodilla doblada a 90 grados, empuja el talón hacia el techo.","Aprieta el glúteo en la parte superior del movimiento.","Baja la pierna a la posición inicial con control.","Completa todas las repeticiones y cambia de lado."],"tips":["Mantén las caderas paralelas al suelo — evita rotar.","Concéntrate en apretar el glúteo, no solo en levantar la pierna.","Agrega una banda de resistencia o cable para sobrecarga progresiva."],"met":3.5,"uni":true,"img":["glute-kickback-start.webp","glute-kickback-peak.webp"]},{"id":"glute-kickback-hold","n":"Patada de Glúteo Isométrica","d":"La posición final de la patada de glúteo mantenida en el tiempo: a cuatro apoyos con una pierna extendida hacia atrás a la altura de la cadera, la pelvis nivelada y el glúteo sosteniendo la pierna en el sitio.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["glúteo mayor"],"m2":["lumbares","glúteo medio","isquiotibiales"],"ins":["Colócate a cuatro apoyos con las manos bajo los hombros y las rodillas bajo las caderas.","Aprieta el tronco y mantén la pelvis nivelada; no dejes que el lado que trabaja rote hacia arriba.","Extiende una pierna hacia atrás y arriba hasta que el muslo quede en línea con el torso.","Mantén esa posición durante el tiempo indicado, con el cuello largo y la zona lumbar plana.","Baja la pierna de forma controlada y repite del otro lado."],"tips":["Aprieta el glúteo en lugar de subir más; la altura la limita que la pelvis siga cuadrada.","Aleja del oído el hombro que te sostiene para que el tronco no se hunda.","Con la rodilla flexionada la tensión se queda en el glúteo; con la pierna estirada pasa más al isquiotibial."],"met":3.5,"uni":true,"img":["glute-kickback-hold-main.webp"]},{"id":"goblet-squat","n":"Sentadilla Goblet","d":"Una sentadilla apta para principiantes con una pesa rusa sujetada a la altura del pecho que mejora la postura y la profundidad.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"kettlebell","home":true,"bw":false,"lv":"principiante","m":["glúteo mayor","cuádriceps"],"m2":["isquiotibiales"],"ins":["Sujeta una pesa rusa a la altura del pecho con ambas manos.","Baja en sentadilla manteniendo el peso cerca del pecho.","Vuelve a subir.","Repite."],"tips":["La posición goblet favorece de forma natural un torso erguido.","Empuja las rodillas hacia afuera en la parte baja."],"met":6.0,"uni":false,"img":["goblet-squat-start.webp","goblet-squat-peak.webp"]},{"id":"good-morning","n":"Buenos Días","d":"Un movimiento de bisagra de cadera con barra en la espalda para el desarrollo de la cadena posterior.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["lumbares","glúteo mayor","isquiotibiales"],"m2":[],"ins":["De pie con una barra sobre la parte superior de la espalda.","Realiza una bisagra de cadera empujando las caderas hacia atrás mientras mantienes la espalda plana.","Baja el torso hasta que quede casi paralelo al suelo.","Impulsa las caderas hacia adelante para volver a la posición erguida.","Repite."],"tips":["Mantén una ligera flexión de rodillas durante todo el movimiento.","Empieza con la barra vacía hasta dominar la bisagra de cadera.","Si la espalda se redondea, reduce el rango de movimiento."],"met":6.0,"uni":false,"img":["good-morning-start.webp","good-morning-peak.webp"]},{"id":"hack-squat","n":"Hack Squat","d":"Un ejercicio guiado en la máquina hack squat que trabaja principalmente los cuádriceps mediante un patrón de sentadilla controlado sobre el trineo.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"hack squat","home":false,"bw":false,"lv":"intermedio","m":["glúteo mayor","cuádriceps"],"m2":["gemelos","isquiotibiales"],"ins":["Carga la máquina hack squat y colócate con la espalda y los hombros contra los almohadillados.","Sitúa los pies a la anchura de los hombros sobre la plataforma con los pies ligeramente girados hacia fuera.","Suelta los asideros de seguridad y baja el trineo flexionando rodillas y caderas.","Desciende hasta que los muslos estén al menos paralelos a la plataforma.","Empuja con los talones para extender las piernas y devolver el trineo a la posición inicial.","Vuelve a enganchar los asideros de seguridad al terminar la serie."],"tips":["Mantén la zona lumbar pegada al almohadillado durante todo el movimiento.","Colocar los pies más arriba en la plataforma desplaza el énfasis hacia glúteos e isquiotibiales.","Controla la bajada; no te impulses desde el punto más bajo."],"met":6.0,"uni":false,"img":["hack-squat-start.webp","hack-squat-peak.webp"]},{"id":"hack-squat-calf-raise","n":"Elevación de Talones en Máquina Hack Squat","d":"Una elevación de talones en la máquina de sentadilla hack, cargando los gemelos con mucho peso sin tener que equilibrar una barra.","cat":"fuerza","g":"piernas","bp":"lower_legs","eq":"hack squat","home":false,"bw":false,"lv":"intermedio","m":["gemelos","sóleo"],"m2":[],"ins":["Colócate en la máquina hack squat con los hombros bajo los apoyos.","Apoya los metatarsos en la plataforma con los talones colgando.","Mantén las piernas rectas con una ligera flexión de rodillas.","Empuja con los metatarsos para elevar los talones.","Baja los talones por debajo de la plataforma para hacer el estiramiento.","Repite el número de repeticiones deseado."],"tips":["Sube tan alto como puedas sobre las puntas de los pies.","Haz una pausa en el estiramiento inferior en lugar de rebotar.","Mantén las rodillas rectas pero sin bloquear para conservar la tensión en los gemelos."],"met":5.0,"uni":false,"img":["hack-squat-calf-raise-start.webp","hack-squat-calf-raise-peak.webp"]},{"id":"half-kneeling-hip-flexor-rock","n":"Balanceo de Flexor de Cadera en Media Rodilla","d":"La versión dinámica del estiramiento de flexor de cadera de rodillas: desde media rodilla las caderas se balancean hacia el estiramiento y vuelven, repetido en lugar de mantenido.","cat":"estiramiento","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["flexores de cadera"],"m2":["glúteo mayor","cuádriceps"],"ins":["Apóyate sobre una rodilla con el otro pie plano en el suelo por delante.","Mete ligeramente el coxis y aprieta el tronco para que la zona lumbar quede neutra.","Balancea las caderas hacia delante hasta notar el alargamiento en la parte frontal del muslo trasero.","Vuelve de forma controlada y repite con ritmo.","Cambia de lado y repite el mismo número de veces."],"tips":["Mantén el movimiento en las caderas; si la zona lumbar se arquea, acorta el recorrido.","Aprieta el glúteo de la pierna arrodillada durante el balanceo hacia delante.","Acolcha la rodilla de apoyo con una esterilla doblada si el suelo es duro."],"met":5.0,"uni":true,"img":["half-kneeling-hip-flexor-rock-start.webp","half-kneeling-hip-flexor-rock-peak.webp"]},{"id":"half-moon-pose","n":"Postura de la Media Luna","d":"Un equilibrio lateral de pie sobre una pierna y una mano, con la pierna de arriba elevada a la altura de la cadera y el pecho abierto hacia el techo.","cat":"fuerza","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"avanzado","m":["glúteo medio","oblicuos"],"m2":["lumbares","cuádriceps"],"ins":["Desde una base amplia, flexiona la rodilla delantera y apoya la mano de abajo en el suelo o un bloque por delante de ese pie.","Desplaza el peso hacia delante y eleva la pierna trasera hasta dejarla paralela al suelo.","Estira la pierna de apoyo y apila la cadera de arriba sobre la de abajo, con el brazo superior hacia el techo.","Mantén el equilibrio durante el tiempo indicado, con el pie elevado en flexión.","Baja el pie trasero y repite del otro lado."],"tips":["Usa un bloque bajo la mano de abajo; llegar al suelo no es el objetivo de la postura.","Empuja el talón elevado hacia la pared de detrás para mantener la pierna activa.","Mira al suelo en lugar de hacia arriba si el equilibrio se rompe una y otra vez."],"met":5.0,"uni":true,"img":["half-moon-pose-main.webp"]},{"id":"hammer-curl","n":"Curl de Martillo con Mancuernas","d":"Una variación del curl de bíceps con agarre neutro que trabaja el braquiorradial.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"mancuernas","home":true,"bw":false,"lv":"principiante","m":["bíceps","braquial"],"m2":["antebrazo"],"ins":["De pie, sujeta las mancuernas a los lados con las palmas enfrentadas.","Sube las mancuernas manteniendo las palmas hacia adentro.","Aprieta en la parte alta y baja de forma controlada.","Repite."],"tips":["Mantén los codos pegados al torso durante todo el recorrido.","Evita balancear el cuerpo para impulsar las mancuernas.","Las muñecas van firmes y neutras durante todo el curl."],"met":5.0,"uni":false,"img":["hammer-curl-start.webp","hammer-curl-peak.webp"]},{"id":"handstand-hold","n":"Pino Isométrico","d":"Un mantenimiento estático libre, en equilibrio boca abajo sobre las manos con el cuerpo alineado en línea recta. Desarrolla fuerza de hombros, estabilidad de muñecas y tronco, y equilibrio.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"sin equipo","home":true,"bw":true,"lv":"avanzado","m":["deltoides anterior","tríceps"],"m2":["antebrazo","abdominales","serrato","trapecio"],"ins":["Coloca las manos en el suelo a la anchura de los hombros aproximadamente y lanza las piernas hasta quedar invertido, una pierna tras otra.","Empuja alto a través de los hombros y mantén los brazos bloqueados.","Aprieta los glúteos y el abdomen para que el cuerpo forme una sola línea recta de las manos a los pies.","Mantén la mirada entre las manos y sostén la posición haciendo pequeñas correcciones con los dedos.","Baja de forma controlada, una pierna cada vez, o sal de la posición dando un paso."],"tips":["Practica contra una pared hasta que puedas mantener la línea sin apoyarte en ella.","Empuja el suelo para que los hombros se mantengan elevados y recoge las costillas para no arquear la espalda.","Calienta las muñecas antes de empezar el mantenimiento."],"met":5.0,"uni":false,"img":["handstand-hold-main.webp"]},{"id":"handstand-push-ups","n":"Flexiones en Pino","d":"Un empuje invertido contra la pared, bajando la cabeza hacia el suelo y empujando de vuelta hasta el pino completo.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"sin equipo","home":true,"bw":true,"lv":"avanzado","m":["deltoides anterior","tríceps"],"m2":["deltoides lateral","abdominales","trapecio"],"ins":["Sube a un pino contra la pared con las manos a la anchura de los hombros.","Contrae el core y mantén el cuerpo recto.","Baja la cabeza hacia el suelo flexionando los codos.","Detente justo antes de que la cabeza toque el suelo.","Empuja con las manos para volver al pino completo.","Repite el número de repeticiones deseado."],"tips":["Mantén los codos a unos 45 grados en lugar de abrirlos por completo.","Contrae el core para que la espalda no se arquee alejándose de la pared.","Progresa primero con flexiones pike y rangos parciales."],"met":5.0,"uni":false,"img":["handstand-push-ups-start.webp","handstand-push-ups-peak.webp"]},{"id":"hang-clean","n":"Cargada desde Colgante","d":"Una variante de la cargada que comienza con la barra a la altura de los muslos, entrenando la triple extensión explosiva y una recepción rápida.","cat":"olímpico","g":"cuerpo completo","bp":"full_body","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["glúteo mayor","cuádriceps","trapecio"],"m2":["deltoides anterior","lumbares","isquiotibiales"],"ins":["De pie, sujeta la barra con agarre a la anchura de los hombros a la altura de los muslos.","Realiza una bisagra de cadera para bajar la barra justo por encima de las rodillas.","Extiende caderas, rodillas y tobillos de forma explosiva.","Encoge los hombros y tira de la barra hacia arriba.","Recibe la barra sobre los deltoides frontales en un cuarto de sentadilla.","Ponte erguido y luego vuelve a la posición de colgante."],"tips":["Flexiona las caderas hasta justo por encima de las rodillas antes de explotar hacia arriba.","Encoge los hombros y tira de la barra cerca del cuerpo.","Recibe la barra sobre los hombros en un cuarto de sentadilla."],"met":8.0,"uni":false,"img":["hang-clean-start.webp","hang-clean-peak.webp"]},{"id":"hang-power-clean","n":"Power Clean desde Colgante","d":"Una cargada desde el colgado recibida en una sentadilla parcial, que desarrolla potencia explosiva sin bajar a una sentadilla completa.","cat":"olímpico","g":"cuerpo completo","bp":"full_body","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["glúteo mayor","cuádriceps","trapecio"],"m2":["lumbares","isquiotibiales"],"ins":["De pie con los pies a la anchura de las caderas sujetando la barra a la altura de los muslos.","Realiza una bisagra de cadera para bajar la barra justo por encima de las rodillas.","Extiende caderas y piernas de forma explosiva.","Tira de la barra hacia arriba y recíbela sobre los deltoides frontales en una sentadilla parcial.","Ponte erguido con la barra apoyada en los hombros.","Baja la barra de vuelta a la posición de colgante."],"tips":["Impulsa con caderas y piernas antes de que tiren los brazos.","Recibe la barra con los muslos por encima de la paralela.","Mantén la espalda plana al flexionar hacia la posición inicial."],"met":8.0,"uni":false,"img":["hang-power-clean-start.webp","hang-power-clean-peak.webp"]},{"id":"hang-snatch","n":"Arrancada desde Colgante","d":"Un levantamiento olímpico en el que una barra se lleva desde la posición de colgante, justo por encima de las rodillas, hasta encima de la cabeza en un movimiento explosivo y se recibe en sentadilla. Desarrolla potencia en caderas, espalda y hombros.","cat":"olímpico","g":"cuerpo completo","bp":"full_body","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["glúteo mayor","cuádriceps","trapecio"],"m2":["deltoides anterior","lumbares","isquiotibiales"],"ins":["Colócate de pie con un agarre ancho de arrancada sobre una barra sostenida a la altura de los muslos y los pies a la anchura de las caderas aproximadamente.","Haz una bisagra de cadera para bajar la barra justo por encima de las rodillas, con la espalda plana y los hombros sobre la barra.","Extiende caderas, rodillas y tobillos de forma explosiva, encogiendo los hombros mientras sube la barra.","Métete bajo la barra y recíbela sobre la cabeza con los brazos bloqueados, en sentadilla.","Ponte de pie por completo con la barra sobre la cabeza y estable.","Baja la barra de forma controlada hasta los muslos y reinicia."],"tips":["Mantén la barra cerca del cuerpo durante todo el tirón.","Termina el tirón con extensión completa antes de meterte bajo la barra.","Aprende el movimiento con una barra ligera o un palo; la recepción ancha sobre la cabeza exige buena movilidad de hombros y caderas."],"met":8.0,"uni":false,"img":["hang-snatch-start.webp","hang-snatch-peak.webp"]},{"id":"hanging-knee-raise","n":"Elevación de Rodillas Colgado","d":"Un ejercicio de core colgado de una barra que trabaja el abdomen bajo y los flexores de cadera con rodillas dobladas.","cat":"fuerza","g":"core","bp":"core","eq":"barra de dominadas","home":true,"bw":false,"lv":"principiante","m":["flexores de cadera","abdominales"],"m2":["antebrazo","oblicuos"],"ins":["Cuélgate de una barra con agarre prono y los brazos completamente extendidos.","Activa el core y sube las rodillas hacia el pecho.","Mantén brevemente arriba.","Baja las piernas despacio a la posición inicial.","Repite el número de repeticiones deseado."],"tips":["Evita el balanceo — inicia el movimiento desde el core.","Exhala al subir las rodillas.","Progresa a elevaciones de piernas rectas cuando esto resulte fácil."],"met":6.0,"uni":false,"img":["hanging-knee-raise-start.webp","hanging-knee-raise-peak.webp"]},{"id":"hanging-l-sit","n":"L-Sit Colgado","d":"Un mantenimiento estático de core colgado de una barra con las piernas estiradas al frente del cuerpo a la altura de la cadera, formando una L. Exige abdominales, flexores de cadera y agarre fuertes.","cat":"fuerza","g":"core","bp":"core","eq":"barra de dominadas","home":true,"bw":false,"lv":"avanzado","m":["flexores de cadera","abdominales"],"m2":["antebrazo","dorsales","cuádriceps","transverso abdominal"],"ins":["Cuélgate de una barra de dominadas con agarre prono, los brazos estirados y los hombros hacia abajo.","Contrae el abdomen y eleva las piernas rectas hasta que queden paralelas al suelo.","Mantén las rodillas bloqueadas y las puntas de los pies estiradas, con las piernas juntas.","Mantén la posición sin balancearte, respirando con regularidad.","Baja las piernas de forma controlada hasta el colgado pasivo."],"tips":["Si las piernas bajan de la horizontal, flexiona las rodillas (un mantenimiento en tuck) y progresa desde ahí.","Mantén los hombros activos; no cuelgues pasivamente de las articulaciones.","Aprieta las piernas entre sí y estira las puntas de los pies para mantener la línea firme."],"met":6.0,"uni":false,"img":["hanging-l-sit-main.webp"]},{"id":"hanging-leg-raise","n":"Elevación de Piernas Colgado","d":"Un ejercicio avanzado de core realizado colgado de una barra.","cat":"fuerza","g":"core","bp":"core","eq":"barra de dominadas","home":true,"bw":false,"lv":"intermedio","m":["flexores de cadera","abdominales"],"m2":["oblicuos"],"ins":["Cuélgate de una barra de dominadas con agarre prono.","Sube las piernas hacia adelante hasta que queden paralelas al suelo.","Mantén brevemente y baja de forma controlada.","Evita balancearte.","Repite."],"tips":["Inclina la pelvis hacia atrás al subir las piernas.","Empieza cada repetición desde una posición completamente quieta.","Flexiona las rodillas si con las piernas rectas resulta demasiado difícil."],"met":5.0,"uni":false,"img":["hanging-leg-raise-start.webp","hanging-leg-raise-peak.webp"]},{"id":"hanging-pike","n":"Pike Colgado","d":"Una elevación de piernas estricta colgado de la barra hasta tocarla: las piernas se mantienen rectas y los pies suben hasta las manos.","cat":"fuerza","g":"core","bp":"core","eq":"barra de dominadas","home":true,"bw":false,"lv":"avanzado","m":["abdominales"],"m2":["antebrazo","flexores de cadera","dorsales"],"ins":["Cuélgate de una barra de dominadas con agarre prono a la anchura de los hombros.","Activa los dorsales y contrae el core para crear un cuerpo hueco.","Manteniendo las piernas completamente rectas, súbelas en un arco suave hasta la barra.","Intenta tocar los pies a la barra entre las manos.","Baja las piernas lentamente a la posición de cuelgue y repite."],"tips":["Sin balanceo: cada repetición empieza desde un cuelgue muerto con el tronco activado.","Si el rango completo es demasiado difícil, sube solo hasta la horizontal y ve progresando."],"met":4.5,"uni":false,"img":["hanging-pike-start.webp","hanging-pike-peak.webp"]},{"id":"hanging-tuck-hold","n":"Encogimiento de Rodillas Colgado Isométrico","d":"Un mantenimiento estático de core colgado de una barra con las rodillas recogidas hacia el pecho. Entrena el abdomen y los flexores de cadera y es un paso hacia el L-sit colgado.","cat":"fuerza","g":"core","bp":"core","eq":"barra de dominadas","home":true,"bw":false,"lv":"intermedio","m":["flexores de cadera","abdominales"],"m2":["antebrazo","dorsales","oblicuos","transverso abdominal"],"ins":["Cuélgate de una barra de dominadas con agarre prono y los brazos estirados.","Contrae el abdomen y sube las rodillas hacia el pecho, redondeando ligeramente la zona lumbar.","Mantén las rodillas juntas y los muslos a la altura de la cadera o por encima.","Mantén la posición encogida sin balancearte y respira con regularidad.","Baja las piernas de forma controlada hasta colgarte por completo."],"tips":["Enrolla la pelvis hacia arriba en lugar de limitarte a subir las rodillas; el trabajo debe hacerlo el abdomen.","Mantén los hombros alejados de las orejas.","Termina la serie cuando las rodillas empiecen a bajar o el cuerpo empiece a balancearse."],"met":6.0,"uni":false,"img":["hanging-tuck-hold-main.webp"]},{"id":"happy-baby","n":"Postura del Bebé Feliz","d":"Una apertura de cadera boca arriba en la que las rodillas se acercan a las axilas y los pies se sujetan por fuera, liberando la cara interna de los muslos y la zona lumbar.","cat":"estiramiento","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["aductores","glúteo mayor"],"m2":["lumbares","isquiotibiales"],"ins":["Túmbate boca arriba y acerca ambas rodillas al pecho.","Agarra los bordes externos de los pies, o las espinillas si los pies quedan lejos.","Abre las rodillas más allá de las costillas y coloca los tobillos sobre las rodillas, con las plantas hacia arriba.","Empuja suavemente los pies contra las manos y mantén durante el tiempo indicado, con la zona lumbar en el suelo.","Suelta los pies y baja las piernas."],"tips":["Mantén el coxis pesado en el suelo en lugar de rodar hacia la espalda alta.","Agarra las espinillas o usa una cinta si el agarre despega los hombros de la esterilla.","Balancéate suavemente de lado a lado si notas tensión en la zona lumbar."],"met":5.0,"uni":false,"img":["happy-baby-main.webp"]},{"id":"head-to-knee-pose","n":"Postura de Cabeza a la Rodilla","d":"Una flexión sentada sobre una pierna: una queda estirada y el otro pie se apoya en la cara interna del muslo, de modo que el isquiotibial se alarga de lado en lado.","cat":"estiramiento","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["lumbares","isquiotibiales"],"m2":["aductores","glúteo mayor"],"ins":["Siéntate con una pierna estirada al frente y la otra rodilla abierta al lado, con ese pie en la cara interna del muslo.","Gira el pecho hacia la pierna estirada para que el ombligo quede alineado con el muslo.","Bascula desde las caderas y alcanza hacia delante a lo largo de la pierna con la columna larga.","Mantén la flexión durante el tiempo indicado, respirando hacia la parte posterior de la pierna.","Sube con la espalda plana y repite del otro lado."],"tips":["Siéntate sobre una manta doblada para que la pelvis pueda bascular en lugar de redondear la espalda.","Mantén los dedos del pie estirado apuntando hacia arriba en lugar de dejarlos caer hacia fuera.","Usa una cinta alrededor del pie cuando las manos no lleguen con comodidad."],"met":5.0,"uni":true,"img":["head-to-knee-pose-main.webp"]},{"id":"heel-elevated-squat","n":"Sentadilla con Talones Elevados","d":"Una variante de sentadilla con los talones elevados sobre discos para enfatizar los cuádriceps y mejorar la profundidad.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["glúteo mayor","cuádriceps"],"m2":["aductores","lumbares","isquiotibiales"],"ins":["Coloca discos de peso o una cuña bajo los talones, pies al ancho de los hombros.","Sostén una barra en la parte superior de la espalda o mancuernas a los lados.","Activa el core y baja en sentadilla manteniendo el torso erguido.","Baja hasta que los muslos estén paralelos al suelo o más abajo.","Empuja a través de los pies para volver a la posición inicial."],"tips":["Los talones elevados permiten un torso más erguido y mayor recorrido de rodilla.","Mantén las rodillas alineadas con los dedos del pie durante todo el movimiento.","Comienza con una elevación pequeña y auméntala a medida que mejore la movilidad."],"met":6.0,"uni":false,"img":["heel-elevated-squat-start.webp","heel-elevated-squat-peak.webp"]},{"id":"heel-flicks","n":"Talones a los Glúteos","d":"Un ejercicio de calentamiento de carrera que alterna los talones hacia los glúteos para aumentar la cadencia, flexionar dinámicamente las rodillas y preparar los isquiotibiales.","cat":"cardio","g":"cuerpo completo","bp":"full_body","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["isquiotibiales"],"m2":["gemelos","glúteo mayor","flexores de cadera"],"ins":["Ponte erguido con los pies bajo las caderas y los brazos flexionados como al correr.","Empieza a trotar suavemente en el sitio.","Lleva un talón rápidamente hacia el glúteo del mismo lado sin impulsar la rodilla hacia delante.","Cambia de pie con rapidez y sigue alternando a un ritmo uniforme.","Mantente ligero sobre los antepiés y conserva el torso erguido durante todo el intervalo."],"tips":["Busca contactos rápidos y relajados en lugar de forzar el talón contra el glúteo.","Mantén las rodillas apuntando hacia abajo en vez de elevarlas como en las rodillas altas.","Empieza despacio y aumenta la cadencia solo cuando el ritmo sea fluido."],"met":8.0,"uni":false,"img":["heel-flicks-main.webp"]},{"id":"heel-to-toe-walk","n":"Marcha en Tándem","d":"Un ejercicio de equilibrio y coordinación caminando sobre una línea imaginaria, colocando el talón de cada paso justo contra los dedos del otro pie para que la base de apoyo se reduzca casi a nada.","cat":"fuerza","g":"piernas","bp":"lower_legs","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["glúteo medio","sóleo"],"m2":["gemelos","cuádriceps","transverso abdominal"],"ins":["Elige una línea recta en el suelo, colócate sobre ella y extiende los brazos a los lados a la altura de los hombros.","Da un paso al frente y coloca el talón justo delante de los dedos del pie de apoyo, en contacto con ellos.","Pasa el peso al pie delantero de forma controlada y haz una pausa breve antes del siguiente paso.","Lleva el pie de atrás hacia delante y colócalo de nuevo talón contra dedos, sin salirte de la línea.","Fija la vista en un punto al frente en lugar de mirarte los pies, y corrige los desequilibrios con los brazos.","Camina el número de pasos deseado, luego date la vuelta y regresa."],"tips":["Ve despacio. Si te apresuras acabas caminando normal sobre una línea estrecha y desaparece por completo la exigencia de equilibrio.","Si no consigues mantener la línea, camina junto a una pared y tócala solo cuando lo necesites — eso es una regresión, no un fracaso.","Súbele la dificultad cruzando los brazos sobre el pecho, y todavía más haciéndolo con los ojos cerrados cerca de una pared."],"met":2.5,"uni":false,"img":["heel-to-toe-walk-main.webp"]},{"id":"heel-touches","n":"Toques de Talón","d":"Un ejercicio de core tumbado en el que haces un crunch ligero hacia un lado y llevas la mano hacia el talón, y luego alternas lados. Trabaja los oblicuos y la parte alta del abdomen con la zona lumbar pegada al suelo.","cat":"fuerza","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["oblicuos","abdominales"],"m2":[],"ins":["Túmbate boca arriba con las rodillas flexionadas y los pies apoyados en el suelo, a la anchura de las caderas aproximadamente.","Levanta ligeramente la cabeza y los hombros del suelo y estira los brazos a lo largo de los costados.","Haz un crunch hacia un lado y lleva esa mano hacia el talón del mismo lado.","Vuelve al centro y alcanza el talón contrario.","Sigue alternando lados con un ritmo fluido mientras la zona lumbar permanece en el suelo.","Continúa el número de repeticiones deseado."],"tips":["Mantén el cuello largo y la barbilla separada del pecho; guía el movimiento con la caja torácica, no con la cabeza.","Haz cada alcance pequeño y controlado; los omóplatos apenas se despegan del suelo.","Mantén los pies apoyados y la zona lumbar pegada al suelo todo el tiempo."],"met":5.0,"uni":false,"img":["heel-touches-start.webp","heel-touches-peak.webp"]},{"id":"hero-pose","n":"Postura del Héroe","d":"Un sentado de rodillas en el que las caderas descienden entre los talones, alargando el cuádriceps y la parte frontal de los tobillos mientras la columna se mantiene erguida.","cat":"estiramiento","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["cuádriceps"],"m2":["lumbares","flexores de cadera"],"ins":["Arrodíllate con las rodillas juntas y los pies algo más separados que las caderas, con el empeine apoyado.","Baja las caderas entre los talones, usando un bloque o cojín si el suelo queda lejos.","Alinea las costillas sobre la pelvis y apoya las manos en los muslos.","Mantén el sentado durante el tiempo indicado, con el peso repartido entre ambos isquiones.","Sal apoyándote en las manos y estirando una pierna cada vez."],"tips":["Siéntate sobre un bloque en cuanto las rodillas protesten; la altura forma parte normal de la postura.","Coloca una toalla enrollada bajo los tobillos si notas tensión en su parte frontal.","Mantén los pies apuntando hacia atrás en lugar de abrirlos hacia los lados."],"met":1.5,"uni":false,"img":["hero-pose-main.webp"]},{"id":"hex-bar-deadlift","n":"Peso Muerto con Barra Hexagonal","d":"Un peso muerto de pie dentro de una barra hexagonal, manteniendo la carga centrada para un tirón más erguido y amable con la espalda.","cat":"fuerza","g":"espalda","bp":"back","eq":"barra hexagonal","home":false,"bw":false,"lv":"intermedio","m":["lumbares","glúteo mayor","cuádriceps"],"m2":["antebrazo","isquiotibiales","trapecio"],"ins":["Colócate dentro de una barra trampa cargada con los pies a la anchura de los hombros.","Flexiona caderas y rodillas para agarrar las asas.","Contrae el core y mantén la espalda plana.","Empuja con los talones y extiende caderas y rodillas para ponerte erguido.","Bloquea en la parte alta con los hombros hacia atrás.","Baja la barra al suelo de forma controlada."],"tips":["Mantén el pecho arriba y la espalda plana mientras ajustas el agarre.","Empuja el suelo en lugar de tirar de la barra con la espalda.","Ponte completamente erguido arriba sin inclinarte hacia atrás."],"met":6.0,"uni":false,"img":["hex-bar-deadlift-start.webp","hex-bar-deadlift-peak.webp"]},{"id":"high-foot-leg-press","n":"Prensa de piernas con pies altos","d":"Una prensa de piernas con los pies colocados altos en la plataforma, que desplaza más trabajo hacia la extensión de cadera y el glúteo mayor con la espalda apoyada.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"prensa","home":false,"bw":false,"lv":"principiante","m":["glúteo mayor"],"m2":["isquiotibiales","cuádriceps"],"ins":["Ajusta el respaldo para que la zona lumbar permanezca apoyada y la pelvis no se redondee al bajar.","Coloca ambos pies altos y aproximadamente al ancho de los hombros, alineando rodillas y puntas de los pies.","Baja el carro flexionando caderas y rodillas hasta una profundidad cómoda sin despegar la zona lumbar del respaldo.","Empuja con todo el pie y extiende caderas y rodillas sin bloquearlas con fuerza.","Baja el carro bajo control y repite el número deseado de repeticiones."],"tips":["Mantén la pelvis pesada contra el respaldo; una posición alta de los pies no justifica redondear la espalda baja.","Mantén los talones y todo el pie apoyados en lugar de empujar solo con los dedos.","Elige una profundidad que conserve la posición de la pelvis."],"met":6.0,"uni":false,"img":["high-foot-leg-press-start.webp","high-foot-leg-press-peak.webp"]},{"id":"high-knees","n":"Rodillas Altas","d":"Un ejercicio cardio con peso corporal en el que las rodillas suben a la altura de la cadera en alternancia rápida.","cat":"cardio","g":"cuerpo completo","bp":"full_body","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["flexores de cadera","cuádriceps"],"m2":["gemelos","abdominales"],"ins":["Mantente erguido con los pies a la anchura de las caderas.","Lleva una rodilla arriba hacia el pecho bombeando el brazo opuesto.","Cambia de pierna rápidamente, espejando la acción del brazo.","Continúa alternando a ritmo rápido.","Continúa durante el intervalo de trabajo indicado."],"tips":["Sube las rodillas al menos a la altura de la cadera.","Mantente ligero sobre las puntas de los pies.","Mantén el torso erguido — no te eches atrás."],"met":8.0,"uni":false,"img":["high-knees-main.webp"]},{"id":"high-plank","n":"Plancha Alta","d":"Una variación de plancha con los brazos totalmente extendidos en posición de push-up.","cat":"fuerza","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["abdominales","transverso abdominal"],"m2":["lumbares","oblicuos"],"ins":["Empieza en posición de push-up con los brazos totalmente extendidos.","Mantén el cuerpo en línea recta de cabeza a talones.","Contrae el core y mantén la posición.","Respira de forma regular durante el ejercicio."],"tips":["Coloca las manos directamente debajo de los hombros.","Aprieta glúteos y abdomen para que la cadera no caiga.","Mira al suelo para mantener el cuello neutro."],"met":5.0,"uni":false,"img":["high-plank-main.webp"]},{"id":"hip-abduction","n":"Abducción de Cadera en Máquina","d":"Un ejercicio en máquina que trabaja los músculos de la cadera externa.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"máquina de abductores","home":false,"bw":false,"lv":"principiante","m":["glúteo medio"],"m2":["abductores"],"ins":["Siéntate en la máquina de abducción de cadera con los apoyos contra la parte externa de los muslos.","Empuja las piernas hacia afuera contra la resistencia.","Mantén brevemente en el punto más amplio.","Vuelve a la posición inicial de forma controlada.","Repite."],"tips":["Mantén la espalda apoyada en el respaldo de la máquina.","Abre las piernas sin impulso, con un ritmo controlado.","Resiste la vuelta al centro en lugar de soltar el peso de golpe."],"met":5.0,"uni":false,"img":["hip-abduction-start.webp","hip-abduction-peak.webp"]},{"id":"hip-adduction","n":"Aducción de cadera","d":"Un ejercicio en máquina apretando las piernas una contra otra frente a la resistencia, aislando y fortaleciendo los aductores de la cara interna del muslo.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"máquina de aductores","home":false,"bw":false,"lv":"intermedio","m":["aductores"],"m2":[],"ins":["Siéntate en la máquina de aducción de cadera con la espalda contra el respaldo.","Coloca las piernas contra las almohadillas con la máquina ajustada a un estiramiento cómodo.","Aprieta las piernas hasta que las almohadillas se junten en el centro.","Mantén brevemente la contracción en la posición completamente cerrada.","Deja que las piernas se abran de vuelta con control hasta el inicio.","Repite el número deseado de repeticiones."],"tips":["Elige una apertura inicial que estire sin forzar la ingle.","Recorre todo el rango a una velocidad uniforme y controlada.","No dejes que la placa de peso golpee al abrir las piernas."],"met":5.0,"uni":false,"img":["hip-adduction-start.webp","hip-adduction-peak.webp"]},{"id":"hip-thrust","n":"Hip thrust con barra","d":"Un ejercicio compuesto para glúteos que utiliza una barra apoyada sobre las caderas.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["glúteo mayor","glúteo medio"],"m2":["isquiotibiales"],"ins":["Siéntate en el suelo con la parte superior de la espalda contra un banco y la barra sobre las caderas.","Empuja las caderas hacia arriba hasta que los muslos queden paralelos al suelo.","Aprieta los glúteos en la parte superior.","Baja las caderas de nuevo con control.","Repite."],"tips":["Mantén la barbilla recogida y las costillas abajo.","Empuja a través de los talones, no de las puntas.","Evita arquear la zona lumbar en la parte alta."],"met":6.0,"uni":false,"img":["hip-thrust-start.webp","hip-thrust-peak.webp"]},{"id":"hollow-body-hold","n":"Mantenimiento del Cuerpo Hueco","d":"Un mantenimiento isométrico de core de la gimnasia, que entrena la tensión de cuerpo completo con la columna en ligera forma de C.","cat":"fuerza","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["abdominales"],"m2":["flexores de cadera","oblicuos","transverso abdominal"],"ins":["Acuéstate boca arriba con los brazos extendidos sobre la cabeza y las piernas rectas.","Presiona la zona lumbar firmemente contra el suelo.","Levanta ligeramente los hombros, la cabeza y las piernas del suelo.","Mantén la posición con brazos y piernas extendidos, cuerpo en forma de plátano poco profundo.","Sostén durante el tiempo indicado."],"tips":["Mantén la zona lumbar pegada al suelo — si se levanta, sube más las piernas.","Mete ligeramente la barbilla para activar los abdominales superiores.","Flexiona las rodillas para escalar si la posición se rompe."],"met":5.0,"uni":false,"img":["hollow-body-hold-main.webp"]},{"id":"horizontal-leg-press","n":"Prensa de piernas horizontal","d":"Una prensa de piernas en máquina realizada en posición horizontal, que trabaja cuádriceps, glúteos e isquiotibiales.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"prensa","home":false,"bw":false,"lv":"principiante","m":["glúteo mayor","cuádriceps"],"m2":["isquiotibiales"],"ins":["Siéntate en la máquina de prensa de piernas horizontal y coloca los pies a la anchura de los hombros.","Desbloquea la máquina y baja la plataforma hacia tu pecho.","Empuja la plataforma de vuelta a la posición inicial.","Repite."],"tips":["No dejes que la zona lumbar se separe del asiento.","Evita bloquear completamente las rodillas."],"met":6.0,"uni":false,"img":["horizontal-leg-press-start.webp","horizontal-leg-press-peak.webp"]},{"id":"human-flag","n":"Human Flag","d":"Un sostén isométrico avanzado de calistenia con el cuerpo horizontal sobre un poste vertical, paralelo al suelo.","cat":"fuerza","g":"core","bp":"core","eq":"barra de dominadas","home":true,"bw":false,"lv":"avanzado","m":["dorsales","oblicuos"],"m2":["deltoides anterior","glúteo mayor","pectoral","abdominales","tríceps"],"ins":["Ponte de pie cerca de un poste vertical resistente.","Agarra el poste arriba con la mano superior (en pronación) y abajo con la mano inferior (en supinación).","Impulsa las piernas hacia arriba y afuera mientras empujas con fuerza el brazo inferior contra el poste.","Extiende el cuerpo en horizontal hasta formar una línea recta paralela al suelo.","Mantén la posición con el cuerpo rígido durante el tiempo objetivo.","Baja de forma controlada."],"tips":["Llega a la bandera completa pasando antes por progresiones agrupada y en straddle.","El brazo inferior empuja y el superior tira; juntos equilibran la palanca.","Activa con fuerza dorsales, oblicuos y glúteos para mantenerte rígido."],"met":6.0,"uni":false,"img":["human-flag-main.webp"]},{"id":"inchworm","n":"Inchworm","d":"Un ejercicio de calentamiento y movilidad con el peso corporal: desde una flexión hacia delante de pie, caminas con las manos por el suelo hasta que el cuerpo queda en plancha baja, con los codos flexionados como en el punto más bajo de una flexión de brazos, y luego las caminas de vuelta hacia los pies. Estira los isquiotibiales y las pantorrillas mientras los hombros, el pecho y el tronco sostienen la plancha baja.","cat":"fuerza","g":"cuerpo completo","bp":"full_body","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["isquiotibiales"],"m2":["deltoides anterior","gemelos","pectoral","abdominales","serrato","tríceps"],"ins":["Ponte de pie, erguido, con los pies separados aproximadamente al ancho de las caderas.","Flexiónate hacia delante desde las caderas y apoya las manos en el suelo delante de los pies, flexionando un poco las rodillas si lo necesitas.","Camina con las manos hacia delante, una tras otra, manteniendo las piernas lo más estiradas que puedas con comodidad, hasta que el cuerpo quede en línea recta cerca del suelo.","Flexiona los codos para que el pecho quede justo por encima del suelo, como en el punto más bajo de una flexión de brazos, y haz una breve pausa con el tronco firme.","Camina con las manos de vuelta hacia los pies con pasos cortos, elevando las caderas, hasta volver a la flexión hacia delante.","Levántate o pasa directamente a la siguiente repetición."],"tips":["Mantén las rodillas lo más estiradas que puedas para que los isquiotibiales y las pantorrillas reciban el estiramiento; una ligera flexión está bien si las manos no llegan al suelo.","Aprieta el tronco en la plancha baja para que las caderas no se hundan ni se eleven. Para una versión más fácil, detente en una plancha con los brazos estirados y omite el descenso.","Da pasos cortos y controlados; caminar demasiado lejos y demasiado rápido hace que acabes desplomándote en el suelo."],"met":5.0,"uni":false,"img":["inchworm-start.webp","inchworm-peak.webp"]},{"id":"incline-bench-ez-bar-press","n":"Press en banco inclinado con barra Z","d":"Un press en banco inclinado con barra Z que trabaja la parte superior del pecho con un agarre cómodo para las articulaciones.","cat":"fuerza","g":"pecho","bp":"chest","eq":"barra Z","home":false,"bw":false,"lv":"intermedio","m":["pectoral"],"m2":["deltoides anterior","tríceps"],"ins":["Ajusta el banco a 30–45 grados. Agarra la barra Z con las manos en las secciones anguladas.","Baja la barra hasta la parte superior del pecho.","Empuja de vuelta hasta la extensión completa.","Repite."],"tips":["La inclinación desplaza el énfasis hacia la parte superior del pectoral.","Controla el descenso para evitar tensión en los hombros."],"met":6.0,"uni":false,"img":["incline-bench-ez-bar-press-start.webp","incline-bench-ez-bar-press-peak.webp"]},{"id":"incline-bench-press","n":"Press en banco inclinado con barra","d":"Un movimiento de press con barra en banco inclinado que trabaja la parte superior del pecho.","cat":"fuerza","g":"pecho","bp":"chest","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["pectoral"],"m2":["deltoides anterior","tríceps"],"ins":["Acuéstate en un banco inclinado a 30-45 grados.","Agarra la barra ligeramente más ancha que los hombros y desrackea.","Baja la barra hasta la parte superior del pecho.","Empuja la barra de vuelta hasta la extensión completa.","Repite."],"tips":["Retrae las escápulas y mantenlas pegadas al banco.","Evita rebotar la barra en el pecho.","Pide asistencia cuando trabajes con cargas pesadas."],"met":6.0,"uni":false,"img":["incline-bench-press-start.webp","incline-bench-press-peak.webp"]},{"id":"incline-db-curl","n":"Curl con mancuernas en banco inclinado","d":"Un curl de bíceps en banco inclinado para un mayor estiramiento de la cabeza larga.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["bíceps"],"m2":["braquial"],"ins":["Siéntate en un banco inclinado a 45 grados con mancuernas a los lados.","Deja que los brazos cuelguen rectos con las palmas hacia adelante.","Sube las mancuernas hacia los hombros.","Baja con control hasta la extensión completa.","Repite."],"tips":["Mantén los hombros y la espalda apoyados en el banco.","No adelantes los hombros al subir las mancuernas.","Aprovecha el estiramiento abajo con una bajada lenta."],"met":5.0,"uni":false,"img":["incline-db-curl-start.webp","incline-db-curl-peak.webp"]},{"id":"incline-db-press","n":"Press con mancuernas en banco inclinado","d":"Un movimiento de press en banco inclinado que enfatiza la parte superior del pecho.","cat":"fuerza","g":"pecho","bp":"chest","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["pectoral"],"m2":["deltoides anterior","tríceps"],"ins":["Ajusta el banco a 30 grados de inclinación y siéntate con las mancuernas a la altura de los hombros.","Empuja las mancuernas hacia arriba y juntas hasta que los brazos estén completamente extendidos.","Baja las mancuernas de vuelta a la altura de los hombros con control.","Repite."],"tips":["Mantén los pies firmes en el suelo y las escápulas retraídas.","Evita chocar las mancuernas en la parte alta.","Baja hasta sentir un estiramiento suave en el pecho."],"met":6.0,"uni":false,"img":["incline-db-press-start.webp","incline-db-press-peak.webp"]},{"id":"incline-dumbbell-fly","n":"Apertura con mancuernas en banco inclinado","d":"Un ejercicio de aislamiento en banco inclinado que abre las mancuernas en un arco amplio, estirando y trabajando el pecho superior.","cat":"fuerza","g":"pecho","bp":"chest","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["pectoral"],"m2":["deltoides anterior","bíceps"],"ins":["Acuéstate en un banco inclinado con mancuernas sobre el pecho.","Sube las mancuernas con las palmas enfrentadas.","Mantén una ligera flexión en los codos durante todo el movimiento.","Baja las mancuernas en un arco amplio hasta sentir el estiramiento del pecho.","Aprieta el pecho para juntar las mancuernas de nuevo.","Repite el número deseado de repeticiones."],"tips":["Mantén una ligera flexión fija en los codos en todo momento.","Baja solo hasta donde permita un estiramiento cómodo del pecho.","Aprieta el pecho para volver a juntar las mancuernas."],"met":5.0,"uni":false,"img":["incline-dumbbell-fly-start.webp","incline-dumbbell-fly-peak.webp"]},{"id":"incline-hammer-curl","n":"Curl martillo en banco inclinado","d":"Un curl martillo realizado en banco inclinado para mayor estiramiento y activación de la cabeza larga del bíceps.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["bíceps","braquial"],"m2":["antebrazo"],"ins":["Siéntate en un banco inclinado con mancuernas en agarre neutro.","Deja que los brazos cuelguen rectos.","Sube las mancuernas en un movimiento de martillo.","Baja lentamente.","Repite."],"tips":["La inclinación proporciona un mayor estiramiento.","Evita balancear el cuerpo."],"met":5.0,"uni":false,"img":["incline-hammer-curl-start.webp","incline-hammer-curl-peak.webp"]},{"id":"incline-push-ups","n":"Push-up inclinado","d":"Una variación del push-up apta para principiantes con las manos elevadas sobre un banco o escalón.","cat":"fuerza","g":"pecho","bp":"chest","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["pectoral"],"m2":["deltoides anterior","tríceps"],"ins":["Coloca las manos sobre un banco o superficie elevada, a la anchura de los hombros.","Extiende las piernas hacia atrás en posición de plancha.","Baja el pecho hacia el banco flexionando los codos.","Empuja de vuelta a la posición inicial.","Repite."],"tips":["Aprieta el abdomen para que la cadera no se hunda.","Cuanto más alta la superficie, más fácil el ejercicio.","Asegúrate de que el banco no se mueva antes de empezar."],"met":5.0,"uni":false,"img":["incline-push-ups-start.webp","incline-push-ups-peak.webp"]},{"id":"incline-treadmill-walk","n":"Caminata en Cinta Inclinada","d":"Una caminata cuesta arriba sostenida sobre una cinta inclinada, manteniendo siempre un pie en contacto con la banda para que glúteos e isquiotibiales trabajen duro casi sin impacto.","cat":"cardio","g":"cuerpo completo","bp":"full_body","eq":"trotadora","home":false,"bw":false,"lv":"principiante","m":["glúteo mayor","cuádriceps"],"m2":["gemelos","isquiotibiales","sóleo"],"ins":["Arranca la banda a velocidad de caminata lenta, súbete y luego eleva la inclinación hasta la pendiente que buscas.","Camina con una zancada larga y deliberada, rodando del talón a la punta y empujando la banda hacia atrás en cada paso.","Mantente erguido e inclínate hacia la cuesta desde los tobillos, sin doblarte hacia delante por la cintura.","Mantén al menos un pie sobre la banda en todo momento — camina la cuesta, no la trotes.","Deja que los brazos se balanceen con naturalidad o apóyalos suavemente en los raíles para equilibrarte, sin descargar el peso en ellos.","Sostén la pendiente durante el tiempo deseado, luego bájala y camina en llano unos minutos para terminar."],"tips":["Elige una velocidad a la que todavía puedas caminar. En cuanto necesites una fase de vuelo para seguir el ritmo, baja la velocidad o la inclinación — es una caminata, no una carrera.","Colgar el peso del cuerpo de los pasamanos elimina casi todo el trabajo que la cuesta está ahí para generar; tócalos solo para equilibrarte.","Es la pendiente pronunciada la que traslada el esfuerzo del cuádriceps a glúteos e isquiotibiales, así que sube la inclinación antes que la velocidad."],"met":8.0,"uni":false,"img":["incline-treadmill-walk-main.webp"]},{"id":"inverted-row","n":"Remo invertido","d":"Un ejercicio de jalón horizontal con el peso corporal realizado bajo una barra fija, tirando del pecho hacia la barra mientras se mantiene el cuerpo rígido.","cat":"fuerza","g":"espalda","bp":"back","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["dorsales","romboides","trapecio"],"m2":["bíceps","deltoides posterior","abdominales"],"ins":["Coloca una barra en un rack a la altura de la cintura aproximadamente.","Acuéstate debajo y agarra la barra ligeramente más ancha que los hombros con agarre prono.","Cuélgate con los brazos extendidos, los talones en el suelo y el cuerpo recto de la cabeza a los tobillos.","Tira del pecho hacia la barra, apretando los omóplatos.","Bájate con control hasta que los brazos estén completamente extendidos.","Repite."],"tips":["Mantén el core contraído — sin que las caderas se hundan.","Para hacerlo más difícil, eleva los pies; para hacerlo más fácil, camina los pies hacia la barra.","Haz una breve pausa en la parte superior con el pecho contra la barra."],"met":6.0,"uni":false,"img":["inverted-row-start.webp","inverted-row-peak.webp"]},{"id":"isometric-neck-side","n":"Flexión Lateral Isométrica de Cuello","d":"Un ejercicio estático de cuello que usa la mano como resistencia contra la cabeza, trabajando el esternocleidomastoideo y los escalenos sin equipo.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["trapecio"],"m2":[],"ins":["Siéntate o ponte de pie erguido. Coloca la palma de una mano en el lado de la cabeza, por encima de la oreja.","Empuja la cabeza contra la mano resistiendo por igual con la mano: la cabeza no se mueve.","Mantén la contracción isométrica de 5 a 10 segundos.","Suelta lentamente y repite en el mismo lado durante la serie.","Cambia de lado y repite."],"tips":["Ajusta la presión; es un 50 % de esfuerzo, no un pulso.","Mantén la mandíbula relajada y los hombros bajos."],"met":3.5,"uni":true,"img":["isometric-neck-side-main.webp"]},{"id":"jackknife-sit-up","n":"Abdominal navaja","d":"Un crunch de cuerpo completo realizado desde el suelo, levantando las piernas y el torso simultáneamente para tocar las manos con los pies.","cat":"fuerza","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["abdominales"],"m2":["flexores de cadera","oblicuos"],"ins":["Acuéstate boca arriba en el suelo con los brazos extendidos por encima de la cabeza y las piernas estiradas.","Levanta simultáneamente el torso y las piernas rectas del suelo.","Lleva las manos hacia los pies mientras estos suben — encuéntralos sobre las caderas.","Baja el torso y las piernas de vuelta al suelo con control.","Repite el número recomendado de repeticiones."],"tips":["Brazos y piernas se mueven a la misma velocidad — evita hacer trampa levantando primero las piernas.","Si la zona lumbar se arquea al bajar, reduce la velocidad y no toques completamente el suelo."],"met":5.0,"uni":false,"img":["jackknife-sit-up-start.webp","jackknife-sit-up-peak.webp"]},{"id":"jefferson-curl","n":"Jefferson curl","d":"Un ejercicio de flexión espinal con carga: de pie y con un peso ligero, redondeas la columna vértebra a vértebra y la vuelves a apilar, desarrollando control segmentario y flexibilidad de isquiotibiales y erectores bajo carga.","cat":"fuerza","g":"espalda","bp":"back","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["lumbares","isquiotibiales"],"m2":["glúteo mayor"],"ins":["Ponte de pie sujetando una mancuerna ligera con los brazos estirados, pies aproximadamente al ancho de las caderas.","Mete la barbilla y empieza a redondear la columna desde arriba, vértebra a vértebra.","Baja despacio dejando colgar el peso y manteniendo las piernas casi rectas.","Llega abajo con la espalda totalmente redondeada y un estiramiento en los isquiotibiales.","Invierte el movimiento, reapilando la columna de abajo hacia arriba hasta ponerte de pie."],"tips":["Usa un peso muy ligero: es un ejercicio de movilidad controlado, no un levantamiento pesado.","Redondea segmento a segmento; no bisagres desde la cadera como en un peso muerto rígido.","Muévete despacio y nunca rebotes abajo."],"met":6.0,"uni":false,"img":["jefferson-curl-start.webp","jefferson-curl-peak.webp"]},{"id":"jump-rope","n":"Saltar la Cuerda","d":"Un ejercicio cardio clásico que trabaja gemelos, tobillos y ritmo con una cuerda y saltos rítmicos.","cat":"cardio","g":"cuerpo completo","bp":"full_body","eq":"cuerda","home":true,"bw":false,"lv":"principiante","m":["gemelos","sóleo"],"m2":["antebrazo","cuádriceps"],"ins":["Sujeta el mango de la cuerda en cada mano con la cuerda detrás de ti.","Balancea la cuerda sobre la cabeza y al frente en un arco fluido.","Salta justo lo suficiente para que la cuerda pase bajo los pies.","Aterriza suave sobre las puntas, rodillas ligeramente flexionadas.","Mantén un ritmo constante durante el intervalo indicado."],"tips":["Gira la cuerda con las muñecas, no con los hombros.","Salta bajo — apenas dos o tres centímetros del suelo.","Mantente erguido con los codos cerca del cuerpo."],"met":11.8,"uni":false,"img":["jump-rope-main.webp"]},{"id":"jump-squat","n":"Sentadilla con Salto","d":"Una sentadilla pliométrica con peso corporal donde explotas hacia arriba en un salto vertical.","cat":"pliometría","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["glúteo mayor","cuádriceps"],"m2":["gemelos","isquiotibiales"],"ins":["Mantente con los pies a la anchura de los hombros.","Baja a una media sentadilla con los brazos atrás.","Explota hacia arriba, balanceando los brazos y saltando lo más alto posible.","Aterriza suave en media sentadilla para absorber el impacto.","Repite sin pausa el número de repeticiones indicado."],"tips":["Aterriza suave con las rodillas flexionadas.","Lanza los brazos arriba para ganar altura en el salto.","Mantén el pecho arriba — no dejes que el torso colapse."],"met":7.0,"uni":false,"img":["jump-squat-start.webp","jump-squat-peak.webp"]},{"id":"jumping-jacks","n":"Saltos de Tijera","d":"Este clásico ejercicio dinámico de cuerpo completo eleva la frecuencia cardíaca y trabaja pantorrillas, hombros, cuádriceps y glúteos, siendo excelente para calentar o acondicionar.","cat":"cardio","g":"cuerpo completo","bp":"full_body","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["gemelos","glúteo medio","deltoides lateral"],"m2":["abductores","cuádriceps","sóleo"],"ins":["Ponte de pie con los pies juntos y los brazos a los lados.","Simultáneamente, salta abriendo las piernas y levantando los brazos por encima de la cabeza.","Asegúrate de que tus brazos se junten o casi se junten por encima de tu cabeza.","Salta juntando los pies de nuevo mientras bajas los brazos a los lados.","Mantén un movimiento continuo y rítmico."],"tips":["Aterriza suavemente sobre las puntas de los pies para absorber el impacto.","Mantén tu core activado durante todo el movimiento.","Controla tu respiración; inhala al saltar hacia afuera, exhala al saltar hacia adentro.","Aumenta la velocidad para un mayor desafío cardiovascular."],"met":8.0,"uni":false,"img":["jumping-jacks-start.webp","jumping-jacks-peak.webp"]},{"id":"kettlebell-bulgarian-split-squat","n":"Sentadilla Búlgara con Kettlebell","d":"Esta variación unilateral de sentadilla desarrolla fuerza, músculo y estabilidad en la parte inferior del cuerpo al elevar el pie trasero y sostener una kettlebell, apuntando principalmente a los cuádriceps y glúteos.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"kettlebell","home":true,"bw":false,"lv":"intermedio","m":["glúteo mayor","cuádriceps"],"m2":["glúteo medio","isquiotibiales"],"ins":["Párate de espaldas a un banco, colocando un pie sobre él detrás de ti, con los cordones hacia abajo. Sostén una kettlebell en la mano del lado contrario a la pierna delantera.","Mantén el torso erguido y activa tu core.","Baja tu cuerpo doblando ambas rodillas, permitiendo que tu rodilla delantera se alinee con tus dedos del pie.","Desciende hasta que tu muslo delantero esté paralelo al suelo o ligeramente por debajo, manteniendo tu rodilla trasera cerca del suelo.","Impúlsate a través del talón delantero para regresar a la posición inicial, extendiendo tus caderas y rodillas.","Completa todas las repeticiones por lado antes de cambiar."],"tips":["Asegúrate de que tu pie delantero esté lo suficientemente lejos del banco para permitir un rango completo de movimiento sin molestias.","Mantén tu torso erguido durante todo el movimiento para maximizar la activación de glúteos y cuádriceps.","Controla la fase excéntrica (descenso) para desarrollar fuerza y estabilidad.","Experimenta sosteniendo la kettlebell en la misma mano que la pierna que trabaja (ipsilateral) o en la mano opuesta (contralateral) para diferentes desafíos."],"met":6.0,"uni":true,"img":["kettlebell-bulgarian-split-squat-start.webp","kettlebell-bulgarian-split-squat-peak.webp"]},{"id":"kettlebell-close-grip-floor-press","n":"Press de Suelo con Agarre Cerrado con Pesa Rusa","d":"Un press de suelo con una sola pesa rusa agarrada con ambas manos juntas, que desplaza el énfasis del pecho a los tríceps.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"kettlebell","home":true,"bw":false,"lv":"intermedio","m":["tríceps"],"m2":["deltoides anterior","pectoral"],"ins":["Túmbate boca arriba en el suelo con las rodillas flexionadas y los pies apoyados.","Sujeta una única pesa rusa por el asa con ambas manos juntas, con la pesa apoyada en el pecho y los codos bien pegados a las costillas.","Activa el core y empuja la pesa rusa recto hacia arriba hasta estirar del todo los brazos.","Baja de forma controlada hasta que la parte alta de los brazos toque el suelo y haz una breve pausa.","Vuelve a empujar hacia arriba hasta la extensión completa.","Repite el número de repeticiones recomendado."],"tips":["Mantén los codos pegados a unos 30–45 grados del torso; abrirlos lo convierte en press de pecho.","La breve pausa al tocar el suelo con los codos elimina el rebote y fuerza un empuje limpio.","Elige una pesa que puedas controlar con dos manos; el agarre estrecho no perdona si se ladea."],"met":6.0,"uni":false,"img":["kettlebell-close-grip-floor-press-start.webp","kettlebell-close-grip-floor-press-peak.webp"]},{"id":"kettlebell-concentration-curl","n":"Curl de concentración con kettlebell","d":"Un ejercicio de aislamiento de bíceps a una mano, sentado: el codo se apoya contra la cara interna del muslo mientras se curla una kettlebell, manteniendo el brazo quieto para que el bíceps haga todo el trabajo.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"kettlebell","home":true,"bw":false,"lv":"principiante","m":["bíceps"],"m2":["braquial"],"ins":["Siéntate en un banco con los pies bien separados, sujetando una kettlebell con una mano.","Apoya la parte posterior del brazo contra la cara interna del muslo y deja colgar la kettlebell.","Curla la kettlebell hacia el hombro, manteniendo el codo fijo contra la pierna.","Contrae el bíceps arriba y luego baja despacio y de forma controlada.","Termina todas las repeticiones de un lado y cambia de brazo."],"tips":["Mantén el brazo fijo y quieto: solo el antebrazo se mueve.","Rota ligeramente la muñeca al curlar para una contracción máxima más fuerte.","Usa un peso más ligero que en un curl normal: aquí importa más la técnica estricta."],"met":5.0,"uni":true,"img":["kettlebell-concentration-curl-start.webp","kettlebell-concentration-curl-peak.webp"]},{"id":"kettlebell-deadlift","n":"Peso muerto con pesa rusa","d":"Un peso muerto con pesa rusa que fortalece glúteos, isquiotibiales y zona lumbar con un patrón de bisagra de cadera.","cat":"fuerza","g":"espalda","bp":"back","eq":"kettlebell","home":true,"bw":false,"lv":"intermedio","m":["lumbares","glúteo mayor","isquiotibiales"],"m2":["antebrazo","cuádriceps"],"ins":["Párate con los pies a la anchura de los hombros y la pesa rusa entre los pies.","Bisagra en las caderas y flexiona las rodillas para agarrar el asa.","Contrae el core y mantén la espalda plana.","Empuja a través de los talones para ponerte de pie con la pesa rusa.","Bloquea en la parte superior con los hombros hacia atrás.","Baja la pesa rusa de vuelta al suelo con control."],"tips":["Mantén la pesa rusa cerca del cuerpo durante todo el recorrido.","Piensa en empujar el suelo con los talones, no en tirar con la espalda.","Lleva las caderas atrás, no las rodillas adelante, al bajar."],"met":6.0,"uni":false,"img":["kettlebell-deadlift-start.webp","kettlebell-deadlift-peak.webp"]},{"id":"kettlebell-farmers-walk","n":"Paseo del Granjero con Pesa Rusa","d":"Un acarreo cargado caminando con un peso pesado en cada mano, que reta el agarre, los trapecios y la estabilidad de todo el cuerpo.","cat":"fuerza","g":"cuerpo completo","bp":"full_body","eq":"kettlebell","home":true,"bw":false,"lv":"intermedio","m":["antebrazo","trapecio"],"m2":["lumbares","glúteo mayor","cuádriceps","abdominales"],"ins":["Ponte de pie entre dos kettlebells pesadas.","Flexiona las caderas y agarra las asas con firmeza en agarre neutro.","Ponte erguido con los hombros atrás y el core activado.","Camina hacia delante con pasos cortos y controlados.","Mantén una postura erguida durante todo el recorrido.","Deja los pesos en el suelo al final de la distancia."],"tips":["Aprieta las asas con fuerza para que el peso no te resbale de las manos.","Mantén el core firme y no te balancees de lado a lado al caminar.","Da pasos cortos y rápidos; las zancadas largas rompen el equilibrio."],"met":5.5,"uni":false,"img":["kettlebell-farmers-walk-main.webp"]},{"id":"kettlebell-floor-press","n":"Press de suelo con pesas rusas","d":"Un press de pecho con dos brazos realizado tumbado en el suelo con una pesa rusa en cada mano. El suelo limita el rango de movimiento (los tríceps tocan el suelo antes del estiramiento completo), haciéndolo amigable para los hombros y una excelente opción en casa.","cat":"fuerza","g":"pecho","bp":"chest","eq":"kettlebell","home":true,"bw":false,"lv":"intermedio","m":["pectoral"],"m2":["deltoides anterior","tríceps"],"ins":["Acuéstate boca arriba en el suelo con las rodillas flexionadas y los pies apoyados.","Sostén una pesa rusa en cada mano a la altura del pecho, con las campanas apoyadas en el antebrazo externo.","Empuja ambas pesas rusas hacia arriba hasta que los brazos estén completamente extendidos.","Baja con control hasta que los tríceps toquen el suelo — no rebotes.","Repite el número recomendado de repeticiones."],"tips":["Los codos se mantienen a unos 45 grados del torso; no los abras.","El agarre importa: mantén las campanas estables contra el exterior de los antebrazos.","El suelo limita el rango de movimiento por diseño — esta es la ventaja, no el problema."],"met":6.0,"uni":false,"img":["kettlebell-floor-press-start.webp","kettlebell-floor-press-peak.webp"]},{"id":"kettlebell-goblet-lunge","n":"Zancada Goblet con Kettlebell","d":"Este ejercicio compuesto unilateral fortalece los cuádriceps, glúteos e isquiotibiales al realizar una zancada con una kettlebell en posición de copa, mejorando la fuerza y estabilidad del tren inferior.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"kettlebell","home":true,"bw":false,"lv":"principiante","m":["glúteo mayor","cuádriceps"],"m2":["glúteo medio","isquiotibiales"],"ins":["Ponte de pie sosteniendo una kettlebell por sus cuernos a la altura del pecho, con los codos pegados al cuerpo, en la posición de copa.","Da un paso controlado hacia adelante con una pierna, bajando las caderas hasta que ambas rodillas estén flexionadas aproximadamente a 90 grados.","Asegúrate de que tu rodilla delantera esté alineada sobre tu tobillo y tu rodilla trasera flote justo por encima del suelo.","Impúlsate a través del talón de tu pie delantero para volver a la posición inicial, manteniendo el equilibrio y la tensión del core.","Completa todas las repeticiones por lado antes de cambiar, o alterna las piernas por serie."],"tips":["Mantén el pecho erguido y el core contraído durante todo el movimiento para proteger tu columna y mantener la estabilidad.","Concéntrate en un descenso controlado y un impulso potente hacia arriba, activando tus glúteos y cuádriceps.","Evita que tu rodilla delantera se colapse hacia adentro; mantenla alineada con tus dedos del pie."],"met":6.0,"uni":true,"img":["kettlebell-goblet-lunge-start.webp","kettlebell-goblet-lunge-peak.webp"]},{"id":"kettlebell-halo","n":"Halo con pesa rusa","d":"Un ejercicio de movilidad de hombros donde se hace girar una pesa rusa alrededor de la cabeza. Calienta el manguito rotador, la columna torácica y la cintura escapular con carga mínima.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"kettlebell","home":true,"bw":false,"lv":"principiante","m":["deltoides lateral"],"m2":["deltoides posterior","trapecio"],"ins":["Párate erguido con el core contraído, sosteniendo una pesa rusa ligera por las asas (boca abajo) a la altura del pecho.","Sube la campana a un lado de la cabeza y hazla pasar por detrás en un círculo suave.","Tráela de vuelta a la posición inicial frente a tu cara.","Invierte la dirección cada pocas repeticiones.","Repite el número recomendado de repeticiones o tiempo."],"tips":["Solo peso ligero — esto es movilidad, no fuerza.","Mantén la cabeza quieta; la campana gira alrededor, no la cabeza.","Si la campana se aleja, reduce el círculo — órbita ajustada, cerca del cráneo."],"met":5.0,"uni":false,"img":["kettlebell-halo-start.webp","kettlebell-halo-peak.webp"]},{"id":"kettlebell-hammer-curl","n":"Curl martillo con pesa rusa","d":"Un curl con agarre neutro sosteniendo el asa de una pesa rusa de modo que la campana cuelgue junto a la muñeca. La masa descentrada y el agarre neutro trabajan principalmente el braquial y el braquiorradial.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"kettlebell","home":true,"bw":false,"lv":"principiante","m":["bíceps","braquial"],"m2":["braquiorradial"],"ins":["Párate sosteniendo una pesa rusa en una mano, agarrando el asa en posición neutra (palma hacia el cuerpo).","La campana descansa sobre o junto al antebrazo.","Mantén el codo pegado al costado y sube la campana hacia el hombro.","Aprieta en la parte superior y baja con control.","Completa todas las repeticiones en un lado y luego cambia."],"tips":["Controla la masa descentrada — la campana tiende a rotar en la parte inferior del recorrido.","El codo se mantiene quieto; solo el antebrazo se mueve.","Carga ligera — esto trabaja el braquial, no el volumen máximo del bíceps."],"met":5.0,"uni":true,"img":["kettlebell-hammer-curl-start.webp","kettlebell-hammer-curl-peak.webp"]},{"id":"kettlebell-hip-thrust","n":"Empuje de Cadera con Kettlebell","d":"Este ejercicio trabaja eficazmente el glúteo mayor y los isquiotibiales, utilizando una kettlebell para añadir resistencia y lograr una potente extensión de cadera y desarrollo de glúteos.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"kettlebell","home":true,"bw":false,"lv":"principiante","m":["glúteo mayor"],"m2":["isquiotibiales","cuádriceps"],"ins":["Siéntate en el suelo con la parte superior de tu espalda apoyada en un banco, las rodillas flexionadas y los pies planos.","Coloca una kettlebell sobre tus caderas, sujetándola firmemente con ambas manos.","Impúlsate a través de tus talones, levantando tus caderas del suelo hasta que tu cuerpo forme una línea recta desde los hombros hasta las rodillas.","Contrae tus glúteos con fuerza en la parte superior del movimiento.","Baja lentamente tus caderas de vuelta a la posición inicial con control."],"tips":["Mantén tu barbilla pegada al pecho para mantener una columna vertebral neutra.","Concéntrate en empujar a través de tus talones para maximizar la activación de los glúteos.","Asegúrate de que tus rodillas sigan la línea de tus dedos de los pies durante todo el movimiento.","Controla la fase excéntrica, resistiendo el peso mientras bajas tus caderas."],"met":6.0,"uni":false,"img":["kettlebell-hip-thrust-start.webp","kettlebell-hip-thrust-peak.webp"]},{"id":"kettlebell-kickstand-deadlift","n":"Peso Muerto Kickstand con Kettlebell","d":"Un movimiento de bisagra de cadera en postura escalonada con una kettlebell que carga la pierna delantera mientras el pie trasero estabiliza.","cat":"fuerza","g":"espalda","bp":"back","eq":"kettlebell","home":true,"bw":false,"lv":"intermedio","m":["glúteo mayor","isquiotibiales"],"m2":["aductores","lumbares"],"ins":["Coloca un pie detrás de modo que solo los dedos toquen el suelo.","Sostén una kettlebell en la mano del lado del pie trasero.","Bisagra en la cadera bajando la kettlebell hacia la espinilla con la espalda recta.","Mantén la mayor parte del peso en el pie delantero.","Empuja con el talón delantero para volver a la posición inicial. Cambia de lado."],"tips":["Mantén la kettlebell cerca de la pierna.","Para al sentir el estiramiento en el isquiotibial.","Todas las repeticiones en un lado antes de cambiar."],"met":6.0,"uni":true,"img":["kettlebell-kickstand-deadlift-start.webp","kettlebell-kickstand-deadlift-peak.webp"]},{"id":"kettlebell-lunge-press","n":"Zancada con press de pesa rusa","d":"Un ejercicio de cuerpo completo que combina una zancada con un press de pesa rusa a un brazo.","cat":"fuerza","g":"cuerpo completo","bp":"full_body","eq":"kettlebell","home":true,"bw":false,"lv":"intermedio","m":["deltoides anterior","glúteo mayor","cuádriceps"],"m2":["isquiotibiales","abdominales","tríceps"],"ins":["Sostén una pesa rusa a la altura del hombro con un brazo.","Da un paso adelante en zancada con la pierna contraria.","Mientras haces la zancada, empuja la pesa rusa por encima de la cabeza.","Bloquea el brazo en la parte superior del press.","Da un paso atrás de vuelta a la posición de pie mientras bajas la pesa rusa.","Completa las repeticiones en un lado y luego cambia."],"tips":["Mantén el abdomen firme para no inclinarte hacia el lado cargado.","La rodilla delantera debe apuntar en la dirección del pie.","Empieza con poco peso hasta dominar la coordinación del movimiento."],"met":6.0,"uni":true,"img":["kettlebell-lunge-press-start.webp","kettlebell-lunge-press-peak.webp"]},{"id":"kettlebell-offset-reverse-lunge-and-press","n":"Zancada inversa con press desequilibrado de pesa rusa","d":"Una zancada inversa combinada con un press de pesa rusa a un brazo, con carga descompensada que exige estabilidad del core.","cat":"fuerza","g":"cuerpo completo","bp":"full_body","eq":"kettlebell","home":true,"bw":false,"lv":"intermedio","m":["deltoides anterior","glúteo mayor","cuádriceps"],"m2":["isquiotibiales","oblicuos","tríceps"],"ins":["Sostén una pesa rusa a la altura del hombro en un lado.","Da un paso hacia atrás en zancada inversa con la pierna contraria.","Al llegar a la parte inferior de la zancada, empuja la pesa rusa por encima de la cabeza.","Empuja con el talón delantero para volver a ponerte de pie.","Baja la pesa rusa de vuelta a la altura del hombro.","Completa las repeticiones en un lado y luego cambia."],"tips":["Mantén el torso erguido frente a la carga descompensada.","Bloquea el codo arriba con la muñeca firme y recta.","Si pierdes el equilibrio, acorta un poco el paso atrás."],"met":6.0,"uni":true,"img":["kettlebell-offset-reverse-lunge-and-press-start.webp","kettlebell-offset-reverse-lunge-and-press-peak.webp"]},{"id":"kettlebell-overhead-carry","n":"Paseo con Kettlebell sobre la Cabeza","d":"Un paseo cargado con una sola kettlebell bloqueada por encima de la cabeza, donde la bola cuelga por detrás de la muñeca y tira del brazo hacia atrás, lo que la hace más difícil de sostener quieta que una mancuerna.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"kettlebell","home":true,"bw":false,"lv":"intermedio","m":["deltoides anterior","deltoides lateral"],"m2":["antebrazo","oblicuos","cuadrado lumbar","serrato","trapecio","tríceps"],"ins":["Lleva una kettlebell en cargada y press hasta el bloqueo, dejando que la bola se asiente sobre el dorso del antebrazo.","Estira el codo del todo y gira el brazo para que la bola quede por detrás y por encima de la muñeca, no desplazada a un lado.","Mantén el hombro activo: empuja el peso hacia el techo y deja que la escápula rote hacia arriba con él en lugar de forzarla hacia abajo.","Aprieta el tronco y camina hacia delante con zancadas regulares, con la bola alineada sobre hombro y cadera.","Mantén la muñeca recta; dejar que se doble hacia atrás es lo que hace que una kettlebell arriba se sienta inestable.","Carga la distancia deseada, baja de forma controlada y repite por el otro lado."],"tips":["Usa menos peso que con mancuerna. La masa descentrada hace que el mismo kilaje cueste bastante más de sostener quieto.","La muñeca doblada es el fallo habitual. Si se te vence una y otra vez, baja el peso en lugar de pelear con él todo el recorrido.","Haz ambos lados la misma distancia — la carga unilateral es el sentido del ejercicio."],"met":5.5,"uni":true,"img":["kettlebell-overhead-carry-main.webp"]},{"id":"kettlebell-overhead-tricep-extension","n":"Extensión de tríceps por encima de la cabeza con pesa rusa","d":"Una extensión de tríceps por encima de la cabeza sosteniendo una pesa rusa por las asas con ambas manos. La carga descentrada jala la campana detrás de la cabeza para un estiramiento profundo de la cabeza larga.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"kettlebell","home":true,"bw":false,"lv":"intermedio","m":["tríceps"],"m2":[],"ins":["Párate o siéntate sosteniendo una pesa rusa por las asas (boca abajo) con ambas manos por encima de la cabeza.","Brazos completamente extendidos, campana sobre la cabeza.","Flexiona solo los codos para bajar la campana detrás de la cabeza en un arco controlado.","Mantén los brazos verticales y pegados a la cabeza; solo los antebrazos se mueven.","Extiende los codos para devolver la campana por encima de la cabeza.","Repite el número recomendado de repeticiones."],"tips":["Agarra las asas firmemente — la campana tiende a rotar en la parte inferior.","Los codos se mantienen pegados; si se abren, reduce la carga.","Una versión sentado en un banco con respaldo es más fácil para la zona lumbar."],"met":5.0,"uni":false,"img":["kettlebell-overhead-tricep-extension-start.webp","kettlebell-overhead-tricep-extension-peak.webp"]},{"id":"kettlebell-pistol-squat","n":"Sentadilla pistola con pesa rusa","d":"Una sentadilla a una pierna con la pesa rusa al pecho que exige fuerza y equilibrio avanzados.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"kettlebell","home":true,"bw":false,"lv":"avanzado","m":["glúteo mayor","cuádriceps"],"m2":["glúteo medio","isquiotibiales","abdominales"],"ins":["Sostén una pesa rusa a la altura del pecho con ambas manos.","Párate en una pierna con la otra extendida hacia adelante.","Baja las caderas en una sentadilla a una sola pierna.","Mantén la pierna elevada fuera del suelo durante todo el movimiento.","Empuja a través del talón de apoyo para volver a ponerte de pie.","Completa las repeticiones en un lado y luego cambia."],"tips":["Mantén la pesa rusa cerca del pecho como contrapeso.","Baja despacio para no desplomarte en la parte final.","El talón de apoyo no se despega del suelo."],"met":6.0,"uni":true,"img":["kettlebell-pistol-squat-start.webp","kettlebell-pistol-squat-peak.webp"]},{"id":"kettlebell-pullover","n":"Pullover con pesa rusa","d":"Un pullover en banco plano con una pesa rusa sostenida por las asas. El profundo estiramiento por encima de la cabeza trabaja los dorsales, el tríceps (cabeza larga) y el serrato.","cat":"fuerza","g":"espalda","bp":"back","eq":"kettlebell","home":true,"bw":false,"lv":"intermedio","m":["dorsales","pectoral"],"m2":["serrato","tríceps"],"ins":["Acuéstate en un banco plano sosteniendo una pesa rusa por las asas con ambas manos sobre el pecho, brazos casi rectos (ligera flexión de codos).","Con el ángulo de los codos fijo, baja la campana por encima de la cabeza en arco hasta que los brazos estén en línea con el torso.","Tira de la campana de vuelta sobre el pecho siguiendo el mismo arco.","Repite el número recomendado de repeticiones."],"tips":["Mantén la zona lumbar presionada contra el banco — no arquees para ganar recorrido.","Agarra las asas con fuerza; la campana intentará voltearse en la parte inferior.","Baja solo hasta donde tu movilidad de hombros lo permita sin dolor."],"met":6.0,"uni":false,"img":["kettlebell-pullover-start.webp","kettlebell-pullover-peak.webp"]},{"id":"kettlebell-reverse-lunge","n":"Zancada Inversa con Kettlebell","d":"Este ejercicio compuesto unilateral desarrolla fuerza y estabilidad en la parte inferior del cuerpo, trabajando principalmente glúteos y cuádriceps, e involucrando isquiotibiales, glúteo medio y oblicuos.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"kettlebell","home":true,"bw":false,"lv":"principiante","m":["glúteo mayor","cuádriceps"],"m2":["glúteo medio","isquiotibiales","oblicuos"],"ins":["Ponte de pie con una kettlebell en una mano, el brazo extendido hacia abajo, en el mismo lado de la pierna que retrocederá.","Da un paso hacia atrás con una pierna, bajando las caderas hasta que ambas rodillas estén flexionadas aproximadamente a 90 grados.","Mantén la espinilla delantera vertical y el pecho erguido, asegurándote de que la rodilla trasera flote justo por encima del suelo.","Impúlsate a través del talón delantero para volver a la posición inicial.","Completa todas las repeticiones por lado antes de cambiar al otro lado."],"tips":["Mantén un core estable durante todo el movimiento para proteger tu columna vertebral.","Concéntrate en un descenso controlado y un ascenso potente.","Mantén el pie delantero plano y distribuye el peso uniformemente entre el talón y la parte media del pie.","Evita que la rodilla delantera se colapse hacia adentro; mantenla alineada con los dedos del pie."],"met":6.0,"uni":true,"img":["kettlebell-reverse-lunge-start.webp","kettlebell-reverse-lunge-peak.webp"]},{"id":"kettlebell-reverse-wrist-curl","n":"Curl de Muñeca Inverso con Kettlebell","d":"Un curl de muñeca inverso unilateral con kettlebell, que entrena los extensores del antebrazo.","cat":"fuerza","g":"brazos","bp":"lower_arms","eq":"kettlebell","home":true,"bw":false,"lv":"principiante","m":["antebrazo"],"m2":[],"ins":["Siéntate en un banco con el antebrazo sobre el muslo, palma hacia abajo.","Sujeta una kettlebell por el asa, muñeca fuera de la rodilla.","Deja caer la muñeca, bajando la kettlebell.","Levanta el dorso de la mano extendiendo la muñeca.","Baja con control. Repeticiones por lado."],"tips":["Usa una kettlebell muy ligera — los extensores se fatigan rápido.","Mueve solo la muñeca.","Sujeta el asa, no la bola."],"met":5.0,"uni":true,"img":["kettlebell-reverse-wrist-curl-start.webp","kettlebell-reverse-wrist-curl-peak.webp"]},{"id":"kettlebell-rotational-lunge","n":"Zancada rotacional con pesa rusa","d":"Una zancada lateral con pesa rusa y rotación del torso que trabaja piernas, glúteos y oblicuos en varios planos.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"kettlebell","home":true,"bw":false,"lv":"intermedio","m":["glúteo mayor","cuádriceps"],"m2":["glúteo medio","isquiotibiales","oblicuos"],"ins":["Sostén una pesa rusa con ambas manos a la altura del pecho.","Da un paso hacia un lado en una zancada lateral.","Rota el torso hacia la pierna que hace la zancada.","Lleva la pesa rusa hacia la rodilla flexionada.","Empuja con la pierna de la zancada para volver al centro.","Completa las repeticiones en un lado y luego cambia."],"tips":["Gira desde el torso, no desde las rodillas.","Mantén la espalda larga al bajar la pesa hacia la rodilla.","Controla la rotación, sin movimientos bruscos."],"met":6.0,"uni":true,"img":["kettlebell-rotational-lunge-start.webp","kettlebell-rotational-lunge-peak.webp"]},{"id":"kettlebell-russian-twist","n":"Giro ruso con pesa rusa","d":"Un Russian Twist con pesa rusa realizado sentado con los pies en el aire, que entrena los oblicuos mediante rotaciones del torso.","cat":"fuerza","g":"core","bp":"core","eq":"kettlebell","home":true,"bw":false,"lv":"intermedio","m":["oblicuos"],"m2":["flexores de cadera","abdominales"],"ins":["Siéntate en el suelo con las rodillas flexionadas y los pies levantados del suelo.","Sostén una pesa rusa con ambas manos frente al pecho.","Inclínate ligeramente hacia atrás para activar el core.","Rota el torso hacia un lado llevando la pesa rusa junto a la cadera.","Rota hacia el lado opuesto en un movimiento controlado.","Repite el número deseado de repeticiones."],"tips":["Gira los hombros, no solo los brazos.","Mantén la espalda recta aunque el torso esté inclinado hacia atrás.","Apoya los pies en el suelo si te cuesta mantener el equilibrio."],"met":6.0,"uni":false,"img":["kettlebell-russian-twist-start.webp","kettlebell-russian-twist-peak.webp"]},{"id":"kettlebell-shrug","n":"Encogimiento de Hombros con Kettlebell","d":"Este ejercicio de aislamiento trabaja los músculos trapecios superiores elevando los hombros, mejorando la estabilidad del hombro y la fuerza del cuello.","cat":"fuerza","g":"espalda","bp":"back","eq":"kettlebell","home":true,"bw":false,"lv":"principiante","m":["trapecio"],"m2":["antebrazo"],"ins":["Ponte de pie con los pies al ancho de las caderas, sosteniendo una kettlebell en cada mano con las palmas hacia tu cuerpo.","Mantén los brazos rectos y los hombros relajados.","Eleva los hombros directamente hacia tus orejas, contrayendo los trapecios en la parte superior.","Mantén la contracción brevemente.","Baja lentamente los hombros a la posición inicial con control.","Repite el movimiento para el número deseado de repeticiones."],"tips":["Concéntrate en mover solo los hombros, manteniendo los brazos rectos durante todo el movimiento.","Evita rodar los hombros; muévelos directamente hacia arriba y hacia abajo.","Mantén una columna vertebral neutra y el core activado para prevenir la tensión en la espalda baja.","Usa un peso que permita un rango completo de movimiento y una ejecución controlada."],"met":5.0,"uni":false,"img":["kettlebell-shrug-start.webp","kettlebell-shrug-peak.webp"]},{"id":"kettlebell-single-leg-deadlift","n":"Peso muerto a una pierna con pesa rusa","d":"Un peso muerto a una pierna con pesa rusa que fortalece glúteos e isquiotibiales y pone a prueba el equilibrio.","cat":"fuerza","g":"espalda","bp":"back","eq":"kettlebell","home":true,"bw":false,"lv":"intermedio","m":["glúteo mayor","isquiotibiales"],"m2":["lumbares","glúteo medio"],"ins":["Sostén una pesa rusa en una mano y párate en la pierna contraria.","Bisagra en la cadera y baja la pesa rusa hacia el suelo.","Extiende la pierna libre hacia atrás para mantener el equilibrio.","Baja hasta que el torso quede paralelo al suelo.","Empuja a través del talón de apoyo para volver a ponerte de pie.","Completa las repeticiones en un lado y luego cambia."],"tips":["Mantén la cadera cuadrada, sin abrirla hacia el lado libre.","Fija la mirada en un punto del suelo para equilibrarte mejor.","Flexiona ligeramente la rodilla de apoyo durante la bisagra."],"met":6.0,"uni":true,"img":["kettlebell-single-leg-deadlift-start.webp","kettlebell-single-leg-deadlift-peak.webp"]},{"id":"kettlebell-skull-crusher","n":"Skull crusher con pesa rusa","d":"Un skull crusher tumbado en un banco plano, sosteniendo una pesa rusa por las asas con ambas manos. La masa descentrada cuelga por debajo de las muñecas, añadiendo un reto de agarre y control.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"kettlebell","home":true,"bw":false,"lv":"intermedio","m":["tríceps"],"m2":[],"ins":["Acuéstate en un banco plano sosteniendo una pesa rusa por las asas con ambas manos, brazos extendidos sobre el pecho.","Flexiona solo los codos para bajar la campana hacia la frente en un arco controlado.","Mantén los brazos verticales; solo los antebrazos se mueven.","Extiende los codos para empujar la campana de vuelta arriba.","Repite el número recomendado de repeticiones."],"tips":["Agarra las asas firmemente — la campana tiende a rotar hacia adelante en la parte inferior.","Los codos se mantienen pegados — si se abren, la carga es demasiado pesada.","Inclina los brazos ligeramente hacia atrás en dirección a la cabeza para mantener tensión en los tríceps al bloquear."],"met":5.0,"uni":false,"img":["kettlebell-skull-crusher-start.webp","kettlebell-skull-crusher-peak.webp"]},{"id":"kettlebell-squat","n":"Sentadilla con Kettlebell","d":"Una variante de sentadilla sosteniendo una kettlebell con ambas manos colgando baja entre las piernas, añadiendo carga a un patrón de sentadilla estándar.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"kettlebell","home":true,"bw":false,"lv":"principiante","m":["cuádriceps"],"m2":["glúteo mayor"],"ins":["Ponte de pie con los pies separados al ancho de los hombros, sosteniendo una kettlebell con ambas manos frente a ti.","Deja que la kettlebell cuelgue naturalmente entre tus piernas mientras contraes el core.","Flexiona las caderas y las rodillas para bajar en sentadilla, manteniendo la kettlebell cerca del cuerpo.","Empuja con los pies para volver a la posición inicial.","Repite el número deseado de repeticiones."],"tips":["Mantén el pecho arriba y la espalda recta durante todo el movimiento.","Usa la kettlebell como contrapeso para ayudarte a bajar más profundo en la sentadilla.","Empuja las rodillas hacia afuera, en línea con los dedos de los pies, al descender."],"met":6.0,"uni":false,"img":["kettlebell-squat-start.webp","kettlebell-squat-peak.webp"]},{"id":"kettlebell-sumo-deadlift","n":"Peso muerto sumo con pesa rusa","d":"Un peso muerto con postura amplia usando una sola pesa rusa entre los pies. La postura amplia y la carga cerca del cuerpo hacen de este un patrón dominante de cuádriceps y glúteos que es fácil de aprender.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"kettlebell","home":true,"bw":false,"lv":"principiante","m":["glúteo mayor","cuádriceps"],"m2":["aductores","lumbares","isquiotibiales","trapecio"],"ins":["Párate con una postura amplia y los pies ligeramente girados hacia afuera, con una pesa rusa en el suelo entre los pies.","Baja con la espalda plana, las rodillas alineadas con los pies, y agarra el asa con ambas manos.","Empuja el suelo y extiende caderas y rodillas juntas para ponerte de pie.","Aprieta los glúteos en la parte superior.","Baja la campana con control de vuelta al suelo empujando las caderas hacia atrás.","Repite el número recomendado de repeticiones."],"tips":["Las rodillas se alinean con los pies — no dejes que colapsen hacia adentro.","Los hombros permanecen por encima de las caderas en la parte inferior; si los hombros caen, estrecha la postura.","Mantén la campana cerca del cuerpo durante todo el levantamiento."],"met":6.0,"uni":false,"img":["kettlebell-sumo-deadlift-start.webp","kettlebell-sumo-deadlift-peak.webp"]},{"id":"kettlebell-sumo-high-pull","n":"Jalón sumo al mentón con pesa rusa","d":"Un jalón con pesa rusa desde el suelo hasta la altura del mentón con postura amplia, combinando una bisagra con un remo en pie para desarrollar el trapecio superior de forma explosiva.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"kettlebell","home":true,"bw":false,"lv":"intermedio","m":["aductores","deltoides lateral","trapecio"],"m2":["glúteo mayor","isquiotibiales","deltoides posterior"],"ins":["Párate con los pies más anchos que los hombros, los dedos ligeramente girados hacia afuera y una pesa rusa en el suelo entre los pies.","Bisagra hacia abajo y agarra el asa con ambas manos.","Empuja con los pies y extiende las caderas de forma explosiva para jalar la pesa rusa hacia arriba.","Al subir, lleva los codos hacia arriba y afuera hasta que el asa alcance la altura del mentón.","Baja la pesa rusa de vuelta entre las piernas con control.","Repite el número recomendado de repeticiones."],"tips":["Impulsa primero con las caderas; los brazos terminan el movimiento.","Mantén los codos más altos que las manos en la parte superior — piensa: ancho y alto, no estrecho."],"met":6.0,"uni":false,"img":["kettlebell-sumo-high-pull-start.webp","kettlebell-sumo-high-pull-peak.webp"]},{"id":"kettlebell-svend-press","n":"Press Svend con Kettlebells","d":"Un ejercicio de pecho de pie presionando dos kettlebells unidas por las bolas, donde la presión hacia dentro mantiene los pectorales en tensión constante.","cat":"fuerza","g":"pecho","bp":"chest","eq":"kettlebell","home":true,"bw":false,"lv":"principiante","m":["pectoral"],"m2":["deltoides anterior","tríceps"],"ins":["De pie, junta dos kettlebells por las bolas a la altura del pecho.","Mantén las kettlebells horizontales — bolas tocándose, asas hacia afuera.","Empuja las kettlebells al frente hasta que los brazos queden casi estirados.","Tíralas de regreso al pecho con control.","Repite el número de repeticiones indicado."],"tips":["La presión entre las bolas hace el ejercicio.","Usa kettlebells muy ligeras — el agarre incómodo dicta la carga.","Mantén los codos ligeramente flexionados en el lockout."],"met":5.0,"uni":false,"img":["kettlebell-svend-press-start.webp","kettlebell-svend-press-peak.webp"]},{"id":"kettlebell-swing","n":"Swing con pesa rusa","d":"Un movimiento explosivo de bisagra de cadera con pesa rusa para potencia y acondicionamiento físico.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"kettlebell","home":true,"bw":false,"lv":"intermedio","m":["glúteo mayor","isquiotibiales"],"m2":["lumbares","cuádriceps"],"ins":["Párate con los pies a la anchura de los hombros y la pesa rusa en el suelo por delante.","Bisagra en las caderas, agarra la pesa rusa y llévala hacia atrás entre las piernas.","Extiende las caderas de forma explosiva para balancear la pesa rusa hasta la altura del pecho.","Deja que la pesa rusa vuelva a balancearse entre las piernas.","Repite en un movimiento fluido."],"tips":["La fuerza nace de la cadera, no de los brazos.","Aprieta glúteos y abdomen en la parte alta del swing.","Es una bisagra de cadera, no una sentadilla."],"met":8.0,"uni":false,"img":["kettlebell-swing-start.webp","kettlebell-swing-peak.webp"]},{"id":"kettlebell-swing-clean","n":"Swing y cargada con pesa rusa","d":"Un clean con pesa rusa iniciado desde el swing, que lleva el peso hasta la posición de rack en el hombro.","cat":"olímpico","g":"cuerpo completo","bp":"full_body","eq":"kettlebell","home":true,"bw":false,"lv":"intermedio","m":["glúteo mayor","isquiotibiales"],"m2":["deltoides anterior","lumbares","trapecio"],"ins":["Párate con los pies a la anchura de los hombros y la pesa rusa entre los pies.","Bisagra en las caderas y agarra el asa con una mano.","Balancea la pesa rusa hacia atrás entre las piernas.","Extiende las caderas hacia adelante para jalar la pesa rusa hasta el hombro.","Recibe la pesa rusa en la posición de rack sobre el hombro.","Completa las repeticiones en un lado y luego cambia."],"tips":["Mantén la pesa cerca del cuerpo en la subida.","Recibe la pesa con suavidad, sin golpearte el antebrazo.","Genera la potencia con la cadera, no tirando con el brazo."],"met":8.0,"uni":false,"img":["kettlebell-swing-clean-start.webp","kettlebell-swing-clean-peak.webp"]},{"id":"kettlebell-tibialis-raise","n":"Elevación de Tibial con Pesa Rusa","d":"Un ejercicio para las espinillas que se hace sentado en un banco con una pesa rusa colgada del frente de un pie. Levantar los dedos hacia la espinilla contra el peso fortalece los músculos de la parte delantera de la pierna.","cat":"fuerza","g":"piernas","bp":"lower_legs","eq":"kettlebell","home":true,"bw":false,"lv":"intermedio","m":["tibial anterior"],"m2":[],"ins":["Siéntate en el extremo de un banco plano con una pierna estirada y el talón apoyado en el suelo.","Cuelga una pesa rusa por el asa del frente del pie, sobre los dedos.","Sube los dedos hacia la espinilla todo lo que te resulte cómodo mientras el talón permanece en el suelo.","Mantén brevemente la posición superior.","Baja el pie despacio hasta que los dedos apunten al suelo.","Completa las repeticiones y luego cambia de pierna."],"tips":["Haz el movimiento solo desde el tobillo; la rodilla y el muslo permanecen quietos.","Empieza con una pesa rusa ligera y aumenta poco a poco; los músculos de la espinilla se fatigan rápido.","Baja despacio en lugar de dejar caer el peso."],"met":5.0,"uni":true,"img":["kettlebell-tibialis-raise-start.webp","kettlebell-tibialis-raise-peak.webp"]},{"id":"kettlebell-turkish-get-ups","n":"Levantamiento Turco con Kettlebell","d":"Un ejercicio de cuerpo completo con kettlebell que pasa de estar tumbado a de pie mientras se mantiene el peso bloqueado por encima de la cabeza, trabajando la fuerza, la estabilidad y la movilidad de todo el cuerpo.","cat":"fuerza","g":"cuerpo completo","bp":"full_body","eq":"kettlebell","home":true,"bw":false,"lv":"intermedio","m":["deltoides anterior","glúteo mayor","abdominales"],"m2":["oblicuos","cuádriceps","tríceps"],"ins":["Túmbate boca arriba sosteniendo una kettlebell por encima de la cabeza con una mano.","Flexiona la rodilla del mismo lado y apoya el pie plano.","Rueda hasta apoyarte en el codo opuesto y luego en la mano.","Empuja las caderas hacia arriba y lleva la pierna estirada hacia atrás a una zancada.","Ponte de pie por completo manteniendo la kettlebell bloqueada por encima de la cabeza.","Invierte la secuencia para volver a la posición inicial."],"tips":["Mantén la vista en la kettlebell hasta que estés de pie, luego mira al frente.","Muévete despacio en cada paso: el levantamiento es una secuencia, no un solo movimiento."],"met":6.0,"uni":false,"img":["kettlebell-turkish-get-ups-start.webp","kettlebell-turkish-get-ups-peak.webp"]},{"id":"kettlebell-windmills","n":"Molino de Viento con Pesa Rusa","d":"Un ejercicio de pesa rusa con el brazo bloqueado por encima de la cabeza, que combina estabilidad de hombro y bisagra lateral de cadera.","cat":"fuerza","g":"cuerpo completo","bp":"full_body","eq":"kettlebell","home":true,"bw":false,"lv":"intermedio","m":["aductores","deltoides anterior","oblicuos"],"m2":["lumbares","glúteo mayor","isquiotibiales"],"ins":["Párate sosteniendo una pesa rusa bloqueada sobre la cabeza con una mano.","Gira los pies unos 45 grados alejándolos del brazo de trabajo.","Con la pesa rusa arriba, inclínate lateralmente desde las caderas.","Lleva la mano opuesta hacia el pie.","Empuja las caderas hacia atrás para volver a la posición erguida.","Completa las repeticiones de un lado y luego cambia."],"tips":["No pierdas de vista la pesa durante todo el movimiento.","El brazo de arriba permanece bloqueado y vertical en todo momento.","Empieza sin peso para aprender el patrón del movimiento."],"met":5.0,"uni":true,"img":["kettlebell-windmills-start.webp","kettlebell-windmills-peak.webp"]},{"id":"kettlebell-wrist-curl","n":"Curl de Muñeca con Kettlebell","d":"Un curl de muñeca unilateral con kettlebell — el peso descentrado añade un reto extra al agarre.","cat":"fuerza","g":"brazos","bp":"lower_arms","eq":"kettlebell","home":true,"bw":false,"lv":"principiante","m":["antebrazo"],"m2":[],"ins":["Siéntate en un banco con el antebrazo sobre el muslo, palma hacia arriba.","Sujeta una kettlebell por el asa, muñeca fuera de la rodilla.","Deja que la kettlebell rote hacia las puntas de los dedos.","Súbela flexionando la muñeca, controlando el peso descentrado.","Baja con control. Repeticiones por lado."],"tips":["Sujeta el asa, no la bola, para que el peso descentrado cargue el agarre.","Mueve solo la muñeca.","Usa una carga más ligera que con una mancuerna."],"met":5.0,"uni":true,"img":["kettlebell-wrist-curl-start.webp","kettlebell-wrist-curl-peak.webp"]},{"id":"knee-push-ups","n":"Push-Up en Rodillas","d":"Una variante de flexión apta para principiantes, con las rodillas apoyadas en el suelo para reducir la carga sobre el tren superior.","cat":"fuerza","g":"pecho","bp":"chest","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["pectoral"],"m2":["deltoides anterior","abdominales","tríceps"],"ins":["Comienza en posición de push-up con las rodillas en el suelo.","Coloca las manos a la anchura de los hombros en el suelo.","Mantén el cuerpo en línea recta desde las rodillas hasta los hombros.","Baja el pecho hacia el suelo doblando los codos.","Empuja con las manos para volver a la posición inicial.","Repite el número de repeticiones deseado."],"tips":["No abras los codos en exceso hacia los lados.","Aprieta los glúteos y el abdomen durante todo el movimiento.","Mira al suelo para mantener el cuello neutro."],"met":5.0,"uni":false,"img":["knee-push-ups-start.webp","knee-push-ups-peak.webp"]},{"id":"knee-to-chest-stretch","n":"Estiramiento Rodilla al Pecho","d":"Un estiramiento tumbado que libera los glúteos y la zona lumbar al abrazar una rodilla contra el pecho.","cat":"estiramiento","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["glúteo mayor"],"m2":["lumbares"],"ins":["Acuéstate boca arriba con ambas piernas estiradas.","Lleva una rodilla y abrázala al pecho con ambas manos.","Mantén la otra pierna relajada en el suelo.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],"tips":["Mantén la cabeza y los hombros relajados en el suelo.","Relájate y sigue respirando todo el tiempo."],"met":5.0,"uni":true,"img":["knee-to-chest-stretch-main.webp"]},{"id":"kneeling-cable-row","n":"Remo en Polea Arrodillado","d":"Un remo en polea ejecutado desde una posición de rodillas erguida, eliminando el impulso de cadera y manteniendo la tensión en la parte superior de la espalda durante todo el movimiento.","cat":"fuerza","g":"espalda","bp":"back","eq":"polea","home":false,"bw":false,"lv":"principiante","m":["dorsales"],"m2":["bíceps","deltoides posterior","romboides","trapecio"],"ins":["Ajusta la polea a la altura del pecho y conecta una cuerda o un mango doble en D.","Arrodíllate erguido frente a la máquina lo suficientemente lejos para que el peso no llegue al tope.","Agarra el mango con ambas manos y sostenlo extendido frente a ti a la altura del pecho.","Lleva el mango hacia el esternón llevando los codos hacia atrás y apretando los omóplatos.","Regresa de forma controlada a la posición inicial con estiramiento.","Repite el número de repeticiones recomendado."],"tips":["Mantente erguido: no te inclines hacia atrás para terminar la repetición.","La postura de rodillas erguidas obliga al core a resistir la rotación en cada tirón."],"met":6.0,"uni":false,"img":["kneeling-cable-row-start.webp","kneeling-cable-row-peak.webp"]},{"id":"kneeling-hip-flexor-stretch","n":"Estiramiento de Flexores de Cadera Arrodillado","d":"Un estiramiento en semiarrodillado que abre los flexores de cadera de la pierna trasera empujando la cadera adelante.","cat":"estiramiento","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["flexores de cadera"],"m2":["aductores","cuádriceps"],"ins":["Arrodíllate sobre una rodilla con el otro pie plano al frente.","Mantén el torso erguido y el core ligeramente activado.","Empuja la cadera adelante hasta sentir el estiramiento en el frente de la cadera trasera.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],"tips":["Aprieta el glúteo de la pierna arrodillada para proteger la zona lumbar.","Evita arquear la zona lumbar."],"met":5.0,"uni":true,"img":["kneeling-hip-flexor-stretch-main.webp"]},{"id":"kneeling-wrist-stretch","n":"Estiramiento de Muñecas Arrodillado","d":"Un estiramiento de rodillas para los flexores del antebrazo y las muñecas, con las palmas abajo y los dedos hacia atrás.","cat":"estiramiento","g":"brazos","bp":"lower_arms","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["antebrazo"],"m2":[],"ins":["Ponte en cuadrupedia y apoya las palmas planas en el suelo.","Gira las manos para que los dedos apunten hacia las rodillas.","Mantén las palmas abajo y desplaza el peso atrás suavemente.","Mantén de 20 a 30 segundos, respirando de forma constante."],"tips":["Mantén las palmas planas mientras te inclinas atrás.","Estira hasta una tensión leve, nunca hasta el dolor."],"met":5.0,"uni":false,"img":["kneeling-wrist-stretch-main.webp"]},{"id":"l-sit","n":"L-Sit","d":"Un ejercicio isométrico avanzado en el que el cuerpo forma una L con las piernas extendidas, exigente para el core y los flexores de cadera.","cat":"fuerza","g":"cuerpo completo","bp":"full_body","eq":"paralelas","home":false,"bw":false,"lv":"avanzado","m":["flexores de cadera","abdominales"],"m2":["dorsales","cuádriceps","tríceps"],"ins":["Siéntate en el suelo o empuja hacia arriba en barras paralelas con los brazos rectos.","Bloquea los codos y deprime los hombros.","Eleva las piernas rectas al frente paralelas al suelo.","Forma una L con el cuerpo.","Mantén la posición durante el tiempo indicado.","Baja las piernas con control para salir."],"tips":["Mantén las puntas de los pies estiradas hacia delante.","Si no llegas, empieza con las rodillas recogidas.","Respira de forma constante; no aguantes el aire durante el sostén."],"met":6.0,"uni":false,"img":["l-sit-main.webp"]},{"id":"landmine-press","n":"Press Landmine","d":"Un press de hombros a dos manos con una barra fijada en un accesorio landmine, cuyo arco natural reduce el estrés en la articulación del hombro.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["deltoides anterior","pectoral"],"m2":["serrato","tríceps"],"ins":["Inserta un extremo de la barra en el accesorio landmine y carga el extremo libre con un disco.","Párate en postura escalonada o paralela y sujeta el extremo libre de la barra con ambas manos a la altura del pecho.","Activa el core y empuja la barra hacia adelante y arriba siguiendo su arco natural.","Extiende completamente los brazos sin bloquear los codos, luego baja con control.","Mantén ambas manos en la barra y repite el número de repeticiones deseado."],"tips":["Mantén el torso erguido y evita inclinarte excesivamente hacia el press.","La trayectoria angular es más amigable para el hombro que un press estricto sobre la cabeza.","Usa impulso de piernas estilo push press para cargas más pesadas."],"met":6.0,"uni":true,"img":["landmine-press-start.webp","landmine-press-peak.webp"]},{"id":"lat-pulldown","n":"Jalón al Pecho","d":"Un ejercicio en máquina de polea que trabaja el dorsal ancho.","cat":"fuerza","g":"espalda","bp":"back","eq":"polea","home":false,"bw":false,"lv":"principiante","m":["dorsales"],"m2":["bíceps","deltoides posterior","romboides"],"ins":["Siéntate en la máquina de jalón con los muslos sujetos bajo los rodillos.","Agarra la barra ancha con un agarre en pronación.","Jala la barra hasta la parte superior del pecho apretando los dorsales.","Regresa la barra lentamente a la posición inicial.","Repite."],"tips":["Inicia el tirón bajando los omóplatos, no doblando los codos.","Evita balancear el torso para mover el peso.","Dirige los codos hacia abajo y atrás, no hacia fuera."],"met":6.0,"uni":false,"img":["lat-pulldown-start.webp","lat-pulldown-peak.webp"]},{"id":"lateral-leg-swing","n":"Balanceo Lateral de Pierna","d":"Un ejercicio dinámico de movilidad de cadera en el que una pierna cruza por delante del cuerpo y después se balancea hacia el lado mientras la pierna de apoyo y el tronco se mantienen controlados.","cat":"estiramiento","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["abductores","aductores"],"m2":["glúteo medio","flexores de cadera"],"ins":["Ponte erguido, activa el tronco y usa un apoyo estable si lo necesitas.","Lleva el peso a una pierna y eleva ligeramente el otro pie del suelo.","Balancea la pierna libre cruzándola por delante del cuerpo.","Invierte el movimiento y llévala hacia el lado dentro de un rango cómodo.","Continúa con fluidez y después cambia de pierna."],"tips":["Mantén la pelvis orientada al frente en lugar de girarla con la pierna.","Usa un rango que puedas controlar sin inclinar el torso.","Amplía el movimiento de forma gradual en lugar de forzar la primera repetición."],"met":3.5,"uni":true,"img":["lateral-leg-swing-start.webp","lateral-leg-swing-peak.webp"]},{"id":"lateral-raise","n":"Elevación Lateral con Mancuernas","d":"Un movimiento de aislamiento que trabaja el deltoides lateral para ganar anchura en los hombros.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"mancuernas","home":true,"bw":false,"lv":"principiante","m":["deltoides lateral"],"m2":["deltoides anterior"],"ins":["Párate con mancuernas a los costados.","Eleva las mancuernas hacia los lados hasta que los brazos queden paralelos al suelo.","Baja de forma controlada.","Repite."],"tips":["Ligera flexión en los codos.","Guía con los codos, no con las manos."],"met":5.0,"uni":false,"img":["lateral-raise-start.webp","lateral-raise-peak.webp"]},{"id":"lean-back-90-90-hold","n":"Estiramiento 90/90 Inclinado Hacia Atrás","d":"Una versión más suave del estiramiento 90/90 de cadera: desde la misma posición 90/90 de las piernas, inclinas el tronco hacia atrás y lo apoyas sobre las manos detrás de ti. Inclinarte hacia atrás quita parte de la carga de las caderas mientras la pierna delantera sigue girada hacia fuera y la trasera girada hacia dentro.","cat":"estiramiento","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["flexores de cadera"],"m2":["glúteo mayor","glúteo medio"],"ins":["Siéntate en el suelo con la pierna delantera flexionada delante de ti a unos 90 grados y la pierna trasera a un lado, también flexionada a unos 90 grados.","Apoya las manos en el suelo detrás de las caderas, con los dedos apuntando hacia atrás o hacia los lados.","Inclina el tronco hacia atrás sobre las manos, manteniendo los brazos estirados y el pecho abierto.","Deja que ambas rodillas bajen hacia el suelo sin forzarlas.","Mantén la posición respirando despacio y nota un estiramiento suave en la parte externa de la cadera de la pierna delantera y en la parte anterior de la cadera de la pierna trasera.","Mantén la postura durante el tiempo previsto; luego intercambia las piernas y mantenla del otro lado."],"tips":["Usa esta versión cuando el 90/90 erguido resulte demasiado intenso; inclínate más hacia atrás sobre las manos para suavizar el estiramiento.","Mantén los hombros bajos y alejados de las orejas en lugar de colgarte de los brazos.","Entra en la posición despacio y mantenla sin dolor, sobre todo en las rodillas."],"met":5.0,"uni":true,"img":["lean-back-90-90-hold-main.webp"]},{"id":"leg-curl","n":"Curl de Piernas Tumbado","d":"Un ejercicio de aislamiento para los isquiotibiales usando la máquina de curl de piernas.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"máquina de femoral","home":false,"bw":false,"lv":"principiante","m":["isquiotibiales"],"m2":["gemelos"],"ins":["Túmbate boca abajo en la máquina de curl de piernas con los tobillos bajo el rodillo.","Lleva los talones hacia los glúteos.","Aprieta los isquiotibiales en la parte superior.","Baja con control.","Repite."],"tips":["Mantén las caderas pegadas al banco durante todo el recorrido.","Evita arquear la zona lumbar al subir los talones.","Elige un peso que permita un recorrido completo y controlado."],"met":5.0,"uni":false,"img":["leg-curl-start.webp","leg-curl-peak.webp"]},{"id":"leg-extension","n":"Extensión de Piernas","d":"Un ejercicio de aislamiento para los cuádriceps usando una máquina.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"máquina de cuádriceps","home":false,"bw":false,"lv":"principiante","m":["cuádriceps"],"m2":[],"ins":["Siéntate en la máquina de extensión de piernas con los tobillos detrás del rodillo.","Extiende las piernas hasta que queden rectas.","Aprieta los cuádriceps en la parte superior.","Baja con control.","Repite."],"tips":["Alinea las rodillas con el eje de giro de la máquina.","Sube el peso sin lanzarlo con impulso.","Agárrate a las asas para mantener la cadera estable en el asiento."],"met":5.0,"uni":false,"img":["leg-extension-start.webp","leg-extension-peak.webp"]},{"id":"leg-press","n":"Prensa de Piernas","d":"Un movimiento compuesto en máquina para cuádriceps y glúteos.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"prensa","home":false,"bw":false,"lv":"principiante","m":["glúteo mayor","cuádriceps"],"m2":["isquiotibiales"],"ins":["Siéntate en la prensa de piernas con los pies a la anchura de los hombros sobre la plataforma.","Suelta los seguros y baja la plataforma doblando las rodillas.","Empuja la plataforma hacia arriba hasta que las piernas queden casi rectas.","No bloquees las rodillas en la parte superior.","Repite."],"tips":["Mantén la zona lumbar pegada al respaldo en todo momento.","Baja solo hasta donde la cadera no se despegue.","Alinea las rodillas con las puntas de los pies."],"met":6.0,"uni":false,"img":["leg-press-start.webp","leg-press-peak.webp"]},{"id":"leg-swing-front-to-back","n":"Balanceo de Pierna Adelante y Atrás","d":"Un ejercicio dinámico de movilidad de cadera que balancea una pierna recta o ligeramente flexionada hacia delante y hacia atrás mientras el lado de apoyo estabiliza la pelvis.","cat":"estiramiento","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["glúteo mayor","flexores de cadera"],"m2":["isquiotibiales","abdominales"],"ins":["Ponte erguido junto a un apoyo estable y lleva el peso a la pierna interior.","Activa el tronco y eleva ligeramente el pie exterior del suelo.","Balancea la pierna libre hacia delante dentro de un rango cómodo.","Déjala viajar hacia atrás sin arquear la zona lumbar.","Continúa con fluidez y después repite con la otra pierna."],"tips":["Mantén el torso erguido y deja que el movimiento salga de la cadera.","Empieza con un rango pequeño y auméntalo a medida que se calienta la cadera.","Conserva el pie de apoyo plantado y la pelvis orientada al frente."],"met":3.5,"uni":true,"img":["leg-swing-front-to-back-start.webp","leg-swing-front-to-back-peak.webp"]},{"id":"legs-up-the-wall","n":"Piernas en la Pared","d":"Una posición restaurativa con las caderas cerca de una pared y las piernas apoyadas en vertical, pensada para recuperar y no para esforzarse.","cat":"estiramiento","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["isquiotibiales"],"m2":["lumbares"],"ins":["Siéntate de lado junto a una pared con una cadera en contacto con ella.","Sube las piernas por la pared mientras te tumbas, de modo que las caderas queden cerca de la base.","Deja las piernas apoyadas en la pared, los pies relajados y los brazos abiertos a los lados.","Permanece durante el tiempo indicado, respirando despacio.","Flexiona las rodillas y rueda hacia un lado para salir."],"tips":["Aleja las caderas unos centímetros de la pared si notas tirón en los isquiotibiales.","Coloca una manta doblada bajo la pelvis para una versión más suave y sostenida.","Mantén las piernas pasivas; esta posición no debe costar esfuerzo."],"met":1.5,"uni":false,"img":["legs-up-the-wall-main.webp"]},{"id":"lizard-stretch","n":"Estiramiento del Lagarto","d":"Un estiramiento en zancada profunda que abre los flexores de cadera, la ingle y los glúteos con los antebrazos hacia el suelo.","cat":"estiramiento","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["aductores","flexores de cadera"],"m2":["glúteo mayor","isquiotibiales"],"ins":["Da un paso adelante a una zancada profunda, con el pie bien abierto.","Baja ambos antebrazos hacia el suelo por dentro del pie delantero.","Extiende la pierna trasera y deja que la cadera baje.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],"tips":["Apóyate en las manos en vez de los antebrazos para una versión más fácil.","Estira hasta una tensión leve, nunca hasta el dolor."],"met":5.0,"uni":true,"img":["lizard-stretch-main.webp"]},{"id":"locust-pose","n":"Postura del Saltamontes","d":"Un sostén boca abajo en el que pecho, brazos y piernas se despegan del suelo, de modo que toda la cadena posterior trabaja de forma isométrica sin carga externa.","cat":"fuerza","g":"espalda","bp":"back","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["lumbares","glúteo mayor"],"m2":["isquiotibiales","deltoides posterior"],"ins":["Túmbate boca abajo con los brazos junto al cuerpo y la frente en la esterilla.","Alarga la nuca y estira las yemas de los dedos hacia los pies.","Eleva a la vez el pecho, los brazos y ambas piernas.","Mantén la posición elevada durante el tiempo indicado, con la mirada hacia el suelo.","Baja todo a la vez y descansa."],"tips":["Eleva desde el alargamiento de la columna en lugar de tirar de la cabeza hacia arriba.","Mantén las piernas a la anchura de las caderas y las rodillas estiradas.","Empieza elevando solo las piernas y añade el pecho después si la versión completa es demasiado."],"met":5.0,"uni":false,"img":["locust-pose-main.webp"]},{"id":"low-lunge","n":"Zancada Baja","d":"Un estiramiento en paso largo con la rodilla trasera apoyada: las caderas se hunden hacia delante y alargan el flexor de la cadera de la pierna de atrás.","cat":"estiramiento","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["flexores de cadera","cuádriceps"],"m2":["lumbares","glúteo mayor"],"ins":["Desde la posición de rodillas, adelanta un pie para que la rodilla quede sobre el tobillo.","Apoya la rodilla trasera en el suelo y deja el empeine estirado.","Mete ligeramente el coxis y empuja las caderas hacia delante hasta notar el alargamiento en la parte frontal del muslo trasero.","Eleva el pecho, sube los brazos si te resulta agradable y mantén durante el tiempo indicado.","Vuelve atrás y repite del otro lado."],"tips":["Acolcha la rodilla trasera con una esterilla doblada si el suelo es duro.","Aprieta el glúteo de atrás para profundizar el estiramiento sin arquear la zona lumbar.","Mantén la rodilla delantera sobre el tobillo en lugar de dejarla deslizarse hacia delante."],"met":5.0,"uni":true,"img":["low-lunge-main.webp"]},{"id":"low-lunge-to-half-split","n":"Zancada Baja a Medio Split","d":"Una secuencia en movimiento para isquiotibiales y flexores de cadera: desde una zancada baja las caderas retroceden sobre la rodilla trasera y la pierna delantera se estira en medio split, y después las caderas vuelven a deslizarse hacia delante.","cat":"estiramiento","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["isquiotibiales"],"m2":["gemelos","flexores de cadera"],"ins":["Empieza en zancada baja con la rodilla trasera en el suelo y la delantera sobre el tobillo.","Apoya las manos en el suelo o en bloques a ambos lados del pie delantero.","Lleva las caderas atrás sobre la rodilla trasera y estira la pierna delantera con el pie en flexión.","Sostén el medio split un instante y desliza las caderas hacia delante otra vez a la zancada.","Repite las veces indicadas y cambia de lado."],"tips":["Mantén larga la parte posterior de la pierna delantera: flexiona un poco la rodilla en lugar de redondear la columna para llegar.","Se mueven las caderas, no el pie delantero; el pie se queda donde estaba.","Acolcha la rodilla trasera y usa bloques bajo las manos si el suelo queda lejos."],"met":5.0,"uni":true,"img":["low-lunge-to-half-split-start.webp","low-lunge-to-half-split-peak.webp"]},{"id":"lunge","n":"Zancada","d":"Una zancada hacia delante con el peso corporal, entrenando cuádriceps, glúteos y equilibrio una pierna a la vez.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["glúteo mayor","cuádriceps"],"m2":["lumbares","glúteo medio","isquiotibiales"],"ins":["Párate erguido con los pies a la anchura de las caderas.","Da un paso adelante largo con una pierna.","Baja la rodilla trasera hacia el suelo hasta que ambas rodillas formen ángulos de 90 grados.","Empuja con el talón delantero para volver a la posición de pie.","Completa las repeticiones de un lado y luego cambia."],"tips":["Da una zancada lo bastante larga para que ambas rodillas lleguen a unos 90 grados.","Mantén el torso erguido y la mirada al frente.","Empuja con el talón delantero para volver en un solo movimiento potente."],"met":5.0,"uni":true,"img":["lunge-start.webp","lunge-peak.webp"]},{"id":"lying-leg-raise","n":"Elevación de Piernas Acostado","d":"Un ejercicio de suelo para el abdomen bajo y los flexores de cadera que consiste en elevar las piernas rectas desde posición supina.","cat":"fuerza","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["flexores de cadera","abdominales"],"m2":["oblicuos","transverso abdominal"],"ins":["Túmbate boca arriba con las piernas rectas y las manos bajo la zona lumbar o sujetando una superficie estable detrás de la cabeza.","Con las piernas juntas y el core activado, eleva las piernas hasta la vertical.","Pausa brevemente arriba.","Baja las piernas despacio hacia el suelo sin llegar a apoyarlas.","Repite el número de repeticiones deseado."],"tips":["Mantén la zona lumbar pegada al suelo durante todo el ejercicio.","Evita el balanceo — controla el descenso para maximizar la tensión.","Dobla ligeramente las rodillas si la flexibilidad de los isquiotibiales lo requiere."],"met":5.0,"uni":false,"img":["lying-leg-raise-start.webp","lying-leg-raise-peak.webp"]},{"id":"lying-tricep-extension","n":"Extensión de Tríceps Tumbado","d":"Un ejercicio de aislamiento de tríceps tumbado: una mancuerna sujeta con las dos manos se baja por detrás de la cabeza flexionando los codos y se vuelve a subir.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["tríceps"],"m2":["deltoides anterior"],"ins":["Túmbate boca arriba en un banco y sujeta una mancuerna con las dos manos, estirada por encima del pecho.","Mantén los brazos casi verticales, con los codos apuntando al techo.","Baja la mancuerna por detrás de la cabeza flexionando los codos.","Extiende los brazos de vuelta a la posición inicial.","Aprieta los tríceps en la parte superior.","Repite el número de repeticiones deseado."],"tips":["Mantén los codos apuntando hacia arriba y cerrados, sin abrirlos hacia los lados.","Mueve solo los codos, no los hombros.","Baja el peso con control en lugar de dejarlo caer."],"met":5.0,"uni":false,"img":["lying-tricep-extension-start.webp","lying-tricep-extension-peak.webp"]},{"id":"machine-back-extension","n":"Extensión de Espalda en Máquina","d":"Un ejercicio de aislamiento sentado para la zona lumbar: con la cadera y las piernas fijas, el torso empuja hacia atrás contra un rodillo acolchado y extiende la columna venciendo la placa de pesas.","cat":"fuerza","g":"espalda","bp":"back","eq":"banco de lumbares","home":false,"bw":false,"lv":"principiante","m":["lumbares"],"m2":["glúteo mayor","isquiotibiales"],"ins":["Siéntate en la máquina de extensión de espalda con los pies apoyados en la plataforma y ajusta el rodillo para que quede sobre la parte alta de la espalda, justo por debajo de los omóplatos.","Agarra las manijas laterales y deja que el torso venga ligeramente hacia delante: esta es la posición inicial.","Empuja hacia atrás contra el rodillo extendiendo la columna hasta que el torso quede inclinado hacia atrás y la zona lumbar esté totalmente contraída.","Haz una pausa breve en la extensión completa y regresa a la posición inicial de forma controlada, resistiendo el peso durante el recorrido.","Repite el número de repeticiones deseado."],"tips":["Coloca el rodillo justo por debajo de los omóplatos: más arriba presiona el cuello y más abajo pierdes recorrido.","Extiende desde la zona lumbar en lugar de lanzar la cabeza y los hombros hacia atrás, y mantén lento el movimiento en ambos sentidos.","Detente con el torso extendido en posición neutra en lugar de forzar la columna más allá, y empieza con poco peso: la zona lumbar responde mejor a repeticiones controladas que a cargas altas."],"met":5.0,"uni":false,"img":["machine-back-extension-start.webp","machine-back-extension-peak.webp"]},{"id":"machine-bicep-curl","n":"Curl de Bíceps en Máquina","d":"Un curl de bíceps en máquina para el entrenamiento aislado de brazos.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"máquina de bíceps","home":false,"bw":false,"lv":"principiante","m":["bíceps"],"m2":["braquial"],"ins":["Siéntate en la máquina y ajusta el rodillo a la longitud de tus brazos.","Agarra las manijas con agarre en supinación.","Lleva las manijas hacia los hombros.","Baja con control.","Repite."],"tips":["Mantén los codos apoyados en la almohadilla en todo momento.","Evita encoger los hombros al subir las asas.","Baja hasta casi extender los brazos sin perder la tensión."],"met":5.0,"uni":false,"img":["machine-bicep-curl-start.webp","machine-bicep-curl-peak.webp"]},{"id":"machine-calf-raise","n":"Elevación de Pantorrillas en Máquina","d":"Un ejercicio de aislamiento en máquina de pie que trabaja los gemelos y el sóleo con un recorrido completo del tobillo.","cat":"fuerza","g":"piernas","bp":"lower_legs","eq":"máquina de gemelos","home":false,"bw":false,"lv":"principiante","m":["gemelos","sóleo"],"m2":[],"ins":["Párate en la máquina de elevación de pantorrillas con los metatarsos sobre la plataforma.","Coloca los rodillos de hombro firmemente.","Baja los talones por debajo de la plataforma para un estiramiento completo.","Empuja con los metatarsos para elevarte en los dedos de los pies.","Aprieta las pantorrillas en la parte superior.","Baja con control y repite."],"tips":["Evita rebotar en la parte baja para no perder tensión.","Mantén las rodillas extendidas pero sin llegar a bloquearlas.","Sube en vertical, sin inclinar los tobillos hacia fuera."],"met":5.0,"uni":false,"img":["machine-calf-raise-start.webp","machine-calf-raise-peak.webp"]},{"id":"machine-chest-fly","n":"Aperturas en Máquina","d":"Un ejercicio de aislamiento de pecho realizado en una máquina que junta las palancas en un arco frente al cuerpo.","cat":"fuerza","g":"pecho","bp":"chest","eq":"máquina de aperturas","home":false,"bw":false,"lv":"principiante","m":["pectoral"],"m2":["deltoides anterior","serrato"],"ins":["Siéntate en la máquina de aperturas y ajusta el asiento para que las palancas queden a la altura del pecho.","Sujeta las palancas con una ligera flexión de codos.","Junta las palancas frente al pecho en un arco suave.","Contrae el pectoral en el punto de máxima contracción.","Vuelve con control a la posición inicial sin dejar caer el peso.","Repite el número de repeticiones deseado."],"tips":["Mantén una flexión de codo ligera y constante durante todo el movimiento.","Enfócate en contraer el pecho en lugar de empujar con los brazos.","Controla el regreso en vez de dejar caer la pila de pesas."],"met":5.0,"uni":false,"img":["machine-chest-fly-start.webp","machine-chest-fly-peak.webp"]},{"id":"machine-preacher-curl","n":"Curl en Máquina de Predicador","d":"Un curl de bíceps en máquina de predicador que fija los codos sobre el almohadillado y ofrece una curva de fuerza guiada.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"banco Scott","home":false,"bw":false,"lv":"principiante","m":["bíceps"],"m2":["braquial"],"ins":["Siéntate y ajusta el asiento para que las axilas queden en la parte superior del almohadillado.","Coloca los brazos sobre el soporte y sujeta las asas.","Comienza con los brazos ligeramente flexionados, sin bloquear los codos.","Flexiona los codos hacia arriba y aprieta en la posición máxima.","Baja lentamente hasta la posición inicial y repite."],"tips":["No separes los codos del almohadillado.","Para justo antes de la extensión completa para proteger los tendones del codo."],"met":5.0,"uni":false,"img":["machine-preacher-curl-start.webp","machine-preacher-curl-peak.webp"]},{"id":"machine-reverse-fly","n":"Apertura Inversa en Máquina","d":"Un ejercicio sentado en máquina para los deltoides posteriores, también conocido como pec deck inverso: de cara a la almohadilla, llevas las dos empuñaduras hacia fuera y atrás en un arco amplio contra la pila de pesas. La almohadilla mantiene el torso quieto, de modo que el trabajo se queda en la parte posterior de los hombros y en los músculos entre los omóplatos.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"máquina de deltoides posterior","home":false,"bw":false,"lv":"principiante","m":["deltoides posterior"],"m2":["romboides","trapecio"],"ins":["Ajusta el asiento para que las empuñaduras queden a la altura de los hombros y siéntate de cara a la máquina con el pecho contra la almohadilla.","Agarra las empuñaduras con los brazos estirados al frente y una ligera flexión en los codos.","Mantén los hombros bajos y alejados de las orejas y aprieta el tronco.","Lleva las empuñaduras hacia fuera y atrás en un arco amplio, guiando el movimiento con los codos, hasta que los brazos queden aproximadamente en línea con los hombros.","Junta los omóplatos brevemente sin echarte hacia atrás separando el pecho de la almohadilla.","Devuelve las empuñaduras hacia delante despacio y repite el número de repeticiones previsto."],"tips":["Guía el movimiento con los codos en lugar de tirar con las manos, para que trabajen los deltoides posteriores y no los bíceps.","Mantén el pecho en la almohadilla y el cuello relajado; si te echas hacia atrás o encoges los hombros, la carga pasa al trapecio superior.","Elige un peso que puedas bajar con control; una carga más ligera con un retorno lento trabaja mejor los deltoides posteriores que un balanceo con mucho peso."],"met":5.0,"uni":false,"img":["machine-reverse-fly-start.webp","machine-reverse-fly-peak.webp"]},{"id":"machine-seated-crunch","n":"Abdominales en Máquina Sentado","d":"Un ejercicio de aislamiento abdominal en una máquina sentada que flexiona la columna contra resistencia.","cat":"fuerza","g":"core","bp":"core","eq":"máquina de abdominales","home":false,"bw":false,"lv":"principiante","m":["abdominales"],"m2":["oblicuos","transverso abdominal"],"ins":["Siéntate en la máquina de abdominales y sujeta las manijas.","Coloca la almohadilla de pecho contra tu torso.","Contrae el abdomen para flexionar el torso hacia adelante y abajo.","Contrae al final del recorrido.","Vuelve a la posición inicial con control.","Repite el número de repeticiones deseado."],"tips":["Inicia el movimiento con el abdomen, no con los brazos.","Exhala mientras flexionas el torso.","Evita el impulso balanceando el cuerpo."],"met":5.0,"uni":false,"img":["machine-seated-crunch-start.webp","machine-seated-crunch-peak.webp"]},{"id":"machine-shoulder-press","n":"Press de Hombros en Máquina","d":"Un movimiento de press por encima de la cabeza en máquina para los hombros.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"máquina de press de hombro","home":false,"bw":false,"lv":"principiante","m":["deltoides anterior","deltoides lateral"],"m2":["trapecio","tríceps"],"ins":["Siéntate en la máquina con la espalda contra el rodillo.","Agarra las manijas a la altura de los hombros.","Presiona las manijas sobre la cabeza hasta que los brazos queden completamente extendidos.","Baja con control a la posición inicial.","Repite."],"tips":["No arquees la zona lumbar al empujar hacia arriba.","Evita bloquear los codos de golpe en la parte alta.","Mantén las muñecas firmes y alineadas con los antebrazos."],"met":6.0,"uni":false,"img":["machine-shoulder-press-start.webp","machine-shoulder-press-peak.webp"]},{"id":"machine-triceps-extension","n":"Extensión de Tríceps en Máquina","d":"Un ejercicio de aislamiento sentado en máquina: los brazos quedan apoyados sobre un rodillo mientras los codos se extienden contra dos manijas, de modo que el tríceps trabaja por un recorrido guiado sin ayuda de los hombros ni del torso.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"máquina de tríceps","home":false,"bw":false,"lv":"principiante","m":["tríceps"],"m2":[],"ins":["Siéntate en la máquina de extensión de tríceps con la espalda apoyada en el respaldo y los brazos apoyados de plano sobre el rodillo, delante del pecho.","Toma una manija con cada mano, con los codos flexionados y las manos a la altura de los hombros.","Manteniendo los brazos pegados al rodillo, extiende los codos para empujar las manijas hacia abajo y hacia delante hasta estirar los brazos por completo.","Aprieta el tríceps en la extensión completa y flexiona los codos para volver al inicio de forma controlada.","Repite el número de repeticiones deseado."],"tips":["Ajusta la altura del asiento para que los brazos queden planos sobre el rodillo y los codos alineados con el eje de giro de la máquina: esa alineación es lo que mantiene el trabajo en el tríceps.","Mantén los brazos pegados al rodillo; si se despegan, el movimiento se convierte en un press y el tríceps deja de trabajar.","Estira los brazos del todo sin bloquear de golpe los codos, y frena la vuelta en lugar de dejar caer las placas."],"met":5.0,"uni":false,"img":["machine-triceps-extension-start.webp","machine-triceps-extension-peak.webp"]},{"id":"medicine-ball-side-throw","n":"Lanzamiento Lateral con Balón Medicinal","d":"Un ejercicio de potencia rotacional: de pie y de lado, con un balón medicinal sujeto a la altura de la cadera, giras las caderas y el torso y lanzas el balón hacia un lado con ambas manos. Los oblicuos y el resto del tronco giran el cuerpo, y las caderas inician la rotación.","cat":"fuerza","g":"core","bp":"core","eq":"balón medicinal","home":true,"bw":false,"lv":"principiante","m":["oblicuos"],"m2":["deltoides anterior","glúteo mayor","pectoral","abdominales"],"ins":["Ponte de pie con los pies algo más separados que el ancho de los hombros, sujetando un balón medicinal con ambas manos delante del torso.","Gira el torso y el balón hacia la cadera trasera, flexionando ligeramente las rodillas y manteniendo el pecho alto.","Inicia el lanzamiento girando la cadera trasera hacia delante y pivotando sobre el metatarso del pie trasero.","Deja que el torso y los brazos sigan el movimiento y lanza el balón hacia un lado con ambas manos.","Termina de cara a la dirección del lanzamiento con los brazos extendidos.","Recupera el balón, vuelve a colocarte y repite el número de repeticiones previsto; luego cambia de lado."],"tips":["Inicia el lanzamiento desde las caderas, no desde los brazos; el tronco y los brazos deben seguir el giro de la cadera.","Lanza de forma explosiva, pero mantén la espalda neutra mientras giras, en lugar de inclinarte hacia un lado.","Usa un balón lo bastante ligero para lanzarlo rápido; un balón pesado ralentiza la rotación y la convierte en un empuje."],"met":6.0,"uni":true,"img":["medicine-ball-side-throw-start.webp","medicine-ball-side-throw-peak.webp"]},{"id":"medicine-ball-slam","n":"Golpe con Balón Medicinal","d":"Un ejercicio explosivo de cuerpo completo donde se levanta un slam ball sobre la cabeza y se lanza contra el suelo con la máxima fuerza.","cat":"fuerza","g":"core","bp":"core","eq":"slam ball","home":false,"bw":false,"lv":"principiante","m":["abdominales"],"m2":["glúteo mayor","dorsales","oblicuos"],"ins":["Párate con los pies a la anchura de los hombros sosteniendo un slam ball frente a las caderas.","Levanta el balón sobre la cabeza extendiendo las caderas y alargándote hacia arriba.","Golpea el balón contra el suelo entre los pies con fuerza, contrayendo el core.","Atrapa el balón en el rebote o recógelo del suelo.","Repite el número de repeticiones recomendado."],"tips":["Usa un slam ball de rebote suave, no un balón medicinal tradicional: los balones normales pueden rebotar hacia la cara.","Termina con todo el cuerpo: es un swing completo, no solo un lanzamiento de brazos."],"met":6.0,"uni":false,"img":["medicine-ball-slam-start.webp","medicine-ball-slam-peak.webp"]},{"id":"mountain-climbers","n":"Mountain Climbers","d":"Un ejercicio dinámico de peso corporal que combina trabajo de core con cardio.","cat":"cardio","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["flexores de cadera","abdominales"],"m2":["oblicuos","cuádriceps"],"ins":["Comienza en posición de plancha alta.","Lleva una rodilla hacia el pecho.","Cambia rápidamente de pierna llevando la otra rodilla hacia adelante.","Continúa alternando a un ritmo brioso.","Repite."],"tips":["Mantén los hombros encima de las muñecas todo el tiempo.","No dejes que la cadera se eleve hacia el techo.","Acelera solo mientras puedas mantener la técnica."],"met":8.0,"uni":false,"img":["mountain-climbers-start.webp","mountain-climbers-peak.webp"]},{"id":"mountain-pose","n":"Postura de la Montaña","d":"La postura básica de pie: pies enraizados, piernas activas, columna larga y hombros relajados. Es la referencia de alineación con la que se miden las demás posturas de pie.","cat":"estiramiento","g":"cuerpo completo","bp":"full_body","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["lumbares"],"m2":["gemelos","cuádriceps"],"ins":["Ponte de pie con los pies a la anchura de las caderas y reparte el peso por igual entre ambos.","Activa ligeramente los muslos y deja caer el coxis para que la pelvis quede neutra.","Alinea las costillas sobre la pelvis y la cabeza sobre las costillas, con los brazos relajados a los lados.","Mantén la postura durante el tiempo indicado, respirando con regularidad.","Observa dónde queda el peso y devuélvelo al centro de cada pie."],"tips":["Levanta y abre los dedos de los pies una vez y vuelve a apoyarlos; eso reinicia el arco del pie.","Mantén las rodillas blandas en lugar de bloquearlas.","Deja que los hombros roten atrás y abajo sin apretar las escápulas entre sí."],"met":2.0,"uni":false,"img":["mountain-pose-main.webp"]},{"id":"muscle-snatch","n":"Muscle Snatch","d":"Una variante de la arrancada que tira de la barra por encima de la cabeza sin caer debajo, desarrollando potencia de tirón y fuerza de bloqueo.","cat":"olímpico","g":"cuerpo completo","bp":"full_body","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["deltoides lateral","trapecio"],"m2":["lumbares","glúteo mayor","isquiotibiales"],"ins":["Párate con los pies a la anchura de las caderas y agarra la barra en ancho con agarre de gancho.","Tira de la barra explosivamente desde el suelo manteniéndola cerca del cuerpo.","Encoge los hombros con fuerza y lleva la barra sobre la cabeza sin flexionar las piernas.","Bloquea la barra sobre la cabeza con los brazos rectos.","Baja la barra con control a la posición inicial.","Repite el número de repeticiones deseado."],"tips":["Encoge los hombros con fuerza y sigue tirando de la barra hacia arriba.","Mantente erguido; no te metas debajo de la barra para recibirla.","Mantén la barra cerca del cuerpo durante todo el tirón."],"met":8.0,"uni":false,"img":["muscle-snatch-start.webp","muscle-snatch-peak.webp"]},{"id":"muscle-ups","n":"Muscle-Ups","d":"Un movimiento avanzado en barra que combina una dominada explosiva con una transición a fondo para terminar por encima de la barra.","cat":"fuerza","g":"espalda","bp":"back","eq":"barra de dominadas","home":true,"bw":false,"lv":"avanzado","m":["dorsales","tríceps"],"m2":["deltoides anterior","bíceps","pectoral"],"ins":["Cuélgate de una barra de dominadas con agarre falso.","Tírate hacia arriba de forma explosiva hacia la barra.","Cuando el pecho llegue a la barra, rota los codos por encima y transiciona a un dip.","Empuja el cuerpo hacia arriba hasta que los brazos queden completamente extendidos sobre la barra.","Baja con control por el mismo recorrido.","Repite el número de repeticiones deseado."],"tips":["Usa agarre falso para que las muñecas ya estén sobre la barra en la transición.","Tira explosivamente hacia el esternón, no solo hasta la barbilla.","Practica la transición en anillas bajas o con bandas antes de hacer repeticiones completas."],"met":6.0,"uni":false,"img":["muscle-ups-start.webp","muscle-ups-peak.webp"]},{"id":"neck-side-stretch","n":"Estiramiento Lateral de Cuello","d":"Un estiramiento suave que alarga el trapecio superior y el lateral del cuello inclinando la oreja hacia el hombro.","cat":"estiramiento","g":"espalda","bp":"back","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["trapecio"],"m2":[],"ins":["Siéntate o párate erguido con los hombros relajados.","Inclina la cabeza para que una oreja baje hacia ese hombro.","Apoya esa mano sobre la cabeza para un peso suave.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],"tips":["Deja que el peso de la mano haga el trabajo, no tires fuerte.","Mantén el hombro opuesto hacia abajo."],"met":5.0,"uni":true,"img":["neck-side-stretch-main.webp"]},{"id":"negative-pull-ups","n":"Dominadas Negativas","d":"Una progresión de dominada centrada en la fase excéntrica, en la que se desciende lentamente desde la barra con control.","cat":"fuerza","g":"espalda","bp":"back","eq":"barra de dominadas","home":true,"bw":false,"lv":"principiante","m":["dorsales"],"m2":["bíceps","antebrazo","deltoides posterior","romboides"],"ins":["Usa un cajón o salta para colocarte en la parte superior de una dominada.","Agarra la barra con las manos a la anchura de los hombros.","Mantén el mentón por encima de la barra un momento.","Bájate lentamente durante 3-5 segundos con control.","Extiende los brazos completamente en la parte inferior.","Vuelve a la posición inicial y repite el número de repeticiones deseado."],"tips":["Resiste la bajada durante todo el recorrido, sin dejarte caer al final.","Mantén los hombros activos, lejos de las orejas.","Aprieta el core para no balancearte durante el descenso."],"met":6.0,"uni":false,"img":["negative-pull-ups-start.webp","negative-pull-ups-peak.webp"]},{"id":"neutral-grip-pull-ups","n":"Dominadas en Agarre Neutro","d":"Una dominada con agarre neutro y palmas enfrentadas que trabaja el dorsal ancho con fuerte participación de los brazos.","cat":"fuerza","g":"espalda","bp":"back","eq":"barra de dominadas","home":true,"bw":false,"lv":"intermedio","m":["dorsales"],"m2":["bíceps","braquial","antebrazo","romboides"],"ins":["Agarra las barras paralelas con las palmas enfrentadas.","Cuelga con los brazos completamente extendidos.","Tírate hacia arriba hasta que el mentón supere la barra.","Aprieta los dorsales en la parte superior del movimiento.","Bájate con control a la posición inicial.","Repite el número de repeticiones deseado."],"tips":["Piensa en llevar los codos hacia las costillas al subir.","Evita balancearte; sube en una línea vertical limpia.","Lleva el pecho hacia las barras en la parte alta."],"met":6.0,"uni":false,"img":["neutral-grip-pull-ups-start.webp","neutral-grip-pull-ups-peak.webp"]},{"id":"nordic-hamstring-curl","n":"Curl Nórdico de Isquiotibiales","d":"Un ejercicio de flexión de rodilla bajando el torso hacia delante desde una posición arrodillada, trabajando los isquiotibiales de forma excéntrica.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"GHD","home":false,"bw":false,"lv":"avanzado","m":["isquiotibiales"],"m2":["gemelos","glúteo mayor"],"ins":["Arrodíllate sobre una colchoneta con los tobillos anclados bajo un soporte fijo.","Mantén el torso erguido y las caderas extendidas.","Baja el cuerpo hacia adelante lentamente resistiendo con los isquiotibiales.","Amortigua la caída con las manos justo antes de tocar el suelo.","Empuja con las manos para volver y tírate hacia la posición inicial.","Repite el número de repeticiones deseado."],"tips":["Baja tan despacio como sea posible: la fase excéntrica es el objetivo.","Mantén las caderas extendidas; no te dobles por la cintura.","Frénate con las manos y empuja ligeramente mientras ganas fuerza."],"met":5.0,"uni":false,"img":["nordic-hamstring-curl-start.webp","nordic-hamstring-curl-peak.webp"]},{"id":"ohp","n":"Press Militar con Barra","d":"Un movimiento de empuje compuesto por encima de la cabeza que trabaja los hombros y el tríceps.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["deltoides anterior","deltoides lateral"],"m2":["trapecio","tríceps"],"ins":["De pie con los pies a la anchura de los hombros y la barra a la altura de las clavículas.","Contrae el core y empuja la barra por encima de la cabeza.","Bloquea los codos arriba con la barra sobre el punto medio del pie.","Baja la barra hasta la altura de las clavículas.","Repite."],"tips":["No te eches demasiado hacia atrás.","Aprieta los glúteos para mayor estabilidad."],"met":6.0,"uni":false,"img":["ohp-start.webp","ohp-peak.webp"]},{"id":"one-arm-dumbbell-preacher-curl","n":"Curl Predicador con Mancuerna a Un Brazo","d":"Un curl de bíceps unilateral hecho sentado en un banco predicador con la parte superior del brazo apoyada en el pad. Entrenar un brazo cada vez mantiene el codo fijo y aísla el bíceps.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["bíceps"],"m2":["braquial","braquiorradial"],"ins":["Siéntate en un banco predicador y apoya la parte posterior de un brazo, a lo largo, sobre el pad.","Sujeta una mancuerna con esa mano con la palma hacia arriba y el brazo casi totalmente extendido.","Sube la mancuerna hacia el hombro sin despegar el codo del pad.","Aprieta el bíceps en la parte alta del movimiento.","Baja la mancuerna despacio hasta que el brazo quede casi recto.","Completa las repeticiones y luego cambia de brazo."],"tips":["Detente justo antes de bloquear el codo abajo para mantener la tensión en el bíceps y cuidar el codo.","Mantén el hombro relajado y el pecho pegado al pad.","Baja el peso más despacio de lo que lo subes."],"met":5.0,"uni":true,"img":["one-arm-dumbbell-preacher-curl-start.webp","one-arm-dumbbell-preacher-curl-peak.webp"]},{"id":"one-arm-dumbbell-push-press","n":"Push Press con Mancuerna a Un Brazo","d":"Un push press unilateral con una sola mancuerna. El impulso de piernas te permite lanzar cargas más pesadas por encima de la cabeza que un press estricto a un brazo, y la carga asimétrica exige una fuerte contención anti-flexión lateral.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["deltoides anterior"],"m2":["glúteo mayor","deltoides lateral","oblicuos","cuádriceps","tríceps"],"ins":["De pie con la mancuerna en un hombro, palma hacia adentro (neutro).","Pies a la anchura de los hombros, core contraído, brazo libre al costado para equilibrio.","Flexiona ligeramente las rodillas manteniendo el torso vertical.","Extiende las piernas de forma explosiva y empuja la mancuerna por encima de la cabeza en un solo movimiento.","Bloquea el codo arriba y baja la mancuerna al hombro con control.","Completa todas las repeticiones de un lado y luego cambia."],"tips":["El impulso viene de las piernas; el brazo termina el movimiento, no lo inicia.","El torso debe mantenerse erguido y cuadrado; no te inclines hacia el lado contrario a la carga.","Menos peso y mejor impulso de piernas superan a más peso con el torso inclinado."],"met":6.0,"uni":true,"img":["one-arm-dumbbell-push-press-start.webp","one-arm-dumbbell-push-press-peak.webp"]},{"id":"one-arm-dumbbell-shoulder-press","n":"Press de Hombros con Mancuerna a Un Brazo","d":"Un press por encima de la cabeza de pie con una sola mancuerna. Trabajar un lado cada vez carga el hombro y el tríceps y obliga al tronco a resistir la inclinación hacia la mano vacía.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["deltoides anterior","tríceps"],"m2":["deltoides lateral","oblicuos","serrato","trapecio"],"ins":["Colócate de pie con los pies a la anchura de las caderas y sujeta una mancuerna a la altura de un hombro con la palma hacia delante.","Contrae el abdomen y deja el brazo libre relajado a un lado.","Empuja la mancuerna en vertical por encima de la cabeza hasta extender del todo el brazo.","Haz una breve pausa arriba con la parte superior del brazo junto a la oreja.","Baja la mancuerna de nuevo al hombro de forma controlada.","Completa las repeticiones con un brazo y luego cambia de lado."],"tips":["Mantén las costillas abajo y los glúteos apretados; no te inclines hacia un lado para subir el peso.","Empuja en línea recta y cerca de la cabeza, no hacia delante.","Empieza con menos peso que con dos mancuernas; el tronco tiene que estabilizar la carga."],"met":6.0,"uni":true,"img":["one-arm-dumbbell-shoulder-press-start.webp","one-arm-dumbbell-shoulder-press-peak.webp"]},{"id":"one-arm-dumbbell-swing","n":"Swing con Mancuerna a un Brazo","d":"Este ejercicio dinámico desarrolla potencia explosiva en glúteos e isquiotibiales mediante una potente bisagra de cadera, involucrando el core y los hombros para un entrenamiento de cuerpo completo.","cat":"fuerza","g":"cuerpo completo","bp":"full_body","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["glúteo mayor","isquiotibiales"],"m2":["lumbares","antebrazo","deltoides lateral"],"ins":["Párate con los pies al ancho de los hombros, una mancuerna en el suelo ligeramente delante de ti.","Haz una bisagra de cadera, manteniendo la espalda recta, y agarra la mancuerna con una mano.","Lleva la mancuerna hacia atrás entre tus piernas, luego impulsa explosivamente tus caderas hacia adelante.","Balancea la mancuerna hasta la altura del pecho, manteniendo tu brazo relajado y estirado.","Permite que la mancuerna baje, haciendo una bisagra de cadera mientras desciende.","Repite las repeticiones deseadas por lado, manteniendo el control."],"tips":["Concéntrate en impulsar con tus caderas, no en tirar con tu brazo.","Mantén tu core contraído durante todo el movimiento para mayor estabilidad.","Mantén una columna vertebral neutra; evita redondear tu espalda.","Controla la fase excéntrica mientras la mancuerna baja."],"met":8.0,"uni":true,"img":["one-arm-dumbbell-swing-start.webp","one-arm-dumbbell-swing-peak.webp"]},{"id":"one-arm-kettlebell-bicep-curl","n":"Curl de Bíceps con Pesa Rusa a Un Brazo","d":"Un curl de bíceps unilateral con pesa rusa que entrena cada brazo por separado e implica con fuerza el antebrazo.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"kettlebell","home":true,"bw":false,"lv":"intermedio","m":["bíceps"],"m2":["braquial","antebrazo"],"ins":["De pie, sostén una pesa rusa en una mano.","Mantén el codo pegado al costado.","Sube la pesa rusa hacia el hombro flexionando el bíceps.","Aprieta en la parte superior del movimiento.","Baja la pesa rusa con control.","Completa las repeticiones de un lado y luego cambia."],"tips":["Mantén la muñeca recta aunque la pesa tire de ella.","Evita balancear el torso para ayudarte a subir el peso.","Empieza siempre por tu lado más débil."],"met":5.0,"uni":true,"img":["one-arm-kettlebell-bicep-curl-start.webp","one-arm-kettlebell-bicep-curl-peak.webp"]},{"id":"one-arm-kettlebell-bottoms-up-press","n":"Press Strict con Pesa Rusa Invertida a Un Brazo","d":"Un press estricto por encima de la cabeza con la pesa rusa boca abajo: la bola arriba y el asa en la palma. La carga invertida exige un agarre fuerte, estabilidad perfecta de hombro y una trayectoria impecable.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"kettlebell","home":true,"bw":false,"lv":"avanzado","m":["deltoides anterior"],"m2":["antebrazo","deltoides lateral","serrato","tríceps"],"ins":["Limpia una pesa rusa ligera a la posición de rack y luego inclínala para que la bola apunte hacia arriba y el asa quede en la palma.","Agarra el asa con fuerza; la muñeca absolutamente recta y vertical.","Contrae el core y empuja la bola recto hacia arriba sin dejarla caer.","Bloquea el codo arriba con la bola todavía perfectamente vertical.","Baja lentamente a la posición de rack manteniendo la pesa vertical durante todo el descenso.","Completa todas las repeticiones de un lado y luego cambia."],"tips":["Si la bola se inclina, la serie termina; no luches para bajarla.","Empieza con muy poco peso; es un ejercicio de habilidad y estabilidad, no un press pesado.","Aprieta fuerte durante todo el recorrido; cualquier relajación y la pesa cae."],"met":6.0,"uni":true,"img":["one-arm-kettlebell-bottoms-up-press-start.webp","one-arm-kettlebell-bottoms-up-press-peak.webp"]},{"id":"one-arm-kettlebell-floor-glute-bridge-press","n":"Press en Puente de Glúteos en Suelo con Pesa Rusa a Un Brazo","d":"Un ejercicio combinado en el suelo que une un puente de glúteos con un press de pesa rusa a un brazo.","cat":"fuerza","g":"pecho","bp":"chest","eq":"kettlebell","home":true,"bw":false,"lv":"intermedio","m":["glúteo mayor","pectoral"],"m2":["deltoides anterior","isquiotibiales","tríceps"],"ins":["Túmbate boca arriba con las rodillas dobladas y los pies planos en el suelo.","Sostén una pesa rusa en una mano a la altura del hombro.","Eleva las caderas en un puente de glúteos.","Empuja la pesa rusa recto hacia el techo.","Baja la pesa rusa y las caderas con control.","Completa las repeticiones de un lado y luego cambia."],"tips":["Mantén las caderas elevadas y firmes mientras haces el press.","Sujeta la pesa con la muñeca recta y firme.","Evita que la cadera rote hacia el lado cargado."],"met":6.0,"uni":true,"img":["one-arm-kettlebell-floor-glute-bridge-press-start.webp","one-arm-kettlebell-floor-glute-bridge-press-peak.webp"]},{"id":"one-arm-kettlebell-floor-press","n":"Press en Suelo con Pesa Rusa a Un Brazo","d":"Un press de pecho unilateral con pesa rusa ejecutado tumbado en el suelo, que acorta el recorrido y trabaja pectoral y tríceps.","cat":"fuerza","g":"pecho","bp":"chest","eq":"kettlebell","home":true,"bw":false,"lv":"intermedio","m":["pectoral"],"m2":["deltoides anterior","tríceps"],"ins":["Túmbate boca arriba en el suelo con las rodillas dobladas.","Sostén una pesa rusa en un hombro con una mano.","Empuja la pesa rusa recto hacia arriba hasta que el brazo quede completamente extendido.","Baja la pesa rusa hasta que la parte superior del brazo toque el suelo.","Mantén el core contraído durante todo el ejercicio.","Completa las repeticiones de un lado y luego cambia."],"tips":["Apoya el brazo en el suelo con suavidad, sin rebotar.","Sujeta la pesa con la muñeca firme, sin dejar que se doble.","Evita abrir el codo en exceso hacia el lado."],"met":6.0,"uni":true,"img":["one-arm-kettlebell-floor-press-start.webp","one-arm-kettlebell-floor-press-peak.webp"]},{"id":"one-arm-kettlebell-front-squat","n":"Sentadilla Frontal con Pesa Rusa a Un Brazo","d":"Una sentadilla frontal con una pesa rusa apoyada en un solo hombro, que obliga al core a resistir la inclinación lateral.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"kettlebell","home":true,"bw":false,"lv":"intermedio","m":["glúteo mayor","cuádriceps"],"m2":["lumbares","isquiotibiales","oblicuos"],"ins":["Sostén una pesa rusa en posición de rack en un hombro.","De pie con los pies a la anchura de los hombros.","Baja en sentadilla flexionando las rodillas y las caderas.","Mantén el pecho alto y el torso erguido durante todo el ejercicio.","Impulsa a través de los talones para volver a ponerte de pie.","Completa las repeticiones de un lado y luego cambia."],"tips":["Resiste la tendencia a inclinarte hacia el lado de la pesa.","Empuja las rodillas hacia afuera en la parte baja.","Mantén el codo pegado al cuerpo bajo la pesa."],"met":6.0,"uni":true,"img":["one-arm-kettlebell-front-squat-start.webp","one-arm-kettlebell-front-squat-peak.webp"]},{"id":"one-arm-kettlebell-push-press","n":"Push Press con Pesa Rusa a Un Brazo","d":"Un press unilateral con pesa rusa que usa un impulso de piernas para llevar el peso por encima de la cabeza.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"kettlebell","home":true,"bw":false,"lv":"intermedio","m":["deltoides anterior"],"m2":["glúteo mayor","cuádriceps","trapecio","tríceps"],"ins":["Sostén una pesa rusa en posición de rack en un hombro.","De pie con los pies a la anchura de los hombros.","Flexiona ligeramente las rodillas.","Extiende las piernas de forma explosiva y empuja la pesa rusa por encima de la cabeza.","Bloquea el codo en la parte superior.","Baja la pesa rusa al hombro con control.","Completa las repeticiones de un lado y luego cambia."],"tips":["Haz la flexión de piernas corta y rápida, sin inclinar el torso.","Sincroniza el empuje de piernas con la extensión del brazo.","Aprieta el core al recibir la pesa de vuelta en el hombro."],"met":6.0,"uni":true,"img":["one-arm-kettlebell-push-press-start.webp","one-arm-kettlebell-push-press-peak.webp"]},{"id":"one-arm-kettlebell-row","n":"Remo con Pesa Rusa a Un Brazo","d":"Un remo unilateral con pesa rusa y apoyo en banco, que fortalece el dorsal ancho y los romboides de cada lado.","cat":"fuerza","g":"espalda","bp":"back","eq":"kettlebell","home":true,"bw":false,"lv":"intermedio","m":["dorsales","romboides"],"m2":["bíceps","deltoides posterior","trapecio"],"ins":["Apoya una mano y una rodilla sobre un banco para sujetarte.","Sostén una pesa rusa en la mano contraria con el brazo extendido.","Jala la pesa rusa hacia la cadera llevando el codo hacia atrás.","Aprieta la espalda en la parte superior del movimiento.","Baja la pesa rusa con control.","Completa las repeticiones de un lado y luego cambia."],"tips":["Mantén la espalda plana y paralela al suelo.","Evita rotar el torso al subir la pesa.","Tira con la espalda, no solo con el bíceps."],"met":6.0,"uni":true,"img":["one-arm-kettlebell-row-start.webp","one-arm-kettlebell-row-peak.webp"]},{"id":"one-arm-kettlebell-shoulder-press","n":"Press de Hombro con Pesa Rusa a Un Brazo","d":"Un press de hombro estricto a un brazo con pesa rusa, que exige estabilidad del core para evitar la inclinación lateral.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"kettlebell","home":true,"bw":false,"lv":"intermedio","m":["deltoides anterior","deltoides lateral"],"m2":["oblicuos","trapecio","tríceps"],"ins":["Sostén una pesa rusa en posición de rack en un hombro.","De pie con los pies a la anchura de las caderas.","Empuja la pesa rusa recto hacia arriba hasta bloquear el codo.","Mantén el core apretado durante todo el ejercicio.","Baja la pesa rusa a la posición de rack con control.","Completa las repeticiones de un lado y luego cambia."],"tips":["No te inclines hacia el lado contrario al empujar.","Mantén el antebrazo vertical bajo la pesa durante el recorrido.","Exhala al empujar y evita encoger el hombro hacia la oreja."],"met":6.0,"uni":true,"img":["one-arm-kettlebell-shoulder-press-start.webp","one-arm-kettlebell-shoulder-press-peak.webp"]},{"id":"one-arm-kettlebell-swing","n":"Swing con Pesa Rusa a Un Brazo","d":"Un swing de pesa rusa a un brazo, un movimiento balístico de bisagra de cadera que desarrolla potencia en glúteos e isquiotibiales.","cat":"fuerza","g":"cuerpo completo","bp":"full_body","eq":"kettlebell","home":true,"bw":false,"lv":"intermedio","m":["glúteo mayor","isquiotibiales"],"m2":["deltoides anterior","lumbares","oblicuos"],"ins":["De pie con los pies a la anchura de los hombros y la pesa rusa en el suelo frente a ti.","Bisagra en las caderas y agarra la pesa rusa con una mano.","Lleva la pesa rusa hacia atrás entre las piernas.","Impulsa las caderas hacia adelante para lanzar la pesa rusa hasta la altura del pecho.","Deja que la gravedad lleve la pesa rusa de vuelta entre las piernas.","Completa las repeticiones de un lado y luego cambia."],"tips":["Genera la potencia con la cadera, no con el brazo.","Mantén la espalda recta cuando la pesa pase entre las piernas.","No dejes que la pesa tire del hombro hacia delante."],"met":8.0,"uni":true,"img":["one-arm-kettlebell-swing-start.webp","one-arm-kettlebell-swing-peak.webp"]},{"id":"one-arm-kettlebell-tricep-kickback","n":"Extensión de Tríceps a Un Brazo con Pesa Rusa","d":"Una extensión de tríceps unilateral con pesa rusa: inclínate, fija el brazo al costado paralelo al suelo y extiende el codo hacia atrás.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"kettlebell","home":true,"bw":false,"lv":"principiante","m":["tríceps"],"m2":["deltoides posterior"],"ins":["Inclínate hacia delante flexionando las caderas con la espalda recta y las rodillas ligeramente flexionadas.","Sujeta una pesa rusa por el asa con una mano, con la palma hacia el cuerpo.","Fija la parte alta del brazo al costado de modo que quede paralela al suelo; el antebrazo cuelga recto hacia abajo.","Extiende el codo hacia atrás para estirar el brazo del todo por detrás de ti, manteniendo inmóvil la parte alta del brazo.","Aprieta el tríceps en la extensión completa y vuelve de forma controlada a la posición inicial.","Completa todas las repeticiones de un lado y luego cambia de mano."],"tips":["La parte alta del brazo no se mueve, solo el antebrazo; balancear el hombro es trampa.","Bloquea la pesa un instante en la extensión completa; tiende a hundirte la muñeca.","Usa una pesa más ligera que en una extensión con mancuerna; la carga descentrada cuesta más de estabilizar."],"met":5.0,"uni":true,"img":["one-arm-kettlebell-tricep-kickback-start.webp","one-arm-kettlebell-tricep-kickback-peak.webp"]},{"id":"one-arm-landmine-press","n":"Press Landmine con Un Brazo","d":"Una variante de press sobre la cabeza unilateral con montaje landmine que sigue un arco natural, reduciendo el riesgo de impingement de hombro.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["deltoides anterior","pectoral"],"m2":["oblicuos","serrato","tríceps"],"ins":["Ancla un extremo de la barra en el accesorio landmine y carga el extremo libre.","Arrodíllate en una rodilla o párate y sujeta el extremo libre a la altura del hombro con una mano.","Empuja la barra hacia arriba y adelante siguiendo su arco hasta extender completamente el brazo.","Baja la barra de regreso a la altura del hombro con control.","Completa todas las repeticiones antes de cambiar de lado."],"tips":["Activa el core para evitar que el torso rote hacia el brazo de trabajo.","El movimiento en arco es más amigable para las articulaciones que un press estricto.","Arrodillarse sobre la rodilla del mismo lado que el brazo que empuja, con el otro pie apoyado delante, aumenta la demanda antirrotacional del core."],"met":6.0,"uni":true,"img":["one-arm-landmine-press-start.webp","one-arm-landmine-press-peak.webp"]},{"id":"one-arm-lat-pulldown","n":"Jalón al Pecho con Un Brazo","d":"Un jalón en cable unilateral con manija individual que trabaja el dorsal ancho permitiendo mayor rango de movimiento y corrección de desequilibrios.","cat":"fuerza","g":"espalda","bp":"back","eq":"polea","home":false,"bw":false,"lv":"intermedio","m":["dorsales"],"m2":["bíceps","deltoides posterior","romboides"],"ins":["Sujeta una manija individual al jalón de cable y siéntate con los muslos asegurados bajo el soporte.","Agarra la manija con una mano, brazo completamente extendido.","Tira de la manija hacia tu hombro llevando el codo hacia la cadera.","Pausa brevemente en la contracción máxima, luego vuelve con control.","Completa todas las repeticiones en un lado antes de cambiar."],"tips":["Inclínate ligeramente alejándote del cable para maximizar el estiramiento del dorsal arriba.","Tira con el codo, no con la mano, para mantener el dorsal activado.","Controla la fase excéntrica para maximizar la tensión en el dorsal durante todo el rango."],"met":6.0,"uni":true,"img":["one-arm-lat-pulldown-start.webp","one-arm-lat-pulldown-peak.webp"]},{"id":"one-arm-seated-cable-row","n":"Remo Unilateral Sentado en Polea","d":"Un remo unilateral sentado en polea para dorsales y espalda alta, manteniendo el torso de frente mientras el omóplato del lado activo avanza y retrocede de forma controlada.","cat":"fuerza","g":"espalda","bp":"back","eq":"polea","home":false,"bw":false,"lv":"intermedio","m":["dorsales","romboides"],"m2":["bíceps","deltoides posterior","trapecio"],"ins":["Siéntate en la estación de polea y sujeta el agarre con el brazo de trabajo extendido.","Apoya bien los pies, siéntate erguido y activa el tronco sin inclinarte hacia atrás.","Lleva el agarre hacia las costillas bajas mientras retraes el omóplato.","Haz una pausa breve sin girar el torso ni elevar el hombro.","Extiende el brazo de forma controlada, termina la serie y cambia de lado."],"tips":["Mantén ambos hombros orientados al frente durante toda la repetición.","Lleva el codo hacia atrás cerca del cuerpo en lugar de flexionar solamente el brazo.","Deja que el omóplato avance al inicio sin redondear la zona lumbar."],"met":6.0,"uni":true,"img":["one-arm-seated-cable-row-start.webp","one-arm-seated-cable-row-peak.webp"]},{"id":"one-arm-single-leg-dumbbell-romanian-deadlift","n":"Peso Muerto Rumano a Una Pierna con Mancuerna a Un Brazo","d":"Un peso muerto rumano a una pierna sosteniendo una mancuerna en una sola mano, generalmente la opuesta a la pierna de apoyo (contralateral). Carga los isquiotibiales y glúteos de la pierna de apoyo mientras exige una fuerte contención anti-rotación del core.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"mancuernas","home":true,"bw":false,"lv":"avanzado","m":["glúteo mayor","isquiotibiales"],"m2":["lumbares","antebrazo","glúteo medio","oblicuos"],"ins":["De pie sobre una pierna, sostén una mancuerna en la mano contraria.","Brazo libre al costado para equilibrarte, pierna libre suspendida justo por encima del suelo.","Bisagra en la cadera de apoyo empujándola hacia atrás mientras la pierna libre se extiende detrás para contrarrestar el peso.","Mantén las caderas cuadradas al suelo; no las abras hacia el lado.","Baja la mancuerna hacia el pie de la pierna de apoyo sintiendo un estiramiento profundo en los isquiotibiales.","Impulsa la cadera hacia adelante para volver a ponerte de pie con control.","Completa todas las repeticiones de un lado y luego cambia."],"tips":["Empieza con menos peso del que crees; el equilibrio y la demanda anti-rotación son el factor limitante, no la fuerza de los isquiotibiales.","Si rotas, haz una pausa y reinicia; un recorrido limpio más corto es mejor que uno completo con rotación.","Fijar la vista en un punto fijo en el suelo a un par de metros al frente ayuda con el equilibrio."],"met":6.0,"uni":true,"img":["one-arm-single-leg-dumbbell-romanian-deadlift-start.webp","one-arm-single-leg-dumbbell-romanian-deadlift-peak.webp"]},{"id":"one-arm-single-leg-kettlebell-romanian-deadlift","n":"Peso Muerto Rumano a Una Pierna con Pesa Rusa a Un Brazo","d":"La versión con pesa rusa del peso muerto rumano a una pierna y un brazo. La masa excéntrica de la pesa rusa y su centro de gravedad más bajo lo convierten en un reto sutilmente diferente al de la mancuerna; excelente para la fuerza de la cadena posterior y el equilibrio bajo carga asimétrica.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"kettlebell","home":true,"bw":false,"lv":"avanzado","m":["glúteo mayor","isquiotibiales"],"m2":["lumbares","antebrazo","glúteo medio","oblicuos"],"ins":["De pie sobre una pierna, sostén una pesa rusa en la mano contraria por el asa.","Brazo libre al costado para equilibrarte, pierna libre suspendida detrás.","Bisagra en la cadera de apoyo empujándola hacia atrás mientras la pierna libre se extiende para contrarrestar el peso.","Mantén las caderas cuadradas al suelo; la pesa rusa desciende recto por la espinilla.","Siente un estiramiento profundo en los isquiotibiales de la pierna de apoyo en la parte inferior.","Impulsa la cadera hacia adelante para volver a ponerte de pie.","Completa todas las repeticiones de un lado y luego cambia."],"tips":["La pesa rusa cuelga más bajo que una mancuerna; acorta ligeramente el recorrido para mantener la espalda plana.","Si la pesa oscila, estás yendo demasiado rápido. Desacelera la fase excéntrica.","Primero domina el peso muerto rumano a una pierna con dos mancuernas antes de progresar a este ejercicio."],"met":6.0,"uni":true,"img":["one-arm-single-leg-kettlebell-romanian-deadlift-start.webp","one-arm-single-leg-kettlebell-romanian-deadlift-peak.webp"]},{"id":"overhead-squat","n":"Sentadilla con Barra en Alto","d":"Una sentadilla con la barra bloqueada por encima de la cabeza con agarre ancho de arrancada, que exige movilidad, estabilidad y un core fuerte.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["glúteo mayor","cuádriceps"],"m2":["lumbares","deltoides lateral","trapecio"],"ins":["Sostén una barra por encima de la cabeza con un agarre ancho de arrancada y los codos bloqueados.","De pie con los pies ligeramente más abiertos que la anchura de los hombros.","Baja en sentadilla empujando las caderas hacia atrás y doblando las rodillas.","Mantén la barra directamente sobre el punto medio de los pies.","Impulsa a través de los talones para volver a ponerte de pie.","Repite el número de repeticiones deseado."],"tips":["Gira las axilas hacia delante para fijar la barra en su sitio.","Mantén la barra sobre el mediopié, con el torso más erguido que en una sentadilla trasera.","Trabaja la movilidad de hombros y tobillos antes de añadir peso."],"met":6.0,"uni":false,"img":["overhead-squat-start.webp","overhead-squat-peak.webp"]},{"id":"overhead-tricep-extension","n":"Extensión de Tríceps por Encima de la Cabeza","d":"Un ejercicio de aislamiento para el tríceps que enfatiza la cabeza larga.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"mancuernas","home":true,"bw":false,"lv":"principiante","m":["tríceps"],"m2":[],"ins":["De pie o sentado, sostén una mancuerna por encima de la cabeza con ambas manos.","Baja la mancuerna detrás de la cabeza doblando los codos.","Extiende los brazos de vuelta a la posición inicial.","Mantén los codos cerca de la cabeza durante todo el ejercicio.","Repite."],"tips":["Mueve solo los antebrazos y mantén quieto todo lo demás.","Evita arquear la zona lumbar cuando la mancuerna baje.","Agarra la mancuerna por debajo del disco superior con ambas palmas."],"met":5.0,"uni":false,"img":["overhead-tricep-extension-start.webp","overhead-tricep-extension-peak.webp"]},{"id":"overhead-triceps-stretch","n":"Estiramiento de Tríceps sobre la Cabeza","d":"Un estiramiento de pie que alarga el tríceps y el dorsal llevando la mano por la espalda alta.","cat":"estiramiento","g":"brazos","bp":"upper_arms","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["tríceps"],"m2":["dorsales"],"ins":["Sube un brazo sobre la cabeza y flexiona el codo.","Deja caer la mano por detrás de la cabeza.","Con la otra mano empuja el codo flexionado hacia atrás.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],"tips":["Mantén la cabeza erguida, no la empujes hacia adelante.","Relájate y sigue respirando todo el tiempo."],"met":5.0,"uni":true,"img":["overhead-triceps-stretch-main.webp"]},{"id":"pause-deadlift","n":"Peso Muerto con Pausa","d":"Una variante del peso muerto con una pausa deliberada justo por encima de las rodillas, que desarrolla fuerza y posición en la mitad superior del tirón.","cat":"fuerza","g":"espalda","bp":"back","eq":"barra","home":false,"bw":false,"lv":"avanzado","m":["lumbares","glúteo mayor","isquiotibiales"],"m2":["cuádriceps","trapecio"],"ins":["Colócate en posición de peso muerto convencional.","Levanta la barra del suelo y haz una pausa cuando pase por las rodillas.","Mantén la posición 2-3 segundos y luego completa el levantamiento.","Baja con control.","Repite."],"tips":["La pausa elimina el impulso y desarrolla fuerza y control desde las rodillas hasta el bloqueo.","Mantén la espalda plana durante la pausa."],"met":6.0,"uni":false,"img":["pause-deadlift-start.webp","pause-deadlift-peak.webp"]},{"id":"pause-pull-up","n":"Dominada con Pausa","d":"Una variante de dominada que añade una breve pausa isométrica en la parte superior del movimiento, con la barbilla sobre la barra, antes de bajar de nuevo.","cat":"fuerza","g":"espalda","bp":"back","eq":"barra de dominadas","home":true,"bw":false,"lv":"avanzado","m":["dorsales"],"m2":["bíceps","deltoides posterior","romboides","trapecio"],"ins":["Cuélgate de una barra de dominadas con agarre prono, brazos completamente extendidos.","Tira de tu cuerpo hacia arriba hasta que la barbilla supere la barra.","Haz una pausa y mantén esa posición superior un momento.","Baja con control de vuelta a la posición de colgado completo.","Repite el número deseado de repeticiones."],"tips":["La pausa elimina el impulso, así que el tirón es más difícil que en una dominada normal -- espera menos repeticiones.","Mantén los hombros activos durante la pausa en lugar de relajarte colgando de la barra.","Baja despacio en vez de caer directamente a la siguiente repetición."],"met":6.0,"uni":false,"img":["pause-pull-up-start.webp","pause-pull-up-peak.webp"]},{"id":"pause-squat","n":"Sentadilla con Pausa","d":"Una sentadilla con barra que incluye una pausa de varios segundos en la posición baja para eliminar el rebote y reforzar la salida del fondo.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["glúteo mayor","cuádriceps"],"m2":["lumbares","glúteo medio","isquiotibiales"],"ins":["Saca la barra del rack y apóyala sobre la parte superior de la espalda.","De pie con los pies a la anchura de los hombros.","Baja en sentadilla hasta que los muslos queden paralelos al suelo.","Mantén la posición inferior durante 2-3 segundos.","Impulsa a través de los talones para volver a ponerte de pie.","Repite el número de repeticiones deseado."],"tips":["Mantén la tensión en la pausa; no te relajes en el fondo.","Coge aire arriba y mantén el abdomen firme toda la repetición.","Mantén el pecho alto para que la barra no te venza hacia delante."],"met":6.0,"uni":false,"img":["pause-squat-start.webp","pause-squat-peak.webp"]},{"id":"paused-bench-press","n":"Press de Banca con Pausa","d":"Un press de banca con barra en el que la pausa sobre el pecho elimina el rebote y endurece la fase inicial del empuje.","cat":"fuerza","g":"pecho","bp":"chest","eq":"barra","home":false,"bw":false,"lv":"avanzado","m":["pectoral"],"m2":["deltoides anterior","tríceps"],"ins":["Túmbate en un banco plano y agarra la barra ligeramente más abierta que la anchura de los hombros.","Saca la barra del rack y bájala hasta el pecho.","Haz una pausa sobre el pecho durante 1-2 segundos.","Empuja la barra hacia arriba hasta que los brazos queden completamente extendidos.","Controla el descenso en cada repetición.","Repite el número de repeticiones deseado."],"tips":["No dejes que la barra se hunda en el pecho durante la pausa.","Mantén los omóplatos retraídos y pegados al banco.","Pide que alguien te asista cuando muevas cargas altas."],"met":6.0,"uni":false,"img":["paused-bench-press-start.webp","paused-bench-press-peak.webp"]},{"id":"paused-incline-bench-press","n":"Press Inclinado con Pausa","d":"Un press inclinado con barra y pausa sobre la parte alta del pecho, que elimina el rebote y enfatiza pectoral superior y deltoides anterior.","cat":"fuerza","g":"pecho","bp":"chest","eq":"barra","home":false,"bw":false,"lv":"avanzado","m":["deltoides anterior","pectoral"],"m2":["tríceps"],"ins":["Túmbate en un banco inclinado y agarra la barra ligeramente más abierta que la anchura de los hombros.","Saca la barra del rack y bájala hasta el pecho superior.","Haz una pausa sobre el pecho durante 1-2 segundos.","Empuja la barra hacia arriba hasta que los brazos queden completamente extendidos.","Mantén los omóplatos retraídos durante todo el ejercicio.","Repite el número de repeticiones deseado."],"tips":["No acortes la pausa cuando la carga se haga pesada.","Mantén las muñecas firmes sobre los codos durante el recorrido.","Mantén los pies firmes en el suelo durante toda la serie."],"met":6.0,"uni":false,"img":["paused-incline-bench-press-start.webp","paused-incline-bench-press-peak.webp"]},{"id":"paused-ohp","n":"Press militar con pausa","d":"Una variante del press militar que hace una pausa con la barra a la altura de los hombros, eliminando el impulso para desarrollar fuerza de empuje estricta y estabilidad por encima de la cabeza.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"barra","home":false,"bw":false,"lv":"avanzado","m":["deltoides anterior","deltoides lateral"],"m2":["trapecio","tríceps"],"ins":["Colócate con la barra a la altura de los hombros, pies al ancho de los hombros y el core firme.","Empuja la barra recta por encima de la cabeza hasta bloquear los codos.","Baja la barra de forma controlada hasta el frente de los hombros.","Mantén una pausa completa de un segundo en los hombros, conservando la tensión y evitando cualquier rebote.","Vuelve a empujar desde la posición estática sin usar impulso de piernas."],"tips":["Mantén la pausa estricta: sin rebotar la barra en los hombros.","Aprieta el core y mantén la trayectoria de la barra vertical sobre el medio del pie.","Usa un peso que puedas controlar desde el arranque estático."],"met":6.0,"uni":false,"img":["paused-ohp-start.webp","paused-ohp-peak.webp"]},{"id":"pec-deck","n":"Pec Deck","d":"Una máquina de aislamiento de pecho con almohadillas de codo fijas que trabaja los pectorales mediante aducción horizontal.","cat":"fuerza","g":"pecho","bp":"chest","eq":"pec deck","home":false,"bw":false,"lv":"principiante","m":["pectoral"],"m2":["deltoides anterior","serrato"],"ins":["Siéntate en la máquina pec deck y coloca los antebrazos contra las almohadillas.","Ajusta el asiento para que las almohadillas queden a la altura media del pecho.","Junta las almohadillas frente al pecho apretando.","Mantén la contracción brevemente en el centro.","Regresa con control a la posición inicial.","Repite el número de repeticiones deseado."],"tips":["No dejes que los brazos viajen demasiado atrás al abrir.","Mantén la espalda y los hombros pegados al respaldo.","Exhala al juntar las almohadillas e inhala al abrir."],"met":5.0,"uni":false,"img":["pec-deck-start.webp","pec-deck-peak.webp"]},{"id":"pendlay-row","n":"Remo Pendlay","d":"Un remo estricto con barra realizado desde una parada muerta en el suelo entre repeticiones con el torso paralelo al suelo. Popularizado por el entrenador Glenn Pendlay.","cat":"fuerza","g":"espalda","bp":"back","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["dorsales","romboides","trapecio"],"m2":["bíceps","lumbares","deltoides posterior"],"ins":["Carga una barra y colócala en el suelo.","Bisagra en las caderas hasta que el torso quede paralelo al suelo con las rodillas ligeramente dobladas.","Agarra la barra ligeramente más abierta que la anchura de los hombros con un agarre en pronación.","Jala la barra de forma explosiva hacia el pecho inferior.","Baja la barra al suelo con control y haz una pausa antes de la siguiente repetición.","Repite."],"tips":["Cada repetición debe comenzar desde el suelo sin rebote.","Mantén el torso fijo a aproximadamente 90 grados; no uses el impulso del cuerpo.","Lleva los codos hacia arriba y atrás, no hacia los lados."],"met":6.0,"uni":false,"img":["pendlay-row-start.webp","pendlay-row-peak.webp"]},{"id":"pigeon-stretch","n":"Estiramiento de la Paloma","d":"Un estiramiento sentado en el suelo para los glúteos y la cadera externa, con la espinilla delantera cruzada al frente.","cat":"estiramiento","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["glúteo mayor"],"m2":["glúteo medio","flexores de cadera"],"ins":["Desde cuadrupedia, lleva una rodilla adelante y apoya la espinilla cruzada al frente.","Extiende la otra pierna recta hacia atrás, con el empeine en el suelo.","Baja la cadera hacia el suelo y mantenla cuadrada.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],"tips":["Coloca un cojín bajo la cadera si no llega al suelo.","Camina las manos hacia adelante para profundizar el estiramiento."],"met":5.0,"uni":true,"img":["pigeon-stretch-main.webp"]},{"id":"pike-push-ups","n":"Flexiones en Pica","d":"Una flexión realizada con las caderas elevadas en posición de pica, empujando en un ángulo pronunciado para cargar los hombros.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["deltoides anterior","deltoides lateral"],"m2":["trapecio","tríceps"],"ins":["Comienza en posición de perro boca abajo con las caderas altas y las manos a la anchura de los hombros.","Acerca los pies a las manos.","Dobla los codos y baja la cabeza hacia el suelo.","Mantén las caderas altas durante todo el ejercicio.","Empuja hacia arriba hasta que los brazos queden completamente extendidos.","Repite el número de repeticiones deseado."],"tips":["Cuanto más altas las caderas, más trabajan los hombros.","Baja la cabeza hacia un punto ligeramente por delante de las manos.","Acerca los pies a las manos para progresar hacia las flexiones en pino."],"met":5.0,"uni":false,"img":["pike-push-ups-start.webp","pike-push-ups-peak.webp"]},{"id":"pilates-kneeling-side-kick","n":"Patada Lateral de Rodillas de Pilates","d":"Un ejercicio clásico de suelo: de rodillas con la mano apoyada en el suelo, la pierna de arriba oscila adelante y atrás a la altura de la cadera mientras el tronco permanece inmóvil.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["glúteo medio","oblicuos"],"m2":["glúteo mayor","flexores de cadera"],"ins":["Arrodíllate y apoya en el suelo la mano del mismo lado, con la otra mano detrás de la cabeza.","Extiende la pierna de arriba hacia el lado a la altura de la cadera, con el pie en flexión.","Mantén el tronco completamente quieto y lleva la pierna hacia delante mientras la pelvis siga cuadrada.","Lleva la pierna por detrás de la línea del cuerpo sin arquear la zona lumbar.","Repite las veces indicadas y cambia de lado."],"tips":["El tronco es el ejercicio: si se balancea con la pierna, acorta el recorrido.","Mantén el hombro de apoyo alejado de la oreja.","Trabaja a un ritmo controlado en lugar de lanzar la pierna."],"met":5.0,"uni":true,"img":["pilates-kneeling-side-kick-start.webp","pilates-kneeling-side-kick-peak.webp"]},{"id":"pilates-leg-pull-back","n":"Leg Pull Back de Pilates","d":"Una plancha invertida con elevaciones alternas de pierna: las caderas se mantienen altas mientras se eleva una pierna cada vez, de modo que glúteos y parte posterior del tronco trabajan ante el apoyo cambiante.","cat":"fuerza","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["lumbares","glúteo mayor"],"m2":["isquiotibiales","deltoides posterior","tríceps"],"ins":["Siéntate con las piernas estiradas y las manos en el suelo detrás de las caderas, con los dedos hacia delante.","Empuja con manos y talones y eleva las caderas a una plancha invertida.","Con las caderas niveladas y altas, eleva una pierna estirada mientras la pelvis siga quieta.","Baja la pierna de forma controlada y repite con la otra.","Termina la serie y baja las caderas al suelo."],"tips":["Detén la elevación donde las caderas empiecen a caer; la altura no es el objetivo.","Mantén el pecho abierto y los hombros lejos de las orejas.","Flexiona un poco las rodillas si la versión con piernas estiradas tira de los isquiotibiales."],"met":5.0,"uni":false,"img":["pilates-leg-pull-back-start.webp","pilates-leg-pull-back-peak.webp"]},{"id":"pilates-leg-pull-front","n":"Leg Pull Front de Pilates","d":"Una plancha alta con elevaciones alternas de pierna: los hombros permanecen sobre las muñecas mientras se eleva una pierna cada vez, lo que añade una demanda antirrotación a la plancha.","cat":"fuerza","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["glúteo mayor","abdominales"],"m2":["deltoides anterior","lumbares","transverso abdominal"],"ins":["Colócate en plancha alta con las manos bajo los hombros y el cuerpo en línea.","Aprieta el tronco y los glúteos para que las caderas no puedan rotar.","Eleva una pierna estirada unos centímetros por encima de la cadera sin que la pelvis se incline.","Bájala de forma controlada y repite con la otra pierna.","Sigue alternando las veces indicadas."],"tips":["Eleva la pierna desde el glúteo y no arqueando la zona lumbar.","Reparte el peso entre ambas manos; la tendencia es inclinarse lejos del lado que se eleva.","Reduce la altura hasta que las caderas se mantengan perfectamente niveladas."],"met":5.0,"uni":false,"img":["pilates-leg-pull-front-start.webp","pilates-leg-pull-front-peak.webp"]},{"id":"pilates-roll-down","n":"Roll Down de Pilates","d":"Una articulación de la columna de pie: la cabeza guía un descenso vértebra a vértebra hacia el suelo y de vuelta, movilizando toda la espalda mientras las piernas se mantienen estables.","cat":"estiramiento","g":"espalda","bp":"back","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["lumbares"],"m2":["isquiotibiales","abdominales"],"ins":["Ponte de pie con los pies a la anchura de las caderas y los brazos colgando a los lados.","Lleva la barbilla al pecho y empieza a rodar hacia abajo vértebra a vértebra.","Deja los brazos y la cabeza colgando pesados cuando la columna esté completamente descendida.","Sube por el mismo camino, apilando las vértebras una a una, la cabeza al final.","Repite las veces indicadas."],"tips":["Mantén las rodillas blandas para que el movimiento venga de la columna y no de los isquiotibiales.","Ve lo bastante despacio como para sentir cada segmento; la velocidad arruina el ejercicio.","Mantén el peso en el centro de los pies mientras bajas."],"met":5.0,"uni":false,"img":["pilates-roll-down-start.webp","pilates-roll-down-peak.webp"]},{"id":"pilates-roll-over","n":"Roll Over de Pilates","d":"Una inversión controlada desde la colchoneta: con los brazos presionando el suelo, las piernas estiradas viajan por encima de la cabeza hasta que los pies apuntan al suelo, y después la columna vuelve a bajar segmento a segmento.","cat":"fuerza","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"avanzado","m":["abdominales","transverso abdominal"],"m2":["lumbares","flexores de cadera"],"ins":["Túmbate boca arriba con las piernas estiradas y los brazos presionando la colchoneta a los lados.","Eleva ambas piernas a la vertical sin dejar que la zona lumbar se arquee.","Presiona los brazos hacia abajo y lleva las piernas por encima de la cabeza hasta dejarlas paralelas al suelo por detrás.","Abre un poco las piernas, flexiona los pies y baja la columna vértebra a vértebra.","Devuelve las piernas a la vertical y repite las veces indicadas."],"tips":["Impulsa el movimiento con el abdomen, no lanzando las piernas.","Mantén el peso fuera del cuello: el descenso se detiene en las escápulas.","Evita este ejercicio si tienes molestias cervicales y constrúyelo antes con curls más pequeños."],"met":5.0,"uni":false,"img":["pilates-roll-over-start.webp","pilates-roll-over-peak.webp"]},{"id":"pilates-saw","n":"La Sierra de Pilates","d":"Un giro con flexión sentado: sentado erguido con las piernas abiertas, el torso rota y después se pliega sobre la pierna contraria para que la mano que alcanza pase junto al dedo meñique como una sierra.","cat":"estiramiento","g":"espalda","bp":"back","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["lumbares","oblicuos"],"m2":["aductores","isquiotibiales"],"ins":["Siéntate erguido con las piernas estiradas y algo más abiertas que las caderas, los brazos hacia los lados.","Rota el torso hacia un lado manteniendo ambos isquiones en el suelo.","Pliégate hacia delante sobre esa pierna y alcanza con la mano contraria más allá del dedo meñique.","Vuelve a subir a través de la columna y regresa al centro.","Repite hacia el otro lado y sigue alternando."],"tips":["Ancla ambos isquiones; si uno se levanta, el giro se convierte en una inclinación.","Primero rota y después pliégate: ese orden es lo que hace funcionar el ejercicio.","Siéntate sobre una manta doblada si la pelvis no puede mantenerse erguida."],"met":5.0,"uni":false,"img":["pilates-saw-start.webp","pilates-saw-peak.webp"]},{"id":"pilates-side-bend","n":"Flexión Lateral de Pilates","d":"Un ejercicio lateral del tronco desde un apoyo de costado: las caderas se elevan y el brazo de arriba se estira por encima de la cabeza, curvando el cuerpo de lado sobre el brazo de apoyo.","cat":"fuerza","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["glúteo medio","oblicuos"],"m2":["deltoides anterior","transverso abdominal"],"ins":["Siéntate sobre una cadera con las piernas dobladas hacia un lado y la mano de apoyo en el suelo bajo el hombro.","Empuja con la mano y la pierna inferior para elevar las caderas del suelo.","Estira el brazo de arriba por encima de la cabeza para formar un arco largo desde la mano hasta los pies.","Baja las caderas de forma controlada hacia la colchoneta.","Completa las repeticiones y cambia de lado."],"tips":["Empuja el suelo para que el hombro de apoyo quede estable y alineado.","Alarga el brazo de arriba en lugar de dejarte caer hacia el lado.","Mantén el movimiento fluido: subir y bajar duran lo mismo."],"met":5.0,"uni":true,"img":["pilates-side-bend-start.webp","pilates-side-bend-peak.webp"]},{"id":"pilates-spine-stretch-forward","n":"Spine Stretch Forward de Pilates","d":"Una articulación sentada: sentado erguido con las piernas abiertas, la columna se enrolla hacia delante segmento a segmento sobre las piernas y después vuelve a apilarse vértebra a vértebra.","cat":"estiramiento","g":"espalda","bp":"back","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["lumbares","abdominales"],"m2":["isquiotibiales","transverso abdominal"],"ins":["Siéntate erguido con las piernas estiradas y algo más abiertas que las caderas, los pies en flexión.","Estira los brazos hacia delante a la altura de los hombros.","Baja la barbilla y enrolla la columna hacia delante vértebra a vértebra, alcanzando más allá de los pies.","Vuelve a apilar la columna desde la base hasta quedar sentado erguido.","Repite las veces indicadas."],"tips":["Mantén la pelvis erguida: la curva viene de la columna, no de bascular la cadera.","Empuja los talones hacia fuera todo el tiempo para que las piernas sigan activas.","Siéntate sobre una manta doblada si ya sentarte erguido te redondea la zona lumbar."],"met":5.0,"uni":false,"img":["pilates-spine-stretch-forward-start.webp","pilates-spine-stretch-forward-peak.webp"]},{"id":"pilates-spine-twist","n":"Spine Twist de Pilates","d":"Una rotación sentada con las piernas juntas y los brazos abiertos: el tronco gira a cada lado de forma controlada mientras la pelvis y las piernas permanecen completamente quietas.","cat":"estiramiento","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["oblicuos"],"m2":["lumbares","transverso abdominal"],"ins":["Siéntate erguido con las piernas estiradas y juntas, los pies en flexión y los brazos abiertos a la altura de los hombros.","Crece a través de la columna y presiona ambos isquiones contra el suelo.","Rota el tronco hacia un lado mientras las caderas sigan cuadradas y vuelve al centro.","Rota hacia el otro lado del mismo modo.","Sigue alternando las veces indicadas."],"tips":["Las piernas son el ancla: si un pie se adelanta, la pelvis se ha movido.","Alárgate hacia arriba antes de cada rotación en lugar de hundirte en ella.","Gira la cabeza con el tronco en lugar de que ella lidere."],"met":5.0,"uni":false,"img":["pilates-spine-twist-start.webp","pilates-spine-twist-peak.webp"]},{"id":"pistol-squat","n":"Sentadilla a una Pierna (Pistol)","d":"Una sentadilla a una pierna con la pierna libre extendida adelante, que exige fuerza y equilibrio.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"avanzado","m":["glúteo mayor","cuádriceps"],"m2":["glúteo medio","isquiotibiales","flexores de cadera"],"ins":["Mantente sobre una pierna, la otra extendida al frente, brazos al lado para equilibrio.","Flexiona la cadera y la rodilla de apoyo, manteniendo el pecho arriba.","Baja lentamente hasta que la parte posterior del muslo toque la pantorrilla.","Empuja con el talón de apoyo para volver a subir.","Repeticiones por lado, luego cambia de pierna."],"tips":["Sostén un contrapeso ligero al pecho si te cuesta el equilibrio.","Construye la fuerza primero con pistol asistido sobre cajón.","Mantén el talón de trabajo plano en el suelo."],"met":6.0,"uni":true,"img":["pistol-squat-start.webp","pistol-squat-peak.webp"]},{"id":"planche","n":"Plancha Calisténica","d":"Una posición avanzada de calistenia que requiere una fuerza excepcional del tren superior y el core para mantener el cuerpo paralelo al suelo.","cat":"fuerza","g":"pecho","bp":"chest","eq":"sin equipo","home":true,"bw":true,"lv":"avanzado","m":["deltoides anterior","pectoral"],"m2":["serrato","tríceps"],"ins":["Comienza en posición de flexión con las manos giradas hacia afuera.","Inclínate hacia adelante hasta que tu centro de masa quede sobre las manos.","Levanta los pies del suelo manteniendo el cuerpo horizontal.","Mantén la posición.","Regresa al suelo con control."],"tips":["Progresa a través de la posición encogida, en estrella y la plancha completa.","Desarrolla la fuerza de muñecas y hombros antes de intentarlo."],"met":6.0,"uni":false,"img":["planche-main.webp"]},{"id":"plank","n":"Plancha","d":"Un ejercicio isométrico de core que fortalece toda la zona media.","cat":"fuerza","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["abdominales","transverso abdominal"],"m2":["lumbares"],"ins":["Apoya los antebrazos en el suelo con los codos bajo los hombros.","Extiende las piernas hacia atrás y apóyate sobre los dedos de los pies.","Mantén el cuerpo en línea recta de la cabeza a los talones.","Contrae el core y aprieta los glúteos.","Mantén la posición durante el tiempo deseado.","Baja las rodillas para salir de la posición."],"tips":["No dejes que las caderas caigan ni se eleven.","Aprieta los glúteos y los cuádriceps."],"met":3.5,"uni":false,"img":["plank-main.webp"]},{"id":"plank-knee-tuck","n":"Rodilla al Pecho en Plancha","d":"Un ejercicio dinámico de core desde la plancha alta: el cuerpo mantiene su línea recta mientras una rodilla se lleva bajo el pecho y vuelve al inicio, alternando lados. Más lento y controlado que un escalador, trabaja el abdomen y los flexores de cadera mientras hombros y tronco permanecen firmes.","cat":"fuerza","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["flexores de cadera","abdominales"],"m2":["deltoides anterior","oblicuos","serrato","transverso abdominal"],"ins":["Colócate en plancha alta con las manos bajo los hombros y el cuerpo en línea recta de la cabeza a los talones.","Empuja el suelo y aprieta el tronco para que la cadera no se hunda ni se eleve.","Lleva una rodilla hacia el pecho sin dejar que la cadera suba.","Extiende la pierna de vuelta a la posición inicial de forma controlada.","Repite con la otra pierna y sigue alternando las veces indicadas."],"tips":["Mantén la cadera a la altura de los hombros; si sube, se convierte en una pica.","Lleva la rodilla con el abdomen en lugar de impulsarte con el pie de apoyo.","Mantén los hombros sobre las muñecas y empuja el suelo para que el tronco no se hunda."],"met":5.0,"uni":false,"img":["plank-knee-tuck-start.webp","plank-knee-tuck-peak.webp"]},{"id":"plate-loaded-donkey-calf-raise","n":"Elevación de Pantorrilla a la Burra en Máquina","d":"Una elevación de pantorrilla a la burra en una máquina de discos, con una almohadilla sobre las caderas y el torso inclinado hacia delante para estirar los gemelos en la parte baja de cada repetición.","cat":"fuerza","g":"piernas","bp":"lower_legs","eq":"máquina de gemelos","home":false,"bw":false,"lv":"principiante","m":["gemelos"],"m2":["sóleo"],"ins":["Carga los soportes de discos y sube a la plataforma con los metatarsos en el borde y los talones al aire.","Inclínate hacia delante desde las caderas, coloca la almohadilla sobre ellas y apoya los antebrazos en el soporte que tienes delante.","Mantén las rodillas estiradas y la espalda plana, con el torso cerca de la paralela al suelo.","Empuja con los metatarsos y eleva los talones tan alto como puedas, con una pausa breve arriba.","Baja los talones por debajo de la plataforma hasta notar un estiramiento fuerte en los gemelos y repite el número de repeticiones deseado."],"tips":["La inclinación hacia delante es el ejercicio. Ponerte erguido lo convierte en una elevación de talones de pie corriente y regala justo el estiramiento extra que venías a buscar.","Mantén las rodillas estiradas todo el tiempo. Flexionarlas traslada el trabajo del gemelo al sóleo, y eso es la elevación sentado, no esta.","Deja que los talones bajen del todo por debajo del borde de la plataforma. La parte baja del recorrido es lo que justifica esta máquina, y recortarla desperdicia todo el montaje."],"met":5.0,"uni":false,"img":["plate-loaded-donkey-calf-raise-start.webp","plate-loaded-donkey-calf-raise-peak.webp"]},{"id":"plate-loaded-glute-drive","n":"Empuje de Glúteo en Máquina de Discos","d":"Un empuje de cadera en una máquina de glúteo de discos, donde el respaldo y la plataforma integrados fijan la posición para que las caderas extiendan contra la carga sin tener que montar un banco.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"máquina de hip thrust","home":false,"bw":false,"lv":"principiante","m":["glúteo mayor"],"m2":["glúteo medio","isquiotibiales","cuádriceps"],"ins":["Carga los soportes de discos por igual y siéntate en la máquina con la parte alta de la espalda contra el respaldo y los pies planos en la plataforma.","Baja la almohadilla o barra sobre tus caderas y ajústala para que apoye en el pliegue de la cadera y no sobre el abdomen.","Coloca los pies de modo que las espinillas queden verticales cuando las caderas estén arriba, y sujeta las empuñaduras.","Empuja las caderas hacia arriba apretando los glúteos hasta que los muslos queden alineados con el torso, y mantén un instante arriba.","Baja de forma controlada hasta justo antes del final del recorrido y repite el número de repeticiones deseado."],"tips":["Coloca la almohadilla en el pliegue de la cadera. Dejarla sobre el abdomen es lo único realmente incómodo de esta máquina, y se resuelve moviendo la almohadilla, no añadiendo acolchado.","Termina el movimiento con la cadera, no con la zona lumbar. Si arriba se te abren las costillas es que se acabó la extensión de cadera y has empezado a arquear, que es donde la máquina deja de entrenar el glúteo.","Este es el empuje de cadera al que recurrir cuando el banco y la barra están ocupados: el respaldo y la plataforma forman parte del bastidor, así que no hay montaje que hacer mal."],"met":6.0,"uni":false,"img":["plate-loaded-glute-drive-start.webp","plate-loaded-glute-drive-peak.webp"]},{"id":"plate-loaded-lateral-raise","n":"Elevación Lateral en Máquina de Discos","d":"Una elevación lateral sentado en una máquina de discos, donde unas almohadillas apoyan contra los brazos para que los deltoides laterales levanten la carga sin sujetarla con las manos.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"máquina de laterales","home":false,"bw":false,"lv":"principiante","m":["deltoides lateral"],"m2":["deltoides anterior","trapecio"],"ins":["Ajusta la altura del asiento para que el eje de giro de las almohadillas quede alineado con la punta de tus hombros al sentarte.","Carga los soportes de discos por igual en ambos lados y siéntate con la espalda apoyada en el respaldo.","Coloca la cara externa de los brazos contra las almohadillas, con los codos flexionados y los brazos colgando.","Empuja hacia fuera y hacia arriba contra las almohadillas hasta que los brazos queden aproximadamente a la altura de los hombros.","Baja de forma controlada hasta que los brazos vuelvan a los costados y repite el número de repeticiones deseado."],"tips":["Ajusta primero el asiento. Si el eje queda por debajo del hombro, las almohadillas llevan el brazo cruzado por delante del cuerpo en lugar de hacia el lado, y el deltoides lateral deja de ser el músculo que trabaja.","Empuja con el brazo, no con la mano. Las empuñaduras solo sirven para que los brazos no resbalen de las almohadillas: apretarlas mete el bíceps y el antebrazo en una elevación que debería ser puro deltoides.","Detente a la altura del hombro. Subir más entrega la última parte de la repetición al trapecio, y la máquina te dejará hacerlo sin protestar."],"met":5.0,"uni":false,"img":["plate-loaded-lateral-raise-start.webp","plate-loaded-lateral-raise-peak.webp"]},{"id":"plate-loaded-seated-dip-machine","n":"Máquina de Fondos Sentado con Discos","d":"Una versión con discos de la máquina de fondos sentado: te sientas con la espalda contra el respaldo y empujas dos brazos de palanca hacia abajo a tus costados contra los discos cargados en un eje detrás de ti. Trabaja los tríceps siguiendo la misma trayectoria de empuje que la máquina de fondos con selector, con la resistencia determinada por los discos que cargues.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"máquina de fondos","home":false,"bw":false,"lv":"intermedio","m":["tríceps"],"m2":["deltoides anterior","pectoral"],"ins":["Carga los discos por igual en el eje y ajusta el asiento para que las empuñaduras queden aproximadamente a la altura de los hombros cuando estés sentado.","Siéntate erguido con la espalda contra el respaldo y agarra las empuñaduras a tus costados con los codos flexionados.","Mantén los hombros bajos y el pecho alto, y empuja las empuñaduras hacia abajo extendiendo los codos.","Aprieta los tríceps abajo, con los brazos estirados pero sin bloquear los codos con fuerza.","Deja que las empuñaduras suban de nuevo de forma controlada hasta que los codos queden flexionados a unos 90 grados.","Repite el número de repeticiones previsto y devuelve la palanca a su tope de seguridad antes de levantarte."],"tips":["Empieza con poco peso y añade discos poco a poco; si las empuñaduras se quedan cortas de la extensión completa, la carga es demasiado pesada.","Mantén los codos cerca de los costados y la espalda contra el respaldo para que el trabajo se quede en los tríceps.","No dejes que los hombros rueden hacia delante ni se encojan al subir las empuñaduras; detente donde el estiramiento del pecho y los hombros sea cómodo."],"met":6.0,"uni":false,"img":["plate-loaded-seated-dip-machine-start.webp","plate-loaded-seated-dip-machine-peak.webp"]},{"id":"plate-loaded-shrug","n":"Encogimiento de Hombros en Máquina de Discos","d":"Un encogimiento de hombros de pie en una máquina de discos, levantando unas empuñaduras que cuelgan a los costados para que el trapecio trabaje sin una barra por delante o por detrás de las piernas.","cat":"fuerza","g":"espalda","bp":"back","eq":"máquina de encogimientos","home":false,"bw":false,"lv":"principiante","m":["trapecio"],"m2":["antebrazo"],"ins":["Carga los soportes de discos por igual y súbete a la plataforma de la máquina, de espaldas al bastidor.","Toma una empuñadura con cada mano, con los brazos colgando rectos a los costados y los hombros relajados.","Ponte erguido con el pecho alto, la barbilla nivelada y las rodillas ligeramente flexionadas.","Encoge los hombros en línea recta hacia las orejas todo lo que puedas y mantén un instante arriba.","Baja de forma controlada hasta que los hombros queden completamente abajo y repite el número de repeticiones deseado."],"tips":["Encoge en línea recta hacia arriba. Rotar los hombros añade recorrido pero no trabajo extra del trapecio, y lleva la articulación del hombro a describir un círculo bajo carga para nada.","Mantén los brazos rectos y pasivos. Flexionar los codos convierte el movimiento en un remo vertical corto y quita la carga del trapecio.","Las empuñaduras colgando a los costados son la razón de ser de esta máquina: no hay barra que esquivar en los muslos, así que puedes estar erguido y usar todo el recorrido sin acortar la parte alta."],"met":5.0,"uni":false,"img":["plate-loaded-shrug-start.webp","plate-loaded-shrug-peak.webp"]},{"id":"plate-pinch","n":"Agarre de Discos","d":"Un ejercicio clásico para el agarre: pellizca dos discos con la cara lisa hacia afuera y mantenlos durante un tiempo determinado, cargando los flexores del pulgar y los dedos en trabajo isométrico sostenido.","cat":"fuerza","g":"brazos","bp":"lower_arms","eq":"discos","home":false,"bw":false,"lv":"intermedio","m":["antebrazo"],"m2":["trapecio"],"ins":["Coloca dos discos de canto en el suelo, juntos, con las caras lisas hacia afuera.","Baja en sentadilla y pellizca ambos discos juntos entre los dedos y el pulgar de una mano — sin agarraderas, solo pellizca.","Levántate y sostén los discos al costado durante el tiempo deseado, manteniendo el brazo recto.","Devuélvelos al suelo con control.","Repite con la otra mano."],"tips":["Empieza con dos discos de 5 kg / 10 lb y ve aumentando.","La magnesia en las manos marca una gran diferencia; con las manos sudadas el agarre falla rápido."],"met":5.0,"uni":true,"img":["plate-pinch-start.webp","plate-pinch-peak.webp"]},{"id":"plate-pullover","n":"Pullover con Disco","d":"Un pullover sosteniendo un disco, que trabaja dorsales, pecho y serrato.","cat":"fuerza","g":"espalda","bp":"back","eq":"discos","home":false,"bw":false,"lv":"principiante","m":["dorsales","pectoral"],"m2":["serrato","tríceps"],"ins":["Acuéstate plano en un banco sujetando un disco con ambas manos.","Empuja el disco sobre el pecho con los brazos casi rectos.","Baja el disco en arco por detrás de la cabeza hasta sentir el estiramiento.","Tira del disco de regreso sobre el pecho por el mismo arco.","Repite el número de repeticiones indicado."],"tips":["Mantén los codos suaves pero con el mismo ángulo.","Detente al final de tu rango limpio — sin estiramiento excesivo del hombro.","Apoya bien los pies para mantener la estabilidad."],"met":6.0,"uni":false,"img":["plate-pullover-start.webp","plate-pullover-peak.webp"]},{"id":"plow-pose","n":"Postura del Arado","d":"Una inversión en la que las piernas pasan por encima de la cabeza hasta que los dedos de los pies llegan al suelo por detrás, alargando toda la parte posterior del cuerpo.","cat":"estiramiento","g":"espalda","bp":"back","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["lumbares","isquiotibiales"],"m2":["glúteo mayor","trapecio"],"ins":["Túmbate boca arriba con los brazos junto al cuerpo y las palmas hacia abajo.","Eleva ambas piernas por encima de la cabeza y sostén la zona lumbar con las manos.","Baja los dedos de los pies hacia el suelo por detrás de la cabeza, con las piernas tan estiradas como resulte cómodo.","Mantén la posición durante el tiempo indicado, respirando con calma y sin mover la cabeza.","Desciende vértebra a vértebra con las manos sosteniendo la espalda."],"tips":["Nunca gires la cabeza dentro de la postura; el cuello está cargado y debe quedar neutro.","Apoya los dedos de los pies en una silla o unos cojines si el suelo queda lejos.","Evita esta postura por completo si tienes molestias cervicales."],"met":5.0,"uni":false,"img":["plow-pose-main.webp"]},{"id":"plyo-lunge","n":"Zancada Pliométrica","d":"Un salto explosivo en posición de zancada que cambia las piernas en el aire, alternando cada repetición.","cat":"pliometría","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["glúteo mayor","cuádriceps"],"m2":["glúteo medio","isquiotibiales"],"ins":["Comienza en una zancada con un pie adelantado.","Baja a una zancada profunda con la rodilla trasera casi tocando el suelo.","Despega ambos pies y cambia las piernas en el aire.","Aterriza suave en zancada con la pierna opuesta adelante.","Continúa alternando sin pausa."],"tips":["Aterriza suave con las rodillas flexionadas.","Cambia la posición de las piernas por completo — no solo saltes en el sitio.","Mantén el torso erguido — no te inclines adelante."],"met":7.0,"uni":true,"img":["plyo-lunge-start.webp","plyo-lunge-peak.webp"]},{"id":"plyo-push-up","n":"Flexión Pliométrica","d":"Una flexión explosiva en la que las manos despegan del suelo al subir, entrena potencia del tren superior.","cat":"pliometría","g":"pecho","bp":"chest","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["pectoral","tríceps"],"m2":["deltoides anterior"],"ins":["Colócate en posición de flexión estándar, manos a la anchura de los hombros.","Baja con control hasta que el pecho casi toque el suelo.","Empuja explosivamente para que las manos despeguen del suelo.","Aterriza suave con los codos ligeramente flexionados.","Repite sin pausa el número de repeticiones indicado."],"tips":["Mantén el cuerpo en línea recta — sin doblar ni hundir.","Aterriza suave con los codos flexionados.","Apoya las rodillas si no puedes despegar limpiamente."],"met":7.0,"uni":false,"img":["plyo-push-up-start.webp","plyo-push-up-peak.webp"]},{"id":"preacher-curl","n":"Curl en Banco Scott","d":"Una variación del curl que usa un banco Scott para aislar el bíceps.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"barra Z","home":false,"bw":false,"lv":"principiante","m":["bíceps"],"m2":["braquial"],"ins":["Siéntate en el banco Scott con los brazos apoyados en el pad.","Sostén una barra Z con agarre supinado.","Sube la barra hacia los hombros.","Baja con control hasta que los brazos queden casi extendidos.","Repite."],"tips":["Evita los rebotes en la parte baja del recorrido.","Mantén las muñecas neutras sobre la barra EZ.","Sube la barra sin impulso de hombros ni espalda."],"met":5.0,"uni":false,"img":["preacher-curl-start.webp","preacher-curl-peak.webp"]},{"id":"preacher-hammer-curl","n":"Curl Martillo en Banco Scott","d":"Un curl de bíceps en banco Scott con agarre neutro tipo martillo que enfatiza el braquial y los antebrazos.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["braquial","braquiorradial"],"m2":["bíceps"],"ins":["Siéntate en un banco Scott con una mancuerna en cada mano.","Apoya los brazos superiores en la almohadilla con las palmas enfrentadas.","Flexiona las mancuernas hacia arriba manteniendo las muñecas neutras.","Contrae el bíceps en la parte alta del movimiento.","Baja las mancuernas con control.","Repite el número de repeticiones deseado."],"tips":["Mantén los brazos superiores apoyados en la almohadilla.","Evita bloquear completamente los codos en la parte baja.","Controla la bajada en lugar de dejar caer el peso."],"met":5.0,"uni":false,"img":["preacher-hammer-curl-start.webp","preacher-hammer-curl-peak.webp"]},{"id":"pseudo-planche-push-ups","n":"Push-Ups de Pseudo Plancha","d":"Una flexión con las manos giradas hacia atrás y los hombros inclinados muy por delante de las muñecas, imitando la carga de la plancha.","cat":"fuerza","g":"pecho","bp":"chest","eq":"sin equipo","home":true,"bw":true,"lv":"avanzado","m":["deltoides anterior","pectoral"],"m2":["serrato","tríceps"],"ins":["Comienza en posición de push-up con las manos giradas de modo que los dedos apunten hacia atrás.","Inclina los hombros hacia adelante por delante de las muñecas.","Baja el pecho hacia el suelo flexionando los codos.","Mantén el cuerpo en línea recta.","Empuja hacia arriba manteniendo la inclinación hacia adelante.","Repite el número deseado de repeticiones."],"tips":["Cuanto más te inclines hacia delante, más difícil será cada repetición.","Mantén los codos pegados al cuerpo al bajar.","Mantén las escápulas protraídas y el cuerpo rígido."],"met":5.0,"uni":false,"img":["pseudo-planche-push-ups-start.webp","pseudo-planche-push-ups-peak.webp"]},{"id":"pull-up","n":"Dominada","d":"Un ejercicio compuesto con el peso corporal que trabaja el dorsal ancho y el bíceps.","cat":"fuerza","g":"espalda","bp":"back","eq":"barra de dominadas","home":true,"bw":false,"lv":"intermedio","m":["dorsales"],"m2":["bíceps","deltoides posterior","romboides"],"ins":["Cuélgate de una barra con agarre prono, ligeramente más ancho que el ancho de los hombros.","Súbete hasta que la barbilla quede por encima de la barra.","Baja con control hasta el cuelgue completo.","Repite."],"tips":["Evita balancearte o usar impulso.","Activa el dorsal ancho jalando los codos hacia abajo."],"met":6.0,"uni":false,"img":["pull-up-start.webp","pull-up-peak.webp"]},{"id":"puppy-pose","n":"Postura del Cachorro","d":"Una postura de rodillas a medio camino entre la postura del niño y el perro boca abajo: las caderas quedan sobre las rodillas mientras el pecho se acerca al suelo, abriendo hombros y espalda alta.","cat":"estiramiento","g":"hombros","bp":"shoulders","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["dorsales","deltoides posterior"],"m2":["lumbares","trapecio"],"ins":["Colócate a cuatro apoyos con las caderas sobre las rodillas y las manos bajo los hombros.","Camina las manos hacia delante y baja el pecho hacia el suelo manteniendo las caderas altas.","Apoya la frente o la barbilla en la esterilla y deja que las axilas se ablanden hacia abajo.","Mantén la posición durante el tiempo indicado, respirando hacia la espalda alta.","Camina las manos de vuelta y siéntate sobre los talones para salir."],"tips":["Mantén las caderas sobre las rodillas; sentarte atrás convierte esto en la postura del niño.","Presiona las palmas hacia abajo y despega los codos del suelo para que los brazos sigan activos.","Apoya la frente en un bloque si el pecho no baja con comodidad."],"met":5.0,"uni":false,"img":["puppy-pose-main.webp"]},{"id":"push-jerk","n":"Jerk de Empuje","d":"Un levantamiento por encima de la cabeza que usa una flexión y un impulso de piernas para lanzar la barra arriba, recibida en un cuarto de sentadilla.","cat":"olímpico","g":"cuerpo completo","bp":"full_body","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["deltoides anterior","tríceps"],"m2":["glúteo mayor","cuádriceps","trapecio"],"ins":["Sostén la barra en posición de rack frontal sobre los hombros.","Párate con los pies a la anchura de las caderas.","Flexiona ligeramente las rodillas.","Impulsa explosivamente con las piernas y empuja la barra sobre la cabeza.","Baja a una sentadilla de un cuarto debajo de la barra y bloquea los brazos.","Levántate completamente y baja la barra para repetir."],"tips":["Mantén el torso erguido durante la flexión.","Impulsa con las piernas antes de empujar con los brazos.","Bloquea los brazos mientras bajas debajo de la barra."],"met":8.0,"uni":false,"img":["push-jerk-start.webp","push-jerk-peak.webp"]},{"id":"push-press","n":"Press de Empuje","d":"Un press de barra sobre la cabeza que usa el impulso de las piernas para empujar cargas más pesadas.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["deltoides anterior","deltoides lateral"],"m2":["cuádriceps","tríceps"],"ins":["Párate con la barra apoyada en los deltoides frontales.","Flexiona ligeramente las rodillas.","Impulsa con las piernas y empuja la barra sobre la cabeza.","Bloquea completamente.","Baja al inicio.","Repite."],"tips":["Usa el impulso de las piernas solo para iniciar — termina con los hombros.","Mantén el core apretado en todo momento."],"met":6.0,"uni":false,"img":["push-press-start.webp","push-press-peak.webp"]},{"id":"push-up","n":"Push-Up","d":"Un ejercicio fundamental con el peso corporal para el pecho, los hombros y los tríceps.","cat":"fuerza","g":"pecho","bp":"chest","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["pectoral","tríceps"],"m2":["deltoides anterior"],"ins":["Comienza en posición de plancha alta con las manos a la anchura de los hombros.","Baja el cuerpo hasta que el pecho casi toque el suelo.","Empuja hacia arriba hasta la posición inicial.","Mantén el cuerpo en línea recta en todo momento.","Repite."],"tips":["Aprieta el abdomen y los glúteos para evitar que la cadera caiga.","No abras los codos en exceso; mantenlos cerca del torso.","Mantén el cuello neutro mirando al suelo."],"met":5.0,"uni":false,"img":["push-up-start.webp","push-up-peak.webp"]},{"id":"pyramid-pose","n":"Postura de la Pirámide","d":"Una flexión de pie sobre la pierna delantera estirada en un paso corto, que aísla el isquiotibial de esa pierna mientras ambas caderas quedan cuadradas.","cat":"estiramiento","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["isquiotibiales"],"m2":["lumbares","gemelos"],"ins":["Lleva un pie atrás cerca del largo de una pierna y gíralo ligeramente hacia fuera.","Cuadra ambas caderas hacia el frente de la esterilla y mantén las dos piernas estiradas.","Bascula desde las caderas y flexiona sobre la pierna delantera, llevando las manos al suelo, a bloques o a la espinilla.","Mantén la flexión durante el tiempo indicado, con la columna larga en lugar de redondeada.","Empuja con los pies para subir y repite del otro lado."],"tips":["Acorta el paso hasta que ambas caderas puedan mirar al frente; la longitud vale menos que las caderas cuadradas.","Usa bloques bajo las manos para que el pecho siga acercándose a la espinilla.","Deja una micro flexión en la rodilla delantera si el isquiotibial se agarrota."],"met":5.0,"uni":true,"img":["pyramid-pose-main.webp"]},{"id":"rack-pull","n":"Rack Pull","d":"Una variación de peso muerto en rango parcial desde pines a la altura de las rodillas, que enfatiza la parte superior de la espalda, el trapecio y la fuerza de bloqueo con cargas superiores al peso muerto completo.","cat":"fuerza","g":"espalda","bp":"back","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["lumbares","glúteo mayor","isquiotibiales","trapecio"],"m2":["antebrazo","dorsales"],"ins":["Coloca los pines de seguridad en un rack a la altura de las rodillas y apoya una barra cargada sobre ellos.","Párate con los pies al ancho de caderas y agarra la barra justo fuera de las piernas.","Activa el core, retrae las escápulas y empuja con las piernas para levantar la barra.","Extiende completamente caderas y rodillas en la parte superior.","Baja la barra a los pines con control y reposiciónate antes de la siguiente repetición."],"tips":["Usa una bisagra de cadera — mantén la barra cerca del cuerpo en todo momento.","Los rack pulls permiten cargas superiores a tu máximo de peso muerto para sobrecargar el bloqueo.","Enfócate en la tensión de la parte superior de la espalda para evitar el redondeo con cargas pesadas."],"met":6.0,"uni":false,"img":["rack-pull-start.webp","rack-pull-peak.webp"]},{"id":"rear-delt-fly","n":"Apertura de Deltoides Posterior","d":"Un movimiento de aislamiento que trabaja los deltoides posteriores y la parte superior de la espalda.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"mancuernas","home":true,"bw":false,"lv":"principiante","m":["deltoides posterior","romboides"],"m2":["trapecio"],"ins":["Sostén las mancuernas e inclínate hacia adelante desde las caderas.","Con una ligera flexión en los codos, eleva las mancuernas hacia los lados.","Aprieta las escápulas en la parte superior.","Baja con control.","Repite."],"tips":["Elige un peso ligero para no usar impulso.","Mantén la espalda recta mientras estás inclinado hacia delante.","Lidera el movimiento con los codos, no con las manos."],"met":5.0,"uni":false,"img":["rear-delt-fly-start.webp","rear-delt-fly-peak.webp"]},{"id":"renegade-row","n":"Remo Renegado","d":"Un ejercicio de remo desde la plancha en el que se rema alternativamente con una mancuerna en cada mano hacia la cadera mientras la otra mano permanece apoyada. Trabaja la espalda y los brazos mientras el tronco resiste la rotación.","cat":"fuerza","g":"espalda","bp":"back","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["dorsales","romboides"],"m2":["bíceps","oblicuos","abdominales"],"ins":["Colócate en plancha alta con una mano sobre cada una de dos mancuernas, a la anchura de los hombros, y los pies bien separados para mayor estabilidad.","Aprieta el tronco para que el cuerpo forme una línea recta de la cabeza a los talones.","Rema una mancuerna hacia la cadera llevando el codo hacia atrás a lo largo de las costillas.","Mantén la cadera cuadrada respecto al suelo y no dejes que el cuerpo gire.","Baja la mancuerna al suelo de forma controlada.","Repite del otro lado y sigue alternando."],"tips":["Usa mancuernas hexagonales para que no rueden, y empieza con poco peso.","Separa más los pies para mantener la cadera nivelada con mayor facilidad.","No encojas los hombros ni gires el cuerpo; haz una breve pausa arriba en cada remo para demostrar control."],"met":6.0,"uni":false,"img":["renegade-row-start.webp","renegade-row-peak.webp"]},{"id":"reverse-crunches","n":"Crunches Inversos","d":"Un ejercicio de core en el suelo que enrolla la cadera hacia el pecho para trabajar la parte baja del abdomen.","cat":"fuerza","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["abdominales"],"m2":["flexores de cadera","oblicuos","transverso abdominal"],"ins":["Túmbate boca arriba con los brazos a los lados.","Eleva las piernas con las rodillas flexionadas a 90 grados.","Despega las caderas del suelo contrayendo el abdomen inferior.","Lleva las rodillas hacia el pecho.","Baja las caderas con control.","Repite el número deseado de repeticiones."],"tips":["Despega la cadera con el abdomen, no con impulso de las piernas.","Exhala al subir para activar mejor el abdomen.","Presiona los brazos contra el suelo para mayor estabilidad."],"met":3.5,"uni":false,"img":["reverse-crunches-start.webp","reverse-crunches-peak.webp"]},{"id":"reverse-curl","n":"Curl Inverso","d":"Un curl con barra en agarre prono que trabaja el braquial y los extensores del antebrazo.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"barra","home":false,"bw":false,"lv":"principiante","m":["braquial","antebrazo"],"m2":["bíceps"],"ins":["Párate y sostén la barra con agarre prono.","Sube la barra hacia los hombros.","Baja con control.","Repite."],"tips":["Mantén las muñecas rectas.","Realiza el movimiento en un rango completo de movimiento."],"met":5.0,"uni":false,"img":["reverse-curl-start.webp","reverse-curl-peak.webp"]},{"id":"reverse-grip-bent-over-row","n":"Remo Inclinado con Agarre Invertido","d":"Un remo con barra y agarre supino que trabaja dorsales y romboides, con participación de los bíceps.","cat":"fuerza","g":"espalda","bp":"back","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["dorsales","romboides"],"m2":["bíceps","lumbares","trapecio"],"ins":["Párate con los pies a la anchura de los hombros y agarra la barra con agarre supinado.","Inclínate hacia adelante desde las caderas con una ligera flexión de rodillas.","Deja que la barra cuelgue con los brazos extendidos.","Jala la barra hacia el abdomen inferior llevando los codos hacia atrás.","Aprieta la espalda en la parte superior.","Baja la barra con control.","Repite el número deseado de repeticiones."],"tips":["Mantén la espalda neutra y el core firme durante todo el recorrido.","No uses impulso con el torso; el cuerpo queda inclinado y estable.","Mantén las muñecas rectas para proteger los codos con este agarre."],"met":6.0,"uni":false,"img":["reverse-grip-bent-over-row-start.webp","reverse-grip-bent-over-row-peak.webp"]},{"id":"reverse-grip-lat-pulldown","n":"Jalón al Pecho Agarre Supino","d":"Una variante del jalón al pecho con agarre supino que aumenta la participación del bíceps.","cat":"fuerza","g":"espalda","bp":"back","eq":"polea","home":false,"bw":false,"lv":"intermedio","m":["bíceps","dorsales"],"m2":["deltoides posterior","romboides"],"ins":["Coloca una barra recta en una máquina de jalón al pecho.","Sujeta la barra con agarre supino, al ancho de los hombros.","Siéntate y asegura tus muslos bajo la almohadilla.","Tira de la barra hacia la parte superior del pecho.","Contrae el dorsal y el bíceps en la parte baja.","Vuelve la barra a la posición inicial con control.","Repite el número de repeticiones deseado."],"tips":["Mantén el pecho erguido y evita inclinarte demasiado hacia atrás.","Tira con los codos, no solo con las manos.","Contrae el dorsal en la parte baja del movimiento."],"met":6.0,"uni":false,"img":["reverse-grip-lat-pulldown-start.webp","reverse-grip-lat-pulldown-peak.webp"]},{"id":"reverse-lunge","n":"Zancada Inversa","d":"Una variación de la zancada que da un paso hacia atrás para mayor estabilidad de rodilla.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["glúteo mayor","cuádriceps"],"m2":["isquiotibiales"],"ins":["Párate sosteniendo mancuernas a los costados.","Da un paso hacia atrás con una pierna y baja la rodilla hacia el suelo.","Baja hasta que el muslo delantero quede paralelo al suelo.","Empuja con el talón delantero para volver a la posición de pie.","Repite en ambos lados."],"tips":["Da el paso atrás lo bastante largo para que la rodilla delantera no pase del pie.","Mantén el torso erguido y las mancuernas pegadas al cuerpo.","Completa el mismo número de repeticiones con cada pierna."],"met":6.0,"uni":true,"img":["reverse-lunge-start.webp","reverse-lunge-peak.webp"]},{"id":"reverse-nordic-curl","n":"Nordic Curl Inverso","d":"Un ejercicio de cuádriceps con el propio peso corporal, arrodillado, inclinando el torso hacia atrás con control mientras se mantiene la cadera extendida.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["cuádriceps"],"m2":["flexores de cadera","abdominales"],"ins":["Arrodíllate sobre una almohadilla con las rodillas a la anchura de las caderas, las tibias y el empeine en el suelo y el torso erguido.","Mantén la cadera extendida y el core activado.","Inclina el torso lentamente hacia atrás manteniendo el cuerpo en línea recta.","Baja tanto como puedas controlar con el cuádriceps.","Vuelve a subir a la posición inicial.","Repite el número de repeticiones deseado."],"tips":["Mantén la cadera extendida en todo momento, sin que se doble.","Baja solo hasta donde puedas controlar el movimiento.","Usa una almohadilla bajo las rodillas para mayor comodidad."],"met":3.5,"uni":false,"img":["reverse-nordic-curl-start.webp","reverse-nordic-curl-peak.webp"]},{"id":"reverse-plank","n":"Plancha Inversa","d":"Una plancha invertida isométrica con el pecho hacia arriba, que fortalece los glúteos y los erectores de la columna.","cat":"fuerza","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["lumbares","glúteo mayor"],"m2":["isquiotibiales","deltoides posterior","tríceps"],"ins":["Siéntate en el suelo con las piernas extendidas al frente.","Coloca las manos detrás de ti con los dedos apuntando hacia los pies.","Eleva las caderas del suelo para formar una línea recta de la cabeza a los talones.","Aprieta los glúteos y contrae el core.","Mantén la posición durante el tiempo deseado.","Baja las caderas con control para salir."],"tips":["Mantén la cadera alta; si baja, descansa y repite.","No dejes caer la cabeza hacia atrás; alarga el cuello.","Reparte el peso entre talones y manos, con los hombros lejos de las orejas."],"met":5.0,"uni":false,"img":["reverse-plank-main.webp"]},{"id":"reverse-plank-dips","n":"Fondos en Plancha Invertida","d":"Fondos de tríceps desde una plancha invertida con las piernas estiradas: las piernas permanecen largas y las caderas altas mientras los codos se flexionan y estiran.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["tríceps"],"m2":["lumbares","glúteo mayor","deltoides posterior"],"ins":["Siéntate con las piernas estiradas y las manos en el suelo detrás de las caderas, con los dedos hacia delante.","Empuja con manos y talones y eleva las caderas a una plancha invertida con las piernas estiradas.","Flexiona los codos hacia atrás y baja un poco las caderas hacia el suelo.","Empuja de nuevo hasta bloquear los brazos, manteniendo las caderas altas.","Repite las veces indicadas."],"tips":["Mantén las caderas elevadas abajo; sentarte entre repeticiones quita la carga.","Lleva los codos rectos hacia atrás en lugar de abrirlos hacia fuera.","Flexiona las rodillas si la versión con piernas estiradas exige demasiado a los isquiotibiales."],"met":5.0,"uni":false,"img":["reverse-plank-dips-start.webp","reverse-plank-dips-peak.webp"]},{"id":"reverse-tabletop-hip-pulses","n":"Pulsos de Cadera en Mesa Invertida","d":"Pulsos de glúteo desde la mesa invertida: los brazos permanecen estirados y solo las caderas bajan y suben, de modo que el trabajo se queda en el glúteo y no en el tríceps.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["glúteo mayor"],"m2":["lumbares","isquiotibiales"],"ins":["Siéntate con las rodillas flexionadas, los pies apoyados y las manos en el suelo detrás de ti.","Empuja con manos y pies y eleva las caderas hasta que el tronco quede a la altura de las rodillas.","Con los codos estirados, baja las caderas unos centímetros.","Aprieta los glúteos para volver a subirlas al nivel.","Pulsa las veces indicadas y baja."],"tips":["Mantén los brazos bloqueados: flexionar los codos convierte esto en un fondo.","Impulsa desde los talones y los glúteos, no desde la zona lumbar.","Mantén el pecho abierto y los hombros lejos de las orejas."],"met":5.0,"uni":false,"img":["reverse-tabletop-hip-pulses-start.webp","reverse-tabletop-hip-pulses-peak.webp"]},{"id":"reverse-tabletop-hold","n":"Mesa Invertida Isométrica","d":"Una mesa invertida estática: rodillas flexionadas, manos bajo los hombros por detrás del cuerpo, caderas elevadas a la altura de las rodillas y sostenidas, de modo que los glúteos y toda la parte posterior del tronco trabajan de forma isométrica.","cat":"fuerza","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["lumbares","glúteo mayor"],"m2":["isquiotibiales","deltoides posterior","tríceps"],"ins":["Siéntate con las rodillas flexionadas, los pies apoyados y las manos en el suelo detrás de ti, con los dedos hacia los talones.","Empuja con manos y pies y eleva las caderas hasta que el tronco quede a la altura de las rodillas.","Abre el pecho, aleja los hombros de las orejas y mira al frente.","Mantén la posición durante el tiempo indicado con las caderas altas.","Baja las caderas de forma controlada para terminar."],"tips":["Empuja el suelo en lugar de colgarte de los hombros.","Mantén las rodillas sobre los tobillos y apuntando al frente.","Deja que la cabeza siga la línea de la columna en lugar de dejarla caer hacia atrás."],"met":5.0,"uni":false,"img":["reverse-tabletop-hold-main.webp"]},{"id":"revolved-chair-pose","n":"Postura de la Silla Girada","d":"La postura de la silla con una torsión cerrada: las caderas se mantienen bajas y niveladas mientras el pecho rota y un codo se engancha por fuera del muslo contrario.","cat":"fuerza","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["oblicuos","cuádriceps"],"m2":["lumbares","glúteo mayor"],"ins":["Colócate en la postura de la silla con las rodillas flexionadas, las caderas atrás y las palmas juntas frente al pecho.","Mantén las rodillas a la misma altura para que las caderas no se abran hacia la torsión.","Gira el pecho hacia un lado y engancha el codo contrario por fuera de ese muslo.","Presiona las palmas entre sí y mantén durante el tiempo indicado, alargando la columna en cada inhalación.","Vuelve al centro y repite del otro lado."],"tips":["Alinea las rodillas antes de girar; una rodilla que se adelanta finge la mayor parte de la rotación.","Gira desde la zona media de la espalda en lugar de hacer palanca con el brazo contra la pierna.","Mantén el peso en los talones para que la postura siga siendo una sentadilla y no una inclinación."],"met":5.0,"uni":false,"img":["revolved-chair-pose-main.webp"]},{"id":"revolved-crescent-lunge","n":"Zancada Alta Girada","d":"Una zancada alta con torsión cerrada: el talón trasero sigue elevado, las caderas miran al frente y el pecho rota sobre el muslo delantero.","cat":"fuerza","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["oblicuos","cuádriceps"],"m2":["lumbares","flexores de cadera"],"ins":["Colócate en zancada alta con la rodilla delantera sobre el tobillo y el talón trasero elevado.","Junta las palmas frente al pecho y cuadra ambas caderas hacia el frente de la esterilla.","Gira el pecho hacia la pierna delantera y engancha el codo contrario por fuera del muslo.","Mantén la torsión durante el tiempo indicado, empujando el talón trasero hacia la pared de detrás.","Deshaz la torsión y repite del otro lado."],"tips":["Mantén la pierna trasera estirada y larga; es lo que impide que la torsión se hunda en las caderas.","Baja la rodilla trasera al suelo para una versión más sencilla con la misma rotación.","Alarga primero la columna y gira después: torcer una espalda redondeada no lleva a ningún sitio."],"met":5.0,"uni":true,"img":["revolved-crescent-lunge-main.webp"]},{"id":"ring-dead-hang","n":"Cuelgue Estático en Anillas","d":"Un cuelgue pasivo en anillas de gimnasia. El agarre de rotación libre recluta más estabilizadores en las manos, los antebrazos y la cintura escapular que una barra fija.","cat":"fuerza","g":"espalda","bp":"back","eq":"anillas","home":false,"bw":false,"lv":"intermedio","m":["antebrazo"],"m2":["dorsales","abdominales","trapecio"],"ins":["Agarra un par de anillas de gimnasia con agarre neutro, palmas enfrentadas entre sí.","Cuélgate con los brazos completamente extendidos y los pies fuera del suelo.","Deja que las anillas giren naturalmente; no luches contra el agarre.","Mantén los hombros activos (sin encogerlos hacia las orejas) y el core ligeramente apretado.","Mantén la posición durante el tiempo deseado."],"tips":["Empieza con series cortas y aumenta el tiempo de forma progresiva.","Agarra fuerte con toda la mano, no solo con los dedos.","Baja apoyando los pies con control, no te sueltes de golpe."],"met":4.5,"uni":false,"img":["ring-dead-hang-main.webp"]},{"id":"ring-dips","n":"Fondos en Anillas","d":"Un fondo con el peso corporal desafiante realizado en anillas de gimnasia, que exige mayor estabilización que los fondos en barra.","cat":"fuerza","g":"pecho","bp":"chest","eq":"anillas","home":false,"bw":false,"lv":"avanzado","m":["pectoral","tríceps"],"m2":["deltoides anterior"],"ins":["Apóyate en las anillas con los brazos bloqueados.","Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo.","Empuja hacia arriba hasta la posición inicial.","Repite."],"tips":["Mantén las anillas cerca del cuerpo.","Gira las anillas hacia afuera en la parte superior para mayor activación del pecho."],"met":6.0,"uni":false,"img":["ring-dips-start.webp","ring-dips-peak.webp"]},{"id":"ring-face-pull","n":"Face Pull en Anillas","d":"Un face pull en anillas de gimnasia para resistencia ajustable y mejora de la salud del hombro.","cat":"fuerza","g":"espalda","bp":"back","eq":"anillas","home":false,"bw":false,"lv":"intermedio","m":["deltoides posterior","romboides"],"m2":["trapecio"],"ins":["Agarra las anillas e inclínate hacia atrás de modo que el cuerpo quede en ángulo.","Jala las anillas hacia la cara, abriendo los codos hacia los lados.","Mantén brevemente y luego regresa.","Repite."],"tips":["Ajusta el ángulo del cuerpo para controlar la dificultad.","Rota los brazos externamente en la parte superior."],"met":6.0,"uni":false,"img":["ring-face-pull-start.webp","ring-face-pull-peak.webp"]},{"id":"ring-l-sit","n":"L-Sit en Anillas","d":"Un L-sit estático realizado en posición de apoyo sobre anillas de gimnasia: los brazos están bloqueados, el cuerpo se mantiene separado del suelo y las piernas se estiran rectas al frente. La inestabilidad de las anillas lo convierte en una exigente prueba de fuerza de core, hombros y brazos.","cat":"fuerza","g":"core","bp":"core","eq":"anillas","home":false,"bw":false,"lv":"avanzado","m":["flexores de cadera","abdominales"],"m2":["deltoides anterior","dorsales","cuádriceps","tríceps"],"ins":["Coloca las anillas aproximadamente a la altura de la cadera y agárralas con los brazos estirados junto al cuerpo.","Empuja las anillas hacia abajo y eleva el cuerpo hasta la posición de apoyo, con los hombros hacia abajo y alejados de las orejas.","Gira ligeramente las anillas hacia fuera, contrae el abdomen y eleva las piernas rectas hasta que queden paralelas al suelo.","Mantén la posición, con las anillas estables y las rodillas bloqueadas.","Baja primero las piernas y después el cuerpo, de forma controlada."],"tips":["Mantén los brazos bloqueados y los hombros hacia abajo; no te hundas entre las anillas.","Progresa desde mantenimientos con las rodillas encogidas y desde parallettes o una estación de fondos antes de pasar a las anillas.","Estira las puntas de los pies y aprieta las piernas entre sí."],"met":6.0,"uni":false,"img":["ring-l-sit-main.webp"]},{"id":"ring-muscle-up","n":"Muscle-Up en Anillas","d":"Un movimiento avanzado de calistenia que combina dominada y fondo en anillas de gimnasia.","cat":"fuerza","g":"espalda","bp":"back","eq":"anillas","home":false,"bw":false,"lv":"avanzado","m":["dorsales","pectoral","tríceps"],"m2":["deltoides anterior","bíceps","romboides"],"ins":["Cuelga de las anillas con agarre falso, palmas enfrentadas.","Tira explosivamente, llevando el pecho hacia las anillas.","Pasa los codos por encima de las anillas mientras sube el pecho.","Empuja arriba hasta extender los brazos.","Baja con control pasando por la transición hasta volver al colgado."],"tips":["El agarre falso es clave para la transición.","Empuja los codos hacia abajo con fuerza durante la transición.","Construye la fuerza primero con negativas y asistido con banda."],"met":6.0,"uni":false,"img":["ring-muscle-up-start.webp","ring-muscle-up-peak.webp"]},{"id":"ring-plank","n":"Plancha en Anillas","d":"Una plancha con las manos en anillas de gimnasia y los pies en el suelo. Las anillas se mueven libremente, por lo que los hombros y el tronco tienen que trabajar más para mantener el cuerpo en línea recta.","cat":"fuerza","g":"core","bp":"core","eq":"anillas","home":false,"bw":false,"lv":"avanzado","m":["abdominales","transverso abdominal"],"m2":["deltoides anterior","oblicuos","pectoral","serrato"],"ins":["Coloca las anillas aproximadamente a la altura de las rodillas y agárralas con los brazos estirados bajo los hombros.","Retrocede con los pies hasta la plancha, con el cuerpo en línea recta de la cabeza a los talones.","Contrae el abdomen y los glúteos y empuja las anillas hacia abajo y ligeramente hacia fuera para mantenerlas estables.","Mantén la posición sin dejar que la cadera se hunda ni que las anillas se separen.","Acerca los pies y ponte de pie para terminar."],"tips":["Mantén las anillas cerca de los costados del pecho; si se balancean, separa más los pies.","Empuja el suelo a través de las anillas para que los omóplatos permanezcan abiertos.","Sube las anillas para que el ejercicio sea más fácil y bájalas para hacerlo más difícil."],"met":6.0,"uni":false,"img":["ring-plank-main.webp"]},{"id":"ring-push-up","n":"Flexión en Anillas","d":"Una flexión sobre anillas de gimnasia, que exige más a los estabilizadores del pecho, hombros y core.","cat":"fuerza","g":"pecho","bp":"chest","eq":"anillas","home":false,"bw":false,"lv":"intermedio","m":["pectoral","tríceps"],"m2":["deltoides anterior","serrato"],"ins":["Coloca las anillas justo por encima del suelo.","Sujeta las anillas y adopta posición de plank con los brazos rectos.","Baja el pecho hacia las anillas, codos pegados al cuerpo.","Empuja arriba hasta extender los brazos.","Repite el número de repeticiones indicado."],"tips":["Gira las anillas hacia afuera arriba para activar más el pecho.","Activa el core — las anillas amplifican cualquier oscilación.","Apoya las rodillas para escalar la dificultad."],"met":6.0,"uni":false,"img":["ring-push-up-start.webp","ring-push-up-peak.webp"]},{"id":"ring-row","n":"Remo en Anillas","d":"Un remo con peso corporal en anillas de gimnasia, realizado en ángulo para trabajar espalda y bíceps.","cat":"fuerza","g":"espalda","bp":"back","eq":"anillas","home":false,"bw":false,"lv":"principiante","m":["dorsales","romboides"],"m2":["bíceps","deltoides posterior","trapecio"],"ins":["Coloca las anillas a la altura de la cadera o el pecho.","Sujeta las anillas con las palmas enfrentadas, inclínate atrás con los brazos rectos.","Activa el core y tira del pecho hacia las anillas.","Junta los omóplatos arriba.","Baja con control hasta extender los brazos."],"tips":["Cuanto más bajo el ángulo del cuerpo, más difícil el remo.","Mantén el cuerpo recto — no dejes caer las caderas.","Tira con los codos atrás, no abiertos, para más implicación dorsal."],"met":6.0,"uni":false,"img":["ring-row-start.webp","ring-row-peak.webp"]},{"id":"rings-inverted-row","n":"Remo Invertido en Anillas","d":"Un remo con peso corporal en anillas colocadas bajas, tirando del pecho hacia las anillas desde una línea corporal recta e inclinada; más difícil que el remo de pie en anillas.","cat":"fuerza","g":"espalda","bp":"back","eq":"anillas","home":false,"bw":false,"lv":"intermedio","m":["dorsales","romboides","trapecio"],"m2":["bíceps","antebrazo","deltoides posterior","abdominales"],"ins":["Coloca las anillas justo por encima de la cadera.","Acuéstate bajo las anillas y agárralas con las palmas enfrentadas.","Camina con los pies adelante hasta que el cuerpo forme una línea recta.","Tira del pecho hacia las anillas, juntando los omóplatos.","Baja con control hasta extender los brazos."],"tips":["Mantén el cuerpo en línea recta — de los talones a la cabeza.","Activa glúteos y core para no hundirte.","Eleva los pies en un cajón para una versión más difícil."],"met":6.0,"uni":false,"img":["rings-inverted-row-start.webp","rings-inverted-row-peak.webp"]},{"id":"romanian-deadlift","n":"Peso Muerto Rumano","d":"Un movimiento de bisagra de cadera que enfatiza los isquiotibiales y los glúteos.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["glúteo mayor","isquiotibiales"],"m2":["lumbares"],"ins":["Párate sosteniendo la barra a la altura de las caderas con agarre prono.","Bisagra en las caderas empujándolas hacia atrás mientras mantienes las piernas casi rectas.","Baja la barra a lo largo de las piernas hasta sentir el estiramiento de los isquiotibiales.","Empuja las caderas hacia adelante para volver a la posición de pie.","Repite."],"tips":["No redondees la espalda baja; mantén la columna neutra.","Baja solo hasta donde llegues sin perder la postura.","Aprieta los dorsales para mantener la barra cerca del cuerpo."],"met":6.0,"uni":false,"img":["romanian-deadlift-start.webp","romanian-deadlift-peak.webp"]},{"id":"rope-climb","n":"Trepa de Cuerda","d":"Un ejercicio de jalón para todo el cuerpo que trepa una cuerda vertical mano a mano, cargando el dorsal ancho, el bíceps, el agarre y el core de forma isométrica.","cat":"fuerza","g":"espalda","bp":"back","eq":"cuerda para trepar","home":false,"bw":false,"lv":"avanzado","m":["dorsales"],"m2":["bíceps","antebrazo","abdominales"],"ins":["Agarra la cuerda lo más arriba posible con ambas manos.","Envuelve la cuerda alrededor de un pie (gancho en S o en J) o apriétala entre ambos pies.","Tira con los brazos y sube las rodillas, luego bloquea la cuerda con los pies y ponte de pie sobre ese bloqueo.","Alcanza más arriba con una mano y luego con la otra, suelta los pies y vuelve a bloquear la cuerda más arriba.","Repite hasta llegar a la cima de la cuerda.","Baja mano bajo mano con los pies controlando la velocidad — nunca te deslices."],"tips":["Aprende el bloqueo de pies antes de intentar trepar más alto; duplica tu capacidad de trabajo.","Nunca te dejes caer desde la cima; el descenso controlado es parte del ejercicio."],"met":6.0,"uni":false,"img":["rope-climb-main.webp"]},{"id":"rowing-machine","n":"Máquina de Remo","d":"Un ejercicio cardiovascular de cuerpo completo en la máquina de remo: cada palada empuja con las piernas, lleva el torso hacia atrás y tira de la manija hasta las costillas, trabajando piernas, espalda y brazos en un ciclo continuo.","cat":"cardio","g":"cuerpo completo","bp":"full_body","eq":"remoergómetro","home":false,"bw":false,"lv":"principiante","m":["dorsales","cuádriceps"],"m2":["bíceps","lumbares","glúteo mayor","isquiotibiales","romboides","trapecio"],"ins":["Siéntate en la máquina de remo, sujeta los pies con las correas de las plataformas y agarra la manija en pronación.","Deslízate hacia delante hasta la posición de ataque: tibias verticales, torso ligeramente por delante de la cadera y brazos estirados hacia el volante.","Empuja primero con las piernas y desplaza el asiento hacia atrás hasta dejar las rodillas casi estiradas.","Lleva el torso hacia atrás pasando de la vertical y tira entonces de la manija hasta las costillas bajas, con los codos pasando junto a los costados.","Invierte el orden en la recuperación — primero los brazos hacia delante, después el torso y por último flexionar las rodillas — y vuelve a deslizarte hasta la posición de ataque para la siguiente palada.","Continúa durante el tiempo, la distancia o el número de paladas que quieras."],"tips":["Respeta el orden: piernas, torso y brazos en el tirón, y brazos, torso y piernas en la recuperación. Flexionar los brazos antes de tiempo desaprovecha la parte más fuerte de la palada.","Rema con la espalda plana y el core activado: redondear la zona lumbar en la posición de ataque es lo que convierte el remo en dolor de espalda en lugar de trabajo cardiovascular.","Lleva la manija en línea recta y horizontal hasta las costillas bajas, y haz la recuperación unas dos veces más lenta que el tirón en lugar de volver de golpe."],"met":8.0,"uni":false,"img":["rowing-machine-start.webp","rowing-machine-peak.webp"]},{"id":"running","n":"Correr","d":"Carrera al aire libre, con una fase de vuelo en cada zancada en la que ningún pie toca el suelo — el impacto y el esfuerzo que la separan de caminar.","cat":"cardio","g":"cuerpo completo","bp":"full_body","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["gemelos","cuádriceps"],"m2":["glúteo mayor","isquiotibiales","flexores de cadera","sóleo"],"ins":["Empieza con un trote suave y sube hasta tu ritmo durante los primeros minutos, en lugar de salir directamente a la velocidad objetivo.","Apoya el pie bajo la cadera, no por delante del cuerpo, y mantén el contacto con el suelo corto y silencioso.","Corre erguido desde la cadera, con una ligera inclinación desde los tobillos y sin doblarte por la cintura.","Flexiona los codos unos noventa grados y lleva los brazos adelante y atrás, sin cruzarlos sobre el pecho.","Respira con ritmo y mantén sueltos los hombros, la mandíbula y las manos.","Sostén el ritmo el tiempo o la distancia deseados, luego trota y camina unos minutos para terminar."],"tips":["Aumenta el volumen semanal poco a poco. Casi toda lesión al correr viene de sumar kilómetros más rápido de lo que se adaptan tendones y huesos, no de una sola tirada dura.","La mayor parte de tus carreras debe ser lo bastante suave como para poder hablar. Correr cada sesión a un ritmo medio-fuerte es la vía más rápida al estancamiento.","Si notas que pisas con estruendo, acorta la zancada y deja subir la cadencia — buscar un paso más largo pone el freno en cada apoyo."],"met":8.0,"uni":false,"img":["running-main.webp"]},{"id":"russian-twist","n":"Giro Ruso","d":"Un ejercicio de core rotacional que trabaja los oblicuos.","cat":"fuerza","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["oblicuos","abdominales"],"m2":["flexores de cadera"],"ins":["Siéntate en el suelo con las rodillas flexionadas e inclínate ligeramente hacia atrás.","Junta las manos o sostén un peso a la altura del pecho.","Rota el torso hacia un lado, luego hacia el otro.","Mantén el core apretado en todo momento.","Repite."],"tips":["Gira desde el torso, no solo con los brazos.","Mantén la espalda recta aunque estés ligeramente reclinado.","Hazlo lento y controlado; la velocidad resta trabajo a los oblicuos."],"met":3.5,"uni":false,"img":["russian-twist-start.webp","russian-twist-peak.webp"]},{"id":"savasana","n":"Postura del Cadáver","d":"El descanso final de una práctica: tumbado boca arriba con el cuerpo completamente pasivo, dejando que los efectos de la sesión se asienten.","cat":"estiramiento","g":"cuerpo completo","bp":"full_body","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["lumbares"],"m2":[],"ins":["Túmbate boca arriba con las piernas cómodamente separadas y los pies cayendo hacia fuera.","Deja los brazos algo separados del cuerpo con las palmas hacia arriba.","Permite que todo el cuerpo se ablande contra el suelo, incluidos la mandíbula, los ojos y las manos.","Permanece durante el tiempo indicado, respirando con naturalidad y sin controlar la respiración.","Flexiona las rodillas y rueda hacia un lado antes de incorporarte despacio."],"tips":["Coloca un bolster bajo las rodillas si la zona lumbar no termina de asentarse.","Cúbrete con una manta; el cuerpo se enfría rápido en cuanto deja de moverse.","Esta postura no debe costar ningún esfuerzo: resiste el impulso de reajustarte constantemente."],"met":1.3,"uni":false,"img":["savasana-main.webp"]},{"id":"scapular-pull-ups","n":"Dominadas Escapulares","d":"Un ejercicio en barra de dominadas con brazos extendidos, que entrena la depresión y retracción de las escápulas.","cat":"fuerza","g":"espalda","bp":"back","eq":"barra de dominadas","home":true,"bw":false,"lv":"intermedio","m":["dorsales","trapecio"],"m2":["antebrazo","romboides"],"ins":["Cuélgate de una barra de dominadas con los brazos completamente extendidos.","Mantén los brazos rectos durante todo el movimiento.","Deprime y retrae las escápulas para elevar el pecho.","Haz una breve pausa en la parte superior del movimiento.","Regresa a la posición de cuelgue completo.","Repite el número deseado de repeticiones."],"tips":["Piensa en alejar los hombros de las orejas al subir el pecho.","No intentes convertirlo en una dominada; el recorrido es corto.","Controla la vuelta a la posición colgada sin desplomarte."],"met":6.0,"uni":false,"img":["scapular-pull-ups-start.webp","scapular-pull-ups-peak.webp"]},{"id":"scissor-kicks","n":"Tijeras","d":"Un ejercicio de core realizado boca arriba, cruzando alternadamente las piernas rectas para trabajar el abdomen bajo y los flexores de cadera.","cat":"fuerza","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["flexores de cadera","abdominales"],"m2":["oblicuos","transverso abdominal"],"ins":["Recuéstate boca arriba con las manos bajo los glúteos.","Eleva ambas piernas unos centímetros del suelo.","Cruza alternadamente una pierna sobre la otra en un movimiento de tijera.","Mantén la zona lumbar presionada contra el suelo.","Mantén un ritmo constante durante todo el ejercicio.","Repite el número de repeticiones deseado."],"tips":["Presiona la zona lumbar contra el suelo en todo momento.","Mantén las piernas rectas y cerca del suelo.","Muévete con control, no con velocidad."],"met":5.0,"uni":false,"img":["scissor-kicks-start.webp","scissor-kicks-peak.webp"]},{"id":"seated-barbell-overhead-press","n":"Press de Barra sobre la Cabeza Sentado","d":"Un press de barra sobre la cabeza estricto en posición sentada, que elimina el impulso de caderas y aísla los deltoides y los tríceps.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["deltoides anterior"],"m2":["deltoides lateral","trapecio","tríceps"],"ins":["Ajusta un banco vertical dentro del rack con los pines a la altura aproximada de los hombros cuando estés sentado.","Siéntate con la espalda plana contra el pad y desrackea la barra en la parte frontal de los hombros.","Empuja la barra sobre la cabeza hasta extender completamente los brazos, pasando la cabeza por delante en la parte superior.","Baja la barra de vuelta a las clavículas con control.","Repite el número de repeticiones recomendado."],"tips":["Mantén las costillas abajo y los glúteos apretados; no te inclines hacia atrás como en un press de banca.","Empuja la barra recto hacia arriba, no hacia adelante."],"met":6.0,"uni":false,"img":["seated-barbell-overhead-press-start.webp","seated-barbell-overhead-press-peak.webp"]},{"id":"seated-cable-row","n":"Remo Sentado en Polea","d":"Un ejercicio de espalda en una máquina de remo con polea, tirando de una manija hacia el torso estando sentado.","cat":"fuerza","g":"espalda","bp":"back","eq":"polea","home":false,"bw":false,"lv":"intermedio","m":["dorsales","romboides"],"m2":["bíceps","lumbares","deltoides posterior"],"ins":["Siéntate en la estación de remo y coloca los pies en los apoyos.","Sujeta la manija y siéntate erguido con una ligera inclinación hacia adelante.","Lleva los codos hacia atrás y tira de la manija hacia la parte baja del abdomen.","Contrae los omóplatos al final del tirón.","Extiende los brazos con control de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"tips":["Mantén el torso erguido con un balanceo mínimo.","Lleva los codos directamente hacia atrás, no hacia los lados.","Contrae los omóplatos al final del tirón."],"met":6.0,"uni":false,"img":["seated-cable-row-start.webp","seated-cable-row-peak.webp"]},{"id":"seated-calf-raise","n":"Elevación de Talones Sentado","d":"Una elevación de talones en máquina realizada sentado para trabajar específicamente el músculo sóleo.","cat":"fuerza","g":"piernas","bp":"lower_legs","eq":"máquina de gemelos sentado","home":false,"bw":false,"lv":"principiante","m":["sóleo"],"m2":["gemelos"],"ins":["Siéntate en la máquina de elevación de talones con los pads apoyados en los muslos.","Baja los talones lo más posible.","Elévate sobre las puntas de los pies.","Baja con control.","Repite."],"tips":["La rodilla flexionada destensa el gastrocnemio, así que el sóleo asume más trabajo.","Utiliza un rango completo de movimiento."],"met":5.0,"uni":false,"img":["seated-calf-raise-start.webp","seated-calf-raise-peak.webp"]},{"id":"seated-db-press","n":"Press de Hombro con Mancuernas Sentado","d":"Un movimiento de press sentado para los hombros usando mancuernas.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["deltoides anterior","deltoides lateral"],"m2":["trapecio","tríceps"],"ins":["Siéntate en un banco con respaldo sosteniendo mancuernas a la altura de los hombros.","Empuja las mancuernas sobre la cabeza hasta extender completamente los brazos.","Baja las mancuernas de vuelta a la altura de los hombros.","Repite."],"tips":["No arquees la espalda baja; mantén el contacto con el respaldo.","Sube las mancuernas en línea recta, sin chocarlas arriba.","Exhala al empujar y mantén el core firme."],"met":6.0,"uni":false,"img":["seated-db-press-start.webp","seated-db-press-peak.webp"]},{"id":"seated-dip-machine","n":"Máquina de Fondos Sentado","d":"Una versión del fondo en máquina de pesas con selector: sentado con la espalda contra el respaldo, empujas dos brazos de palanca hacia abajo a tus costados hasta que los brazos quedan estirados. El movimiento sigue la trayectoria de un fondo con el peso corporal, pero la carga es el peso que eliges en la pila y el asiento soporta tu peso corporal.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"máquina de fondos","home":false,"bw":false,"lv":"principiante","m":["tríceps"],"m2":["deltoides anterior","pectoral"],"ins":["Selecciona el peso en la pila y ajusta el asiento para que las empuñaduras queden aproximadamente a la altura de los hombros cuando estés sentado.","Siéntate erguido con la espalda contra el respaldo y agarra las empuñaduras a tus costados con los codos flexionados.","Mantén los hombros bajos y el pecho alto, y empuja las empuñaduras hacia abajo extendiendo los codos.","Aprieta los tríceps abajo, con los brazos estirados pero sin bloquear los codos con fuerza.","Deja que las empuñaduras suban de nuevo de forma controlada hasta que los codos queden flexionados a unos 90 grados.","Repite el número de repeticiones previsto manteniendo la espalda contra el respaldo."],"tips":["Mantén los codos cerca de los costados para que el trabajo se quede en los tríceps.","No dejes que los hombros rueden hacia delante ni se encojan al subir las empuñaduras; detente donde el estiramiento del pecho y los hombros sea cómodo.","Mantén la espalda contra el respaldo; inclinarte hacia delante traslada el trabajo hacia el pecho."],"met":6.0,"uni":false,"img":["seated-dip-machine-start.webp","seated-dip-machine-peak.webp"]},{"id":"seated-dumbbell-curl","n":"Curl con Mancuernas Sentado","d":"Un curl de bíceps sentado con mancuernas, donde la posición sentada y erguida elimina el impulso para una técnica más estricta.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"mancuernas","home":true,"bw":false,"lv":"principiante","m":["bíceps"],"m2":["braquial","braquiorradial"],"ins":["Siéntate en un banco con una mancuerna en cada mano.","Deja los brazos colgando a los lados con las palmas hacia adelante.","Sube ambas mancuernas hacia los hombros flexionando los bíceps.","Aprieta en la parte superior del movimiento.","Baja las mancuernas con control.","Repite el número deseado de repeticiones."],"tips":["Mantén los codos pegados a los costados en todo momento.","Evita inclinarte hacia atrás para ayudar a levantar el peso.","Estira los brazos por completo al final de cada repetición."],"met":5.0,"uni":false,"img":["seated-dumbbell-curl-start.webp","seated-dumbbell-curl-peak.webp"]},{"id":"seated-dumbbell-lateral-raise","n":"Elevación Lateral con Mancuerna Sentado","d":"Un ejercicio de aislamiento sentado que levanta las mancuernas hacia los lados, trabajando los deltoides laterales sin impulso de piernas.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"mancuernas","home":true,"bw":false,"lv":"principiante","m":["deltoides lateral"],"m2":["deltoides anterior","trapecio"],"ins":["Siéntate en un banco con una mancuerna en cada mano a los lados.","Mantén la espalda erguida y el core contraído.","Eleva ambas mancuernas hacia los lados hasta la altura de los hombros.","Mantén una ligera flexión en los codos.","Baja las mancuernas con control.","Repite el número de repeticiones deseado."],"tips":["Usa un peso ligero para mantener la elevación estricta.","Lidera con los codos en lugar de con las manos.","Eleva hasta la altura de los hombros y baja con control."],"met":5.0,"uni":false,"img":["seated-dumbbell-lateral-raise-start.webp","seated-dumbbell-lateral-raise-peak.webp"]},{"id":"seated-dumbbell-tricep-extension","n":"Extensión de Tríceps con Mancuerna Sentado","d":"Una extensión por encima de la cabeza sentado que baja la mancuerna detrás de la cabeza, estirando y trabajando los tríceps.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"mancuernas","home":true,"bw":false,"lv":"principiante","m":["tríceps"],"m2":["deltoides anterior"],"ins":["Siéntate en un banco con una mancuerna sostenida sobre la cabeza con ambas manos.","Mantén los brazos superiores verticales junto a las orejas.","Baja la mancuerna detrás de la cabeza flexionando los codos.","Extiende los brazos para empujar la mancuerna de vuelta arriba.","Aprieta los tríceps en la parte superior.","Repite el número de repeticiones deseado."],"tips":["Mantén los brazos verticales junto a las orejas.","Mueve solo los antebrazos, manteniendo los codos quietos.","Contrae el core para evitar arquear la zona lumbar."],"met":5.0,"uni":false,"img":["seated-dumbbell-tricep-extension-start.webp","seated-dumbbell-tricep-extension-peak.webp"]},{"id":"seated-forward-fold","n":"Flexión Sentado hacia Adelante","d":"Un estiramiento sentado para los isquiotibiales y la zona lumbar, inclinando el torso sobre las piernas estiradas.","cat":"estiramiento","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["isquiotibiales"],"m2":["lumbares"],"ins":["Siéntate en el suelo con ambas piernas estiradas al frente.","Mantén la espalda larga e inclínate desde las caderas.","Lleva las manos hacia los pies.","Mantén de 20 a 30 segundos, respirando de forma constante."],"tips":["Inicia con el pecho, no con la cabeza, para mantener la espalda larga.","Estira hasta una tensión leve, nunca hasta el dolor."],"met":5.0,"uni":false,"img":["seated-forward-fold-main.webp"]},{"id":"seated-leg-curl","n":"Curl de Piernas Sentado","d":"Un ejercicio de aislamiento de isquiotibiales en máquina en posición sentada, con tensión constante y menor implicación de los flexores de cadera respecto a la variante tumbada.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"máquina de femoral","home":false,"bw":false,"lv":"principiante","m":["isquiotibiales"],"m2":["gemelos"],"ins":["Ajusta el respaldo y el cojín de tobillo para que las rodillas queden alineadas con el pivote de la máquina.","Siéntate erguido, coloca la parte posterior de los tobillos sobre el cojín y sujeta las asas.","Flexiona las piernas hacia abajo y atrás bajo el asiento hasta donde la máquina lo permita.","Pausa en la contracción máxima, luego vuelve lentamente a la posición inicial.","Repite el número de repeticiones deseado."],"tips":["Mantén la espalda firmemente apoyada en el respaldo durante todo el movimiento.","Flexiona ligeramente los pies hacia las espinillas en la contracción máxima para mayor activación de los isquios.","Controla la fase excéntrica — no dejes que el peso jale las piernas de vuelta rápidamente."],"met":5.0,"uni":false,"img":["seated-leg-curl-start.webp","seated-leg-curl-peak.webp"]},{"id":"seated-smith-machine-shoulder-press","n":"Press de Hombros en Máquina Smith Sentado","d":"Un press de hombros sentado en máquina Smith, cuyo recorrido guiado facilita el aprendizaje del empuje vertical.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"máquina Smith","home":false,"bw":false,"lv":"principiante","m":["deltoides anterior","deltoides lateral"],"m2":["trapecio","tríceps"],"ins":["Coloca un banco dentro de la máquina Smith.","Siéntate mirando hacia adelante con la barra a la altura de los hombros.","Agarra la barra ligeramente más ancho que el ancho de hombros.","Desbloquea la barra y empuja hacia arriba hasta extender los brazos.","Baja la barra de vuelta a la altura de los hombros con control.","Repite el número de repeticiones deseado."],"tips":["Coloca el banco de modo que la barra baje justo delante de la cara.","No bloquees los codos con brusquedad en la parte alta.","Mantén el torso erguido y el core activo durante toda la serie."],"met":6.0,"uni":false,"img":["seated-smith-machine-shoulder-press-start.webp","seated-smith-machine-shoulder-press-peak.webp"]},{"id":"seated-spinal-twist","n":"Giro Espinal Sentado","d":"Una rotación sentada que estira los oblicuos, la espalda media y los glúteos girando hacia una rodilla flexionada.","cat":"estiramiento","g":"espalda","bp":"back","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["lumbares","oblicuos"],"m2":["glúteo mayor"],"ins":["Siéntate con una pierna estirada y cruza el otro pie por encima.","Apoya el codo opuesto contra la parte externa de la rodilla flexionada.","Gira el torso hacia la rodilla flexionada y mira sobre el hombro.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],"tips":["Siéntate erguido y alarga la columna antes de girar.","Gira desde la espalda media, no desde la lumbar."],"met":5.0,"uni":true,"img":["seated-spinal-twist-main.webp"]},{"id":"seated-straddle-stretch","n":"Estiramiento en Apertura Sentado","d":"Un estiramiento sentado con piernas abiertas para aductores e isquiotibiales, inclinando el torso entre las piernas.","cat":"estiramiento","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["aductores","isquiotibiales"],"m2":["lumbares"],"ins":["Siéntate con las piernas estiradas y bien abiertas en V.","Mantén la espalda larga e inclínate desde las caderas.","Camina las manos hacia adelante por el suelo.","Mantén de 20 a 30 segundos, respirando de forma constante."],"tips":["Mantén los dedos de los pies hacia arriba, no girados.","Entra en el estiramiento lentamente, nunca rebotes."],"met":5.0,"uni":false,"img":["seated-straddle-stretch-main.webp"]},{"id":"shrug","n":"Encogimiento con Barra","d":"Un movimiento de aislamiento para el trapecio superior.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"barra","home":false,"bw":false,"lv":"principiante","m":["trapecio"],"m2":["romboides"],"ins":["De pie, sostén una barra a lo largo de los brazos con agarre en pronación.","Encoge los hombros directamente hacia las orejas.","Mantén brevemente en la parte superior.","Baja los hombros con control.","Repite."],"tips":["Sube los hombros en vertical, sin hacer círculos.","No uses los brazos; los codos quedan extendidos todo el tiempo.","Evita impulsarte con las piernas para subir más peso."],"met":5.0,"uni":false,"img":["shrug-start.webp","shrug-peak.webp"]},{"id":"side-lunge","n":"Zancada Lateral","d":"Una zancada lateral que da un paso amplio hacia un lado, trabajando los cuádriceps, glúteos y la cara interna de los muslos en un patrón lateral.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["glúteo mayor","cuádriceps"],"m2":["glúteo medio","isquiotibiales","flexores de cadera"],"ins":["De pie con los pies al ancho de las caderas y las manos en el pecho.","Da un paso amplio hacia un lado con una pierna, manteniendo la otra recta.","Flexiona la rodilla de la pierna que dio el paso y empuja las caderas hacia atrás en una sentadilla lateral.","Mantén el pecho erguido y el talón de trabajo apoyado.","Empuja con la pierna flexionada para volver a la posición de pie.","Completa las repeticiones de un lado y luego cambia."],"tips":["Empuja las caderas hacia atrás mientras flexionas la rodilla del paso.","Mantén la pierna contraria estirada y ambos talones apoyados.","Mantén el pecho erguido en lugar de redondear hacia delante."],"met":5.0,"uni":true,"img":["side-lunge-start.webp","side-lunge-peak.webp"]},{"id":"side-lying-hip-abduction","n":"Abducción de Cadera Acostado de Lado","d":"Un ejercicio de aislamiento con peso corporal que trabaja el glúteo medio y los abductores de cadera.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["abductores","glúteo medio"],"m2":[],"ins":["Acuéstate de lado con las piernas apiladas.","Mantén la pierna inferior ligeramente flexionada.","Eleva la pierna superior hacia el techo.","Baja con control.","Repite de ambos lados."],"tips":["Mantén las caderas apiladas durante todo el ejercicio.","Evita inclinar la pelvis."],"met":3.5,"uni":true,"img":["side-lying-hip-abduction-start.webp","side-lying-hip-abduction-peak.webp"]},{"id":"side-lying-hip-abduction-hold","n":"Abducción de Cadera Acostado de Lado Isométrica","d":"La parte alta de la elevación lateral de pierna mantenida en el tiempo: tumbado de lado con la pierna superior elevada y ligeramente por detrás del cuerpo, cargando el glúteo medio de forma isométrica.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["abductores","glúteo medio"],"m2":[],"ins":["Túmbate de lado con las piernas estiradas y apiladas, apoyando la cabeza sobre el brazo inferior.","Aprieta el tronco para que el torso quede cuadrado y no ruede hacia atrás.","Eleva la pierna superior unos 30 o 45 grados, con los dedos del pie apuntando al frente.","Mantén la pierna ahí durante el tiempo indicado, respirando con normalidad.","Baja la pierna de forma controlada y repite del otro lado."],"tips":["Girar los dedos hacia el techo pasa el trabajo al flexor de la cadera; mantenlos mirando al frente.","Lleva la pierna algo por detrás de la línea del cuerpo para enfatizar el glúteo medio.","Apoya la mano superior en el suelo por delante si el equilibrio es lo que te limita."],"met":3.5,"uni":true,"img":["side-lying-hip-abduction-hold-main.webp"]},{"id":"side-lying-hip-adduction","n":"Aducción de Cadera Acostado de Lado","d":"Un ejercicio de aducción tumbado de lado que eleva la pierna inferior contra la gravedad para trabajar la cadera con el propio peso.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["aductores"],"m2":[],"ins":["Acuéstate de lado con la pierna inferior recta.","Flexiona la pierna superior y coloca su pie plano frente al muslo inferior.","Apoya la cabeza con el brazo inferior.","Eleva la pierna inferior hacia el techo.","Baja la pierna con control.","Completa las repeticiones de un lado y luego cambia."],"tips":["Mueve solo la pierna; la cadera y el torso quedan quietos.","Sube la pierna sin impulso y baja despacio.","Alinea hombros, cadera y pies antes de empezar a moverte."],"met":3.5,"uni":false,"img":["side-lying-hip-adduction-start.webp","side-lying-hip-adduction-peak.webp"]},{"id":"side-lying-hip-adduction-hold","n":"Aducción de Cadera Acostado de Lado Isométrica","d":"La parte alta de la elevación de cara interna del muslo mantenida en el tiempo: tumbado de lado con la pierna superior cruzada por delante y la pierna inferior separada del suelo por los aductores.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["aductores"],"m2":[],"ins":["Túmbate de lado con la pierna inferior estirada y la superior cruzada por encima, con el pie apoyado en el suelo.","Apoya la cabeza sobre el brazo inferior y mantén las caderas apiladas en vertical.","Eleva la pierna inferior todo lo que puedas con la rodilla estirada y los dedos del pie al frente.","Mantén esa posición elevada durante el tiempo indicado sin rodar la cadera hacia atrás.","Baja la pierna de forma controlada y repite del otro lado."],"tips":["El recorrido es corto: unos pocos centímetros con la pelvis quieta valen más que un balanceo amplio.","Mantén la pierna elevada en línea con el torso en lugar de dejar que se vaya hacia delante.","Presiona ligeramente el pie superior contra el suelo si necesitas estabilizar la posición."],"met":3.5,"uni":false,"img":["side-lying-hip-adduction-hold-main.webp"]},{"id":"side-lying-lateral-raise","n":"Elevación Lateral Tumbado de Lado","d":"Un ejercicio de aislamiento del deltoides lateral con mancuerna en posición lateral sobre un banco plano, que proporciona tensión constante sin impulso.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"mancuernas","home":true,"bw":false,"lv":"principiante","m":["deltoides lateral"],"m2":["supraespinoso","trapecio"],"ins":["Túmbate de lado sobre un banco plano usando el brazo inferior para apoyar la cabeza o sujetar el borde del banco.","Sujeta una mancuerna con la mano superior con el brazo descansando a lo largo del costado.","Con el codo ligeramente flexionado, eleva la mancuerna hasta que el brazo quede perpendicular al suelo.","Pausa brevemente arriba, luego baja la mancuerna despacio hasta el costado.","Completa todas las repeticiones en un lado antes de cambiar."],"tips":["Mantén el torso quieto — solo el brazo de trabajo debe moverse.","La posición tumbada elimina el impulso y aísla eficazmente el deltoides lateral.","Usa un peso más ligero que en la elevación lateral de pie — la palanca es más exigente."],"met":5.0,"uni":true,"img":["side-lying-lateral-raise-start.webp","side-lying-lateral-raise-peak.webp"]},{"id":"side-plank","n":"Plancha Lateral","d":"Una variación de plancha lateral que trabaja los oblicuos y el core lateral.","cat":"fuerza","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["oblicuos","transverso abdominal"],"m2":["glúteo medio","abdominales"],"ins":["Acuéstate de lado con el antebrazo en el suelo y el codo bajo el hombro.","Levanta las caderas del suelo formando una línea recta de la cabeza a los pies.","Mantén la posición con el core apretado.","Respira con regularidad.","Repite de ambos lados."],"tips":["No dejes que la cadera se hunda hacia el suelo.","Alinea hombros y cadera en un mismo plano, sin rotar el torso.","Empuja el suelo con el antebrazo para no colgarte del hombro."],"met":3.5,"uni":false,"img":["side-plank-main.webp"]},{"id":"side-plank-leg-lift","n":"Plancha Lateral con Elevación de Pierna","d":"Una plancha lateral con elevación de la pierna superior, que combina trabajo de core lateral con abducción de cadera.","cat":"fuerza","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["glúteo medio","oblicuos"],"m2":["glúteo mayor","abdominales","transverso abdominal"],"ins":["Túmbate de lado con el antebrazo en el suelo y el codo bajo el hombro.","Coloca un pie sobre el otro y eleva las caderas hasta una plancha lateral.","Desde esta plancha lateral estable, sube la pierna de arriba recta hacia el techo.","Baja la pierna de forma controlada sin dejar caer las caderas.","Completa las repeticiones de un lado y luego cambia."],"tips":["Mantén las caderas elevadas toda la serie; no dejes que se hundan.","Guía la elevación de la pierna con el talón, no con la punta.","Mantén el cuerpo en una sola línea recta de la cabeza al pie de abajo."],"met":5.0,"uni":true,"img":["side-plank-leg-lift-start.webp","side-plank-leg-lift-peak.webp"]},{"id":"side-plank-leg-lift-hold","n":"Plancha Lateral con Elevación de Pierna Isométrica","d":"Una plancha lateral sostenida con la pierna superior elevada: la cadera se mantiene alta y cuadrada mientras la pierna se separa, lo que añade una demanda de glúteo medio al trabajo lateral del tronco.","cat":"fuerza","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["glúteo medio","oblicuos"],"m2":["glúteo mayor","abdominales","transverso abdominal"],"ins":["Colócate en plancha lateral sobre el antebrazo, con el codo bajo el hombro y los pies apilados.","Eleva la cadera hasta que el cuerpo forme una línea recta desde los tobillos hasta la cabeza.","Sube la pierna superior aproximadamente a la altura de la cadera, con los dedos del pie al frente.","Mantén la posición durante el tiempo indicado, con la cadera alta y el hombro alineado sobre el codo.","Baja la pierna y la cadera de forma controlada y repite del otro lado."],"tips":["Aleja del oído el hombro de apoyo para que el pecho no se venga abajo hacia el suelo.","Termina la serie cuando la cadera empiece a caer, no cuando se canse la pierna.","Apoya la rodilla inferior en el suelo para una versión más sencilla que conserva la elevación de pierna."],"met":5.0,"uni":true,"img":["side-plank-leg-lift-hold-main.webp"]},{"id":"single-arm-chest-supported-dumbbell-row","n":"Remo con Mancuerna a Una Mano con Pecho Apoyado","d":"Un remo unilateral realizado con un brazo a la vez sobre un banco inclinado con apoyo para el pecho, que aísla cada lado de la espalda y reduce el impulso.","cat":"fuerza","g":"espalda","bp":"back","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["dorsales","romboides"],"m2":["bíceps","deltoides posterior"],"ins":["Túmbate boca abajo en un banco inclinado sujetando una mancuerna con una mano, con el brazo colgando recto hacia abajo.","Rema la mancuerna hacia tu costado, llevando el codo más allá del torso.","Aprieta el omóplato en la parte superior y luego baja de forma controlada.","Completa todas las repeticiones de un lado antes de cambiar de brazo."],"tips":["Trabajar un lado a la vez te permite concentrarte en una contracción completa sin que el otro brazo compense.","Mantén el pecho presionado contra el banco durante todo el movimiento para evitar usar impulso.","Iguala el número de repeticiones en ambos lados para evitar desequilibrios."],"met":6.0,"uni":true,"img":["single-arm-chest-supported-dumbbell-row-start.webp","single-arm-chest-supported-dumbbell-row-peak.webp"]},{"id":"single-arm-db-row","n":"Remo con Mancuerna a Un Brazo","d":"Un ejercicio de espalda unilateral con mancuerna para un desarrollo equilibrado.","cat":"fuerza","g":"espalda","bp":"back","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["dorsales","romboides"],"m2":["bíceps","deltoides posterior"],"ins":["Coloca una rodilla y una mano en un banco como apoyo.","Sostén una mancuerna en la otra mano con el brazo extendido.","Tira de la mancuerna hacia la cadera apretando el omóplato.","Baja la mancuerna con control.","Repite de ambos lados."],"tips":["No gires el torso al tirar; mantén la cadera estable.","Evita encoger el hombro hacia la oreja al iniciar el tirón.","Haz las mismas repeticiones con cada brazo."],"met":6.0,"uni":true,"img":["single-arm-db-row-start.webp","single-arm-db-row-peak.webp"]},{"id":"single-arm-dumbbell-bench-press","n":"Press de Banca con Mancuerna a Un Brazo","d":"Un press en banco plano con una mancuerna cada vez. La carga unilateral trabaja el pecho, el hombro y el tríceps mientras el tronco se esfuerza por evitar que el cuerpo rote fuera del banco.","cat":"fuerza","g":"pecho","bp":"chest","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["pectoral","tríceps"],"m2":["deltoides anterior","oblicuos","serrato"],"ins":["Túmbate en un banco plano con los pies apoyados en el suelo y una mancuerna sujeta con una mano a la altura del pecho.","Apoya la mano libre sobre el estómago o ábrela hacia un lado para mantener el equilibrio.","Empuja la mancuerna hacia arriba sobre el pecho hasta que el brazo quede recto.","Haz una breve pausa arriba sin dejar que el cuerpo gire hacia el brazo que empuja.","Baja la mancuerna despacio hacia el costado del pecho.","Completa las repeticiones de un lado y luego cambia de brazo."],"tips":["Aprieta los glúteos y mantén los omóplatos pegados al banco para resistir la rotación.","Baja hacia el costado del pecho, con el codo a unos 45 grados del cuerpo.","Usa un peso que puedas mantener nivelado sin torcerte; añade carga solo cuando ambos lados rindan igual."],"met":6.0,"uni":true,"img":["single-arm-dumbbell-bench-press-start.webp","single-arm-dumbbell-bench-press-peak.webp"]},{"id":"single-arm-dumbbell-overhead-tricep-extension","n":"Extensión de Tríceps sobre la Cabeza con Mancuerna a Un Brazo","d":"Una extensión de tríceps sobre la cabeza a un brazo que proporciona un estiramiento largo y unilateral de la cabeza larga y entrena la estabilidad del core contra la flexión lateral.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"mancuernas","home":true,"bw":false,"lv":"principiante","m":["tríceps"],"m2":["oblicuos"],"ins":["De pie o sentado, sostén una mancuerna en una mano sobre la cabeza con el brazo completamente extendido.","La palma mira hacia adelante; la otra mano puede apoyarse en la cadera o en un soporte para mayor estabilidad.","Flexiona el codo para bajar la mancuerna detrás de la cabeza en un arco controlado.","Mantén el brazo superior vertical y cerca de la cabeza durante todo el movimiento.","Extiende el codo para regresar la mancuerna sobre la cabeza.","Completa todas las repeticiones de un lado y luego cambia."],"tips":["Solo el antebrazo se mueve — el brazo superior permanece fijo en su lugar.","No dejes que el torso se incline hacia un lado; este también es un ejercicio de core."],"met":5.0,"uni":true,"img":["single-arm-dumbbell-overhead-tricep-extension-start.webp","single-arm-dumbbell-overhead-tricep-extension-peak.webp"]},{"id":"single-arm-hammer-curl","n":"Curl martillo unilateral","d":"Un curl unilateral con mancuerna y agarre neutro que mantiene el codo de trabajo junto al torso mientras el braquial y el braquiorradial flexionan el codo.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["braquial","braquiorradial"],"m2":["bíceps","antebrazo"],"ins":["Colócate con los pies al ancho de las caderas y sostén una mancuerna al costado con la palma hacia dentro.","Activa el tronco y mantén el brazo de trabajo junto a las costillas mientras cuelga extendido.","Lleva la mancuerna hacia el hombro sin girar la palma ni balancear el torso.","Aprieta los flexores del codo arriba y baja la mancuerna de forma controlada hasta extender el brazo.","Completa las repeticiones de un lado y después cambia de brazo."],"tips":["Deja que el lado más débil marque el peso y las repeticiones para que ambos lados reciban el mismo trabajo.","Mantén la muñeca neutra y el hombro quieto; el movimiento debe venir del codo.","Controla la bajada en lugar de dejar caer la mancuerna desde arriba."],"met":5.0,"uni":true,"img":["single-arm-hammer-curl-start.webp","single-arm-hammer-curl-peak.webp"]},{"id":"single-arm-machine-shoulder-press","n":"Press de hombros unilateral en máquina","d":"Un press de hombros unilateral sentado en máquina que permite empujar cada brazo por separado mientras la espalda permanece apoyada y la máquina guía la resistencia.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"máquina de press de hombro","home":false,"bw":false,"lv":"principiante","m":["deltoides anterior","deltoides lateral"],"m2":["trapecio","tríceps"],"ins":["Ajusta el asiento para que el agarre de trabajo comience cerca del hombro y apoya firmemente la espalda en el respaldo.","Sujeta un agarre con la muñeca recta y deja la mano libre sobre el soporte.","Empuja el agarre hacia arriba sin separarte del respaldo ni girar el torso.","Baja el agarre bajo control hasta que el codo quede justo por debajo de la posición inicial.","Completa las repeticiones de un lado y después entrena el otro lado."],"tips":["Comienza con el brazo más débil y deja que marque el peso y las repeticiones de ambos lados.","Mantén las costillas abajo y la espalda contra el respaldo en lugar de inclinarte hacia un lado.","Detén el movimiento ante una posición dolorosa del hombro; el recorrido de la máquina debe sentirse controlado."],"met":6.0,"uni":true,"img":["single-arm-machine-shoulder-press-start.webp","single-arm-machine-shoulder-press-peak.webp"]},{"id":"single-arm-plate-loaded-lateral-raise","n":"Elevación Lateral a Un Brazo en Máquina de Discos","d":"La elevación lateral en máquina de discos trabajando un brazo cada vez, de modo que cada lado levanta su propia carga y ambos pueden entrenarse hasta el mismo nivel.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"máquina de laterales","home":false,"bw":false,"lv":"principiante","m":["deltoides lateral"],"m2":["deltoides anterior","trapecio"],"ins":["Ajusta la altura del asiento para que el eje de la almohadilla quede alineado con tu hombro y carga solo el lado que vas a trabajar.","Siéntate con la espalda apoyada en el respaldo y coloca la cara externa del brazo que trabaja contra su almohadilla.","Sujeta la empuñadura del lado libre o apoya esa mano en el regazo, y mantén el torso alineado con el asiento.","Empuja el brazo que trabaja hacia fuera y hacia arriba contra la almohadilla hasta la altura del hombro, y baja de forma controlada.","Completa todas las repeticiones de ese lado, luego carga y trabaja el otro lado."],"tips":["Iguala los lados por el brazo débil, no por el fuerte. Trabajar un lado cada vez solo revela un desequilibrio si dejas que el lado débil fije el número de repeticiones.","No dejes que el torso se incline hacia el lado que trabaja. Con carga en un solo brazo la máquina ya no se equilibra sola, y inclinarse convierte la elevación en una flexión lateral.","Empieza por el brazo débil para que marque el objetivo, y da el mismo descanso a los dos lados."],"met":5.0,"uni":true,"img":["single-arm-plate-loaded-lateral-raise-start.webp","single-arm-plate-loaded-lateral-raise-peak.webp"]},{"id":"single-arm-tricep-pushdown","n":"Extensión de Tríceps a Un Brazo en Polea","d":"Un ejercicio de aislamiento de tríceps realizado con un brazo a la vez en una máquina de polea con una sola manija.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"polea","home":false,"bw":false,"lv":"intermedio","m":["tríceps"],"m2":["antebrazo"],"ins":["Coloca una manija individual en una polea alta.","Sujeta la manija con una mano y mantén el codo pegado al costado.","Empuja la manija hacia abajo hasta extender completamente el brazo.","Contrae el tríceps en la parte baja.","Vuelve lentamente a la posición inicial.","Completa las repeticiones de un lado y luego cambia."],"tips":["Mantén el codo pegado al costado en todo momento.","Evita inclinarte hacia adelante para generar impulso.","Extiende el brazo por completo en la parte baja para una contracción total."],"met":6.0,"uni":true,"img":["single-arm-tricep-pushdown-start.webp","single-arm-tricep-pushdown-peak.webp"]},{"id":"single-db-svend-press","n":"Press Svend con una Mancuerna","d":"Un press de pecho de pie sosteniendo una sola mancuerna en vertical entre las palmas, donde lo que trabaja los pectorales es la presión hacia adentro y no la carga.","cat":"fuerza","g":"pecho","bp":"chest","eq":"mancuernas","home":true,"bw":false,"lv":"principiante","m":["pectoral"],"m2":["deltoides anterior","tríceps"],"ins":["De pie y erguido, sostén una sola mancuerna en vertical frente al esternón, con el mango entre las palmas planas.","Aprieta con fuerza las palmas contra la mancuerna para que la tensión vaya al pecho y el peso no resbale.","Empuja la mancuerna recto hacia adelante hasta que los brazos queden casi estirados, manteniéndola a la altura del pecho todo el recorrido.","Haz una breve pausa sin soltar la presión y devuelve la mancuerna al pecho con control.","Repite el número de repeticiones recomendado."],"tips":["La presión sobre la mancuerna hace el ejercicio. Si agarras el mango en lugar de aplastar el peso entre las palmas planas, el pecho no trabaja.","Usa una mancuerna ligera. Las palmas la sostienen solo por fricción, así que el agarre marca el límite mucho antes que el pecho.","Mantén los codos ligeramente flexionados en el lockout y la mancuerna a la altura del esternón; si baja hacia las caderas, los pectorales dejan de trabajar."],"met":5.0,"uni":false,"img":["single-db-svend-press-start.webp","single-db-svend-press-peak.webp"]},{"id":"single-leg-calf-raise","n":"Elevación de Pantorrilla a Una Pierna","d":"Una elevación de pantorrilla unilateral que carga una pantorrilla a la vez y expone desequilibrios laterales.","cat":"fuerza","g":"piernas","bp":"lower_legs","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["gemelos"],"m2":["sóleo"],"ins":["Mantente sobre un pie con la punta sobre una plataforma elevada, talón al aire.","Sujétate a una pared o barandilla con una mano para equilibrio.","Baja el talón por debajo de la plataforma para un estiramiento profundo.","Empuja arriba sobre la punta tan alto como puedas.","Baja con control. Repeticiones por lado, luego cambia."],"tips":["Pausa arriba para maximizar la contracción.","Usa una excéntrica lenta para el estiramiento completo.","Sostén una mancuerna del lado que trabaja cuando el peso corporal sea fácil."],"met":3.5,"uni":true,"img":["single-leg-calf-raise-start.webp","single-leg-calf-raise-peak.webp"]},{"id":"single-leg-extension","n":"Extensión de Cuádriceps a Una Pierna","d":"Un ejercicio de aislamiento de cuádriceps en una máquina de extensión de piernas, trabajando una pierna a la vez.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"máquina de cuádriceps","home":false,"bw":false,"lv":"intermedio","m":["cuádriceps"],"m2":[],"ins":["Siéntate en una máquina de extensión de piernas y coloca un pie bajo la almohadilla.","Deja el otro pie apoyado en el suelo o colgando.","Extiende la pierna de trabajo hasta que quede casi recta.","Contrae el cuádriceps en la parte alta.","Baja la pierna con control.","Completa las repeticiones de un lado y luego cambia."],"tips":["Contrae con fuerza el cuádriceps en la parte alta del movimiento.","Baja el peso con control en lugar de dejarlo caer.","Mantén la espalda plana contra el respaldo."],"met":5.0,"uni":true,"img":["single-leg-extension-start.webp","single-leg-extension-peak.webp"]},{"id":"single-leg-glute-bridge","n":"Puente de Glúteo a Una Pierna","d":"Un puente de glúteo unilateral que carga un glúteo a la vez y ayuda a corregir desequilibrios laterales.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["glúteo mayor"],"m2":["lumbares","isquiotibiales"],"ins":["Acuéstate boca arriba con una rodilla flexionada y el pie plano, la otra pierna extendida recta.","Activa el core y contrae el glúteo del lado que trabaja.","Empuja las caderas arriba presionando con el talón de trabajo.","Pausa arriba con el cuerpo en línea recta de hombros a rodilla.","Baja con control. Repeticiones por lado, luego cambia."],"tips":["Mantén la pierna extendida en línea con el muslo de trabajo.","Contrae el glúteo arriba — no empujes desde la zona lumbar.","Ralentiza la fase de bajada para más estímulo."],"met":5.0,"uni":true,"img":["single-leg-glute-bridge-start.webp","single-leg-glute-bridge-peak.webp"]},{"id":"single-leg-glute-bridge-hold","n":"Puente de Glúteo a Una Pierna Isométrico","d":"La parte alta del puente de glúteo a una pierna mantenida en el tiempo: la cadera queda extendida y nivelada mientras una pierna permanece elevada, de modo que un solo glúteo sostiene toda la posición.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["glúteo mayor"],"m2":["lumbares","isquiotibiales"],"ins":["Túmbate boca arriba con una rodilla flexionada y ese pie apoyado, y eleva la otra pierna hasta que el muslo quede casi vertical.","Empuja con el talón del pie apoyado y eleva la cadera hasta que el cuerpo quede recto desde la rodilla hasta los hombros.","Nivela la pelvis para que el lado elevado no caiga y lleva las costillas hacia abajo.","Mantén la posición alta durante el tiempo indicado, con la rodilla elevada quieta.","Baja la cadera de forma controlada y repite del otro lado."],"tips":["Fíjate en la pelvis más que en la altura: una cadera nivelada un poco más abajo vale más que una alta y girada.","Mantén el talón apoyado cerca del glúteo para que el isquiotibial no se acalambre.","Estira del todo la pierna libre si la posición te resulta fácil, pero solo mientras la pelvis siga nivelada."],"met":5.0,"uni":true,"img":["single-leg-glute-bridge-hold-main.webp"]},{"id":"single-leg-lying-leg-curl","n":"Curl de Pierna Tumbado a Una Pierna","d":"Un curl femoral tumbado a una pierna en máquina, que aísla los isquiotibiales de cada lado por separado.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"máquina de femoral","home":false,"bw":false,"lv":"intermedio","m":["isquiotibiales"],"m2":["gemelos"],"ins":["Acuéstate boca abajo en la máquina de curl de piernas tumbado.","Coloca un tobillo bajo el apoyo y deja el otro pie fuera de la máquina.","Flexiona la pierna de trabajo llevando el talón hacia el glúteo.","Aprieta los isquiotibiales en la parte superior.","Baja la pierna con control.","Completa las repeticiones de un lado y luego cambia."],"tips":["Mantén la cadera pegada al apoyo durante todo el recorrido.","Usa un peso que te permita subir y bajar sin tirones.","Empieza por la pierna más débil y repite igual con la otra."],"met":5.0,"uni":true,"img":["single-leg-lying-leg-curl-start.webp","single-leg-lying-leg-curl-peak.webp"]},{"id":"single-leg-press","n":"Prensa de Piernas a Una Pierna","d":"Un ejercicio de tren inferior en una máquina de prensa, empujando la plataforma con una pierna a la vez.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"prensa","home":false,"bw":false,"lv":"intermedio","m":["glúteo mayor","cuádriceps"],"m2":["isquiotibiales"],"ins":["Siéntate en la máquina de prensa con un pie sobre la plataforma.","Mantén la otra pierna fuera de la plataforma, apoyada a un lado.","Suelta los seguros y baja la plataforma flexionando la rodilla.","Detente cuando la rodilla forme un ángulo cercano a 90 grados.","Empuja a través del talón para devolver la plataforma.","Completa las repeticiones de un lado y luego cambia."],"tips":["Mantén el pie plano y centrado en la plataforma.","Evita que la rodilla se desplace hacia adentro.","No bloquees la rodilla con fuerza en la parte alta."],"met":6.0,"uni":true,"img":["single-leg-press-start.webp","single-leg-press-peak.webp"]},{"id":"single-leg-rdl-hold","n":"Peso Muerto Rumano a Una Pierna Isométrico","d":"Un mantenimiento de equilibrio en la parte baja de un peso muerto rumano a una pierna: de pie sobre una pierna, el torso se inclina hacia delante y la otra pierna se extiende hacia atrás en línea con el cuerpo. Entrena los isquiotibiales, los glúteos y el tronco mientras desafía el equilibrio.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["glúteo mayor","isquiotibiales"],"m2":["aductores","lumbares","glúteo medio","oblicuos"],"ins":["Colócate sobre una pierna con una ligera flexión de rodilla y los brazos colgando delante de ti.","Haz una bisagra de cadera, enviando la pierna libre recta hacia atrás mientras el torso se inclina hacia delante.","Mantén la espalda plana y la cadera cuadrada respecto al suelo.","Detente cuando el torso y la pierna libre queden aproximadamente paralelos al suelo y mantén la posición.","Vuelve a ponerte de pie de forma controlada y luego cambia de pierna."],"tips":["Piensa en un balancín: el torso y la pierna libre se mueven juntos.","Mantén la cadera nivelada; no dejes que la cadera de la pierna libre rote hacia arriba.","Fija la mirada en un punto del suelo delante de ti para ayudar al equilibrio."],"met":5.0,"uni":true,"img":["single-leg-rdl-hold-main.webp"]},{"id":"single-leg-romanian-deadlift","n":"Peso Muerto Rumano a Una Pierna","d":"Un peso muerto rumano a una pierna con mancuernas, que trabaja isquiotibiales y glúteos mientras exige equilibrio y estabilidad de cadera.","cat":"fuerza","g":"espalda","bp":"back","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["glúteo mayor","isquiotibiales"],"m2":["lumbares","glúteo medio"],"ins":["Apóyate en una pierna sosteniendo una mancuerna en cada mano frente a los muslos.","Mantén una ligera flexión en la rodilla de apoyo.","Bisagra en la cadera extendiendo la pierna libre detrás.","Baja las mancuernas a lo largo de la pierna de apoyo hasta sentir el estiramiento en los isquiotibiales.","Empuja con el talón para volver a la posición erguida.","Completa las repeticiones de un lado y luego cambia."],"tips":["Mantén la cadera cuadrada; no dejes que se abra hacia el lado.","Si pierdes el equilibrio, reduce el rango o usa menos peso.","Mira un punto fijo en el suelo para estabilizarte."],"met":6.0,"uni":true,"img":["single-leg-romanian-deadlift-start.webp","single-leg-romanian-deadlift-peak.webp"]},{"id":"sit-ups","n":"Abdominales","d":"Un ejercicio abdominal clásico con rango de movimiento completo.","cat":"fuerza","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["flexores de cadera","abdominales"],"m2":["oblicuos"],"ins":["Acuéstate boca arriba con las rodillas flexionadas y los pies anclados.","Cruza los brazos sobre el pecho o coloca las manos detrás de la cabeza.","Siéntate completamente hasta que el torso quede erguido.","Baja con control.","Repite."],"tips":["No tires del cuello con las manos al subir.","Exhala mientras subes para mantener el abdomen activo.","Si notas tirantez lumbar, reduce el rango de movimiento."],"met":5.0,"uni":false,"img":["sit-ups-start.webp","sit-ups-peak.webp"]},{"id":"six-inch-hold","n":"Mantenimiento a 15 cm del Suelo","d":"Un mantenimiento estático de core tumbado boca arriba con la cabeza, los hombros y las piernas rectas elevados unos 15 cm del suelo. Entrena la parte baja del abdomen y los flexores de cadera.","cat":"fuerza","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["flexores de cadera","abdominales"],"m2":["oblicuos","cuádriceps","transverso abdominal"],"ins":["Túmbate boca arriba con las piernas estiradas y los brazos descansando a lo largo de los costados.","Presiona la zona lumbar contra el suelo y contrae el abdomen.","Levanta la cabeza, los hombros y las piernas rectas unos 15 cm del suelo.","Mantén la posición respirando con regularidad.","Baja despacio para descansar."],"tips":["Mantén la zona lumbar plana; si se arquea, sube un poco más las piernas o flexiona las rodillas.","Mantén el cuello relajado y la barbilla ligeramente metida.","Progresa con mantenimientos cortos y descansa entre ellos."],"met":5.0,"uni":false,"img":["six-inch-hold-main.webp"]},{"id":"ski-erg","n":"SkiErg","d":"Un ejercicio cardiovascular de pie en un ergómetro de esquí que combina un potente tirón de doble bastón con una ligera bisagra de cadera para desarrollar potencia y resistencia de todo el cuerpo.","cat":"cardio","g":"cuerpo completo","bp":"full_body","eq":"ski erg","home":false,"bw":false,"lv":"intermedio","m":["dorsales","abdominales","tríceps"],"m2":["glúteo mayor","isquiotibiales","cuádriceps"],"ins":["Ponte frente al SkiErg con los agarres por encima de la cabeza y los pies separados al ancho de las caderas.","Activa el tronco y lleva los agarres hacia abajo tirando con los dorsales mientras haces una ligera bisagra de cadera.","Termina con las manos junto a los muslos y las rodillas suavemente flexionadas.","Deja que los cordones se recojan mientras elevas los brazos y vuelves a erguirte.","Repite con fluidez manteniendo los talones apoyados y el tronco controlado."],"tips":["Inicia el tirón con los dorsales en lugar de convertirlo en un movimiento solo de brazos.","Mantén la bisagra compacta y no bajes a una sentadilla profunda.","Controla el retorno de los agarres para mantener tensos los cordones."],"met":8.0,"uni":false,"img":["ski-erg-start.webp","ski-erg-peak.webp"]},{"id":"skull-crusher","n":"Skull Crusher","d":"Una extensión de tríceps tumbado con barra que aísla los tríceps a través de un rango de movimiento completo.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["tríceps"],"m2":[],"ins":["Acuéstate en un banco plano sosteniendo una barra sobre el pecho con agarre estrecho.","Baja la barra hacia la frente flexionando los codos.","Extiende los brazos de vuelta a la posición inicial.","Repite."],"tips":["Mantén los brazos superiores verticales durante todo el ejercicio.","Baja lentamente para proteger los codos."],"met":5.0,"uni":false,"img":["skull-crusher-start.webp","skull-crusher-peak.webp"]},{"id":"sled-push","n":"Empuje de Trineo","d":"Un ejercicio de acondicionamiento y fuerza de piernas: inclinado contra las barras verticales de un trineo cargado, lo desplazas por el suelo con pasos cortos y potentes. Las piernas y los glúteos empujan la carga mientras los brazos y el tronco se mantienen firmes, y la columna no soporta peso.","cat":"fuerza","g":"cuerpo completo","bp":"full_body","eq":"trineo","home":false,"bw":false,"lv":"intermedio","m":["gemelos","glúteo mayor","cuádriceps"],"m2":["isquiotibiales","abdominales","tríceps"],"ins":["Carga el trineo y colócate detrás, sujetando las barras verticales con las manos aproximadamente a la altura del pecho.","Inclínate hacia delante de modo que el cuerpo forme una línea diagonal recta desde la cabeza hasta el talón trasero, con los brazos extendidos.","Aprieta el tronco e impulsa una rodilla hacia delante, empujando el suelo con el metatarso del pie trasero.","Sigue dando pasos cortos y potentes, empujando con fuerza cada pierna hacia atrás para hacer avanzar el trineo.","Mantén las caderas bajas y la espalda plana, y mira a poca distancia por delante del trineo.","Empuja durante la distancia o el tiempo previstos; luego detente con control y descansa antes del siguiente empuje."],"tips":["Mantente bajo con los brazos bloqueados o ligeramente flexionados; si te yergues, pierdes impulso y acabas empujando el trineo con los brazos.","Empuja con los metatarsos dando pasos cortos y rápidos en lugar de zancadas largas.","Elige una carga que puedas mantener en movimiento a un ritmo constante; si el trineo se detiene, la carga es demasiado pesada para la serie."],"met":6.0,"uni":false,"img":["sled-push-main.webp"]},{"id":"sled-row","n":"Remo con Trineo","d":"Un remo con carga: agarras el trineo y lo tiras hacia ti mientras caminas hacia atrás, trabajando la espalda con un arrastre continuo en lugar de repeticiones sueltas.","cat":"fuerza","g":"espalda","bp":"back","eq":"trineo","home":false,"bw":false,"lv":"intermedio","m":["dorsales"],"m2":["bíceps","glúteo mayor","deltoides posterior","romboides","trapecio"],"ins":["Carga el trineo y agarra sus postes con ambas manos, una en cada poste.","Ponte de pie frente al trineo con los brazos estirados y el torso ligeramente inclinado hacia atrás contra la carga.","Tira del trineo hacia ti llevando los codos atrás y da un paso corto hacia atrás al mismo tiempo.","Estira los brazos de nuevo, da otro paso atrás y repite el tirón.","Continúa por distancia o por tiempo, manteniendo un ritmo constante de tirón y paso."],"tips":["Pecho arriba y espalda recta: deja que las piernas te lleven hacia atrás en vez de encorvarte sobre el trineo.","Usa una carga que puedas mover de forma continua; la idea es un arrastre constante, no un tirón máximo.","Si tu gimnasio tiene asas o una cuerda para el trineo, funcionan igual."],"met":6.0,"uni":false,"img":["sled-row-start.webp","sled-row-peak.webp"]},{"id":"smith-machine-bench-press","n":"Press de Banca en Máquina Smith","d":"Un press de banca en máquina Smith cuyo recorrido guiado permite entrenar el pecho con menos demanda de estabilización.","cat":"fuerza","g":"pecho","bp":"chest","eq":"máquina Smith","home":false,"bw":false,"lv":"principiante","m":["pectoral"],"m2":["deltoides anterior","tríceps"],"ins":["Acuéstate en un banco plano dentro de la máquina Smith.","Agarra la barra ligeramente más ancho que el ancho de hombros y desbloquéala.","Baja la barra con control hasta el centro del pecho.","Haz una breve pausa sin rebotar.","Empuja la barra hacia arriba hasta extender completamente los brazos.","Repite el número de repeticiones deseado."],"tips":["Alinea el banco para que la barra baje a la mitad del pecho.","Mantén los pies firmes en el suelo durante toda la serie.","Aprende el giro de muñeca para enganchar la barra antes de cargar peso."],"met":6.0,"uni":false,"img":["smith-machine-bench-press-start.webp","smith-machine-bench-press-peak.webp"]},{"id":"smith-machine-bent-over-row","n":"Remo Inclinado en Máquina Smith","d":"Un remo inclinado en máquina Smith que trabaja dorsales y romboides con una trayectoria de barra fija.","cat":"fuerza","g":"espalda","bp":"back","eq":"máquina Smith","home":false,"bw":false,"lv":"principiante","m":["dorsales","romboides"],"m2":["bíceps","lumbares","trapecio"],"ins":["De pie dentro de la máquina Smith con los pies al ancho de los hombros.","Agarra la barra en pronación ligeramente más ancho que los hombros.","Bisagra en las caderas hasta que el torso esté aproximadamente a 45 grados.","Tira de la barra hacia el pecho inferior llevando los codos hacia atrás.","Aprieta los omóplatos en la parte superior.","Baja la barra con control y repite."],"tips":["Mantén la espalda recta y el core firme en la inclinación.","No te incorpores al tirar; el ángulo del torso no cambia.","Evita encoger los hombros hacia las orejas durante el remo."],"met":6.0,"uni":false,"img":["smith-machine-bent-over-row-start.webp","smith-machine-bent-over-row-peak.webp"]},{"id":"smith-machine-bulgarian-split","n":"Sentadilla Búlgara en Máquina Smith","d":"Una sentadilla búlgara realizada en la máquina Smith para mayor estabilidad y control de la carga.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"máquina Smith","home":false,"bw":false,"lv":"intermedio","m":["glúteo mayor","cuádriceps"],"m2":["isquiotibiales"],"ins":["Coloca un banco detrás de la máquina Smith. Apoya la barra sobre los trapecios.","Coloca el pie trasero en el banco y el pie delantero hacia adelante.","Baja la rodilla trasera hacia el suelo.","Empuja con el talón delantero para volver.","Repite de ambos lados."],"tips":["La máquina Smith guía la trayectoria de la barra.","Concéntrate en mantener la rodilla delantera alineada sobre los dedos del pie."],"met":6.0,"uni":true,"img":["smith-machine-bulgarian-split-start.webp","smith-machine-bulgarian-split-peak.webp"]},{"id":"smith-machine-calf-raise","n":"Elevación de Talón en Máquina Smith","d":"Una elevación de talones en máquina Smith de pie sobre una plataforma, que aísla los gemelos con un estiramiento completo.","cat":"fuerza","g":"piernas","bp":"lower_legs","eq":"máquina Smith","home":false,"bw":false,"lv":"principiante","m":["gemelos"],"m2":["sóleo"],"ins":["Coloca la barra de la máquina Smith sobre la parte superior de la espalda y los hombros.","De pie sobre una pequeña plataforma para que los talones puedan bajar por debajo de los dedos.","Desbloquea la barra y elévate sobre las puntas de los pies.","Aprieta las pantorrillas con fuerza en la parte superior.","Baja los talones por debajo de la plataforma para un estiramiento completo.","Repite el número de repeticiones deseado."],"tips":["Haz una pausa arriba y otra abajo para eliminar el rebote.","No dobles las rodillas; el movimiento sale solo del tobillo.","Mantén el cuerpo erguido, sin inclinarte hacia delante."],"met":5.0,"uni":false,"img":["smith-machine-calf-raise-start.webp","smith-machine-calf-raise-peak.webp"]},{"id":"smith-machine-decline-bench-press","n":"Press de Banca Declinado en Máquina Smith","d":"Un press de banca en banco declinado bajo la máquina Smith, donde el ángulo con la cabeza abajo y la trayectoria guiada llevan el trabajo al pectoral inferior.","cat":"fuerza","g":"pecho","bp":"chest","eq":"máquina Smith","home":false,"bw":false,"lv":"principiante","m":["pectoral"],"m2":["deltoides anterior","tríceps"],"ins":["Coloca un banco declinado en la máquina de modo que la barra quede alineada con tu pecho inferior al tumbarte, y engancha las piernas bajo los rodillos.","Túmbate con la cabeza en el extremo bajo, toma un agarre prono algo más ancho que los hombros y desengancha la barra.","Baja la barra de forma controlada hasta que toque el pecho inferior, manteniendo los codos a unos cuarenta y cinco grados del torso.","Empuja la barra hacia arriba hasta extender los brazos, sin bloquear los codos con fuerza.","Repite el número de repeticiones deseado y vuelve a enganchar la barra antes de soltar las piernas."],"tips":["Alinea el banco antes de cargarlo. La barra solo se mueve en un plano, así que si el banco está unos centímetros desviado la barra te llegará a la garganta o al estómago en lugar del pecho inferior.","Asegura primero las piernas bajo los rodillos. Con la cabeza abajo y sin sujeción, te deslizarás hacia el extremo bajo del banco en la primera repetición dura.","Incorpórate despacio entre series. Las series largas con la cabeza por debajo del corazón marean a mucha gente, y esta es la variante donde ocurre."],"met":6.0,"uni":false,"img":["smith-machine-decline-bench-press-start.webp","smith-machine-decline-bench-press-peak.webp"]},{"id":"smith-machine-front-squat","n":"Sentadilla Frontal en Máquina Smith","d":"Una sentadilla en máquina Smith con la barra apoyada al frente sobre los hombros, donde la trayectoria fija y el torso erguido mantienen el trabajo en los cuádriceps.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"máquina Smith","home":false,"bw":false,"lv":"principiante","m":["glúteo mayor","cuádriceps"],"m2":["lumbares","glúteo medio","isquiotibiales"],"ins":["Coloca la barra a la altura del pecho alto y métete debajo para que se apoye al frente de los hombros, contra las clavículas.","Cruza los brazos sobre la barra o toma un agarre frontal abierto, y sube los codos hasta que los brazos queden casi paralelos al suelo.","Desengancha la barra y separa los pies aproximadamente al ancho de los hombros, ligeramente por delante de ella.","Baja en línea recta manteniendo los codos altos y el torso erguido, hasta que los muslos queden al menos paralelos al suelo.","Empuja desde el medio de los pies para volver a subir y repite el número de repeticiones deseado."],"tips":["Los codos altos son toda la ejercicio. En cuanto bajan, la barra rueda de los hombros hacia las manos y la posición frontal se desmorona.","Ajusta los topes de seguridad justo por debajo de tu posición más profunda antes de desenganchar nada: en una sentadilla frontal, soltar la barra es la salida más rápida de una repetición fallida.","Colocarte ligeramente por delante de la barra te permite mantener el torso vertical. Con una trayectoria fija, situarte justo debajo de la barra te obliga a inclinarte y empuja la barra fuera del apoyo frontal."],"met":6.0,"uni":false,"img":["smith-machine-front-squat-start.webp","smith-machine-front-squat-peak.webp"]},{"id":"smith-machine-good-morning","n":"Buenos Días en Máquina Smith","d":"Una bisagra de cadera con la barra de la máquina Smith apoyada sobre la espalda alta, inclinándote hacia delante desde las caderas contra una trayectoria fija para cargar isquiotibiales y erectores espinales.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"máquina Smith","home":false,"bw":false,"lv":"principiante","m":["lumbares","isquiotibiales"],"m2":["glúteo mayor"],"ins":["Coloca la barra a la altura de la espalda alta, métete debajo y apóyala sobre los trapecios; desengánchala con los pies al ancho de las caderas.","Flexiona ligeramente las rodillas y déjalas así: esto es una bisagra, no una sentadilla.","Empuja las caderas rectas hacia atrás y deja que el torso se incline hacia delante, con la espalda plana y la cabeza en línea con la columna.","Detente cuando sientas un estiramiento fuerte en los isquiotibiales, con el torso cerca de la paralela al suelo.","Lleva las caderas hacia delante para volver a erguirte, aprieta los glúteos arriba y repite las repeticiones deseadas."],"tips":["Usa mucho menos peso del que usarías en una sentadilla. Abajo, la barra queda muy lejos de tus caderas, y ese brazo de palanca, no el número en la barra, es lo que cuesta el ejercicio.","Caderas atrás, no pecho abajo. Si el torso baja sin que las caderas retrocedan, estás flexionando la columna en lugar de hacer bisagra en la cadera.","Termina el recorrido donde tu espalda empezaría a redondearse. En un buenos días la profundidad la marcan tus isquiotibiales, y la máquina te llevará encantada más allá de ese punto."],"met":6.0,"uni":false,"img":["smith-machine-good-morning-start.webp","smith-machine-good-morning-peak.webp"]},{"id":"smith-machine-hip-thrust","n":"Hip Thrust en Máquina Smith","d":"Un empuje de cadera con la barra en las guías de la máquina Smith, de modo que la carga recorre una línea vertical fija sobre las caderas mientras los hombros quedan apoyados en un banco.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"máquina Smith","home":false,"bw":false,"lv":"principiante","m":["glúteo mayor","glúteo medio"],"m2":["isquiotibiales"],"ins":["Coloca un banco plano dentro de la máquina Smith, paralelo a la barra y situado de forma que la barra quede sobre el pliegue de tu cadera.","Baja la barra lo suficiente para poder pasar por debajo sentado en el suelo, y apoya la parte alta de la espalda en el banco.","Rueda la barra sobre las caderas, ponle una almohadilla si la necesitas y desengánchala, con los pies planos y a la anchura de las caderas.","Empuja con los talones y extiende las caderas hasta que muslos y torso formen una línea recta, apretando los glúteos arriba.","Baja las caderas de forma controlada hasta quedar justo por encima del suelo y repite el número de repeticiones deseado."],"tips":["Alinea el banco antes de cargar la barra. La barra solo sube y baja en vertical, así que si el banco está desplazado la barra acaba sobre el abdomen o los muslos, y a mitad de serie no hay forma de corregirlo.","Pon los topes de seguridad donde queda la barra al final del recorrido. Salir de debajo de una barra Smith cargada estando en el suelo es incómodo, y con los topes deja de ser un problema.","Mira a un punto por delante de ti en lugar de al techo. Mantener la barbilla recogida evita que el movimiento acabe en un arqueo lumbar al bloquear arriba."],"met":6.0,"uni":false,"img":["smith-machine-hip-thrust-start.webp","smith-machine-hip-thrust-peak.webp"]},{"id":"smith-machine-incline-bench-press","n":"Press Inclinado en Máquina Smith","d":"Un press inclinado en máquina Smith que enfatiza la parte superior del pecho y los deltoides anteriores con una trayectoria guiada.","cat":"fuerza","g":"pecho","bp":"chest","eq":"máquina Smith","home":false,"bw":false,"lv":"principiante","m":["deltoides anterior","pectoral"],"m2":["tríceps"],"ins":["Ajusta un banco inclinado a 30-45 grados dentro de la máquina Smith.","Recuéstate y agarra la barra ligeramente más ancho que el ancho de hombros.","Desbloquea y baja la barra hasta la parte superior del pecho.","Haz una breve pausa en la parte inferior.","Empuja la barra hacia arriba hasta extender los brazos.","Repite el número de repeticiones deseado."],"tips":["Ajusta la posición del banco para que la barra llegue a la parte alta del pecho.","Baja la barra sin rebotarla en el pecho.","Mantén los glúteos en el banco y los pies bien apoyados."],"met":6.0,"uni":false,"img":["smith-machine-incline-bench-press-start.webp","smith-machine-incline-bench-press-peak.webp"]},{"id":"smith-machine-rdl","n":"Peso Muerto Rumano en Máquina Smith","d":"Un peso muerto rumano realizado en la máquina Smith, que fija la trayectoria de la barra para que puedas concentrarte en la bisagra de cadera y el estiramiento de la cadena posterior.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"máquina Smith","home":false,"bw":false,"lv":"principiante","m":["isquiotibiales"],"m2":["lumbares","glúteo mayor","trapecio"],"ins":["Ajusta la barra de la máquina Smith a la altura de la mitad del muslo y colócate frente a ella con los pies al ancho de las caderas, tan cerca que la barra toque los muslos.","Desbloquea la barra con agarre en pronación justo por fuera de las caderas.","Empuja las caderas hacia atrás mientras deslizas la barra por la parte delantera de las piernas.","Baja hasta sentir un estiramiento profundo en los isquiotibiales, con la espalda plana y las rodillas ligeramente flexionadas.","Empuja las caderas hacia adelante para volver a la posición de pie, manteniendo la barra cerca del cuerpo.","Repite el número de repeticiones recomendado."],"tips":["La barra está guiada en una trayectoria recta — úsala para perfeccionar el patrón de bisagra.","No redondees la zona lumbar al bajar; detente al final del rango de los isquiotibiales."],"met":6.0,"uni":false,"img":["smith-machine-rdl-start.webp","smith-machine-rdl-peak.webp"]},{"id":"smith-machine-reverse-grip-bent-over-row","n":"Remo Inclinado con Agarre Inverso en Máquina Smith","d":"Un remo inclinado con agarre supino en máquina Smith, que dirige el trabajo a los dorsales y bíceps.","cat":"fuerza","g":"espalda","bp":"back","eq":"máquina Smith","home":false,"bw":false,"lv":"principiante","m":["bíceps","dorsales"],"m2":["lumbares","romboides","trapecio"],"ins":["De pie dentro de la máquina Smith y agarra la barra con agarre en supinación.","Bisagra hacia adelante en las caderas hasta que el torso esté aproximadamente a 45 grados.","Mantén la espalda plana y el core contraído.","Tira de la barra hacia el abdomen inferior.","Aprieta los dorsales y los omóplatos en la parte superior.","Baja la barra con control y repite."],"tips":["Mantén las muñecas rectas; el agarre supino las carga más.","No conviertas el remo en un curl; tira con la espalda.","Evita incorporarte al tirar; el torso mantiene su inclinación."],"met":6.0,"uni":false,"img":["smith-machine-reverse-grip-bent-over-row-start.webp","smith-machine-reverse-grip-bent-over-row-peak.webp"]},{"id":"smith-machine-reverse-lunge","n":"Zancada Inversa en Máquina Smith","d":"Una zancada inversa bajo la barra de la máquina Smith, dando un paso atrás con un pie y devolviéndolo a la posición de pie en cada repetición mientras la barra guiada mantiene la carga estable.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"máquina Smith","home":false,"bw":false,"lv":"intermedio","m":["glúteo mayor","cuádriceps"],"m2":["glúteo medio","isquiotibiales"],"ins":["Coloca la barra de modo que descanse sobre los trapecios altos al estar de pie y desengánchala con los pies bajo las caderas.","Da un paso recto hacia atrás con un pie y baja la rodilla trasera hacia el suelo, manteniendo la tibia delantera vertical y la mayor parte del peso en el pie delantero.","Detente cuando la rodilla trasera esté a punto de tocar el suelo y el muslo delantero quede aproximadamente paralelo a él.","Empuja con el talón delantero y devuelve el pie trasero a la posición de pie bajo la barra.","Completa todas las repeticiones de un lado y luego cambia de pierna, o alterna las piernas en cada repetición."],"tips":["Da un paso atrás lo bastante largo. Un paso corto lleva la rodilla delantera muy por delante de los dedos, y la trayectoria fija de la barra no te dejará corregirlo una vez cargado.","El pie que se desplaza hace todo el recorrido; el pie delantero no se mueve en absoluto. Si cambia de sitio entre repeticiones, tu paso es demasiado largo o demasiado corto.","La máquina te quita el equilibrio, no la carga: mantén el tronco firme y levántate desde abajo en lugar de recostarte contra la barra."],"met":6.0,"uni":true,"img":["smith-machine-reverse-lunge-start.webp","smith-machine-reverse-lunge-peak.webp"]},{"id":"smith-machine-shoulder-press","n":"Press de Hombros en Máquina Smith","d":"Un press vertical para deltoides en máquina Smith realizado sentado en un banco, con la barra estabilizada por los raíles.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"máquina Smith","home":false,"bw":false,"lv":"principiante","m":["deltoides anterior","deltoides lateral"],"m2":["trapecio","tríceps"],"ins":["Siéntate en un banco colocado dentro de una máquina Smith.","Agarra la barra ligeramente más ancha que el ancho de los hombros a la altura de los hombros.","Desrackea la barra y empújala por encima de la cabeza hasta que los brazos estén extendidos.","Baja la barra de vuelta a la altura de los hombros de forma controlada.","Mantén el core contraído durante todo el ejercicio.","Repite el número de repeticiones deseado."],"tips":["Sitúate de forma que la barra no roce la cabeza al subir.","Evita arquear la zona lumbar al empujar.","Suelta el aire en la subida de cada repetición."],"met":6.0,"uni":false,"img":["smith-machine-shoulder-press-start.webp","smith-machine-shoulder-press-peak.webp"]},{"id":"smith-machine-shrug","n":"Encogimiento de Hombros en Máquina Smith","d":"Un encogimiento de hombros en máquina Smith que aísla el trapecio sin necesidad de estabilizar la barra.","cat":"fuerza","g":"espalda","bp":"back","eq":"máquina Smith","home":false,"bw":false,"lv":"principiante","m":["trapecio"],"m2":["antebrazo"],"ins":["Párate erguido dentro de una máquina Smith con la barra a la altura de los muslos.","Agarra la barra ligeramente más ancha que el ancho de los hombros con agarre prono.","Desrackea la barra y deja que cuelgue frente a tus muslos.","Encoge los hombros hacia arriba en dirección a las orejas.","Mantén la posición alta un momento, luego baja lentamente.","Repite el número de repeticiones deseado."],"tips":["Evita rotar los hombros; súbelos y bájalos en vertical.","No tires con los bíceps; los brazos solo sostienen la barra.","Mantén el cuello relajado y la mirada al frente."],"met":5.0,"uni":false,"img":["smith-machine-shrug-start.webp","smith-machine-shrug-peak.webp"]},{"id":"smith-machine-split-squat","n":"Sentadilla en Tijera en Máquina Smith","d":"Una sentadilla en tijera estática bajo la barra de la máquina Smith, con el pie trasero apoyado en el suelo en lugar de un banco, de modo que la trayectoria guiada quita el equilibrio de un movimiento unilateral.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"máquina Smith","home":false,"bw":false,"lv":"intermedio","m":["glúteo mayor","cuádriceps"],"m2":["isquiotibiales"],"ins":["Coloca la barra en los ganchos justo por debajo de la altura de los hombros, métete debajo y apóyala sobre los trapecios altos.","Desengancha la barra y da una zancada larga hacia delante con un pie, dejando el pie trasero apoyado en el suelo con el talón elevado.","Comprueba que la tibia delantera quedará vertical al bajar; ajusta la longitud de la zancada antes de empezar a cargarla.","Baja en línea recta flexionando ambas rodillas hasta que la rodilla trasera quede justo por encima del suelo y el muslo delantero cerca de la paralela.","Empuja con el talón delantero para volver al inicio sin mover los pies, y repite las repeticiones deseadas antes de cambiar de lado."],"tips":["Fija primero la longitud de la zancada sin carga. Una vez que la barra está sobre tu espalda, la trayectoria fija no te dejará avanzar para corregir una posición demasiado corta.","Baja recto, no hacia delante. La barra solo puede desplazarse en vertical, así que empujar la cadera hacia delante únicamente adelanta la rodilla más allá de los dedos.","Haz el mismo número de repeticiones por lado y empieza por la pierna más débil, ya que una sentadilla en tijera guiada oculta una diferencia entre lados que una barra libre dejaría en evidencia."],"met":6.0,"uni":true,"img":["smith-machine-split-squat-start.webp","smith-machine-split-squat-peak.webp"]},{"id":"smith-machine-squat","n":"Sentadilla en Máquina Smith","d":"Una sentadilla guiada en máquina Smith con la barra sobre los trapecios, que trabaja cuádriceps y glúteos con trayectoria fija.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"máquina Smith","home":false,"bw":false,"lv":"principiante","m":["glúteo mayor","cuádriceps"],"m2":["lumbares","glúteo medio","isquiotibiales"],"ins":["Ajusta la barra de la máquina Smith a la altura de los hombros y colócate debajo de ella.","Apoya la barra sobre tus trapecios superiores y desrackéala.","Párate con los pies al ancho de los hombros, ligeramente por delante de la barra.","Desciende hasta que los muslos queden paralelos al suelo.","Empuja a través de los talones para volver a la posición de pie.","Repite el número de repeticiones deseado."],"tips":["Coloca los pies ligeramente por delante de la barra.","Baja hasta que los muslos queden paralelos al suelo.","Empuja con los talones para volver a subir."],"met":6.0,"uni":false,"img":["smith-machine-squat-start.webp","smith-machine-squat-peak.webp"]},{"id":"smith-machine-upright-row","n":"Remo al Mentón en Máquina Smith","d":"Un remo al mentón en máquina Smith, tirando de la barra guiada por delante del torso con los codos al frente, para trabajar los deltoides laterales y el trapecio superior.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"máquina Smith","home":false,"bw":false,"lv":"principiante","m":["deltoides lateral","trapecio"],"m2":["deltoides anterior","bíceps"],"ins":["Coloca la barra a la altura de las caderas, toma un agarre prono algo más ancho que los hombros y sitúate cerca de ella con los brazos estirados.","Desengancha la barra y ponte erguido con los hombros atrás y el core activado.","Tira de la barra en línea recta por delante del cuerpo, guiando con los codos y manteniendo la barra cerca.","Detente cuando la barra llegue al pecho inferior y los codos queden a la altura de los hombros, y haz una pausa breve.","Baja la barra de forma controlada hasta estirar los brazos de nuevo y repite las repeticiones deseadas."],"tips":["Detente a la altura del pecho. Tirar de la barra hasta la clavícula rota el hombro hacia la posición que provoca el pinzamiento por el que este ejercicio es conocido.","Guía con los codos, no con las manos. Si las muñecas suben primero, toman el relevo los bíceps y los deltoides laterales apenas trabajan.","Abre el agarre si el movimiento pincha. Un agarre estrecho fuerza más rotación interna, y la trayectoria fija de la barra no te deja ninguna alternativa."],"met":6.0,"uni":false,"img":["smith-machine-upright-row-start.webp","smith-machine-upright-row-peak.webp"]},{"id":"snatch","n":"Arrancada","d":"Un levantamiento olímpico que tira de la barra desde el suelo hasta encima de la cabeza en un solo movimiento, recibida en una sentadilla por encima de la cabeza.","cat":"olímpico","g":"cuerpo completo","bp":"full_body","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["glúteo mayor","cuádriceps","trapecio"],"m2":["lumbares","isquiotibiales","deltoides lateral"],"ins":["Párate con los pies al ancho de las caderas y agarra la barra con un agarre ancho.","Inclínate hacia abajo manteniendo la espalda plana y el pecho arriba.","Extiende explosivamente caderas, rodillas y tobillos para impulsar la barra hacia arriba.","Colócate debajo de la barra en una sentadilla por encima de la cabeza.","Levántate con la barra bloqueada por encima de la cabeza.","Devuelve la barra al suelo y repite."],"tips":["Mantén la barra cerca del cuerpo mientras sube.","Extiende completamente las caderas antes de tirar por debajo de la barra.","Bloquea los brazos y estabiliza antes de ponerte de pie."],"met":8.0,"uni":false,"img":["snatch-start.webp","snatch-peak.webp"]},{"id":"sphinx-pose","n":"Postura de la Esfinge","d":"Una extensión suave boca abajo sobre los antebrazos: los codos quedan bajo los hombros y el pecho se eleva, de modo que la zona lumbar se extiende sin esfuerzo de los brazos.","cat":"estiramiento","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["lumbares"],"m2":["flexores de cadera","pectoral"],"ins":["Túmbate boca abajo y apoya los antebrazos en el suelo con los codos justo bajo los hombros.","Presiona los antebrazos y el empeine contra el suelo y eleva el pecho.","Aleja los hombros de las orejas y alarga la nuca.","Mantén la posición durante el tiempo indicado, respirando hacia la parte frontal del pecho.","Baja el pecho al suelo y descansa."],"tips":["Desliza los codos algo hacia delante para una extensión más suave, o hacia atrás para una más profunda.","Mantén los glúteos blandos para que la zona lumbar no se apriete.","Quédate donde se siente estiramiento, no pinzamiento."],"met":5.0,"uni":false,"img":["sphinx-pose-main.webp"]},{"id":"spider-curl","n":"Curl Araña","d":"Un curl tumbado boca abajo en banco inclinado con los brazos colgando verticales, aislando el bíceps en un rango estricto.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["bíceps"],"m2":["braquial"],"ins":["Túmbate boca abajo en un banco inclinado con los brazos colgando rectos hacia abajo.","Sostén una mancuerna en cada mano con agarre supino.","Mantén los brazos superiores verticales mientras curleas los pesos hacia arriba.","Aprieta fuerte los bíceps en la parte superior.","Baja las mancuernas de forma controlada hasta la extensión completa.","Repite el número de repeticiones deseado."],"tips":["Mantén el pecho pegado al respaldo durante toda la serie.","Aprieta arriba sin dejar que los codos se desplacen hacia atrás.","Usa el rango completo: el estiramiento abajo es la mitad del beneficio."],"met":5.0,"uni":false,"img":["spider-curl-start.webp","spider-curl-peak.webp"]},{"id":"spiderman-push-up","n":"Flexión Spiderman","d":"Una flexión en la que se lleva una rodilla hacia el codo del mismo lado mientras el cuerpo baja, como una araña trepando por una pared. Trabaja el pecho, los hombros y los tríceps, mientras los oblicuos y los flexores de cadera mantienen estable el tronco.","cat":"fuerza","g":"pecho","bp":"chest","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["pectoral","tríceps"],"m2":["deltoides anterior","flexores de cadera","oblicuos","abdominales","serrato"],"ins":["Colócate en plancha alta con las manos algo más abiertas que los hombros y el cuerpo en línea recta.","Empieza a bajar el pecho hacia el suelo y, al mismo tiempo, levanta un pie del suelo.","Lleva esa rodilla hacia fuera y arriba, hacia el codo del mismo lado, manteniendo la cadera baja.","Empuja para volver a la plancha mientras devuelves la pierna a la posición inicial.","Repite del otro lado y sigue alternando."],"tips":["Mantén la cadera nivelada; si la subes en pica o la hundes, el tronco deja de trabajar.","Lleva la rodilla hacia el codo sin que el pie toque el suelo.","Baja con control y mantén los codos a unos 45 grados del cuerpo."],"met":5.0,"uni":false,"img":["spiderman-push-up-start.webp","spiderman-push-up-peak.webp"]},{"id":"split-jerk","n":"Jerk con Tijera","d":"Un levantamiento por encima de la cabeza que impulsa la barra con una flexión de piernas y la recibe en posición de tijera con los brazos bloqueados.","cat":"olímpico","g":"cuerpo completo","bp":"full_body","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["deltoides anterior","cuádriceps"],"m2":["glúteo mayor","trapecio","tríceps"],"ins":["Sostén la barra en el rack frontal con los codos altos.","Baja recto doblando ligeramente las rodillas.","Impulsa la barra por encima de la cabeza explosivamente con piernas y brazos.","Abre los pies hacia adelante y hacia atrás mientras la barra se bloquea.","Levántate juntando los pies bajo la barra.","Baja la barra y repite."],"tips":["Flexiona recto hacia abajo en lugar de inclinar el torso hacia delante.","Separa los pies adelante y atrás mientras la barra se bloquea.","Al recuperarte, lleva primero el pie delantero hacia atrás."],"met":8.0,"uni":false,"img":["split-jerk-start.webp","split-jerk-peak.webp"]},{"id":"split-squat","n":"Sentadilla en Tijera","d":"Una zancada estática bajando en línea recta con las piernas en tijera, desarrollando fuerza unilateral sin dar el paso.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["glúteo mayor","cuádriceps"],"m2":["glúteo medio","isquiotibiales"],"ins":["Párate en posición de tijera con un pie adelante y otro atrás.","Mantén el torso erguido y el core contraído.","Baja las caderas rectas hacia abajo doblando ambas rodillas.","Detente cuando la rodilla trasera esté justo por encima del suelo.","Empuja a través del talón delantero para volver al inicio.","Completa las repeticiones de un lado y luego cambia."],"tips":["Baja en línea recta en lugar de lanzarte hacia delante.","Mantén la mayor parte del peso sobre el pie delantero.","Mantén el talón delantero apoyado durante toda la repetición."],"met":6.0,"uni":true,"img":["split-squat-start.webp","split-squat-peak.webp"]},{"id":"spoto-press","n":"Press Spoto","d":"Un press de banca con barra que incluye una pausa con la barra suspendida sobre el pecho, eliminando el rebote.","cat":"fuerza","g":"pecho","bp":"chest","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["pectoral"],"m2":["deltoides anterior","tríceps"],"ins":["Túmbate en un banco plano y agarra la barra ligeramente más ancha que los hombros.","Desrackea la barra y sostenla sobre el pecho con los brazos extendidos.","Baja la barra hasta que quede a un centímetro por encima del pecho.","Mantén esa posición un segundo completo sin tocar el pecho.","Empuja la barra hacia arriba hasta que los brazos estén extendidos.","Repite el número de repeticiones deseado."],"tips":["Detén la barra a un par de centímetros del pecho.","Mantén la pausa un segundo completo sin tocar el pecho.","Conserva los omóplatos retraídos durante todo el recorrido."],"met":6.0,"uni":false,"img":["spoto-press-start.webp","spoto-press-peak.webp"]},{"id":"squat","n":"Sentadilla Trasera con Barra","d":"Un movimiento compuesto de tren inferior que trabaja cuádriceps, glúteos e isquiotibiales.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["glúteo mayor","cuádriceps"],"m2":["lumbares","isquiotibiales"],"ins":["Coloca la barra sobre tus trapecios superiores.","Desrackea y da un paso atrás, con los pies al ancho de los hombros.","Contrae el core y haz la sentadilla hasta que los muslos queden paralelos.","Empuja a través de los talones para volver a la posición de pie.","Repite."],"tips":["Mantén el pecho arriba durante todo el movimiento.","Empuja las rodillas hacia afuera en línea con los dedos de los pies."],"met":6.0,"uni":false,"img":["squat-start.webp","squat-peak.webp"]},{"id":"squat-hold","n":"Sentadilla Isométrica","d":"Una sentadilla estática en la que se mantienen los muslos aproximadamente paralelos al suelo y los brazos estirados al frente para mantener el equilibrio. Desarrolla resistencia en los cuádriceps y los glúteos sin equipo.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["glúteo mayor","cuádriceps"],"m2":["aductores","lumbares","glúteo medio","isquiotibiales"],"ins":["Colócate de pie con los pies a la anchura de los hombros y las puntas ligeramente hacia fuera.","Estira los brazos rectos al frente como contrapeso.","Baja en sentadilla hasta que los muslos queden paralelos al suelo, con el pecho erguido y los talones apoyados.","Mantén la posición, con las rodillas en línea con las puntas de los pies.","Ponte de pie para terminar."],"tips":["Reparte el peso por el centro de los pies y mantén los talones en el suelo.","No dejes que las rodillas se vayan hacia dentro ni que la espalda se redondee.","Aumenta el tiempo de mantenimiento poco a poco y descansa cuando los muslos empiecen a temblar."],"met":5.0,"uni":false,"img":["squat-hold-main.webp"]},{"id":"squat-pulse","n":"Sentadilla con Pulsos","d":"Una variante de la sentadilla con el peso corporal en la que bajas a la sentadilla y haces pulsos cortos y controlados, hacia arriba y hacia abajo, en la mitad inferior del movimiento sin llegar a ponerte de pie. La tensión constante mantiene trabajando los muslos y los glúteos durante toda la serie.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["glúteo mayor","cuádriceps"],"m2":["aductores","lumbares","isquiotibiales"],"ins":["Colócate de pie con los pies separados a la anchura de los hombros aproximadamente y las puntas ligeramente hacia fuera, con los brazos estirados al frente para mantener el equilibrio.","Baja en sentadilla hasta que los muslos queden al menos paralelos al suelo, con el pecho erguido y los talones apoyados.","Desde abajo, sube solo un poco, unos pocos centímetros, y vuelve a bajar.","Sigue haciendo pulsos en el rango inferior sin extender del todo las piernas ni descansar arriba.","Ponte de pie por completo cuando termines la serie."],"tips":["Mantén las rodillas en línea con las puntas de los pies; no dejes que se vayan hacia dentro.","Quédate en la mitad inferior de la sentadilla; ponerte de pie entre pulsos elimina la tensión que busca este ejercicio.","Haz los pulsos pequeños y rápidos, pero controlados; no rebotes en el fondo."],"met":5.0,"uni":false,"img":["squat-pulse-start.webp","squat-pulse-peak.webp"]},{"id":"stability-ball-hip-bridge","n":"Puente de Cadera con Balón de Estabilidad","d":"Un puente de glúteos con los pies sobre un balón de estabilidad, que añade demanda antirotación y de equilibrio al patrón básico del puente.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"fitball","home":true,"bw":false,"lv":"principiante","m":["glúteo mayor"],"m2":["isquiotibiales","abdominales"],"ins":["Túmbate boca arriba en el suelo y coloca ambos pies sobre un balón de estabilidad.","Los brazos descansan a los lados en el suelo para equilibrarte.","Aprieta los glúteos y presiona los talones contra el balón para elevar las caderas.","Termina con una línea recta desde los hombros hasta las rodillas.","Baja las caderas de forma controlada sin que el balón ruede.","Repite el número de repeticiones recomendado."],"tips":["El balón intentará desplazarse: mantén los pies presionados directamente hacia abajo.","Sin hiperextensión en la parte superior; detente cuando el cuerpo esté en línea."],"met":5.0,"uni":false,"img":["stability-ball-hip-bridge-start.webp","stability-ball-hip-bridge-peak.webp"]},{"id":"stability-ball-knee-tuck","n":"Encogimiento de Rodillas con Balón de Estabilidad","d":"Un encogimiento de rodillas en posición de plancha con los pies sobre un balón de estabilidad, rodando el balón hacia las caderas para trabajar el abdomen dinámicamente.","cat":"fuerza","g":"core","bp":"core","eq":"fitball","home":true,"bw":false,"lv":"intermedio","m":["abdominales"],"m2":["deltoides anterior","flexores de cadera","oblicuos","serrato"],"ins":["Comienza en plancha alta con las espinillas o el dorso de los pies sobre un balón de estabilidad.","Las manos están bajo los hombros y el cuerpo en línea recta.","Contrae el core y lleva el balón hacia el pecho encogiendo las rodillas.","Rueda de vuelta hacia afuera extendiendo completamente las piernas a la posición de plancha.","Repite el número de repeticiones recomendado."],"tips":["Las caderas no se elevan; mantén el tronco nivelado durante todo el encogimiento.","Los hombros permanecen sobre las muñecas: no dejes que se desplacen hacia adelante."],"met":6.0,"uni":false,"img":["stability-ball-knee-tuck-start.webp","stability-ball-knee-tuck-peak.webp"]},{"id":"stability-ball-push-up","n":"Push-Up con Balón de Estabilidad","d":"Un push-up realizado con los pies sobre un balón de estabilidad, que añade una fuerte demanda antirotación al push-up estándar.","cat":"fuerza","g":"pecho","bp":"chest","eq":"fitball","home":true,"bw":false,"lv":"intermedio","m":["pectoral"],"m2":["deltoides anterior","abdominales","serrato","tríceps"],"ins":["Arrodíllate frente a un balón de estabilidad y coloca las espinillas o los pies encima.","Apoya las manos en el suelo bajo los hombros en posición de plancha alta.","Contrae fuerte el core: el balón querrá rodar hacia los lados.","Baja el pecho al suelo doblando los codos.","Vuelve a empujar hasta la posición inicial sin dejar que el balón se tambalee.","Repite el número de repeticiones recomendado."],"tips":["Comienza con las espinillas sobre el balón; solo con los pies es mucho más difícil.","Si el balón se desplaza de lado a lado, falta contracción del core: reduce la velocidad."],"met":6.0,"uni":false,"img":["stability-ball-push-up-start.webp","stability-ball-push-up-peak.webp"]},{"id":"stability-ball-push-up-hands-on-ball","n":"Flexión sobre pelota de estabilidad (manos en la pelota)","d":"Una flexión inclinada realizada con ambas manos sobre una pelota de estabilidad y los pies en el suelo. La superficie inestable exige más al pecho, los hombros y los tríceps, mientras el core mantiene el cuerpo rígido.","cat":"fuerza","g":"pecho","bp":"chest","eq":"fitball","home":true,"bw":false,"lv":"intermedio","m":["pectoral"],"m2":["deltoides anterior","abdominales","serrato","tríceps"],"ins":["Coloca ambas manos sobre una pelota de estabilidad y camina con los pies hacia atrás hasta una plancha con los brazos extendidos, el cuerpo en línea recta de la cabeza a los talones.","Activa el core y mantén la pelota firme bajo las manos.","Flexiona los codos para bajar el pecho hacia la pelota de forma controlada.","Empuja de nuevo hasta la extensión completa de los brazos sin dejar que la pelota ruede.","Repite las repeticiones deseadas."],"tips":["Mantén el cuerpo en una línea recta y rígida: no dejes que las caderas se hundan ni se eleven.","Muévete lento y con control; la inestabilidad de la pelota es lo que hace efectivo el ejercicio, así que resístela en lugar de combatirla con rapidez.","Coloca las manos algo más anchas que los hombros sobre la pelota y mantén los codos a unos 45 grados."],"met":6.0,"uni":false,"img":["stability-ball-push-up-hands-on-ball-start.webp","stability-ball-push-up-hands-on-ball-peak.webp"]},{"id":"stability-ball-wall-squat","n":"Sentadilla en Pared con Pelota","d":"Una sentadilla con peso corporal apoyando una pelota suiza entre la zona lumbar y la pared, que guía la columna.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"fitball","home":true,"bw":false,"lv":"principiante","m":["glúteo mayor","cuádriceps"],"m2":["isquiotibiales"],"ins":["Coloca una pelota suiza entre tu zona lumbar y una pared.","Adelanta los pies unos 30 cm, un poco más anchos que los hombros.","Baja en sentadilla mientras la pelota rueda por la espalda.","Detente cuando los muslos queden paralelos al suelo.","Empuja con los talones para volver a subir."],"tips":["Carga el peso en talones y medio del pie.","No dejes que las rodillas pasen las puntas de los pies.","La pelota debe rodar suavemente — no te separes de ella."],"met":6.0,"uni":false,"img":["stability-ball-wall-squat-start.webp","stability-ball-wall-squat-peak.webp"]},{"id":"stair-climber","n":"Escaladora de Escaleras","d":"Un ejercicio de máquina cardiovascular que sube escalón tras escalón por una escalera giratoria, cargando glúteos y cuádriceps de forma continua y sin impacto de aterrizaje.","cat":"cardio","g":"piernas","bp":"upper_legs","eq":"escaladora","home":false,"bw":false,"lv":"principiante","m":["glúteo mayor","cuádriceps"],"m2":["gemelos","glúteo medio","isquiotibiales","sóleo"],"ins":["Súbete al escalón inferior con la máquina en su ajuste más lento y sujeta los raíles con suavidad para equilibrarte.","Sube de escalón en escalón apoyando el pie entero en cada uno, no solo la punta.","Mantente erguido con el pecho abierto y la cadera bajo los hombros, sin encorvarte sobre la consola.","Empuja el escalón hacia abajo con el talón del pie adelantado y deja que el glúteo de esa pierna haga el trabajo.","Ajusta el ritmo para poder sostener la postura y sigue subiendo durante el tiempo o el número de pisos deseados."],"tips":["No te apoyes en los raíles ni cuelgues los antebrazos sobre ellos — descargar ahí el peso quita trabajo a las piernas y la pantalla deja de significar nada.","Pie entero sobre el escalón, talón incluido. Subir de puntillas traslada toda la sesión a los gemelos y los agota pronto.","Sube escalón a escalón antes de intentar saltártelos; una subida deliberada y erguida vale más que un trote rápido en la parte baja de la escalera."],"met":8.0,"uni":false,"img":["stair-climber-main.webp"]},{"id":"standing-calf-raise","n":"Elevación de Talones de Pie","d":"Una elevación de talones realizada de pie para desarrollar el gastrocnemio a través de un rango completo de movimiento.","cat":"fuerza","g":"piernas","bp":"lower_legs","eq":"máquina de gemelos","home":false,"bw":false,"lv":"principiante","m":["gemelos"],"m2":["sóleo"],"ins":["Párate en el borde de una plataforma o máquina de elevación de talones.","Baja los talones por debajo de la plataforma.","Empuja hacia arriba de puntillas.","Baja lentamente.","Repite."],"tips":["Haz una pausa en la parte superior para maximizar la contracción.","Bajar el talón completamente aumenta el rango de movimiento."],"met":5.0,"uni":false,"img":["standing-calf-raise-start.webp","standing-calf-raise-peak.webp"]},{"id":"standing-calf-stretch","n":"Estiramiento de Pantorrilla de Pie","d":"Un estiramiento en paso escalonado que alarga la pantorrilla presionando el talón trasero con la pierna estirada.","cat":"estiramiento","g":"piernas","bp":"lower_legs","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["gemelos"],"m2":["sóleo"],"ins":["Lleva un pie atrás a un paso escalonado.","Mantén la pierna trasera estirada y el talón presionado al suelo.","Flexiona la rodilla delantera e inclina el peso hacia adelante.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],"tips":["Mantén el talón trasero plano y los dedos al frente.","Flexiona un poco la rodilla trasera para trabajar la pantorrilla baja."],"met":5.0,"uni":true,"img":["standing-calf-stretch-main.webp"]},{"id":"standing-forward-fold","n":"Flexión de Pie hacia Adelante","d":"Un estiramiento de pie que alarga los isquiotibiales y la zona lumbar al inclinar el torso sobre las piernas estiradas.","cat":"estiramiento","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["isquiotibiales"],"m2":["lumbares","gemelos"],"ins":["Párate erguido con los pies al ancho de cadera y las piernas estiradas.","Flexiónate desde las caderas y baja el torso hacia el suelo.","Deja que las manos y la cabeza cuelguen hacia los pies.","Mantén de 20 a 30 segundos, respirando de forma constante."],"tips":["Flexiona un poco las rodillas si sientes tensos los isquiotibiales.","Entra en el estiramiento lentamente, nunca rebotes."],"met":5.0,"uni":false,"img":["standing-forward-fold-main.webp"]},{"id":"standing-forward-fold-to-half-lift","n":"Flexión de Pie a Media Elevación","d":"La articulación conocida como media elevación: desde una flexión de pie el pecho sube hasta dejar la espalda plana y la columna larga, y luego vuelve a plegarse. Enseña la diferencia entre una flexión redondeada y una bisagra con la columna larga.","cat":"estiramiento","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["lumbares","isquiotibiales"],"m2":["glúteo mayor"],"ins":["Ponte de pie con los pies a la anchura de las caderas y pliégate hacia delante desde las caderas.","Apoya las manos en las espinillas, en el suelo o en bloques.","Desliza las manos por las espinillas y eleva el pecho hasta dejar la espalda plana y la columna larga.","Vuelve a plegarte dejando que la cabeza y el cuello se relajen.","Sigue alternando entre ambas posiciones las veces indicadas."],"tips":["Deja una ligera flexión en las rodillas para que el movimiento venga de las caderas.","Sube a espalda plana en lugar de mirar hacia arriba; el cuello sigue a la columna.","Aleja los hombros de las orejas en la posición elevada."],"met":5.0,"uni":false,"img":["standing-forward-fold-to-half-lift-start.webp","standing-forward-fold-to-half-lift-peak.webp"]},{"id":"standing-quad-stretch","n":"Estiramiento de Cuádriceps de Pie","d":"Un estiramiento de equilibrio de pie que alarga el cuádriceps llevando el talón hacia el glúteo.","cat":"estiramiento","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["cuádriceps"],"m2":["flexores de cadera"],"ins":["Párate sobre una pierna, apoyándote en una pared si lo necesitas.","Flexiona la otra rodilla y agarra ese tobillo por detrás.","Lleva el talón hacia el glúteo, manteniendo las rodillas juntas.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],"tips":["Mete la pelvis hacia adentro para profundizar el estiramiento.","Mantén las rodillas juntas en todo momento."],"met":5.0,"uni":true,"img":["standing-quad-stretch-main.webp"]},{"id":"standing-side-bend","n":"Flexión Lateral de Pie","d":"Un estiramiento de pie que alarga los oblicuos y dorsales al estirar los brazos arriba e inclinarse a un lado.","cat":"estiramiento","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["oblicuos"],"m2":["dorsales","cuadrado lumbar"],"ins":["Párate con los pies al ancho de cadera y sube ambos brazos.","Junta las manos y estírate hacia arriba.","Inclínate suavemente a un lado en una curva larga.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],"tips":["Mantén ambos pies fijos y las caderas estables.","Estírate hacia arriba y al lado en vez de solo dejarte caer."],"met":5.0,"uni":true,"img":["standing-side-bend-main.webp"]},{"id":"standing-side-bend-flow","n":"Flexión Lateral de Pie Alterna","d":"Un flujo lateral de pie: los brazos se estiran por encima de la cabeza y el tronco se inclina de lado a lado con un ritmo controlado, alargando el costado sin sostener ninguna posición final.","cat":"estiramiento","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["oblicuos"],"m2":["dorsales","cuadrado lumbar"],"ins":["Ponte de pie con los pies a la anchura de las caderas y estira ambos brazos por encima de la cabeza.","Inclina el tronco hacia un lado manteniendo los pies apoyados y las caderas niveladas.","Vuelve por el centro con las costillas alineadas sobre la pelvis.","Inclínate hacia el otro lado del mismo modo.","Sigue alternando las veces indicadas."],"tips":["Inclínate solo lateralmente: si el pecho rota, se convierte en un giro.","Mantén ambos talones apoyados para que el movimiento se quede en el tronco.","Muévete con la respiración en lugar de rebotar al final del recorrido."],"met":5.0,"uni":false,"img":["standing-side-bend-flow-start.webp","standing-side-bend-flow-peak.webp"]},{"id":"standing-split","n":"Split de Pie","d":"Una flexión de pie con una pierna elevada por detrás: el torso se pliega sobre la pierna de apoyo mientras la pierna libre se eleva hacia el techo.","cat":"estiramiento","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"avanzado","m":["glúteo mayor","isquiotibiales"],"m2":["lumbares","cuádriceps"],"ins":["Desde una flexión hacia delante, apoya ambas manos en el suelo o en bloques junto al pie de apoyo.","Pasa el peso a una pierna y eleva la otra por detrás.","Mantén la pierna de apoyo estirada y las caderas tan niveladas como permita la elevación.","Mantén la posición durante el tiempo indicado, acercando el pecho a la espinilla de apoyo.","Baja el pie elevado y repite del otro lado."],"tips":["Nivela primero las caderas y acepta menos altura; abrir la cadera convierte esto en otra postura.","Usa bloques bajo las manos para que la columna pueda mantenerse larga.","Agarra el tobillo de apoyo con una mano solo cuando el equilibrio ya sea estable."],"met":5.0,"uni":true,"img":["standing-split-main.webp"]},{"id":"stationary-bike","n":"Bicicleta Estática","d":"Un ejercicio cardiovascular sentado que mueve un volante de inercia mediante un pedaleo continuo, trabajando las piernas sin impacto sobre las articulaciones.","cat":"cardio","g":"piernas","bp":"upper_legs","eq":"bicicleta estática","home":false,"bw":false,"lv":"principiante","m":["cuádriceps"],"m2":["gemelos","glúteo mayor","isquiotibiales","sóleo"],"ins":["Ajusta la altura del sillín para que la rodilla quede ligeramente flexionada en el punto más bajo del pedaleo, siéntate y apoya la parte anterior de los pies en los pedales.","Sujeta el manillar con un agarre relajado y siéntate erguido, con la espalda neutra y los hombros bajos.","Empuja un pedal hacia abajo y hacia delante mientras el otro sube, manteniendo el esfuerzo en las piernas en lugar de tirar del manillar.","Sigue pedaleando en un círculo suave y regular a una cadencia constante, respirando al ritmo del pedaleo.","Ajusta la resistencia para sostener el esfuerzo que buscas y continúa durante el tiempo o la distancia deseados."],"tips":["Ajusta el sillín antes de empezar: demasiado bajo castiga las rodillas y demasiado alto hace que la cadera bascule de lado a lado en cada pedalada.","Empuja con las piernas y mantén el tren superior quieto — agarrarte y tirar del manillar solo añade tensión en el cuello y los hombros.","Sube la resistencia en lugar de girar los pedales sueltos y rápidos; un volante ligero a cadencia alta se siente duro en los pulmones pero aporta poco a las piernas."],"met":8.0,"uni":false,"img":["stationary-bike-main.webp"]},{"id":"step-ups","n":"Step Ups","d":"Una subida a un cajón o banco con una pierna que entrena cuádriceps y glúteos de forma funcional.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["glúteo mayor","cuádriceps"],"m2":["gemelos","glúteo medio","isquiotibiales"],"ins":["Párate frente a una caja o banco resistente.","Coloca un pie completamente sobre la superficie de la caja.","Empuja a través de ese talón para subir el cuerpo a la caja.","Sube el pie de atrás para quedar completamente sobre la caja.","Baja con el mismo pie que subió primero.","Alterna piernas o completa todas las repeticiones de un lado antes de cambiar."],"tips":["Apoya todo el pie sobre la superficie del cajón.","Impulsa con el talón de la pierna que sube, no con la de atrás.","Controla el descenso en lugar de dejarte caer."],"met":5.0,"uni":false,"img":["step-ups-start.webp","step-ups-peak.webp"]},{"id":"stiff-leg-deadlift","n":"Peso Muerto con Piernas Rígidas","d":"Una bisagra de cadera con las piernas casi rectas, bajando la barra a lo largo de los muslos para estirar y cargar los isquiotibiales.","cat":"fuerza","g":"espalda","bp":"back","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["glúteo mayor","isquiotibiales"],"m2":["lumbares","trapecio"],"ins":["Párate con los pies al ancho de las caderas, sosteniendo una barra frente a los muslos.","Mantén las piernas casi rectas con solo una ligera flexión de rodillas.","Inclínate en las caderas y baja la barra a lo largo de las piernas.","Baja hasta donde la flexibilidad de los isquiotibiales lo permita con la espalda plana.","Empuja a través de los talones para volver a la posición erguida.","Repite el número de repeticiones deseado."],"tips":["Lleva las caderas hacia atrás y mantén la barra cerca de las piernas.","Baja solo hasta donde te permita mantener la espalda plana.","Siente la carga en los isquiotibiales al estirar y luego empuja las caderas hacia delante para subir."],"met":6.0,"uni":false,"img":["stiff-leg-deadlift-start.webp","stiff-leg-deadlift-peak.webp"]},{"id":"straight-arm-pulldown","n":"Jalón con Brazos Rectos","d":"Un ejercicio de aislamiento para los dorsales usando cable con los brazos rectos.","cat":"fuerza","g":"espalda","bp":"back","eq":"polea","home":false,"bw":false,"lv":"intermedio","m":["dorsales"],"m2":["deltoides posterior","tríceps"],"ins":["Párate frente a una máquina de cable con una barra recta enganchada a la polea alta.","Con los brazos casi rectos, empuja la barra hacia abajo en un arco hacia los muslos.","Aprieta los dorsales en la parte inferior.","Devuelve la barra lentamente a la posición inicial.","Repite."],"tips":["Mantén los brazos casi rectos durante todo el movimiento.","Lleva la barra hacia los muslos describiendo un arco.","Aprieta los dorsales en la parte baja del recorrido."],"met":5.0,"uni":false,"img":["straight-arm-pulldown-start.webp","straight-arm-pulldown-peak.webp"]},{"id":"straight-bar-cable-front-raise","n":"Elevación frontal en polea con barra recta","d":"Una elevación frontal en la polea baja sujetando una barra recta con ambas manos. A diferencia de la elevación frontal en polea a un brazo, los dos brazos mueven la misma barra y el cable mantiene la tensión sobre el deltoides anterior en todo el recorrido.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"polea","home":false,"bw":false,"lv":"intermedio","m":["deltoides anterior"],"m2":["deltoides lateral","pectoral"],"ins":["Engancha una barra recta a la polea baja y colócate de espaldas a la máquina, con el cable pasando por delante de las piernas.","Sujeta la barra en pronación con las manos a la anchura de los hombros y los brazos colgando estirados delante de los muslos.","Mantén los codos casi extendidos y el core firme para que el torso no se incline hacia atrás.","Eleva la barra hacia delante en un arco suave hasta la altura de los hombros.","Bájala de forma controlada hasta los muslos y repite las repeticiones deseadas."],"tips":["Usa poco peso: impulsar la barra con las piernas o inclinarte hacia atrás quita el trabajo al deltoides anterior.","Detente a la altura de los hombros; subir más traslada la carga al trapecio.","Mantén las muñecas neutras en lugar de dejar que se doblen bajo la barra."],"met":5.0,"uni":false,"img":["straight-bar-cable-front-raise-start.webp","straight-bar-cable-front-raise-peak.webp"]},{"id":"straight-bar-dips","n":"Fondos en Barra Recta","d":"Un fondo realizado encima de una sola barra recta en lugar de paralelas: desde un apoyo con los brazos estirados sobre la barra, el cuerpo baja hasta que el pecho queda cerca de la barra y vuelve a subir.","cat":"fuerza","g":"pecho","bp":"chest","eq":"barra de dominadas","home":true,"bw":false,"lv":"intermedio","m":["pectoral"],"m2":["tríceps"],"ins":["Agarra una barra recta en prono, algo más abierto que la anchura de los hombros, y salta a un apoyo con los brazos estirados encima de ella, con la barra a la altura de las caderas.","Inclina ligeramente el pecho hacia delante y flexiona los codos para bajar hacia la barra, con los codos apuntando hacia atrás.","Detente cuando la barra quede cerca de la parte alta del pecho o en el punto más bajo que puedas controlar.","Empuja la barra hacia abajo para estirar los brazos y volver a la posición de apoyo.","Repite el número de repeticiones deseado."],"tips":["Inclina el pecho hacia delante sobre la barra al bajar; la barra queda delante de ti y, si te mantienes erguido, te vas hacia atrás.","Contrae el core para evitar que el cuerpo se balancee.","Esta posición de muñeca y hombro es más exigente que los fondos estándar -- aumenta el volumen gradualmente."],"met":6.0,"uni":false,"img":["straight-bar-dips-start.webp","straight-bar-dips-peak.webp"]},{"id":"strict-curl","n":"Curl Estricto","d":"Un curl de pie realizado sin ningún impulso corporal — el torso permanece quieto y los codos se mantienen fijos, de modo que el bíceps hace todo el trabajo.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["bíceps"],"m2":["braquial","antebrazo"],"ins":["Ponte de pie con una mancuerna en cada mano, los brazos a los costados y las palmas hacia adelante.","Fija los codos a los costados y contrae el core para que el torso no pueda balancearse.","Flexiona ambas mancuernas hacia arriba moviendo solo los codos.","Bájalas de forma controlada hasta que los brazos queden rectos.","Repite las repeticiones deseadas."],"tips":["Ponerte de pie con la espalda contra una pared o poste es una buena autoevaluación — si los hombros o las caderas se separan de ella, estás usando impulso.","Evita que los codos se adelanten; los brazos superiores deben permanecer verticales durante todo el movimiento.","Baja más lento de lo que subes — la versión estricta vive en el descenso."],"met":5.0,"uni":false,"img":["strict-curl-start.webp","strict-curl-peak.webp"]},{"id":"suitcase-carry","n":"Paseo del Maletín","d":"Un paseo cargado con el peso en una sola mano, de modo que el tronco tiene que resistir la inclinación lateral durante todo el recorrido — la versión unilateral del paseo del granjero.","cat":"fuerza","g":"core","bp":"core","eq":"kettlebell","home":true,"bw":false,"lv":"principiante","m":["antebrazo","oblicuos","cuadrado lumbar"],"m2":["lumbares","glúteo medio","cuádriceps","trapecio"],"ins":["Colócate junto a una sola kettlebell o mancuerna, con los pies a la anchura de las caderas.","Flexiona por la cadera, agarra el asa con una mano e incorpórate con el peso colgando a un costado.","Lleva ese hombro abajo y atrás, y aprieta el tronco como si fueran a empujarte de lado.","Camina hacia delante con zancadas normales y regulares, manteniendo el torso erguido y cuadrado en lugar de inclinarte para escapar del peso.","Mantén el brazo libre relajado junto al cuerpo, sin separarlo como contrapeso.","Carga la distancia o el tiempo deseados, deja el peso en el suelo de forma controlada y repite por el otro lado."],"tips":["Haz la misma distancia por los dos lados. Todo el valor está en la asimetría, y solo funciona si cargas ambas direcciones por igual.","Si te inclinas hacia el peso o levantas la cadera contraria, el peso es excesivo: esto es ante todo un ejercicio de postura.","El agarre suele fallar antes que el tronco. Es un efecto de entrenamiento legítimo, pero si siempre es el límite, usa correas en las series pesadas."],"met":5.5,"uni":true,"img":["suitcase-carry-main.webp"]},{"id":"sumo-deadlift","n":"Peso Muerto Sumo","d":"Una variante del peso muerto con postura amplia que desplaza el énfasis hacia glúteos, cuádriceps e interior de los muslos.","cat":"fuerza","g":"espalda","bp":"back","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["glúteo mayor","cuádriceps"],"m2":["lumbares","isquiotibiales"],"ins":["Párate con los pies más anchos que el ancho de los hombros, con los pies apuntando hacia afuera.","Agarra la barra entre las piernas.","Contrae el core y empuja a través de los talones para levantarte.","Baja de forma controlada.","Repite."],"tips":["Mantén la barra pegada al cuerpo.","Empuja las rodillas hacia afuera en línea con los dedos de los pies."],"met":6.0,"uni":false,"img":["sumo-deadlift-start.webp","sumo-deadlift-peak.webp"]},{"id":"sumo-squat","n":"Sentadilla Sumo","d":"Una sentadilla con barra y postura amplia con las puntas hacia afuera, que enfatiza glúteos y cara interna de los muslos.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["glúteo mayor","cuádriceps"],"m2":["lumbares","glúteo medio","isquiotibiales"],"ins":["Párate con los pies más anchos que el ancho de los hombros y los pies apuntando hacia afuera.","Sostén una barra sobre la parte superior de la espalda.","Contrae el core y mantén el pecho arriba.","Dobla caderas y rodillas para bajar a una sentadilla profunda.","Empuja a través de los talones para volver a la posición de pie.","Repite el número de repeticiones deseado."],"tips":["Abre las puntas de los pies y empuja las rodillas hacia afuera.","Mantén el pecho alto y el core firme.","Baja en profundidad flexionando caderas y rodillas a la vez."],"met":6.0,"uni":false,"img":["sumo-squat-start.webp","sumo-squat-peak.webp"]},{"id":"superman","n":"Superman","d":"Un ejercicio de peso corporal para la zona lumbar realizado en prono, levantando brazos y piernas simultáneamente.","cat":"fuerza","g":"espalda","bp":"back","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["lumbares","glúteo mayor"],"m2":["isquiotibiales"],"ins":["Túmbate boca abajo con los brazos extendidos por encima de la cabeza.","Levanta simultáneamente los brazos, el pecho y las piernas del suelo.","Mantén brevemente la posición superior.","Baja de forma controlada.","Repite."],"tips":["Aprieta los glúteos al levantar.","Evita los movimientos bruscos."],"met":3.5,"uni":false,"img":["superman-start.webp","superman-peak.webp"]},{"id":"supine-spinal-twist","n":"Giro Espinal Tumbado","d":"Un giro tumbado que estira la zona lumbar, los glúteos y los oblicuos al cruzar una rodilla flexionada sobre el cuerpo.","cat":"estiramiento","g":"espalda","bp":"back","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["lumbares","oblicuos"],"m2":["glúteo mayor"],"ins":["Acuéstate boca arriba y lleva una rodilla al pecho.","Guía esa rodilla cruzando el cuerpo hacia el suelo.","Extiende los brazos y gira la cabeza hacia el lado contrario.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],"tips":["Mantén ambos hombros en el suelo.","Relájate y sigue respirando todo el tiempo."],"met":5.0,"uni":true,"img":["supine-spinal-twist-main.webp"]},{"id":"supine-windshield-wipers","n":"Limpiaparabrisas Tumbado","d":"Un ejercicio de rotación tumbado: con las rodillas flexionadas o las piernas elevadas, ambas piernas oscilan de lado a lado como limpiaparabrisas mientras los hombros permanecen pegados al suelo.","cat":"fuerza","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["oblicuos","abdominales"],"m2":["flexores de cadera","transverso abdominal"],"ins":["Túmbate boca arriba con los brazos abiertos a los lados y las rodillas flexionadas sobre las caderas.","Aprieta el tronco para que la zona lumbar no se despegue del suelo.","Baja ambas piernas juntas hacia un lado mientras los hombros sigan apoyados.","Devuélvelas por el centro y bájalas hacia el otro lado.","Sigue alternando las veces indicadas."],"tips":["Ambos hombros se quedan en el suelo; son ellos los que definen el recorrido, no las piernas.","Mantén las rodillas juntas para que la pelvis se mueva como una unidad.","Estira las piernas para una versión mucho más difícil cuando tengas el control."],"met":5.0,"uni":false,"img":["supine-windshield-wipers-start.webp","supine-windshield-wipers-peak.webp"]},{"id":"supported-shoulderstand","n":"Vela con Apoyo","d":"Una inversión apoyada en los hombros y los brazos, con las manos sosteniendo la espalda y el cuerpo alineado en vertical sobre los hombros.","cat":"fuerza","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["lumbares","abdominales"],"m2":["glúteo mayor","trapecio"],"ins":["Túmbate boca arriba, idealmente con una manta doblada bajo los hombros y la cabeza fuera de ella.","Eleva las piernas por encima de la cabeza y sostén la zona lumbar con ambas manos, los codos a la anchura de los hombros.","Camina las manos por la espalda y alinea las caderas sobre los hombros hasta que el cuerpo quede vertical.","Mantén la posición durante el tiempo indicado, con la cabeza y el cuello completamente quietos.","Baja las piernas por encima de la cabeza y desciende despacio con las manos sosteniendo la espalda."],"tips":["El peso va en los hombros y los brazos, nunca en el cuello.","No gires la cabeza mientras estás invertido.","Construye la postura con piernas en la pared y el arado antes de sostenerla mucho tiempo."],"met":5.0,"uni":false,"img":["supported-shoulderstand-main.webp"]},{"id":"svend-press","n":"Press Svend","d":"Un press con apretón de disco que carga los pectorales a través de la aducción isométrica mientras se extiende el peso alejándolo del pecho.","cat":"fuerza","g":"pecho","bp":"chest","eq":"discos","home":false,"bw":false,"lv":"principiante","m":["pectoral"],"m2":["deltoides anterior","tríceps"],"ins":["Párate erguido sosteniendo un disco de pesas (o dos apretados juntos) entre las palmas a la altura del pecho.","Aprieta fuerte los discos para generar tensión en los pectorales.","Empuja los discos recto hacia adelante hasta que los brazos estén completamente extendidos.","Haz una breve pausa manteniendo el apretón, luego devuelve los discos al pecho.","Repite el número de repeticiones recomendado."],"tips":["Cuanto más fuerte aprietes los discos, mayor activación del pecho obtendrás.","Mantén los discos a la altura del esternón durante todo el ejercicio: no dejes que caigan hacia las caderas."],"met":5.0,"uni":false,"img":["svend-press-start.webp","svend-press-peak.webp"]},{"id":"t-bar-row","n":"Remo en T","d":"Un remo compuesto con barra en T y torso inclinado, que desarrolla dorsales y romboides con cargas elevadas.","cat":"fuerza","g":"espalda","bp":"back","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["dorsales","romboides"],"m2":["bíceps","lumbares","trapecio"],"ins":["Colócate a horcajadas sobre la barra en T con los pies al ancho de los hombros.","Inclínate en las caderas hasta que el torso quede a unos 45 grados.","Agarra los mangos y mantén la espalda plana.","Tira de la barra hacia el pecho llevando los codos hacia atrás.","Aprieta los omóplatos en la parte superior.","Baja la barra de forma controlada y repite."],"tips":["Inclina el torso unos 45 grados manteniendo la espalda plana.","Tira llevando los codos hacia atrás, no solo con los brazos.","Junta los omóplatos en la parte alta del tirón."],"met":6.0,"uni":false,"img":["t-bar-row-start.webp","t-bar-row-peak.webp"]},{"id":"thoracic-bridge","n":"Puente Torácico","d":"Un sostén de movilidad que eleva las caderas desde sentado, con las manos detrás, hasta una mesa invertida y abre el pecho, extendiendo la columna torácica mientras los glúteos y los hombros sostienen el puente.","cat":"fuerza","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["lumbares","glúteo mayor"],"m2":["deltoides posterior","tríceps"],"ins":["Siéntate en el suelo con las rodillas flexionadas y las manos detrás, los dedos apuntando hacia atrás.","Empuja con las manos y los pies para elevar las caderas del suelo.","Sigue empujando hasta que el pecho se abra y los brazos queden extendidos.","Deja caer la cabeza hacia atrás y mantén la posición.","Respira de forma constante mientras mantienes el puente.","Baja de nuevo de forma controlada."],"tips":["Eleva bien las caderas y aprieta los glúteos para proteger la zona lumbar.","Mantén los pies planos y el peso repartido entre manos y pies."],"met":5.0,"uni":false,"img":["thoracic-bridge-main.webp"]},{"id":"thread-the-needle","n":"Enhebrar la Aguja","d":"Una rotación de rodillas: un brazo se desliza por debajo del cuerpo y el hombro y el lateral de la cabeza descansan en el suelo, rotando la columna torácica de forma pasiva.","cat":"estiramiento","g":"espalda","bp":"back","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["deltoides posterior","trapecio"],"m2":["lumbares","oblicuos"],"ins":["Comienza a cuatro apoyos con las manos bajo los hombros y las rodillas bajo las caderas.","Desliza un brazo por debajo del cuerpo con la palma hacia arriba hasta que el hombro y el lateral de la cabeza apoyen en la esterilla.","Mantén las caderas sobre las rodillas y camina la mano de arriba hacia delante o llévala a la espalda.","Mantén la torsión durante el tiempo indicado, respirando hacia la espalda alta.","Presiona la mano de arriba contra el suelo para subir y repite del otro lado."],"tips":["Mantén las caderas altas sobre las rodillas; si bajan, la rotación se convierte en una inclinación lateral.","Apoya la cabeza en un bloque si el hombro no llega cómodamente al suelo.","Deja que el hombro se asiente con la respiración en lugar de forzar la torsión."],"met":5.0,"uni":true,"img":["thread-the-needle-main.webp"]},{"id":"thread-the-needle-flow","n":"Enhebrar la Aguja Dinámico","d":"La versión en movimiento de enhebrar la aguja: desde cuatro apoyos el brazo pasa por debajo del cuerpo y después se abre hacia el techo, rotando la columna torácica por todo su recorrido.","cat":"estiramiento","g":"espalda","bp":"back","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["oblicuos","trapecio"],"m2":["lumbares","deltoides posterior"],"ins":["Comienza a cuatro apoyos con las manos bajo los hombros y las rodillas bajo las caderas.","Desliza un brazo por debajo del cuerpo hasta que el hombro se acerque a la esterilla.","Invierte el movimiento y abre ese brazo hacia el techo, siguiendo la mano con la mirada.","Vuelve por el centro y repite las veces indicadas.","Cambia de lado y repite."],"tips":["Mantén las caderas sobre las rodillas para que la rotación se quede en la espalda alta.","Trabaja a un ritmo uniforme en lugar de abrir el brazo de golpe.","Deja que la cabeza siga a la mano en lugar de liderar el movimiento."],"met":5.0,"uni":true,"img":["thread-the-needle-flow-start.webp","thread-the-needle-flow-peak.webp"]},{"id":"three-legged-dog","n":"Perro de Tres Patas","d":"El perro boca abajo con una pierna elevada: los hombros asumen más carga mientras la pierna elevada se alinea con la columna y las caderas se mantienen cuadradas.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["deltoides anterior","glúteo mayor"],"m2":["isquiotibiales","trapecio"],"ins":["Colócate en perro boca abajo con las manos a la anchura de los hombros y las caderas altas.","Presiona ambas manos por igual contra el suelo y desplaza el peso ligeramente hacia delante.","Eleva una pierna por detrás hasta alinearla con la columna, con ambas caderas niveladas.","Mantén la posición durante el tiempo indicado, con el talón de apoyo bajando hacia el suelo.","Baja la pierna y repite del otro lado."],"tips":["Evita que la cadera elevada se abra; una pelvis cuadrada importa más que la altura.","Presiona la base del índice contra el suelo para que las muñecas queden cómodas.","Flexiona ligeramente la rodilla de apoyo si el isquiotibial limita la forma."],"met":5.0,"uni":true,"img":["three-legged-dog-main.webp"]},{"id":"thruster","n":"Thruster","d":"Un movimiento de cuerpo completo con barra que combina una sentadilla frontal con un press por encima de la cabeza en un solo impulso fluido.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["deltoides anterior","cuádriceps"],"m2":["glúteo mayor","trapecio","tríceps"],"ins":["Sostén una barra en posición de rack frontal con los codos altos.","Párate con los pies al ancho de los hombros.","Baja en sentadilla hasta paralelo manteniendo el torso erguido.","Impúlsate saliendo de la sentadilla y empuja la barra por encima de la cabeza en un solo movimiento.","Bloquea los brazos en la parte superior con la barra sobre la cabeza.","Baja la barra al rack frontal y repite."],"tips":["Aprovecha el impulso de la sentadilla para lanzar el press.","Mantén los codos altos para que la barra descanse en los hombros, no en las muñecas.","Termina cada repetición con la barra bloqueada sobre las orejas."],"met":6.0,"uni":false,"img":["thruster-start.webp","thruster-peak.webp"]},{"id":"toes-to-bar","n":"Toes to Bar","d":"Un ejercicio avanzado de core colgado de una barra que requiere fuerza de flexión de cadera y activación del dorsal para llevar los pies hasta la barra.","cat":"fuerza","g":"core","bp":"core","eq":"barra de dominadas","home":true,"bw":false,"lv":"intermedio","m":["flexores de cadera","abdominales"],"m2":["antebrazo","dorsales","oblicuos"],"ins":["Cuélgate de una barra con agarre prono y los brazos completamente extendidos, cuerpo quieto.","Activa los dorsales y el core para evitar balanceos.","Eleva las piernas con rodillas rectas llevando los pies hacia la barra.","Toca la barra con los pies, luego baja las piernas con control.","Repite el número de repeticiones deseado."],"tips":["Inicia el movimiento desde el core, no con impulso de patada.","Exhala con fuerza al elevar las piernas para aumentar la presión intraabdominal.","Si todavía no llegas a la barra, practica antes las elevaciones de piernas colgado; son el paso previo más fácil."],"met":6.0,"uni":false,"img":["toes-to-bar-start.webp","toes-to-bar-peak.webp"]},{"id":"torso-twists","n":"Giros de Torso","d":"Un calentamiento rotacional de pie que gira la caja torácica de un lado a otro mientras la pelvis permanece relativamente estable, movilizando la columna torácica y el tronco.","cat":"estiramiento","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["oblicuos","transverso abdominal"],"m2":["lumbares"],"ins":["Ponte de pie con los pies separados al ancho de los hombros y las rodillas ligeramente flexionadas.","Activa suavemente el tronco y junta las manos frente al pecho.","Gira la caja torácica hacia un lado sin desplazar los pies.","Vuelve al centro y gira hacia el otro lado.","Sigue alternando con fluidez dentro de un rango cómodo."],"tips":["Gira desde la espalda alta en lugar de retorcer bruscamente la zona lumbar.","Mantén las caderas casi al frente y reparte el peso por igual entre ambos pies.","Usa un ritmo controlado; es movilidad, no un balanceo balístico."],"met":3.5,"uni":false,"img":["torso-twists-main.webp"]},{"id":"treadmill-running","n":"Carrera en Cinta","d":"Una carrera realizada sobre una cinta motorizada, que permite sostener un ritmo y una distancia bajo techo controlando la superficie y la pendiente.","cat":"cardio","g":"cuerpo completo","bp":"full_body","eq":"trotadora","home":false,"bw":false,"lv":"principiante","m":["gemelos","cuádriceps"],"m2":["glúteo mayor","isquiotibiales","flexores de cadera","sóleo"],"ins":["Súbete a la cinta con un pie sobre cada raíl lateral, arranca la banda a velocidad de caminata y pisa cuando ya esté en movimiento.","Sube progresivamente hasta tu ritmo de carrera, apoyando el pie bajo la cadera en lugar de estirar la zancada hacia delante.","Corre erguido con los hombros relajados, los codos flexionados unos noventa grados y los brazos balanceándose adelante y atrás, no cruzando el cuerpo.","Mira al frente y mantente en el centro de la banda en lugar de dejarte llevar hacia el rodillo trasero.","Sostén el ritmo durante el tiempo o la distancia deseados, luego baja la velocidad y camina unos minutos antes de bajarte."],"tips":["Engancha la llave de seguridad a la cinturilla — es lo único que detiene la banda si pierdes el pie.","No te agarres a los pasamanos mientras corres. Apoyarte en ellos acorta la zancada, tuerce la postura y oculta cuánto estás trabajando de verdad.","Una pendiente del uno o dos por ciento acerca la carrera en cinta a la carrera al aire libre, donde además hay que vencer la resistencia del aire."],"met":8.0,"uni":false,"img":["treadmill-running-main.webp"]},{"id":"tree-pose","n":"Postura del Árbol","d":"Un equilibrio de pie sobre una pierna con la planta del pie libre apoyada en la pantorrilla o el muslo interno y las caderas niveladas.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["glúteo medio","cuádriceps"],"m2":["lumbares","sóleo"],"ins":["Ponte de pie y pasa el peso a un pie.","Apoya la planta del otro pie en la cara interna de la pantorrilla o del muslo, evitando la rodilla.","Presiona el pie y la pierna entre sí y nivela las caderas.","Lleva las manos al pecho o por encima de la cabeza y mantén durante el tiempo indicado.","Baja el pie y repite del otro lado."],"tips":["No apoyes nunca el pie contra el lateral de la rodilla; solo por encima o por debajo.","Fija la mirada en un punto quieto para estabilizar el equilibrio.","Mantén la pelvis mirando al frente en lugar de dejar que la rodilla elevada la abra."],"met":5.0,"uni":true,"img":["tree-pose-main.webp"]},{"id":"triangle-pose","n":"Postura del Triángulo","d":"Una postura de base amplia con ambas piernas estiradas y el torso inclinándose lateralmente sobre la pierna delantera, que alarga el isquiotibial y todo el costado.","cat":"estiramiento","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["isquiotibiales","oblicuos"],"m2":["aductores","glúteo medio"],"ins":["Sepárate en una base amplia con el pie delantero girado hacia fuera y el trasero algo hacia dentro.","Mantén ambas piernas estiradas y estira la mano delantera hacia delante mientras las caderas van atrás.","Inclínate lateralmente y lleva la mano de abajo a la espinilla, un bloque o el suelo, con el brazo de arriba hacia el techo.","Mantén la posición durante el tiempo indicado, girando el pecho hacia el techo.","Empuja con los pies para subir y repite del otro lado."],"tips":["Alárgate primero sobre la pierna delantera antes de inclinarte; bajar demasiado pronto derrumba la postura.","Usa un bloque bajo la mano de abajo en lugar de arrastrar el pecho hacia el suelo.","Mantén ambas piernas estiradas y las rótulas activas."],"met":5.0,"uni":true,"img":["triangle-pose-main.webp"]},{"id":"tricep-kickback","n":"Patada de Tríceps con Mancuerna","d":"Un ejercicio de aislamiento para los tríceps realizado en posición inclinada hacia adelante.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"mancuernas","home":true,"bw":false,"lv":"principiante","m":["tríceps"],"m2":[],"ins":["Inclínate hacia adelante en las caderas sosteniendo una mancuerna con el codo doblado a 90 grados.","Extiende el brazo recto hacia atrás apretando el tríceps.","Mantén brevemente en la extensión completa.","Baja con control.","Repite en ambos lados."],"tips":["Mantén el codo pegado y fijo junto al torso.","Extiende el brazo por completo apretando el tríceps al final.","Trabaja un lado a la vez con control en la bajada."],"met":5.0,"uni":true,"img":["tricep-kickback-start.webp","tricep-kickback-peak.webp"]},{"id":"tricep-pushdown","n":"Jalón de Tríceps en Cable","d":"Un ejercicio de aislamiento para los tríceps usando una máquina de cable.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"polea","home":false,"bw":false,"lv":"principiante","m":["tríceps"],"m2":[],"ins":["Párate frente a una máquina de cable con un accesorio de barra recta.","Agarra la barra y pega los codos a los costados.","Empuja la barra hacia abajo hasta que los brazos estén completamente extendidos.","Regresa lentamente a la posición inicial.","Repite."],"tips":["Mantén el torso erguido.","Solo deben moverse los antebrazos."],"met":5.0,"uni":false,"img":["tricep-pushdown-start.webp","tricep-pushdown-peak.webp"]},{"id":"trx-bicep-curl","n":"Curl de Bíceps TRX","d":"Este ejercicio utiliza un entrenador de suspensión para aislar y fortalecer los músculos bíceps braquial y braquial, desarrollando fuerza e hipertrofia en la parte superior del brazo.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"TRX","home":true,"bw":false,"lv":"principiante","m":["bíceps"],"m2":["braquial","braquiorradial"],"ins":["Ajusta las correas del entrenador de suspensión a una longitud media.","Párate frente al punto de anclaje, sujeta las asas con un agarre supino e inclínate hacia atrás hasta que tus brazos estén completamente extendidos.","Mantén tu cuerpo recto y el core activado, jala tu pecho hacia tus manos doblando los codos.","Contrae tus bíceps en la parte superior del movimiento.","Extiende lentamente tus brazos de regreso a la posición inicial, controlando el descenso.","Mantén la tensión durante toda la serie."],"tips":["Ajusta el ángulo de tu cuerpo para aumentar o disminuir la dificultad; inclinarte más hacia atrás lo hace más difícil.","Mantén los codos altos y fijos para aislar los bíceps de manera efectiva.","Evita balancear tu cuerpo o usar el impulso; concéntrate en una contracción controlada.","Asegura un rango completo de movimiento, desde la extensión total hasta una fuerte contracción máxima."],"met":5.0,"uni":false,"img":["trx-bicep-curl-start.webp","trx-bicep-curl-peak.webp"]},{"id":"trx-chest-press","n":"Press de Pecho con TRX","d":"Un ejercicio compuesto de empuje que utiliza un entrenador de suspensión para desarrollar fuerza y estabilidad en el pecho.","cat":"fuerza","g":"pecho","bp":"chest","eq":"TRX","home":true,"bw":false,"lv":"principiante","m":["pectoral"],"m2":["deltoides anterior","abdominales","tríceps"],"ins":["Ajusta las asas del entrenador de suspensión a la altura de la mitad de la pantorrilla.","Ponte de espaldas al punto de anclaje, sosteniendo un asa en cada mano, con los brazos extendidos.","Inclínate hacia adelante en una posición de plancha, manteniendo tu cuerpo recto de la cabeza a los talones.","Baja tu pecho hacia tus manos doblando los codos, manteniendo la tensión en las correas.","Empuja hacia arriba a la posición inicial, extendiendo completamente los brazos y contrayendo el pecho."],"tips":["Mantén tu core activado durante todo el movimiento para mantener una plancha rígida.","Controla la fase excéntrica (descenso) para una mejor activación muscular.","Ajusta la posición de tus pies para modificar la dificultad: más cerca del anclaje (más horizontal) es más difícil, más lejos (más erguido) es más fácil.","Asegúrate de que tus codos se muevan ligeramente hacia afuera y hacia atrás, sin abrirlos demasiado."],"met":6.0,"uni":false,"img":["trx-chest-press-start.webp","trx-chest-press-peak.webp"]},{"id":"trx-face-pull","n":"Face Pull con TRX","d":"El Face Pull con TRX es un ejercicio de tracción compuesto que trabaja los deltoides posteriores y los romboides, utilizando un entrenador de suspensión para mejorar la fuerza de la parte superior de la espalda y la postura.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"TRX","home":true,"bw":false,"lv":"principiante","m":["deltoides posterior","romboides"],"m2":["trapecio"],"ins":["Sujeta las asas del TRX con un agarre prono, las palmas hacia abajo.","Inclínate hacia atrás hasta que tus brazos estén completamente extendidos y tu cuerpo forme una línea recta.","Tira de las asas hacia tu cara, llevando los codos altos y abiertos.","Aprieta los omóplatos al máximo de la contracción.","Extiende lentamente los brazos de vuelta a la posición inicial con control."],"tips":["Mantén el torso rígido durante todo el movimiento; evita arquear la espalda baja.","Concéntrate en iniciar la tracción con los músculos de la parte superior de la espalda, no solo con los brazos.","Ajusta el ángulo de tu cuerpo para modificar la dificultad: una posición más horizontal es más difícil."],"met":6.0,"uni":false,"img":["trx-face-pull-start.webp","trx-face-pull-peak.webp"]},{"id":"trx-hamstring-curl","n":"Curl de Isquiotibiales con TRX","d":"Este ejercicio de aislamiento utiliza un entrenador de suspensión para trabajar los isquiotibiales, glúteos y pantorrillas al flexionar los talones hacia los glúteos.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"TRX","home":true,"bw":false,"lv":"intermedio","m":["isquiotibiales"],"m2":["gemelos","glúteo mayor"],"ins":["Acuéstate boca arriba con los talones en los soportes del entrenador de suspensión, rodillas flexionadas a 90 grados.","Levanta tus caderas del suelo, creando una línea recta desde las rodillas hasta los hombros.","Extiende tus piernas hacia adelante, manteniendo las caderas elevadas y la tensión en el core.","Tira de tus talones hacia tus glúteos, contrayendo los isquiotibiales con fuerza.","Controla el movimiento, evitando que las caderas caigan durante toda la serie."],"tips":["Mantén tu core contraído para evitar que tus caderas se hundan.","Concéntrate en una fuerte contracción de los isquiotibiales en el punto máximo del curl.","Controla la fase excéntrica extendiendo lentamente tus piernas."],"met":5.0,"uni":false,"img":["trx-hamstring-curl-start.webp","trx-hamstring-curl-peak.webp"]},{"id":"trx-lunge","n":"Zancada TRX","d":"Un ejercicio unilateral de tren inferior apto para principiantes que utiliza un entrenador de suspensión para trabajar los cuádriceps y glúteos, mientras involucra los isquiotibiales y el glúteo medio para la estabilidad.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"TRX","home":true,"bw":false,"lv":"principiante","m":["glúteo mayor","cuádriceps"],"m2":["glúteo medio","isquiotibiales"],"ins":["Ponte de espaldas al punto de anclaje con las correas del entrenador de suspensión detrás de ti, las manos en la cadera o libres para equilibrarte.","Coloca el empeine de un pie en los estribos, extendiendo esa pierna hacia atrás.","Contrae tu abdomen y baja tu cuerpo doblando la rodilla delantera, manteniendo el torso erguido.","Desciende hasta que tu muslo delantero esté paralelo al suelo o ligeramente por debajo, manteniendo la tensión en el entrenador de suspensión.","Impúlsate a través del talón delantero para volver a la posición inicial, extendiendo la pierna delantera.","Completa todas las repeticiones en un lado, luego cambia de pierna y repite por lado."],"tips":["Mantén tu rodilla delantera alineada con tus dedos del pie, evitando que colapse hacia adentro.","Conserva una columna vertebral neutra durante todo el movimiento, previniendo un arqueo o redondeo excesivo.","Controla la fase excéntrica (de descenso) para maximizar el compromiso muscular.","Ajusta tu distancia del punto de anclaje para modificar la dificultad."],"met":6.0,"uni":true,"img":["trx-lunge-start.webp","trx-lunge-peak.webp"]},{"id":"trx-pistol-squat","n":"Sentadilla Pistola con TRX","d":"Un desafiante ejercicio unilateral de pierna que utiliza un entrenador de suspensión para asistir el equilibrio y la profundidad, trabajando principalmente los cuádriceps y glúteos.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"TRX","home":true,"bw":false,"lv":"intermedio","m":["glúteo mayor","cuádriceps"],"m2":["glúteo medio","isquiotibiales"],"ins":["Ancla el entrenador de suspensión y sujeta las asas con ambas manos, con los brazos extendidos.","Ponte de pie, levanta una pierna recta hacia adelante, manteniéndola separada del suelo.","Inicia la sentadilla empujando las caderas hacia atrás y doblando la rodilla de la pierna de apoyo, bajando el cuerpo lo más profundo posible.","Mantén el pecho erguido, la espalda recta y usa el TRX para el equilibrio y soporte según sea necesario.","Impúlsate a través del talón para volver a la posición inicial, extendiendo completamente la pierna de apoyo.","Completa todas las repeticiones por lado antes de cambiar de pierna."],"tips":["Mantén la tensión en las correas del TRX durante todo el movimiento para mayor estabilidad.","Concéntrate en un descenso controlado y un ascenso potente.","Mantén la pierna que no trabaja extendida y elevada para activar los flexores de la cadera.","Ajusta tu agarre en el TRX para modificar el nivel de asistencia."],"met":6.0,"uni":true,"img":["trx-pistol-squat-start.webp","trx-pistol-squat-peak.webp"]},{"id":"trx-plank","n":"Plancha en TRX","d":"Una plancha con los pies suspendidos en el TRX, que aumenta la demanda sobre el core y la estabilidad.","cat":"fuerza","g":"core","bp":"core","eq":"TRX","home":true,"bw":false,"lv":"intermedio","m":["abdominales","transverso abdominal"],"m2":["deltoides anterior","oblicuos"],"ins":["Coloca ambos pies en los estribos del TRX.","Adopta una posición de plancha en antebrazos o plancha alta en el suelo.","Mantén el cuerpo en línea recta de la cabeza a los talones.","Contrae el core y aprieta los glúteos.","Mantén la posición el tiempo deseado.","Baja las rodillas para salir de forma segura."],"tips":["Mantén el cuerpo en línea recta de la cabeza a los talones.","Aprieta abdomen y glúteos durante toda la retención.","Evita que la cadera se hunda o se eleve."],"met":6.0,"uni":false,"img":["trx-plank-main.webp"]},{"id":"trx-row","n":"Remo TRX","d":"Este ejercicio de tracción con peso corporal utiliza un entrenador de suspensión para trabajar toda tu espalda, desarrollando fuerza en los dorsales, romboides y bíceps.","cat":"fuerza","g":"espalda","bp":"back","eq":"TRX","home":true,"bw":false,"lv":"principiante","m":["dorsales","romboides"],"m2":["bíceps","deltoides posterior","trapecio"],"ins":["Sujeta las asas de un entrenador de suspensión con agarre neutro, las palmas enfrentadas.","Inclínate hacia atrás, extendiendo completamente los brazos y manteniendo el cuerpo recto de la cabeza a los talones.","Activa tu core y tira del pecho hacia las manos, juntando los omóplatos.","Haz una breve pausa en la parte superior, luego baja lentamente a la posición inicial con control.","Mantén el cuerpo rígido durante todo el movimiento, evitando que las caderas se caigan."],"tips":["Ajusta la posición de tus pies: cuanto más cerca estén tus pies del punto de anclaje, más difícil será el ejercicio.","Mantén los codos cerca del cuerpo para enfatizar los dorsales, o ábrelos ligeramente para trabajar más la parte superior de la espalda.","Concéntrate en iniciar la tracción con los músculos de la espalda, no solo con los brazos.","Controla la fase excéntrica (de descenso) para maximizar el compromiso muscular."],"met":6.0,"uni":false,"img":["trx-row-start.webp","trx-row-peak.webp"]},{"id":"trx-side-plank","n":"Plancha Lateral en TRX","d":"Una plancha lateral con los pies en el TRX, que trabaja los oblicuos y la estabilidad de la cadera.","cat":"fuerza","g":"core","bp":"core","eq":"TRX","home":true,"bw":false,"lv":"intermedio","m":["oblicuos","transverso abdominal"],"m2":["glúteo medio","deltoides lateral"],"ins":["Coloca ambos pies en los soportes del TRX y recuéstate de lado.","Apóyate en el antebrazo inferior con el codo bajo el hombro.","Eleva las caderas de modo que el cuerpo forme una línea recta.","Apila el pie superior sobre el pie inferior.","Mantén la posición respirando de forma constante.","Baja y cambia de lado al terminar la serie."],"tips":["Coloca el codo justo debajo del hombro de apoyo.","Eleva la cadera hasta formar una línea recta.","Respira de forma constante y cambia de lado al terminar."],"met":6.0,"uni":false,"img":["trx-side-plank-main.webp"]},{"id":"trx-squat","n":"Sentadilla TRX","d":"Este ejercicio compuesto de peso corporal utiliza un entrenador de suspensión para asistir en la realización de una sentadilla, trabajando eficazmente cuádriceps, glúteos e isquiotibiales.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"TRX","home":true,"bw":false,"lv":"principiante","m":["glúteo mayor","cuádriceps"],"m2":["isquiotibiales"],"ins":["Párate mirando hacia el punto de anclaje, sosteniendo las asas con las palmas enfrentadas y los brazos extendidos.","Inclínate ligeramente hacia atrás, manteniendo tu cuerpo recto y el core activado, con los pies al ancho de los hombros.","Inicia la sentadilla empujando las caderas hacia atrás y doblando las rodillas, bajando tu cuerpo como si te sentaras en una silla.","Desciende hasta que tus muslos estén paralelos al suelo o tan profundo como te sea cómodo, manteniendo la tensión en las correas.","Impúlsate a través de los talones para volver a la posición inicial, extendiendo completamente las caderas y las rodillas."],"tips":["Mantén el pecho erguido y la mirada al frente durante todo el movimiento para mantener una columna vertebral neutra.","Usa el entrenador de suspensión para ayudarte a controlar el descenso y el ascenso, especialmente si eres nuevo en las sentadillas.","Concéntrate en empujar las rodillas ligeramente hacia afuera para activar los glúteos de manera más efectiva."],"met":6.0,"uni":false,"img":["trx-squat-start.webp","trx-squat-peak.webp"]},{"id":"trx-tricep-extension","n":"Extensión de Tríceps TRX","d":"Este ejercicio trabaja el tríceps braquial utilizando un entrenador de suspensión, enfocándose en la extensión del codo para el desarrollo y la fuerza de la parte superior del brazo.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"TRX","home":true,"bw":false,"lv":"intermedio","m":["tríceps"],"m2":[],"ins":["Ponte de espaldas al punto de anclaje, sosteniendo las asas del TRX con agarre prono, las palmas hacia abajo.","Inclínate hacia adelante, extendiendo tus brazos rectos frente a ti a la altura de los hombros, creando tensión en las correas.","Manteniendo los codos altos y fijos, dóblalos para bajar tu cuerpo, llevando tus manos hacia tus sienes.","Extiende los codos con fuerza para empujar tu cuerpo de vuelta a la posición inicial, contrayendo tus tríceps.","Mantén una posición de plancha rígida durante todo el movimiento, activando tu core y glúteos."],"tips":["Ajusta el ángulo de tu cuerpo para aumentar o disminuir la dificultad; cuanto más horizontal, más difícil será el ejercicio.","Mantén los codos apuntando hacia adelante y altos para maximizar el aislamiento del tríceps y minimizar la participación del hombro.","Controla la fase excéntrica (descenso) para una mejor activación y crecimiento muscular."],"met":5.0,"uni":false,"img":["trx-tricep-extension-start.webp","trx-tricep-extension-peak.webp"]},{"id":"trx-y-fly","n":"TRX Y-Fly","d":"Este ejercicio con el entrenador de suspensión fortalece los deltoides posteriores y el trapecio, mejorando la salud del hombro y la postura al fortalecer la parte superior de la espalda.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"TRX","home":true,"bw":false,"lv":"intermedio","m":["deltoides posterior","trapecio"],"m2":["deltoides lateral","romboides"],"ins":["Ponte frente al punto de anclaje, sujetando las asas con agarre prono, las palmas hacia abajo.","Inclínate hacia atrás, extendiendo los brazos rectos hacia adelante, manteniendo tu cuerpo en posición de plancha.","Lleva los brazos hacia arriba y hacia fuera formando una \"Y\" por encima de la cabeza, juntando y bajando los omóplatos mientras el cuerpo sube hacia el anclaje.","Mantén los codos ligeramente flexionados y fijos todo el tiempo, apretando los omóplatos en la parte superior.","Controla lentamente el descenso de vuelta a la posición inicial, resistiendo la tracción de las correas."],"tips":["Ajusta el ángulo de tu cuerpo para modificar la dificultad: inclinarte más hacia atrás aumenta el desafío.","Concéntrate en la retracción y depresión de tus omóplatos durante todo el movimiento.","Mantén un core rígido y una línea corporal recta para evitar que las caderas se caigan."],"met":5.0,"uni":false,"img":["trx-y-fly-start.webp","trx-y-fly-peak.webp"]},{"id":"upright-row","n":"Remo al Mentón con Barra","d":"Un movimiento de tirón compuesto para los deltoides laterales y el trapecio superior.","cat":"fuerza","g":"hombros","bp":"shoulders","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["deltoides lateral","trapecio"],"m2":["deltoides anterior","bíceps"],"ins":["Párate sosteniendo una barra con un agarre en pronación a la anchura de los hombros.","Tira de la barra hacia arriba a lo largo del cuerpo en dirección al mentón.","Lidera con los codos, manteniéndolos por encima de las manos.","Baja la barra de forma controlada.","Repite."],"tips":["Sube la barra pegada al cuerpo hacia la barbilla.","Guía el movimiento con los codos por encima de las manos.","Baja la barra de forma controlada en cada repetición."],"met":6.0,"uni":false,"img":["upright-row-start.webp","upright-row-peak.webp"]},{"id":"upward-dog","n":"Perro Boca Arriba","d":"Una extensión boca abajo sobre los brazos estirados con los muslos despegados del suelo, donde los brazos y los extensores de la espalda mantienen el pecho abierto y la columna larga.","cat":"estiramiento","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["lumbares","tríceps"],"m2":["glúteo mayor","pectoral"],"ins":["Túmbate boca abajo con las manos junto a las costillas bajas y el empeine apoyado en el suelo.","Presiona las manos y estira los brazos, elevando primero el pecho y después los muslos de la esterilla.","Lleva los hombros atrás y abajo y mantén el cuello largo.","Mantén la posición durante el tiempo indicado con solo las manos y el empeine en el suelo.","Flexiona los brazos y baja de forma controlada."],"tips":["Mantén los hombros sobre las muñecas en lugar de por detrás de ellas.","Presiona el empeine contra el suelo; eso es lo que eleva los muslos.","Si los muslos no pueden despegarse, quédate en la cobra en lugar de forzar la posición."],"met":5.0,"uni":false,"img":["upward-dog-main.webp"]},{"id":"v-bar-lat-pulldown","n":"Jalón al Pecho con Barra en V","d":"Un jalón con agarre neutro realizado con una barra en V estrecha, maximizando el estiramiento del dorsal y permitiendo una contracción más profunda.","cat":"fuerza","g":"espalda","bp":"back","eq":"polea al pecho","home":false,"bw":false,"lv":"principiante","m":["dorsales"],"m2":["bíceps","romboides","trapecio"],"ins":["Coloca una barra en V (mango doble-D) en el cable de jalón al pecho.","Siéntate con los muslos asegurados bajo el pad y agarra el mango con las palmas enfrentadas.","Comienza con los brazos completamente extendidos por encima de la cabeza.","Tira del mango hacia el esternón empujando los codos hacia abajo y ligeramente hacia atrás.","Aprieta los dorsales en la posición inferior y sube lentamente de forma controlada.","Repite el número de repeticiones recomendado."],"tips":["El agarre neutro es más suave con los hombros que los agarres en pronación o supinación.","Imagina que acercas las costillas hacia las caderas: piensa en los dorsales, no en los brazos."],"met":6.0,"uni":false,"img":["v-bar-lat-pulldown-start.webp","v-bar-lat-pulldown-peak.webp"]},{"id":"v-bar-tricep-pushdown","n":"Extensión de Tríceps en Polea con Barra en V","d":"Una extensión de tríceps en polea con barra en V que fija las muñecas en posición pronada y ligeramente angulada, cargando la cabeza lateral.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"polea","home":false,"bw":false,"lv":"principiante","m":["tríceps"],"m2":[],"ins":["Coloca una barra en V en la polea alta.","Párate frente a la pila y agarra la barra en V con ambas manos, palmas hacia abajo.","Comienza con los codos pegados a los costados y los antebrazos paralelos al suelo.","Empuja el mango hacia abajo hasta que los brazos estén completamente extendidos.","Aprieta los tríceps y vuelve de forma controlada a la posición inicial.","Repite el número de repeticiones recomendado."],"tips":["Mantén los codos pegados a los costados durante toda la serie.","No te apoyes en la barra; una pequeña inclinación hacia adelante está bien, pero deja que los tríceps hagan el trabajo."],"met":5.0,"uni":false,"img":["v-bar-tricep-pushdown-start.webp","v-bar-tricep-pushdown-peak.webp"]},{"id":"v-sit","n":"Posición en V","d":"Un sostén estático del core en equilibrio sobre los isquiones, con las piernas y el torso elevados formando una V, que exige a los abdominales y los flexores de cadera.","cat":"fuerza","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["flexores de cadera","abdominales"],"m2":["oblicuos","cuádriceps"],"ins":["Siéntate en el suelo con las piernas extendidas frente a ti.","Inclínate ligeramente hacia atrás y eleva las piernas del suelo.","Extiende los brazos hacia adelante para que el cuerpo forme una V.","Equilíbrate sobre los isquiones con el core firme.","Mantén la posición respirando de forma constante.","Baja las piernas y el torso para salir."],"tips":["Mantén el pecho elevado y la columna larga en lugar de redondear la espalda.","Flexiona las rodillas si aún no puedes mantener las piernas estiradas."],"met":5.0,"uni":false,"img":["v-sit-main.webp"]},{"id":"v-ups","n":"V-Ups","d":"Un ejercicio dinámico de core que eleva las piernas y el torso juntos formando una V, trabajando los abdominales y los flexores de la cadera.","cat":"fuerza","g":"core","bp":"core","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["flexores de cadera","abdominales"],"m2":["oblicuos","transverso abdominal"],"ins":["Túmbate boca arriba con los brazos extendidos por encima de la cabeza y las piernas rectas.","Levanta simultáneamente las piernas y la parte superior del cuerpo hacia el centro.","Alcanza las manos hacia los pies en la parte superior, formando una V.","Mantén las piernas rectas durante todo el movimiento.","Baja ambos extremos de forma controlada hasta el suelo.","Repite el número de repeticiones deseado."],"tips":["Mantén las piernas estiradas mientras las elevas.","Lleva las manos hacia los pies en la parte alta.","Baja ambos extremos con control en lugar de dejarte caer plano."],"met":5.0,"uni":false,"img":["v-ups-start.webp","v-ups-peak.webp"]},{"id":"walking","n":"Caminar","d":"Marcha natural sobre terreno llano, manteniendo siempre un pie en contacto con el suelo, lo que la convierte en la forma de menor impacto de acumular trabajo aeróbico.","cat":"cardio","g":"cuerpo completo","bp":"full_body","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["gemelos","cuádriceps"],"m2":["glúteo mayor","isquiotibiales","flexores de cadera","sóleo"],"ins":["Ponte erguido, con el peso sobre la parte media de los pies y los hombros relajados, sin llevarlos hacia atrás.","Da un paso al frente y apoya primero el talón, luego rueda sobre el pie y empuja con la almohadilla y los dedos.","Mantén al menos un pie en el suelo en todo momento — en cuanto ambos se despegan estás corriendo, no caminando.","Deja que los brazos oscilen con naturalidad desde el hombro, brazo contrario a pierna contraria, con los codos ligeramente flexionados.","Mira al frente en lugar de a los pies y respira con un ritmo constante y sostenible.","Continúa el tiempo o la distancia deseados, eligiendo un ritmo al que todavía podrías mantener una conversación."],"tips":["El ritmo lo es todo aquí. Un paseo y una caminata enérgica son estímulos distintos, así que elige uno a propósito en vez de dejarte llevar.","Alarga el empuje por detrás en lugar de estirar más hacia delante: la zancada larga te hace aterrizar con la pierna recta y frena cada paso.","Es el único trabajo de acondicionamiento que puedes hacer a diario sin necesitar recuperarte de él, y por eso merece la pena programarlo en vez de dejarlo al azar."],"met":3.5,"uni":false,"img":["walking-main.webp"]},{"id":"walking-lunge","n":"Zancada Caminando","d":"Una zancada en movimiento que avanza pierna tras pierna, trabajando los cuádriceps y glúteos con un desafío de equilibrio adicional.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["glúteo mayor","cuádriceps"],"m2":["glúteo medio","isquiotibiales"],"ins":["Párate erguido con los pies separados al ancho de las caderas y las manos en las caderas.","Da un paso adelante largo con un pie en zancada.","Baja hasta que ambas rodillas estén en torno a 90 grados.","Empuja con el talón delantero y lleva el pie trasero hacia adelante.","Continúa alternando piernas al avanzar.","Repite el número de repeticiones deseado."],"tips":["Baja hasta que ambas rodillas formen unos 90 grados.","Mantén el torso erguido al dar el paso.","Impulsa con el talón delantero para avanzar con fluidez."],"met":5.0,"uni":true,"img":["walking-lunge-start.webp","walking-lunge-peak.webp"]},{"id":"wall-ball","n":"Wall Ball","d":"Un ejercicio de acondicionamiento de cuerpo completo que combina una sentadilla frontal y un lanzamiento: sujetando un balón medicinal grande y blando a la altura del pecho, bajas en sentadilla, subes con fuerza y lanzas el balón a un objetivo situado en lo alto de una pared; después lo atrapas y pasas directamente a la siguiente sentadilla. Las piernas y las caderas generan la potencia y los brazos terminan el lanzamiento.","cat":"fuerza","g":"cuerpo completo","bp":"full_body","eq":"wall ball","home":false,"bw":false,"lv":"intermedio","m":["glúteo mayor","cuádriceps"],"m2":["deltoides anterior","abdominales","tríceps"],"ins":["Ponte de pie frente a una pared, a aproximadamente un brazo de distancia, con los pies separados al ancho de los hombros y el balón sujeto a la altura del pecho con ambas manos.","Mantén los codos debajo del balón y el pecho alto.","Baja en sentadilla hasta que las caderas queden a la altura de las rodillas o por debajo, manteniendo los talones en el suelo.","Sube con fuerza empujando con las piernas y las caderas y, mientras te levantas, lanza el balón hacia el objetivo con ambos brazos.","Atrapa el balón a la altura del pecho cuando baje, dejando que los brazos amortigüen el impacto.","Encadena la recepción directamente con la siguiente sentadilla y repite el número de repeticiones previsto."],"tips":["Deja que sean las piernas las que lancen el balón: el impulso de la sentadilla debe llevarlo la mayor parte del recorrido y los brazos solo terminan el movimiento.","Mantén el pecho alto y el balón cerca del cuerpo en la sentadilla para que la espalda se mantenga neutra.","Atrapa el balón y baja en sentadilla en un solo movimiento; descansar con el balón arriba rompe el ritmo y cansa los hombros."],"met":6.0,"uni":false,"img":["wall-ball-main.webp"]},{"id":"wall-push-ups","n":"Push-Ups en Pared","d":"Una flexión de pie contra la pared apta para principiantes, que trabaja el pecho con carga reducida.","cat":"fuerza","g":"pecho","bp":"chest","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["pectoral"],"m2":["deltoides anterior","tríceps"],"ins":["Párate frente a una pared y coloca las palmas sobre ella a la altura de los hombros.","Retrocede con los pies hasta que los brazos estén completamente extendidos.","Flexiona los codos para acercar el pecho a la pared.","Mantén el cuerpo en línea recta durante todo el movimiento.","Empuja de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"tips":["Apoya las palmas a la altura de los hombros.","Mantén el cuerpo en línea recta de la cabeza a los pies.","Acerca el pecho a la pared flexionando los codos."],"met":5.0,"uni":false,"img":["wall-push-ups-start.webp","wall-push-ups-peak.webp"]},{"id":"wall-sit","n":"Sentadilla en Pared","d":"Un ejercicio isométrico estático que consiste en mantener la posición de sentadilla contra una pared para desarrollar la resistencia de los cuádriceps.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["glúteo mayor","cuádriceps"],"m2":["isquiotibiales"],"ins":["Párate con la espalda contra una pared.","Deslízate hacia abajo hasta que los muslos estén paralelos al suelo.","Mantén la posición.","Vuelve a ponerte de pie cuando termines."],"tips":["Mantén las rodillas a 90 grados.","Presiona la espalda plana contra la pared."],"met":5.0,"uni":false,"img":["wall-sit-main.webp"]},{"id":"warrior-one","n":"Guerrero I","d":"Una postura en paso largo con el pie trasero apoyado en diagonal, la rodilla delantera flexionada y los brazos arriba, con las caderas mirando al frente.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["glúteo mayor","cuádriceps"],"m2":["deltoides anterior","lumbares"],"ins":["Lleva un pie atrás y gíralo unos cuarenta y cinco grados, apoyando toda la planta.","Flexiona la rodilla delantera hasta que quede sobre el tobillo y mantén la pierna trasera estirada.","Lleva ambas caderas hacia el frente de la esterilla y eleva los brazos por encima de la cabeza.","Mantén la posición durante el tiempo indicado, con las costillas cerradas y el pecho alto.","Junta los pies y repite del otro lado."],"tips":["Separa los pies lateralmente para que ambas caderas miren al frente sin forzar la rodilla trasera.","Presiona el borde externo del pie trasero para mantener la base estable.","Separa los brazos a la anchura de los hombros si juntar las palmas te arquea la zona lumbar."],"met":5.0,"uni":true,"img":["warrior-one-main.webp"]},{"id":"warrior-three","n":"Guerrero III","d":"Un equilibrio sobre una pierna con el torso y la pierna elevada paralelos al suelo, formando una línea larga desde las yemas de los dedos hasta el talón elevado.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["glúteo mayor","isquiotibiales"],"m2":["lumbares","glúteo medio"],"ins":["Ponte de pie sobre una pierna con la rodilla blanda y las caderas niveladas.","Bascula hacia delante desde las caderas mientras la otra pierna se eleva por detrás.","Continúa hasta que el torso y la pierna elevada queden aproximadamente paralelos al suelo.","Estira los brazos hacia delante, junto al cuerpo o hacia los lados, y mantén durante el tiempo indicado.","Baja la pierna y repite del otro lado."],"tips":["Evita que la cadera elevada se abra hacia arriba; ambas deben mirar al suelo.","Flexiona el pie elevado y empuja el talón hacia atrás para mantener la pierna activa.","Apoya las manos en bloques o en una pared mientras construyes el equilibrio."],"met":5.0,"uni":true,"img":["warrior-three-main.webp"]},{"id":"warrior-two","n":"Guerrero II","d":"Una postura de base amplia con la rodilla delantera flexionada, las caderas abiertas al lado y los brazos extendidos a la altura de los hombros.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["glúteo medio","cuádriceps"],"m2":["aductores","deltoides lateral"],"ins":["Sepárate en una base amplia con el pie delantero girado noventa grados y el trasero algo hacia dentro.","Flexiona la rodilla delantera hasta que quede sobre el tobillo y apunte hacia los dedos centrales.","Abre las caderas y el pecho hacia el lado y extiende los brazos paralelos al suelo.","Mantén la posición durante el tiempo indicado, con la mirada sobre la mano delantera.","Estira la pierna delantera y repite del otro lado."],"tips":["Evita que la rodilla delantera caiga hacia dentro; empújala hacia el lado del dedo meñique.","Alinea los hombros sobre las caderas en lugar de inclinarte hacia la pierna delantera.","Acorta la base si el muslo delantero no puede acercarse a la paralela."],"met":5.0,"uni":true,"img":["warrior-two-main.webp"]},{"id":"weighted-dips","n":"Fondos Lastrados","d":"Un fondo en paralelas con carga añadida — normalmente un disco colgado de un cinturón de lastre entre las piernas — para mantener el ejercicio en un rango de fuerza cuando los fondos con el propio peso ya resultan fáciles.","cat":"fuerza","g":"pecho","bp":"chest","eq":"paralelas","home":false,"bw":false,"lv":"avanzado","m":["pectoral","tríceps"],"m2":["deltoides anterior"],"ins":["Cuelga un disco del cinturón de lastre y ajústalo a la cintura de modo que el peso quede suelto entre las piernas.","Agarra las barras paralelas y súbete hasta la posición inicial con los brazos estirados y los pies separados del suelo.","Inclina ligeramente el torso hacia delante y baja el cuerpo flexionando los codos hasta que los hombros queden por debajo de ellos.","Empuja con las palmas para volver a subir hasta estirar los brazos, evitando que el disco colgante se balancee.","Repite el número de repeticiones deseado."],"tips":["Añade peso solo cuando hagas fondos limpios con el propio peso en todo el recorrido: saltos de 2,5 a 5 kg son suficientes, porque la carga se suma a tu propio peso corporal.","Mantén las piernas juntas y el core apretado para que el disco no empiece a balancearse; un peso que oscila estropea la parte baja de la repetición.","Mantén los hombros alejados de las orejas y detén el descenso si notas pinzamiento en la parte delantera del hombro."],"met":6.0,"uni":false,"img":["weighted-dips-start.webp","weighted-dips-peak.webp"]},{"id":"weighted-pull-up","n":"Dominada Lastrada","d":"Una dominada con carga añadida — normalmente un disco colgado de un cinturón de lastre entre las piernas — para mantener el ejercicio en un rango de fuerza cuando las dominadas con el propio peso ya resultan fáciles.","cat":"fuerza","g":"espalda","bp":"back","eq":"barra de dominadas","home":true,"bw":false,"lv":"avanzado","m":["dorsales"],"m2":["bíceps","deltoides posterior","romboides","trapecio"],"ins":["Cuelga un disco del cinturón de lastre y ajústalo a la cintura de modo que el peso quede suelto entre las piernas; también puedes sujetar la carga entre los pies.","Agarra la barra en pronación algo más abierto que la anchura de los hombros y cuélgate con los brazos estirados y las piernas juntas.","Tira de los codos hacia abajo y hacia atrás llevando el pecho hacia la barra hasta que la barbilla la supere.","Baja de forma controlada hasta la suspensión completa, mantén la tensión en los dorsales y deja que el peso se estabilice antes de la siguiente repetición.","Repite el número de repeticiones deseado."],"tips":["Añade peso solo cuando hagas dominadas limpias con el propio peso en todo el recorrido: saltos de 2,5 a 5 kg son suficientes, porque la carga se suma a tu propio peso corporal.","Mantén las piernas juntas y el core apretado para que el disco colgante no empiece a balancearse; un peso que oscila convierte la repetición en un kipping.","No recortes la parte baja: vuelve a la suspensión completa en cada repetición y termina la serie cuando la barbilla deje de superar la barra, en lugar de forzar repeticiones parciales."],"met":6.0,"uni":false,"img":["weighted-pull-up-start.webp","weighted-pull-up-peak.webp"]},{"id":"weighted-wall-crunch","n":"Crunch en Pared con Peso","d":"Una variante del crunch con las piernas apartadas del movimiento —los pies apoyados contra una pared o un cajón, o simplemente las piernas en alto— para que la cadera no ayude y trabajen los abdominales.","cat":"fuerza","g":"core","bp":"core","eq":"discos","home":false,"bw":false,"lv":"intermedio","m":["abdominales"],"m2":["oblicuos"],"ins":["Túmbate boca arriba y coloca las piernas de modo que la cadera no pueda ayudar: apoya los pies contra una pared o un cajón, o mantén las piernas en alto con las rodillas flexionadas.","Sujeta un peso contra el pecho con ambas manos: un disco, una mancuerna o una pesa rusa sirven igual.","Haz el crunch hacia arriba, despegando los omóplatos del suelo.","Baja de forma controlada.","Repite."],"tips":["Apoya los pies en la pared con las rodillas a 90 grados.","Sujeta el disco sobre el pecho durante todo el ejercicio.","Despega los omóplatos del suelo sin tirar del cuello."],"met":5.0,"uni":false,"img":["weighted-wall-crunch-start.webp","weighted-wall-crunch-peak.webp"]},{"id":"wide-grip-bench-press","n":"Press de Banca en Agarre Ancho","d":"Una variante del press de banca con un agarre más ancho que los hombros para maximizar la activación del pectoral.","cat":"fuerza","g":"pecho","bp":"chest","eq":"barra","home":false,"bw":false,"lv":"intermedio","m":["pectoral"],"m2":["deltoides anterior","tríceps"],"ins":["Túmbate en un banco plano. Agarra la barra más ancha que los hombros.","Baja la barra hasta la mitad del pecho.","Empuja de vuelta a la extensión completa.","Repite."],"tips":["Un agarre más ancho reduce la participación de los tríceps.","Evita doblar las muñecas en exceso."],"met":6.0,"uni":false,"img":["wide-grip-bench-press-start.webp","wide-grip-bench-press-peak.webp"]},{"id":"wide-grip-pull-ups","n":"Dominadas en Agarre Ancho","d":"Una dominada con agarre prono más ancho que los hombros, que enfatiza el desarrollo de los dorsales.","cat":"fuerza","g":"espalda","bp":"back","eq":"barra de dominadas","home":true,"bw":false,"lv":"intermedio","m":["dorsales"],"m2":["bíceps","deltoides posterior","romboides","trapecio"],"ins":["Agarra la barra de dominadas con un agarre en pronación más ancho que los hombros.","Cuélgate con los brazos completamente extendidos y el core contraído.","Tira del pecho hacia la barra empujando los codos hacia abajo.","Mantén los hombros hacia atrás al subir.","Baja de forma controlada hasta la extensión completa.","Repite el número de repeticiones deseado."],"tips":["Cuelga con los brazos extendidos y el core firme.","Lleva el pecho hacia la barra bajando los codos.","Desciende con control hasta la extensión completa."],"met":6.0,"uni":false,"img":["wide-grip-pull-ups-start.webp","wide-grip-pull-ups-peak.webp"]},{"id":"wide-grip-push-ups","n":"Flexiones con Agarre Ancho","d":"Una variante de flexión con las manos colocadas más separadas para enfatizar el pecho.","cat":"fuerza","g":"pecho","bp":"chest","eq":"sin equipo","home":true,"bw":true,"lv":"intermedio","m":["pectoral"],"m2":["deltoides anterior","serrato","tríceps"],"ins":["Comienza en una plancha alta con las manos más separadas que el ancho de hombros.","Mantén el cuerpo en línea recta de la cabeza a los talones.","Baja el pecho hacia el suelo flexionando los codos.","Mantén el core activado y los glúteos contraídos.","Empuja de vuelta hasta extender los brazos.","Repite el número de repeticiones deseado."],"tips":["Mantén los codos a unos 45 grados respecto al torso.","Mantén una línea recta de la cabeza a los talones.","Baja hasta que el pecho quede cerca del suelo."],"met":5.0,"uni":false,"img":["wide-grip-push-ups-start.webp","wide-grip-push-ups-peak.webp"]},{"id":"wide-grip-seated-cable-row","n":"Remo en Polea Sentado en Agarre Ancho","d":"Una variante del remo sentado con agarre ancho que hace énfasis en la parte superior de la espalda.","cat":"fuerza","g":"espalda","bp":"back","eq":"polea","home":false,"bw":false,"lv":"intermedio","m":["dorsales","romboides"],"m2":["bíceps","deltoides posterior"],"ins":["Siéntate en la estación de remo con los pies en la plataforma.","Agarra la barra ancha con un agarre en pronación.","Tira de la barra hacia el abdomen superior apretando los omóplatos.","Extiende los brazos de vuelta a la posición inicial de forma controlada.","Repite."],"tips":["Sujeta la barra ancha con agarre prono.","Lleva la barra hacia el abdomen alto juntando los omóplatos.","Extiende los brazos al frente de forma controlada."],"met":6.0,"uni":false,"img":["wide-grip-seated-cable-row-start.webp","wide-grip-seated-cable-row-peak.webp"]},{"id":"wide-legged-forward-fold","n":"Flexión con Piernas Abiertas","d":"Una flexión de pie desde una base amplia con las manos en el suelo, que alarga los isquiotibiales y la cara interna de los muslos mientras la columna cuelga larga.","cat":"estiramiento","g":"piernas","bp":"upper_legs","eq":"sin equipo","home":true,"bw":true,"lv":"principiante","m":["aductores","isquiotibiales"],"m2":["lumbares","gemelos"],"ins":["Ponte de pie con los pies muy separados y los bordes externos paralelos.","Apoya las manos en las caderas, eleva el pecho y bascula hacia delante desde las articulaciones de la cadera.","Lleva las manos al suelo bajo los hombros y deja que la cabeza cuelgue.","Mantén la flexión durante el tiempo indicado, desplazando ligeramente el peso hacia las puntas de los pies.","Devuelve las manos a las caderas y sube con la espalda plana."],"tips":["Deja una micro flexión en las rodillas para que la flexión venga de las caderas y no de la zona lumbar.","Mantén los pies paralelos; girarlos hacia fuera quita el estiramiento de la cara interna de los muslos.","Apoya las manos en bloques cuando el suelo quede lejos."],"met":5.0,"uni":false,"img":["wide-legged-forward-fold-main.webp"]},{"id":"wide-stance-leg-press","n":"Prensa de piernas con postura amplia","d":"Una prensa de piernas con una postura amplia y ligeramente abierta, que aumenta la participación de los aductores junto con la extensión de cadera y rodilla.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"prensa","home":false,"bw":false,"lv":"principiante","m":["aductores"],"m2":["glúteo mayor","isquiotibiales","cuádriceps"],"ins":["Ajusta el asiento y el respaldo para que la zona lumbar permanezca apoyada en la parte baja del recorrido.","Coloca los pies separados en la plataforma y gira las puntas hacia fuera solo hasta donde las rodillas puedan seguirlas.","Baja el carro flexionando caderas y rodillas y mantén las rodillas en la misma dirección que los pies.","Empuja con todo el pie y extiende caderas y rodillas sin forzar el bloqueo.","Baja el carro bajo control y repite el número deseado de repeticiones."],"tips":["Elige una anchura y un ángulo de los pies que puedas controlar desde la cadera; más ancho no siempre es mejor.","Mantén las rodillas siguiendo a los pies y evita que se hundan hacia dentro.","Detén el descenso antes de que la pelvis se despegue y la espalda pierda contacto con el respaldo."],"met":6.0,"uni":false,"img":["wide-stance-leg-press-start.webp","wide-stance-leg-press-peak.webp"]},{"id":"wrist-curl","n":"Curl de Muñeca con Mancuernas Bilateral","d":"Un curl de muñeca con mancuernas realizado con ambos brazos a la vez, que aísla los flexores del antebrazo para un entrenamiento eficiente.","cat":"fuerza","g":"brazos","bp":"lower_arms","eq":"mancuernas","home":true,"bw":false,"lv":"principiante","m":["antebrazo"],"m2":["braquiorradial"],"ins":["Siéntate en un banco sujetando una mancuerna en cada mano, con los antebrazos apoyados sobre los muslos, palmas hacia arriba.","Deja que ambas mancuernas rueden hacia las puntas de los dedos.","Flexiona las muñecas para levantar ambas mancuernas.","Aprieta arriba y baja con control.","Repite el número deseado de repeticiones."],"tips":["Mantén los antebrazos apoyados en los muslos durante todo el movimiento — solo se mueven las muñecas.","Usa una carga por mano más ligera que en la versión unilateral, ya que ambos lados trabajan a la vez."],"met":5.0,"uni":false,"img":["wrist-curl-start.webp","wrist-curl-peak.webp"]},{"id":"wrist-roller","n":"Rodillo de Muñeca","d":"Un ejercicio para el antebrazo que consiste en enrollar un peso con la cuerda mediante el giro de las muñecas.","cat":"fuerza","g":"brazos","bp":"lower_arms","eq":"rodillo de muñeca","home":false,"bw":false,"lv":"intermedio","m":["antebrazo"],"m2":["deltoides anterior"],"ins":["Agarra el mango del rodillo con los brazos extendidos al frente a la altura de los hombros.","Deja que el peso cuelgue del cordón.","Enrolla el mango hacia adelante con movimientos alternos de muñeca para subir el peso.","Mantén los brazos rectos durante todo el movimiento.","Una vez enrollado por completo, invierte la rotación para bajar el peso.","Repite el número de repeticiones deseado."],"tips":["Mantén los brazos extendidos al frente a la altura de los hombros.","Enrolla la cuerda con giros alternos de las muñecas.","Invierte la rotación para bajar el peso de forma controlada."],"met":6.0,"uni":false,"img":["wrist-roller-start.webp","wrist-roller-peak.webp"]},{"id":"zercher-squat","n":"Sentadilla Zercher","d":"Una sentadilla en la que la barra se sostiene en el pliegue de los codos, delante del cuerpo. La barra cargada al frente mantiene el torso erguido y trabaja los cuádriceps, los glúteos, la parte alta de la espalda y el core.","cat":"fuerza","g":"piernas","bp":"upper_legs","eq":"barra","home":false,"bw":false,"lv":"avanzado","m":["glúteo mayor","cuádriceps"],"m2":["bíceps","lumbares","isquiotibiales"],"ins":["Coloca una barra en un rack aproximadamente a la altura de la cintura, acércate y engánchala en el pliegue de los codos, con los antebrazos cruzados o las manos entrelazadas delante del pecho.","Saca la barra del rack, da un paso atrás y colócate con los pies a la anchura de los hombros aproximadamente.","Contrae el core y mantén el pecho erguido y los codos juntos.","Baja en sentadilla flexionando caderas y rodillas hasta que los muslos queden al menos paralelos al suelo.","Empuja con el centro de los pies para volver a ponerte de pie.","Repite el número de repeticiones deseado y luego vuelve a dejar la barra en el rack."],"tips":["Envuelve la barra con una almohadilla o una toalla; el pliegue del codo es sensible y puede amoratarse.","Mantén los codos altos y juntos para que la barra no ruede hacia las manos.","Mantén el torso erguido; si el pecho se cae, reduce la carga."],"met":6.0,"uni":false,"img":["zercher-squat-start.webp","zercher-squat-peak.webp"]},{"id":"zottman-curl","n":"Curl Zottman","d":"Un curl con mancuernas de pie que sube con agarre supinado, gira las palmas hacia abajo en la parte superior y desciende en pronación para combinar el trabajo del bíceps con una fase excéntrica centrada en los antebrazos.","cat":"fuerza","g":"brazos","bp":"upper_arms","eq":"mancuernas","home":true,"bw":false,"lv":"intermedio","m":["bíceps"],"m2":["braquial","braquiorradial","antebrazo"],"ins":["Colócate de pie con los pies aproximadamente al ancho de las caderas, los brazos extendidos a los lados y una mancuerna en cada mano con las palmas hacia delante.","Mantén los brazos junto a las costillas y lleva ambas mancuernas hacia los hombros sin balancear el torso.","En la parte superior, conserva los codos flexionados y gira los antebrazos hasta que las palmas miren hacia abajo.","Baja lentamente las mancuernas con el agarre pronado hasta extender los brazos.","Vuelve a girar las palmas hacia delante en la parte inferior y repite las repeticiones deseadas."],"tips":["Usa menos peso que en un curl con mancuernas convencional; la bajada con las palmas hacia abajo suele ser la parte limitante.","Gira desde los antebrazos y mantén las muñecas rectas en lugar de doblarlas alrededor de las empuñaduras.","Mantén los codos cerca de las costillas y evita convertir el curl en un balanceo de hombros."],"met":5.0,"uni":false,"img":["zottman-curl-start.webp","zottman-curl-peak.webp"]}];
